def builtin_scientific_skills() -> list[dict[str, Any]]:
    domains = {
        "PaperToProtocolSkill": ["papers", "SOP", "wet-lab methods"],
        "KitManualParserSkill": ["kit manuals", "ELISA", "qPCR", "vendor protocols"],
        "CSVTemplateParserSkill": ["CSV", "Excel", "instrument exports"],
        "qPCRAnalysisSkill": ["qPCR", "RT-qPCR", "gene expression"],
        "ELISAAnalysisSkill": ["ELISA", "plate reader", "standard curve"],
        "WBRecordStructuringSkill": ["Western blot", "ImageJ", "protein records"],
        "LCMSFeatureTableStructuringSkill": ["LC-MS", "metabolomics", "feature tables"],
        "AnimalRecordStructuringSkill": ["animal records", "dose records", "body weight"],
        "ExperimentLogStructuringSkill": ["experiment logs", "failure records", "next steps"],
        "ReagentCalculationSkill": ["dilution", "molarity", "dose table"],
        "PlateLayoutSkill": ["96-well plate", "replicates", "sample mapping"],
        "DataNamingConventionSkill": ["data naming", "versioning", "raw file traceability"],
        "WeeklyReportSkill": ["weekly report", "project progress"],
        "ProjectGapAnalysisSkill": ["gap analysis", "publication risk", "unsupported conclusions"],
        "MemoryUpdateSkill": ["research memory", "provenance", "relationship graph"],
        "ConflictDetectionSkill": ["sample conflicts", "file duplicates", "timepoint mismatch"],
    }
    file_types = {
        "KitManualParserSkill": ["pdf", "txt", "md"],
        "CSVTemplateParserSkill": ["csv", "tsv", "xlsx"],
        "qPCRAnalysisSkill": ["csv", "xlsx", "txt"],
        "ELISAAnalysisSkill": ["csv", "xlsx"],
        "WBRecordStructuringSkill": ["txt", "csv", "image metadata"],
        "LCMSFeatureTableStructuringSkill": ["csv", "tsv", "xlsx"],
        "AnimalRecordStructuringSkill": ["csv", "xlsx", "md"],
        "ExperimentLogStructuringSkill": ["md", "txt", "docx text"],
    }
    skills: list[dict[str, Any]] = []
    for name in BUILTIN_SKILL_NAMES:
        skills.append(
            {
                "skill_id": stable_id("builtin", name, "0.1", length=20),
                "skill_name": name,
                "version": "0.1",
                "description": skill_description(name),
                "applicable_domains": domains.get(name, ["wet-lab research"]),
                "input_schema": {"project_id": "string optional", "source_file_id": "string optional", "text_or_table": "string|object"},
                "output_schema": {"structured_output": "object", "confidence": "number", "provenance": "object[]"},
                "required_tools": ["local SQLite", "rule parser", "mock LLM adapter"],
                "required_file_types": file_types.get(name, ["txt", "md", "csv", "xlsx", "pdf text"]),
                "example_inputs": [{"description": f"Run {name} on a local file or pasted experimental text."}],
                "example_outputs": [{"description": f"Structured {name} output with confidence and provenance."}],
                "safety_or_reliability_notes": [
                    "Do not present unsupported conclusions as facts.",
                    "Keep project data isolated from global reusable skill memory.",
                    "Require human confirmation for important scientific decisions.",
                ],
                "handler": name,
                "status": "enabled",
            }
        )
    return skills


def skill_description(name: str) -> str:
    words = re.sub(r"Skill$", "", name)
    words = re.sub(r"([a-z])([A-Z])", r"\1 \2", words)
    return f"Reusable scientific skill for {words.lower()} in local-first wet-lab workflows."


def now() -> str:
    return datetime.now().isoformat(timespec="seconds")


def clean(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip()


def stable_id(*parts: Any, length: int = 24) -> str:
    joined = "|".join(clean(part).lower() for part in parts)
    return hashlib.sha1(joined.encode("utf-8")).hexdigest()[:length]


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def json_dumps(value: Any) -> str:
    return json.dumps(value if value is not None else None, ensure_ascii=False, sort_keys=True)


def json_loads(value: Any, default: Any) -> Any:
    if value in (None, ""):
        return default
    if isinstance(value, (dict, list)):
        return value
    try:
        return json.loads(str(value))
    except json.JSONDecodeError:
        return default


def as_list(value: Any) -> list[Any]:
    if value is None or value == "":
        return []
    if isinstance(value, list):
        return value
    if isinstance(value, tuple):
        return list(value)
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return []
        if stripped.startswith("["):
            parsed = json_loads(stripped, [])
            return parsed if isinstance(parsed, list) else [parsed]
        return [item.strip() for item in re.split(r"[,，;；、\n]+", stripped) if item.strip()]
    return [value]


def row_to_dict(row: sqlite3.Row | None) -> dict[str, Any] | None:
    if row is None:
        return None
    item = dict(row)
    json_fields = {
        "keywords",
        "tags",
        "aliases",
        "involved_items",
        "steps",
        "input_requirements",
        "output_type",
        "tool_required",
        "result_json",
        "logs",
        "input_schema",
        "output_schema",
        "applicable_domains",
        "required_tools",
        "required_file_types",
        "example_inputs",
        "example_outputs",
        "safety_or_reliability_notes",
        "input_materials",
        "reagents",
        "parsed_reagents",
        "parsed_steps",
        "parsed_calculations",
        "parsed_plate_layout",
        "parsed_qc_rules",
        "parsed_output_schema",
        "equipment",
        "safety_notes",
        "variables",
        "controls",
        "sample_plan",
        "sample_numbering",
        "experimental_groups",
        "dose_design",
        "timeline",
        "instrument_parameters",
        "data_naming_rules",
        "expected_output_files",
        "required_human_confirmation_points",
        "extracted_entities",
        "related_samples",
        "related_figures",
        "related_conclusions",
        "related_reports",
        "expected_files",
        "data_outputs",
        "quality_control_points",
        "expected_results",
        "failure_modes",
        "parameters",
        "risk_points",
        "QC_points",
        "package_json",
        "evidence_file_ids",
        "limitations",
        "metadata",
        "input_object_refs",
        "output_object_refs",
        "input_payload",
        "output_payload",
        "provenance",
        "raw_row",
        "missing_metadata",
        "evidence_metadata",
        "protocol_candidates",
        "groups",
        "sample_ids",
        "conditions",
        "concentrations",
        "time_points",
        "cell_lines",
        "organisms",
        "instruments",
        "assays",
        "processed_data_file_ids",
        "columns",
        "sample_mapping",
        "related_memory_ids",
        "supported_by_experiment_ids",
        "supported_by_file_ids",
        "contradicted_by_ids",
        "supersedes",
        "downstream_effects",
        "do_not_repeat_without",
        "related_file_ids",
        "related_experiment_ids",
    }
    for key in list(item.keys()):
        if key in json_fields or key.endswith("_json"):
            parsed_key = key[:-5] if key.endswith("_json") else key
            default: Any = [] if key not in {"result_json", "package_json", "metadata"} else {}
            item[parsed_key] = json_loads(item.pop(key), default)
    return item


def rows_to_dicts(rows: list[sqlite3.Row]) -> list[dict[str, Any]]:
    return [row_to_dict(row) or {} for row in rows]


def db_table_exists(conn: sqlite3.Connection, table: str) -> bool:
    row = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table,)).fetchone()
    return row is not None


def db_count(conn: sqlite3.Connection, table: str, where: str = "", params: tuple[Any, ...] = ()) -> int:
    if not db_table_exists(conn, table):
        return 0
    sql = f'SELECT COUNT(*) FROM "{table}"'
    if where:
        sql += f" WHERE {where}"
    try:
        return int(conn.execute(sql, params).fetchone()[0])
    except Exception:
        return 0


def research_os_db(agent_root: Path) -> Path:
    agent_root.mkdir(parents=True, exist_ok=True)
    return agent_root / "research_group_os.sqlite"


def connect(agent_root: Path) -> sqlite3.Connection:
    db_path = research_os_db(agent_root)
    conn = sqlite3.connect(db_path, timeout=60)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout = 60000")
    conn.execute("PRAGMA foreign_keys = ON")
    schema_key = str(db_path.resolve())
    with _SCHEMA_LOCK:
        if schema_key not in _SCHEMA_READY:
            conn.execute("PRAGMA journal_mode = WAL")
            conn.execute("PRAGMA synchronous = NORMAL")
            ensure_schema(conn)
            _SCHEMA_READY.add(schema_key)
    return conn


