def bootstrap_system_agent_memory(conn: sqlite3.Connection) -> None:
    system_entries = [
        {
            "memory_type": "system_capability",
            "title": "Five-layer ResearchOS architecture",
            "content": "Research memory, protocol structure, workflow coordination, data contextualization, and reporting decision loop are separate but linked layers.",
            "structured_content": {
                "layers": [
                    "research_memory",
                    "protocol_structure",
                    "workflow_coordination",
                    "data_contextualization",
                    "reporting_decision_loop",
                ]
            },
        },
        {
            "memory_type": "privacy_rule",
            "title": "Project memory isolation",
            "content": "Reusable skills may be shared across labs, but project-level research data must remain isolated by project or lab.",
            "structured_content": {"do_not_mix_project_data_into_system_memory": True},
        },
    ]
    timestamp = now()
    for entry in system_entries:
        entry_id = stable_id("system", entry["memory_type"], entry["title"], length=24)
        conn.execute(
            """
            INSERT INTO agent_memory_entries(
              id, memory_scope, project_id, memory_type, title, content, structured_content_json,
              source_type, source_id, provenance_json, confidence, trust_level, status, created_at, updated_at
            )
            VALUES (?, 'system', '', ?, ?, ?, ?, 'bootstrap', '', ?, 0.96, 'system', 'active', ?, ?)
            ON CONFLICT(id) DO UPDATE SET
              content=excluded.content,
              structured_content_json=excluded.structured_content_json,
              updated_at=excluded.updated_at
            """,
            (
                entry_id,
                entry["memory_type"],
                entry["title"],
                entry["content"],
                json_dumps(entry["structured_content"]),
                json_dumps([{"source": "research_os_mvp.py", "type": "system_bootstrap"}]),
                timestamp,
                timestamp,
            ),
        )
    conn.commit()


def data_dir(agent_root: Path) -> Path:
    root = agent_root / "research_os_files"
    root.mkdir(parents=True, exist_ok=True)
    return root


def normalize_filename(filename: str) -> str:
    path = Path(filename)
    stem = re.sub(r"[^A-Za-z0-9._-]+", "_", path.stem).strip("._-").lower()
    stem = re.sub(r"_+", "_", stem) or "research_file"
    suffix = path.suffix.lower()
    return f"{stem}{suffix}"


def version_group(filename: str) -> str:
    stem = Path(normalize_filename(filename)).stem
    stem = re.sub(r"[_-]?(?:v|version)[_-]?\d+$", "", stem, flags=re.IGNORECASE)
    stem = re.sub(r"[_-]?\d{4}[-_]?\d{2}[-_]?\d{2}$", "", stem)
    stem = re.sub(r"[_-]?\d{8}$", "", stem)
    return stable_id(stem or filename, length=16)


def classify_file(filename: str, text: str = "") -> str:
    value = f"{filename} {text[:2000]}".lower()
    suffix = Path(filename).suffix.lower()
    if any(term in value for term in ["qpcr", "rt-qpcr", "ct value", "delta ct", "Δct"]):
        return "qPCR data"
    if any(term in value for term in ["western blot", " wb ", "imagej", "gapdh", "beta-actin"]):
        return "WB data"
    if "elisa" in value or "od450" in value or "plate reader" in value:
        return "ELISA data"
    if any(term in value for term in ["lc-ms", "lcms", "m/z", "retention time", "feature table"]):
        return "LC-MS data"
    if any(term in value for term in ["animal", "mouse", "mice", "rat", "body weight", "dose mg/kg"]):
        return "animal record"
    if any(term in value for term in ["cell", "passage", "seeding density", "confluence"]):
        return "cell experiment record"
    if any(term in value for term in ["sop", "standard operating procedure"]):
        return "SOP"
    if any(term in value for term in ["protocol", "method", "reagent", "incubate", "centrifuge"]):
        return "protocol"
    if any(term in value for term in ["manuscript", "abstract", "introduction", "discussion"]):
        return "manuscript draft"
    if any(term in value for term in ["experiment log", "lab note", "observation", "failed", "next step"]):
        return "experiment log"
    if suffix in {".xlsx", ".xls", ".csv", ".tsv"}:
        return "Excel spreadsheet"
    if suffix in {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".svg"}:
        return "figure"
    if suffix in {".pdf"}:
        return "paper"
    if any(term in value for term in ["instrument", "export", "raw data"]):
        return "instrument export"
    return "unknown"


def _plain_text_pdf_fallback(path: Path) -> str:
    try:
        raw = path.read_bytes()[:2_000_000]
    except Exception:
        return ""
    text = raw.decode("utf-8", errors="ignore")
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if len(text) < 40:
        return ""
    words = re.findall(r"[A-Za-z][A-Za-z0-9-]{2,}", text)
    return text if len(words) >= 8 else ""


def text_from_path(path: Path) -> str:
    if not path.exists():
        raise FileNotFoundError(f"file not found: {path}")
    if path.suffix.lower() in {".txt", ".md", ".csv", ".tsv", ".json"}:
        return path.read_text(encoding="utf-8", errors="replace")
    if path.suffix.lower() == ".pdf":
        try:
            if path.read_bytes()[:5] != b"%PDF-":
                return _plain_text_pdf_fallback(path)
        except Exception:
            return ""
        try:
            from pypdf import PdfReader  # type: ignore
        except Exception:
            return _plain_text_pdf_fallback(path)
        try:
            reader = PdfReader(str(path))
            parts: list[str] = []
            total_chars = 0
            for page in reader.pages[:120]:
                page_text = clean(page.extract_text() or "")
                if not page_text:
                    continue
                parts.append(page_text)
                total_chars += len(page_text)
                if total_chars >= 160000:
                    break
            parsed_text = "\n\n".join(parts)
            return parsed_text or _plain_text_pdf_fallback(path)
        except Exception:
            return _plain_text_pdf_fallback(path)
    return ""


def create_project(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    title = clean(payload.get("title") or payload.get("project_name") or payload.get("display_name"))
    if not title:
        raise ValueError("title is required")
    status = clean(payload.get("status")) or "active"
    if status not in PROJECT_STATUSES:
        raise ValueError(f"unsupported project status: {status}")
    timestamp = now()
    project_id = clean(payload.get("id")) or stable_id(title, payload.get("owner"), length=20)
    project_name = clean(payload.get("project_name")) or title or "未命名项目"
    display_name = clean(payload.get("display_name")) or project_name or "未命名项目"
    root_dir = clean(payload.get("root_dir"))
    uploads_dir = clean(payload.get("uploads_dir"))
    pdf_dir = clean(payload.get("pdf_dir"))
    kb_dir = clean(payload.get("kb_dir"))
    if not root_dir or not uploads_dir or not pdf_dir or not kb_dir:
        dirs = default_project_dirs(agent_root, display_name)
        root_dir = root_dir or dirs["root_dir"]
        uploads_dir = uploads_dir or dirs["uploads_dir"]
        pdf_dir = pdf_dir or dirs["pdf_dir"]
        kb_dir = kb_dir or dirs["kb_dir"]
    row = {
        "id": project_id,
        "project_id": project_id,
        "project_name": project_name,
        "display_name": display_name,
        "aliases_json": json_dumps(as_list(payload.get("aliases"))),
        "title": title,
        "short_description": clean(payload.get("short_description") or payload.get("description")),
        "research_area": clean(payload.get("research_area")),
        "keywords_json": json_dumps(as_list(payload.get("keywords"))),
        "owner": clean(payload.get("owner")) or "local_user",
        "status": status,
        "root_dir": root_dir,
        "uploads_dir": uploads_dir,
        "pdf_dir": pdf_dir,
        "kb_dir": kb_dir,
        "memory_scope_id": clean(payload.get("memory_scope_id")) or project_id,
        "is_active": 0 if status == "archived" else int(payload.get("is_active") if payload.get("is_active") is not None else 1),
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO projects(
          id, project_id, project_name, display_name, aliases_json, title, short_description, research_area,
          keywords_json, owner, status, root_dir, uploads_dir, pdf_dir, kb_dir, memory_scope_id, is_active,
          created_at, updated_at
        )
        VALUES (
          :id, :project_id, :project_name, :display_name, :aliases_json, :title, :short_description, :research_area,
          :keywords_json, :owner, :status, :root_dir, :uploads_dir, :pdf_dir, :kb_dir, :memory_scope_id, :is_active,
          :created_at, :updated_at
        )
        ON CONFLICT(id) DO UPDATE SET
          project_id=excluded.project_id,
          project_name=excluded.project_name,
          display_name=excluded.display_name,
          aliases_json=excluded.aliases_json,
          title=excluded.title,
          short_description=excluded.short_description,
          research_area=excluded.research_area,
          keywords_json=excluded.keywords_json,
          owner=excluded.owner,
          status=excluded.status,
          root_dir=excluded.root_dir,
          uploads_dir=excluded.uploads_dir,
          pdf_dir=excluded.pdf_dir,
          kb_dir=excluded.kb_dir,
          memory_scope_id=excluded.memory_scope_id,
          is_active=excluded.is_active,
          updated_at=excluded.updated_at
        """,
        row,
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone())
    conn.close()
    project = saved or row
    canonical_memory.sync_project(agent_root, project)
    return project


def project_storage_slug(display_name: str) -> str:
    value = normalize_filename(clean(display_name) or "未命名项目")
    value = re.sub(r"\.[A-Za-z0-9]{1,8}$", "", value).strip("._- ")
    return value or "unnamed_project"


def default_project_dirs(agent_root: Path, display_name: str) -> dict[str, str]:
    root = agent_root / "research_os_files" / "projects" / project_storage_slug(display_name)
    return {
        "root_dir": str(root),
        "uploads_dir": str(root / "uploads"),
        "pdf_dir": str(root / "pdf"),
        "kb_dir": str(root / "kb"),
    }


def project_display_name(project: dict[str, Any] | None) -> str:
    project = project or {}
    return clean(project.get("display_name") or project.get("project_name") or project.get("title")) or "未命名项目"


def normalize_project_row(agent_root: Path, project: dict[str, Any] | None) -> dict[str, Any]:
    if not project:
        return {}
    display_name = project_display_name(project)
    dirs = default_project_dirs(agent_root, display_name)
    normalized = dict(project)
    normalized["project_id"] = clean(normalized.get("project_id")) or clean(normalized.get("id"))
    normalized["project_name"] = clean(normalized.get("project_name")) or clean(normalized.get("title")) or "未命名项目"
    normalized["display_name"] = display_name
    normalized["aliases"] = as_list(normalized.get("aliases")) or json_loads(normalized.get("aliases_json"), [])
    normalized["aliases_json"] = json_dumps(normalized["aliases"])
    normalized["root_dir"] = clean(normalized.get("root_dir")) or dirs["root_dir"]
    normalized["uploads_dir"] = clean(normalized.get("uploads_dir")) or dirs["uploads_dir"]
    normalized["pdf_dir"] = clean(normalized.get("pdf_dir")) or dirs["pdf_dir"]
    normalized["kb_dir"] = clean(normalized.get("kb_dir")) or dirs["kb_dir"]
    normalized["memory_scope_id"] = clean(normalized.get("memory_scope_id")) or clean(normalized.get("id"))
    normalized["is_active"] = 0 if clean(normalized.get("status")) == "archived" else int(normalized.get("is_active") if normalized.get("is_active") is not None else 1)
    return normalized


def list_projects(agent_root: Path) -> list[dict[str, Any]]:
    conn = connect(agent_root)
    rows = conn.execute("SELECT * FROM projects WHERE COALESCE(status,'active')!='purged' ORDER BY updated_at DESC").fetchall()
    conn.close()
    return [normalize_project_row(agent_root, row) for row in rows_to_dicts(rows)]


def project_public_view(project: dict[str, Any]) -> dict[str, Any]:
    return {
        "display_name": project_display_name(project),
        "project_name": clean(project.get("project_name")) or project_display_name(project),
        "aliases": as_list(project.get("aliases")),
        "status": clean(project.get("status")) or "active",
        "is_active": bool(project.get("is_active")),
        "updated_at": clean(project.get("updated_at")),
    }


def list_projects_grouped(agent_root: Path) -> dict[str, Any]:
    active: list[dict[str, Any]] = []
    archived: list[dict[str, Any]] = []
    for project in list_projects(agent_root):
        view = project_public_view(project)
        if clean(project.get("status")) == "archived":
            archived.append(view)
        else:
            active.append(view)
    return {"active": active, "archived": archived, "counts": {"active": len(active), "archived": len(archived)}}


def list_projects_for_ui(agent_root: Path) -> list[dict[str, Any]]:
    items = []
    for project in list_projects(agent_root):
        items.append(project_public_view(project))
    return items


def ensure_default_chat_project(agent_root: Path, project_id: str) -> None:
    if clean(project_id) != "default":
        return
    conn = connect(agent_root)
    try:
        exists = conn.execute("SELECT 1 FROM projects WHERE id=?", ("default",)).fetchone()
    finally:
        conn.close()
    if exists:
        return
    create_project(
        agent_root,
        {
            "id": "default",
            "project_name": "default",
            "display_name": "默认项目 default",
            "title": "默认项目 default",
            "short_description": "默认 Chat 使用的稳定项目。",
        },
    )


def normalize_project_match_text(value: Any) -> str:
    return re.sub(r"\s+", "", clean(value).lower())


def project_list_requested(message: str) -> bool:
    text = clean(message)
    lower = text.lower()
    return any(term in lower for term in ["project list", "all projects", "list projects"]) or any(term in text for term in ["有哪些项目", "项目列表", "全部课题", "所有项目", "全部项目"])


def extract_project_switch_target(message: str) -> str:
    text = clean(message)
    patterns = [
        r"切换到\s*(.+)",
        r"进入\s*(.+)",
        r"打开\s*(.+)",
        r"把当前项目设为\s*(.+)",
        r"把当前课题设为\s*(.+)",
        r"switch to\s+(.+)",
        r"open project\s+(.+)",
        r"enter project\s+(.+)",
        r"set current project to\s+(.+)",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            target = clean(match.group(1))
            target = re.sub(r"[。.!！?？]+$", "", target).strip()
            return target
    return ""


def project_switch_requested(message: str) -> bool:
    return bool(extract_project_switch_target(message))


def resolve_project_by_display_name_or_alias(agent_root: Path, query: str, *, include_archived: bool = False) -> dict[str, Any]:
    needle = normalize_project_match_text(query)
    if not needle:
        return {"status": "no_query", "matches": []}
    projects = [project for project in list_projects(agent_root) if include_archived or clean(project.get("status")) != "archived"]
    exact: list[dict[str, Any]] = []
    partial: list[dict[str, Any]] = []
    for project in projects:
        names = [project_display_name(project), clean(project.get("project_name")), clean(project.get("title")), *as_list(project.get("aliases"))]
        normalized_names = [normalize_project_match_text(name) for name in names if clean(name)]
        if needle in normalized_names:
            exact.append(project)
        elif any(needle in name or name in needle for name in normalized_names):
            partial.append(project)
    matches = exact or partial
    if not matches:
        return {"status": "not_found", "matches": []}
    if len(matches) == 1:
        return {"status": "matched", "project": matches[0], "matches": matches}
    return {"status": "ambiguous", "matches": matches}


def format_project_list_answer(grouped: dict[str, Any]) -> str:
    lines = ["当前可用项目："]
    active = as_list(grouped.get("active"))
    archived = as_list(grouped.get("archived"))
    if active:
        for item in active:
            if isinstance(item, dict):
                lines.append(f"- {project_display_name(item)}：{clean(item.get('status')) or 'active'}")
    else:
        lines.append("- 暂无 active 项目")
    if archived:
        lines.append("归档项目：")
        for item in archived:
            if isinstance(item, dict):
                lines.append(f"- {project_display_name(item)}：archived")
    return "\n".join(lines)


def format_project_switch_ambiguous_answer(matches: list[dict[str, Any]]) -> str:
    lines = ["找到多个相似项目，请回复要进入的项目名："]
    for project in matches[:8]:
        lines.append(f"- {project_display_name(project)}")
    return "\n".join(lines)


def update_project(agent_root: Path, project_id: str, patch: dict[str, Any]) -> dict[str, Any]:
    allowed = {"title", "project_name", "display_name", "aliases_json", "short_description", "research_area", "keywords_json", "owner", "status", "root_dir", "uploads_dir", "pdf_dir", "kb_dir", "memory_scope_id", "is_active"}
    assignments: list[str] = []
    values: list[Any] = []
    for key, value in patch.items():
        column = "keywords_json" if key == "keywords" else ("aliases_json" if key == "aliases" else key)
        if column not in allowed:
            continue
        assignments.append(f"{column}=?")
        values.append(json_dumps(as_list(value)) if column.endswith("_json") else clean(value))
    if not assignments:
        raise ValueError("no supported project fields to update")
    assignments.append("updated_at=?")
    values.extend([now(), project_id])
    conn = connect(agent_root)
    conn.execute(f"UPDATE projects SET {', '.join(assignments)} WHERE id=?", values)
    row = conn.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone()
    if not row:
        conn.close()
        raise KeyError("project not found")
    conn.commit()
    conn.close()
    return normalize_project_row(agent_root, row_to_dict(row) or {})


def archive_project(agent_root: Path, project_id: str) -> dict[str, Any]:
    return update_project(agent_root, project_id, {"status": "archived", "is_active": 0})


def unarchive_project(agent_root: Path, project_id: str) -> dict[str, Any]:
    return update_project(agent_root, project_id, {"status": "active", "is_active": 1})


def _safe_int(value: Any) -> int:
    try:
        return int(value or 0)
    except Exception:
        return 0


def _path_size(path: Path) -> int:
    try:
        if path.is_file():
            return path.stat().st_size
        if path.is_dir():
            total = 0
            for child in path.rglob("*"):
                if child.is_file():
                    try:
                        total += child.stat().st_size
                    except Exception:
                        pass
            return total
    except Exception:
        return 0
    return 0


def _project_file_paths(conn: sqlite3.Connection, project_id: str, scope: str) -> list[str]:
    paths: list[str] = []
    if db_table_exists(conn, "research_files") and scope in {"uploads", "downloaded_pdfs", "all", "purge"}:
        if scope == "uploads":
            rows = rows_to_dicts(conn.execute("SELECT stored_path, file_path FROM research_files WHERE project_id=? AND COALESCE(source,'uploaded')='uploaded'", (project_id,)).fetchall())
        elif scope == "downloaded_pdfs":
            rows = rows_to_dicts(conn.execute("SELECT stored_path, file_path FROM research_files WHERE project_id=? AND (source='downloaded' OR file_type='pdf' OR detected_document_category='paper')", (project_id,)).fetchall())
        else:
            rows = rows_to_dicts(conn.execute("SELECT stored_path, file_path FROM research_files WHERE project_id=?", (project_id,)).fetchall())
        for row in rows:
            path_value = clean(row.get("stored_path") or row.get("file_path"))
            if path_value:
                paths.append(path_value)
    if db_table_exists(conn, "references") and scope in {"downloaded_pdfs", "kb", "all", "purge"}:
        for row in rows_to_dicts(conn.execute('SELECT full_text_path FROM "references" WHERE project_id=? AND full_text_path IS NOT NULL AND full_text_path!=?', (project_id, "")).fetchall()):
            if clean(row.get("full_text_path")):
                paths.append(clean(row.get("full_text_path")))
    return sorted(set(paths))


PROJECT_CLEAR_SCOPES: dict[str, list[str]] = {
    "uploads": ["research_files"],
    "downloaded_pdfs": ["literature_ingest_items", "paper_requests", "unmatched_pdfs"],
    "kb": ['"references"', "reference_chunks", "knowledge_base_entries", "rag_queries", "documents", "document_chunks"],
    "memory": ["agent_memory_entries", "memory_entities", "memory_consolidation_runs", "pending_memory_candidates"],
    "tasks": ["literature_search_tasks", "agent_tasks", "skill_runs", "execution_memory", "agent_inbox_items", "agent_watch_state"],
    "data_context": ["data_contexts", "file_sample_links"],
}
PROJECT_RESEARCH_RECORD_TABLES = ["experiments", "samples", "protocols", "conclusions", "decisions"]


def _scope_tables(scope: str) -> list[str]:
    scope = clean(scope) or "all"
    if scope == "all":
        tables: list[str] = []
        for key in ["uploads", "downloaded_pdfs", "kb", "memory", "tasks", "data_context"]:
            tables.extend(PROJECT_CLEAR_SCOPES[key])
        tables.extend(PROJECT_RESEARCH_RECORD_TABLES)
        tables.extend(["artifacts", "weekly_digest_reports", "weekly_digest_configs", "reports", "claims", "claim_evidence", "claim_reference_links", "failure_logs", "experiment_log_entries", "decision_logs", "retrospective_notes"])
        return list(dict.fromkeys(tables))
    if scope not in PROJECT_CLEAR_SCOPES:
        raise ValueError(f"unsupported clear scope: {scope}")
    return PROJECT_CLEAR_SCOPES[scope]


def _table_count(conn: sqlite3.Connection, table: str, project_id: str) -> int:
    table_name = table.strip('"')
    if not db_table_exists(conn, table_name):
        return 0
    return db_count(conn, table_name, "project_id=?", (project_id,))


def _project_runtime_dirs(agent_root: Path, project: dict[str, Any]) -> list[str]:
    project_id = clean(project.get("id") or project.get("project_id"))
    dirs: list[str] = []
    if project_id:
        dirs.append(str(data_dir(agent_root) / "literature_harvest" / project_id))
    return dirs


def _project_dirs_for_scope(agent_root: Path, project: dict[str, Any], scope: str) -> list[str]:
    if scope == "uploads":
        return [clean(project.get("uploads_dir"))]
    if scope == "downloaded_pdfs":
        return [clean(project.get("pdf_dir"))]
    if scope == "kb":
        return [clean(project.get("kb_dir"))]
    if scope == "all":
        return [clean(project.get("uploads_dir")), clean(project.get("pdf_dir")), clean(project.get("kb_dir"))]
    if scope == "purge":
        return [clean(project.get("root_dir")), clean(project.get("uploads_dir")), clean(project.get("pdf_dir")), clean(project.get("kb_dir")), *_project_runtime_dirs(agent_root, project)]
    return []


def build_project_deletion_plan(agent_root: Path, project_id: str, scope: str = "all", *, purge: bool = False) -> dict[str, Any]:
    project = get_project_detail(agent_root, project_id)
    scope_key = "purge" if purge else (clean(scope) or "all")
    conn = connect(agent_root)
    try:
        tables = _scope_tables("all" if purge else scope_key)
        table_counts = {table.strip('"'): _table_count(conn, table, project_id) for table in tables}
        file_paths = _project_file_paths(conn, project_id, "purge" if purge else scope_key)
    finally:
        conn.close()
    dirs = [item for item in _project_dirs_for_scope(agent_root, project, "purge" if purge else scope_key) if item]
    existing_files = [path for path in file_paths if Path(path).exists()]
    bytes_to_free = sum(_path_size(Path(path)) for path in existing_files)
    if purge and clean(project.get("root_dir")) and Path(clean(project.get("root_dir"))).exists():
        bytes_to_free = max(bytes_to_free, _path_size(Path(clean(project.get("root_dir")))))
    return {
        "project": {"display_name": project_display_name(project), "status": clean(project.get("status"))},
        "scope": "purge" if purge else scope_key,
        "affected_dirs": dirs,
        "affected_tables": table_counts,
        "record_count": sum(table_counts.values()),
        "file_count": len(existing_files),
        "file_paths": file_paths,
        "estimated_free_bytes": bytes_to_free,
        "estimated_free_mb": round(bytes_to_free / (1024 * 1024), 3),
        "requires_confirmation": True,
        "confirmation_phrase": ("CONFIRM PURGE " if purge else "确认清空 ") + project_display_name(project),
    }


def _confirmation_matches(action: str, display_name: str, confirmation: str) -> bool:
    text = clean(confirmation)
    if action == "clear":
        return text == f"确认清空 {display_name}"
    if action == "purge":
        return text in {f"确认彻底删除 {display_name}", f"CONFIRM PURGE {display_name}"}
    return False


def _delete_project_files(file_paths: list[str]) -> list[dict[str, str]]:
    failed: list[dict[str, str]] = []
    for path_text in sorted(set(clean(path) for path in file_paths if clean(path))):
        path = Path(path_text)
        if not path.exists() or not path.is_file():
            continue
        try:
            path.unlink()
        except Exception as exc:  # noqa: BLE001
            failed.append({"path": path_text, "error": str(exc)})
    return failed


def _delete_project_dirs(dirs: list[str]) -> list[dict[str, str]]:
    failed: list[dict[str, str]] = []
    for path_text in sorted(set(clean(path) for path in dirs if clean(path)), key=len, reverse=True):
        path = Path(path_text)
        if not path.exists() or not path.is_dir():
            continue
        try:
            shutil.rmtree(path)
        except Exception as exc:  # noqa: BLE001
            failed.append({"path": path_text, "error": str(exc)})
    return failed


def _delete_project_table_rows(conn: sqlite3.Connection, project_id: str, tables: list[str]) -> list[dict[str, str]]:
    failed: list[dict[str, str]] = []
    for table in tables:
        table_name = table.strip('"')
        if not db_table_exists(conn, table_name):
            continue
        try:
            conn.execute(f"DELETE FROM {table} WHERE project_id=?", (project_id,))
        except Exception as exc:  # noqa: BLE001
            failed.append({"table": table_name, "error": str(exc)})
    return failed


def clear_project(agent_root: Path, project_id: str, scope: str, dry_run: bool = False, confirmation: str = "") -> dict[str, Any]:
    project = get_project_detail(agent_root, project_id)
    display_name = project_display_name(project)
    plan = build_project_deletion_plan(agent_root, project_id, scope, purge=False)
    if dry_run or not _confirmation_matches("clear", display_name, confirmation):
        return {"ok": True, "executed": False, "reason": "confirmation_required" if not dry_run else "dry_run", "deletion_plan": plan, "failed_files": [], "failed_tables": []}
    failed_files = _delete_project_files(plan.get("file_paths") or [])
    if failed_files:
        return {"ok": False, "executed": False, "reason": "file_delete_failed", "deletion_plan": plan, "failed_files": failed_files, "failed_tables": []}
    conn = connect(agent_root)
    try:
        failed_tables = _delete_project_table_rows(conn, project_id, _scope_tables(clean(scope) or "all"))
        if failed_tables:
            conn.rollback()
            return {"ok": False, "executed": False, "reason": "table_delete_failed", "deletion_plan": plan, "failed_files": [], "failed_tables": failed_tables}
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "executed": True, "scope": clean(scope) or "all", "display_name": display_name, "deletion_plan": plan, "failed_files": [], "failed_tables": []}


def purge_project(agent_root: Path, project_id: str, dry_run: bool = False, confirmation: str = "", confirmed_by_user: str = "") -> dict[str, Any]:
    project = get_project_detail(agent_root, project_id)
    display_name = project_display_name(project)
    plan = build_project_deletion_plan(agent_root, project_id, "all", purge=True)
    if dry_run or not _confirmation_matches("purge", display_name, confirmation):
        return {"ok": True, "executed": False, "reason": "confirmation_required" if not dry_run else "dry_run", "deletion_plan": plan, "failed_files": [], "failed_tables": []}
    failed_files = _delete_project_files(plan.get("file_paths") or [])
    if failed_files:
        return {"ok": False, "executed": False, "reason": "file_delete_failed", "deletion_plan": plan, "failed_files": failed_files, "failed_tables": []}
    failed_dirs = _delete_project_dirs(plan.get("affected_dirs") or [clean(project.get("root_dir"))])
    if failed_dirs:
        return {"ok": False, "executed": False, "reason": "directory_delete_failed", "deletion_plan": plan, "failed_files": failed_dirs, "failed_tables": []}
    conn = connect(agent_root)
    try:
        failed_tables = _delete_project_table_rows(conn, project_id, _scope_tables("all"))
        if failed_tables:
            conn.rollback()
            return {"ok": False, "executed": False, "reason": "table_delete_failed", "deletion_plan": plan, "failed_files": [], "failed_tables": failed_tables}
        timestamp = now()
        audit_id = stable_id(project_id, "purge", timestamp, length=24)
        conn.execute(
            """
            INSERT INTO project_purge_audit(id, project_id, display_name, purged_at, confirmed_by_user, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (audit_id, project_id, display_name, timestamp, clean(confirmed_by_user) or "user_confirmed", timestamp),
        )
        conn.execute("UPDATE projects SET status='purged', is_active=0, updated_at=? WHERE id=?", (timestamp, project_id))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "executed": True, "display_name": display_name, "deletion_plan": plan, "audit_id": audit_id, "failed_files": [], "failed_tables": []}


def get_project_status(agent_root: Path, project_id: str) -> dict[str, Any]:
    project = get_project_detail(agent_root, project_id)
    conn = connect(agent_root)
    try:
        uploaded_files = db_count(conn, "research_files", "project_id=? AND COALESCE(source,'uploaded')='uploaded'", (project_id,))
        downloaded_pdfs = db_count(conn, "research_files", "project_id=? AND (source='downloaded' OR file_type='pdf' OR detected_document_category='paper')", (project_id,))
        kb_records = (
            db_count(conn, "references", "project_id=?", (project_id,))
            + db_count(conn, "reference_chunks", "project_id=?", (project_id,))
            + db_count(conn, "knowledge_base_entries", "project_id=?", (project_id,))
            + db_count(conn, "rag_queries", "project_id=?", (project_id,))
        )
        project_memory = db_count(conn, "agent_memory_entries", "project_id=?", (project_id,)) + db_count(conn, "memory_entities", "project_id=?", (project_id,))
        task_records = (
            db_count(conn, "literature_search_tasks", "project_id=?", (project_id,))
            + db_count(conn, "agent_tasks", "project_id=?", (project_id,))
            + db_count(conn, "skill_runs", "project_id=?", (project_id,))
            + db_count(conn, "execution_memory", "project_id=?", (project_id,))
        )
        data_contexts = db_count(conn, "data_contexts", "project_id=?", (project_id,))
        file_paths = _project_file_paths(conn, project_id, "purge")
    finally:
        conn.close()
    root_dir = clean(project.get("root_dir"))
    bytes_used = sum(_path_size(Path(path)) for path in file_paths if Path(path).exists())
    if root_dir and Path(root_dir).exists():
        bytes_used = max(bytes_used, _path_size(Path(root_dir)))
    counts = {
        "uploaded_files": uploaded_files,
        "downloaded_pdfs": downloaded_pdfs,
        "kb_records": kb_records,
        "project_memory": project_memory,
        "task_records": task_records,
        "data_contexts": data_contexts,
    }
    return {
        "project_id": project_id,
        "display_name": project_display_name(project),
        "project_name": clean(project.get("project_name")) or project_display_name(project),
        "status": clean(project.get("status")) or "active",
        "is_archived": clean(project.get("status")) == "archived",
        "is_active": bool(project.get("is_active")),
        "counts": counts,
        "storage": {"bytes": bytes_used, "mb": round(bytes_used / (1024 * 1024), 3)},
        "paths": {"root_dir": root_dir, "uploads_dir": clean(project.get("uploads_dir")), "pdf_dir": clean(project.get("pdf_dir")), "kb_dir": clean(project.get("kb_dir"))},
        "updated_at": clean(project.get("updated_at")),
    }


