def update_file_context_experiment(conn: sqlite3.Connection, file_id: str, project_id: str, experiment_id: str, experiment_title: str = "") -> None:
    context_row = row_to_dict(conn.execute("SELECT * FROM data_contexts WHERE file_id=?", (file_id,)).fetchone())
    if not context_row:
        return
    context_row["experiment_id"] = experiment_id
    apply_context_validation(context_row)
    timestamp = now()
    conn.execute(
        """
        UPDATE data_contexts
        SET experiment_id=?, context_status=?, missing_metadata_json=?, confidence=?, updated_at=?
        WHERE file_id=?
        """,
        (
            experiment_id,
            context_row["context_status"],
            json_dumps(context_row["missing_metadata"]),
            context_row["confidence"],
            timestamp,
            file_id,
        ),
    )
    conn.execute(
        "UPDATE research_files SET experiment_id=?, context_status=?, updated_at=? WHERE id=?",
        (experiment_id, context_row["context_status"], timestamp, file_id),
    )
    create_link(conn, project_id, "file", file_id, "belongs_to_experiment", "experiment", experiment_id, 1)


def create_link(
    conn: sqlite3.Connection,
    project_id: str,
    source_type: str,
    source_id: str,
    relation: str,
    target_type: str,
    target_id: str,
    evidence_count: int = 0,
) -> dict[str, Any]:
    timestamp = now()
    link_id = stable_id(project_id, source_type, source_id, relation, target_type, target_id, length=24)
    row = {
        "id": link_id,
        "project_id": project_id,
        "source_type": source_type,
        "source_id": source_id,
        "relation": relation,
        "target_type": target_type,
        "target_id": target_id,
        "evidence_count": evidence_count,
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn.execute(
        """
        INSERT INTO research_links(id, project_id, source_type, source_id, relation, target_type, target_id, evidence_count, created_at, updated_at)
        VALUES (:id, :project_id, :source_type, :source_id, :relation, :target_type, :target_id, :evidence_count, :created_at, :updated_at)
        ON CONFLICT(id) DO UPDATE SET evidence_count=excluded.evidence_count, updated_at=excluded.updated_at
        """,
        row,
    )
    return row


def snippet_around(text: str, term: str, window: int = 120) -> str:
    if not text:
        return ""
    if not term:
        return clean(text[: window * 2])
    match = re.search(re.escape(term), text, re.IGNORECASE)
    if not match:
        return clean(text[: window * 2])
    return clean(text[max(0, match.start() - window) : min(len(text), match.end() + window)])


def insert_memory_entity(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    source_file_id: str | None,
    entity_type: str,
    canonical_name: str,
    aliases: list[str] | None = None,
    source_location: str = "",
    source_text_snippet: str = "",
    source_table_cell: str = "",
    row_number: int | None = None,
    column_name: str = "",
    experiment_id: str = "",
    extracted_entities: dict[str, Any] | None = None,
    confidence: float = 0.7,
    extracted_by: str = "rule",
    trust_level: str = "raw_extracted",
    version: str = "v1",
    human_confirmation_status: str = "unconfirmed",
    workflow_id: str = "",
    skill_run_id: str = "",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if entity_type not in ENTITY_TYPES:
        raise ValueError(f"unsupported entity type: {entity_type}")
    timestamp = now()
    entity_id = stable_id(project_id, source_file_id or "", entity_type, canonical_name, source_location, length=24)
    row = {
        "id": entity_id,
        "entity_type": entity_type,
        "canonical_name": clean(canonical_name),
        "aliases_json": json_dumps(aliases or []),
        "project_id": project_id,
        "experiment_id": clean(experiment_id),
        "source_file_id": source_file_id,
        "source_location": source_location,
        "extracted_entities_json": json_dumps(extracted_entities or {"entity_type": entity_type, "canonical_name": clean(canonical_name)}),
        "confidence": float(confidence),
        "extracted_by": extracted_by,
        "trust_level": trust_level,
        "version": clean(version) or "v1",
        "human_confirmation_status": clean(human_confirmation_status) or "unconfirmed",
        "status": "active",
        "workflow_id": clean(workflow_id),
        "skill_run_id": clean(skill_run_id),
        "metadata_json": json_dumps(metadata or {}),
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn.execute(
        """
        INSERT INTO memory_entities(
          id, entity_type, canonical_name, aliases_json, project_id, experiment_id, source_file_id, source_location,
          extracted_entities_json, confidence, extracted_by, trust_level, version, human_confirmation_status,
          status, workflow_id, skill_run_id, metadata_json, created_at, updated_at
        )
        VALUES (
          :id, :entity_type, :canonical_name, :aliases_json, :project_id, :experiment_id, :source_file_id, :source_location,
          :extracted_entities_json, :confidence, :extracted_by, :trust_level, :version, :human_confirmation_status,
          :status, :workflow_id, :skill_run_id, :metadata_json, :created_at, :updated_at
        )
        ON CONFLICT(id) DO UPDATE SET
          aliases_json=excluded.aliases_json,
          confidence=MAX(memory_entities.confidence, excluded.confidence),
          extracted_entities_json=excluded.extracted_entities_json,
          metadata_json=excluded.metadata_json,
          updated_at=excluded.updated_at
        """,
        row,
    )
    provenance_id = stable_id(entity_id, source_file_id or "", source_text_snippet, row_number or "", column_name, length=24)
    conn.execute(
        """
        INSERT OR IGNORE INTO provenance_records(
          id, memory_item_id, source_file_id, source_type, source_text_snippet, source_table_cell,
          page_number, row_number, column_name, confidence, created_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            provenance_id,
            entity_id,
            source_file_id,
            "file" if source_file_id else "manual",
            source_text_snippet,
            source_table_cell,
            None,
            row_number,
            column_name,
            float(confidence),
            timestamp,
        ),
    )
    if source_file_id:
        create_link(conn, project_id, "file", source_file_id, "supports", "memory_entity", entity_id, 1)
    return row


def csv_rows_from_text(text: str) -> list[dict[str, str]]:
    stripped = text.strip()
    if not stripped:
        return []
    sample = stripped[:4096]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",\t;")
    except csv.Error:
        dialect = csv.excel
    reader = csv.DictReader(stripped.splitlines(), dialect=dialect)
    return [{clean(k): clean(v) for k, v in row.items() if k is not None} for row in reader]


def first_present(row: dict[str, str], candidates: list[str]) -> str:
    lowered = {key.lower(): key for key in row}
    for candidate in candidates:
        if candidate.lower() in lowered:
            return row.get(lowered[candidate.lower()], "")
    for key, value in row.items():
        if any(candidate.lower() in key.lower() for candidate in candidates):
            return value
    return ""


def parse_table_entities(conn: sqlite3.Connection, file_record: dict[str, Any]) -> list[dict[str, Any]]:
    rows = csv_rows_from_text(file_record.get("extracted_text") or "")
    created: list[dict[str, Any]] = []
    if not rows:
        return created
    project_id = file_record["project_id"]
    category = file_record["detected_document_category"]
    assay_name = category.replace(" data", "")
    assay = insert_memory_entity(
        conn,
        project_id=project_id,
        source_file_id=file_record["id"],
        entity_type="assay",
        canonical_name=assay_name,
        source_text_snippet=f"{len(rows)} table rows in {file_record['original_filename']}",
        confidence=0.82,
        metadata={"category": category},
    )
    created.append(assay)

    experiment_title = clean(re.sub(r"[_-]+", " ", Path(file_record["normalized_filename"]).stem))
    experiment_id = stable_id(project_id, experiment_title, category, length=20)
    timestamp = now()
    conn.execute(
        """
        INSERT INTO experiments(
          id, project_id, title, experiment_type, experiment_date, operator, purpose, protocol_id,
          raw_data_file_ids_json, result_summary, conclusion, conclusion_memory_id, status, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET raw_data_file_ids_json=excluded.raw_data_file_ids_json, updated_at=excluded.updated_at
        """,
        (
            experiment_id,
            project_id,
            experiment_title,
            category,
            "",
            "",
            f"Imported from {file_record['original_filename']}",
            "",
            json_dumps([file_record["id"]]),
            "",
            "",
            "",
            "imported",
            timestamp,
            timestamp,
        ),
    )
    create_link(conn, project_id, "experiment", experiment_id, "generated_raw_file", "file", file_record["id"], len(rows))
    create_link(conn, project_id, "file", file_record["id"], "belongs_to_experiment", "experiment", experiment_id, len(rows))
    update_file_context_experiment(conn, file_record["id"], project_id, experiment_id, experiment_title)

    for idx, row in enumerate(rows, start=2):
        sample_id = clean(first_present(row, ["sample_id", "sample", "SampleID", "animal_id"]))
        group_name = clean(first_present(row, ["group", "Group", "treatment_group"]))
        condition = clean(first_present(row, ["condition", "treatment", "Treatment"]))
        dose = clean(first_present(row, ["dose", "Dose", "concentration"]))
        timepoint = clean(first_present(row, ["timepoint", "time", "Time"]))
        well = clean(first_present(row, ["well", "Well", "well_id", "position"]))
        result_value = clean(first_present(row, ["result", "direction", "fold_change", "ct", "delta_ct", "OD450", "value", "intensity"]))
        if sample_id:
            sample_entity = insert_memory_entity(
                conn,
                project_id=project_id,
                source_file_id=file_record["id"],
                entity_type="sample",
                canonical_name=sample_id.upper(),
                aliases=[sample_id],
                source_location=f"row {idx}",
                source_text_snippet=json_dumps(row),
                source_table_cell=sample_id,
                row_number=idx,
                column_name="sample_id",
                confidence=0.86,
                metadata={"normalized_sample_id": sample_id.upper()},
            )
            created.append(sample_entity)
            sample = upsert_sample_record(
                conn,
                project_id=project_id,
                sample_label=sample_id,
                condition=condition,
                group_name=group_name,
                dose=dose,
                timepoint=timepoint,
                metadata={"source_file_id": file_record["id"], "row": row},
            )
            sample_pk = sample["id"]
            create_file_sample_link(
                conn,
                project_id=project_id,
                file_id=file_record["id"],
                sample_pk=sample_pk,
                sample_label=sample_id,
                experiment_id=experiment_id,
                row_number=idx,
                well=well,
                group_name=group_name,
                condition=condition,
                dose=dose,
                timepoint=timepoint,
                assay_type=assay_name,
                raw_row=row,
            )
            flow_id = stable_id(project_id, experiment_id, sample_id.upper(), file_record["id"], idx, length=24)
            conn.execute(
                """
                INSERT OR REPLACE INTO sample_flows(
                  id, sample_id, parent_sample_id, project_id, experiment_id, condition, group_name, dose, timepoint,
                  processing_step, expected_data_output, storage_location, status, created_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    flow_id,
                    sample_id.upper(),
                    "",
                    project_id,
                    experiment_id,
                    condition,
                    group_name,
                    dose,
                    timepoint,
                    assay_name,
                    file_record["original_filename"],
                    "",
                    "data_uploaded",
                    timestamp,
                    timestamp,
                ),
            )
            create_link(conn, project_id, "sample", sample_pk, "used_in_assay", "memory_entity", assay["id"], 1)
            create_link(conn, project_id, "experiment", experiment_id, "used_sample", "sample", sample_pk, 1)
        for entity_type, value, col in [
            ("group", group_name, "group"),
            ("condition", condition, "condition"),
            ("dose", dose, "dose"),
            ("timepoint", timepoint, "timepoint"),
        ]:
            if value:
                created.append(
                    insert_memory_entity(
                        conn,
                        project_id=project_id,
                        source_file_id=file_record["id"],
                        entity_type=entity_type,
                        canonical_name=value,
                        source_location=f"row {idx}",
                        source_text_snippet=json_dumps(row),
                        source_table_cell=value,
                        row_number=idx,
                        column_name=col,
                        confidence=0.8,
                    )
                )
        if result_value:
            direction = infer_result_direction(row, result_value)
            created.append(
                insert_memory_entity(
                    conn,
                    project_id=project_id,
                    source_file_id=file_record["id"],
                    entity_type="result",
                    canonical_name=f"{assay_name} result for {sample_id or group_name or idx}: {direction or result_value}",
                    source_location=f"row {idx}",
                    source_text_snippet=json_dumps(row),
                    source_table_cell=result_value,
                    row_number=idx,
                    column_name="result",
                    confidence=0.76,
                    metadata={"direction": direction, "raw_row": row},
                )
            )
    return created


def infer_result_direction(row: dict[str, str], result_value: str) -> str:
    joined = " ".join(row.values()).lower()
    if any(term in joined for term in ["increase", "increased", "up", "higher"]):
        return "increased"
    if any(term in joined for term in ["decrease", "decreased", "down", "lower"]):
        return "decreased"
    try:
        value = float(result_value)
        if value > 1:
            return "increased"
        if value < 1:
            return "decreased"
    except ValueError:
        pass
    return ""


def extract_entities_from_text(conn: sqlite3.Connection, file_record: dict[str, Any]) -> list[dict[str, Any]]:
    text = file_record.get("extracted_text") or ""
    project_id = file_record["project_id"]
    file_id = file_record["id"]
    created: list[dict[str, Any]] = []
    patterns: list[tuple[str, str, float]] = [
        ("instrument", r"\b(?:qPCR|RT-qPCR|ELISA|LC-MS|LCMS|HPLC|NMR|Western blot|WB|plate reader|thermocycler|flow cytometer|ImageJ)\b", 0.82),
        ("assay", r"\b(?:qPCR|ELISA|Western blot|LC-MS|LCMS|NMR|cell viability|animal study|dose response)\b", 0.78),
        ("reagent", r"\b(?:LPS|IL-6|TNF-?alpha|DMSO|PBS|TRIzol|SYBR Green|antibody|primer|extract|compound [A-Za-z0-9_-]+)\b", 0.7),
        ("dose", r"\b\d+(?:\.\d+)?\s?(?:nM|uM|µM|mM|M|mg/mL|ug/mL|µg/mL|ng/mL|mg/kg|%)\b", 0.82),
        ("timepoint", r"\b\d+(?:\.\d+)?\s?(?:s|min|h|hr|hrs|hour|hours|d|day|days)\b", 0.76),
        ("sample", r"\b(?:S|M|A|NP|CELL|AN)[-_]?\d{2,4}[A-Za-z]?\b", 0.72),
        ("group", r"\b(?:control|vehicle|model|positive control|negative control|treated|treatment group|LPS|blank)\b", 0.68),
    ]
    for entity_type, pattern, confidence in patterns:
        values = []
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            value = clean(match.group(0))
            if value.lower() not in {v.lower() for v in values}:
                values.append(value)
        for value in values[:40]:
            created.append(
                insert_memory_entity(
                    conn,
                    project_id=project_id,
                    source_file_id=file_id,
                    entity_type=entity_type,
                    canonical_name=value.upper() if entity_type == "sample" else value,
                    aliases=[value],
                    source_location="text",
                    source_text_snippet=snippet_around(text, value),
                    confidence=confidence,
                )
            )
    for line_no, line in enumerate(text.splitlines(), start=1):
        lower = line.lower()
        if not clean(line):
            continue
        if any(term in lower for term in ["experiment", "assay", "study"]):
            created.append(
                insert_memory_entity(
                    conn,
                    project_id=project_id,
                    source_file_id=file_id,
                    entity_type="experiment",
                    canonical_name=clean(line[:120]),
                    source_location=f"line {line_no}",
                    source_text_snippet=clean(line),
                    confidence=0.66,
                )
            )
        if any(term in lower for term in ["failed", "failure", "contamination", "no signal", "abnormal"]):
            created.append(
                insert_memory_entity(
                    conn,
                    project_id=project_id,
                    source_file_id=file_id,
                    entity_type="failure reason" if "because" in lower or "due to" in lower else "abnormal observation",
                    canonical_name=clean(line[:140]),
                    source_location=f"line {line_no}",
                    source_text_snippet=clean(line),
                    confidence=0.78,
                )
            )
        if any(term in lower for term in ["conclude", "suggest", "indicate", "showed", "supports"]):
            created.append(
                insert_memory_entity(
                    conn,
                    project_id=project_id,
                    source_file_id=file_id,
                    entity_type="conclusion",
                    canonical_name=clean(line[:140]),
                    source_location=f"line {line_no}",
                    source_text_snippet=clean(line),
                    confidence=0.62,
                    metadata={"requires_human_confirmation": True},
                )
            )
        if any(term in lower for term in ["next step", "todo", "repeat", "follow up"]):
            created.append(
                insert_memory_entity(
                    conn,
                    project_id=project_id,
                    source_file_id=file_id,
                    entity_type="next step",
                    canonical_name=clean(line[:140]),
                    source_location=f"line {line_no}",
                    source_text_snippet=clean(line),
                    confidence=0.72,
                )
            )
    created.extend(parse_table_entities(conn, file_record))
    return created


def run_extraction(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    file_id = clean(payload.get("file_id"))
    if not file_id:
        raise ValueError("file_id is required")
    file_record = read_file_record(agent_root, file_id)
    conn = connect(agent_root)
    created = extract_entities_from_text(conn, file_record)
    if clean(file_record.get("experiment_id")):
        update_file_context_experiment(
            conn,
            file_id,
            file_record["project_id"],
            clean(file_record["experiment_id"]),
            clean(payload.get("experiment_name")) or clean(file_record.get("experiment_id")),
        )
    conn.commit()
    file_record = row_to_dict(conn.execute("SELECT * FROM research_files WHERE id=?", (file_id,)).fetchone()) or file_record
    experiment = row_to_dict(conn.execute("SELECT * FROM experiments WHERE id=?", (clean(file_record.get("experiment_id")),)).fetchone()) if clean(file_record.get("experiment_id")) else None
    samples = rows_to_dicts(conn.execute("SELECT * FROM samples WHERE project_id=? AND id IN (SELECT sample_id FROM file_sample_links WHERE file_id=?)", (file_record["project_id"], file_id)).fetchall())
    conn.close()
    conflicts = detect_conflicts(agent_root, file_record["project_id"])
    if experiment:
        canonical_memory.sync_experiment(agent_root, experiment)
    for sample in samples:
        canonical_memory.sync_sample(agent_root, sample)
    canonical_memory.sync_data_file(agent_root, read_file_record(agent_root, file_id))
    return {"file": read_file_record(agent_root, file_id), "entities": created, "conflicts": conflicts}


def search_memory(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    query = clean(payload.get("query") or payload.get("q"))
    project_id = clean(payload.get("project_id"))
    entity_type = clean(payload.get("entity_type"))
    trust_level = clean(payload.get("trust_level"))
    params: list[Any] = []
    clauses = ["m.status='active'"]
    if project_id:
        clauses.append("m.project_id=?")
        params.append(project_id)
    if entity_type:
        clauses.append("m.entity_type=?")
        params.append(entity_type)
    if trust_level:
        clauses.append("m.trust_level=?")
        params.append(trust_level)
    if query:
        clauses.append("(m.canonical_name LIKE ? OR m.aliases_json LIKE ? OR p.source_text_snippet LIKE ?)")
        like = f"%{query}%"
        params.extend([like, like, like])
    sql = f"""
        SELECT DISTINCT m.*
        FROM memory_entities m
        LEFT JOIN provenance_records p ON p.memory_item_id=m.id
        WHERE {' AND '.join(clauses)}
        ORDER BY m.confidence DESC, m.updated_at DESC
        LIMIT ?
    """
    params.append(int(payload.get("limit") or 100))
    conn = connect(agent_root)
    memory = rows_to_dicts(conn.execute(sql, params).fetchall())
    for item in memory:
        prov_rows = conn.execute(
            """
            SELECT p.*, f.original_filename
            FROM provenance_records p
            LEFT JOIN research_files f ON f.id=p.source_file_id
            WHERE p.memory_item_id=?
            ORDER BY p.confidence DESC
            LIMIT 5
            """,
            (item["id"],),
        ).fetchall()
        item["provenance"] = rows_to_dicts(prov_rows)
    conn.close()
    return {"memory": memory, "query": query}


def update_memory_entity(agent_root: Path, entity_id: str, patch: dict[str, Any]) -> dict[str, Any]:
    allowed = {"canonical_name", "aliases_json", "confidence", "trust_level", "status", "metadata_json", "version", "human_confirmation_status"}
    assignments: list[str] = []
    values: list[Any] = []
    action = clean(patch.get("action"))
    if action == "confirm":
        patch["trust_level"] = clean(patch.get("trust_level")) or "user_confirmed"
        patch["human_confirmation_status"] = "confirmed"
    elif action == "reject":
        patch["trust_level"] = "deprecated"
        patch["status"] = "rejected"
        patch["human_confirmation_status"] = "rejected"
    for key, value in patch.items():
        column = "aliases_json" if key == "aliases" else "metadata_json" if key == "metadata" else key
        if column not in allowed:
            continue
        assignments.append(f"{column}=?")
        values.append(json_dumps(value) if column.endswith("_json") else value)
    if not assignments:
        raise ValueError("no supported memory fields to update")
    assignments.append("updated_at=?")
    values.extend([now(), entity_id])
    conn = connect(agent_root)
    conn.execute(f"UPDATE memory_entities SET {', '.join(assignments)} WHERE id=?", values)
    row = conn.execute("SELECT * FROM memory_entities WHERE id=?", (entity_id,)).fetchone()
    if not row:
        conn.close()
        raise KeyError("memory entity not found")
    conn.commit()
    conn.close()
    return row_to_dict(row) or {}


def merge_memory_entities(agent_root: Path, target_id: str, source_ids: list[str]) -> dict[str, Any]:
    conn = connect(agent_root)
    target = row_to_dict(conn.execute("SELECT * FROM memory_entities WHERE id=?", (target_id,)).fetchone())
    if not target:
        conn.close()
        raise KeyError("target memory entity not found")
    aliases = list(dict.fromkeys(as_list(target.get("aliases")) + [target["canonical_name"]]))
    for source_id in source_ids:
        source = row_to_dict(conn.execute("SELECT * FROM memory_entities WHERE id=?", (source_id,)).fetchone())
        if not source:
            continue
        aliases.extend(as_list(source.get("aliases")) + [source["canonical_name"]])
        conn.execute("UPDATE provenance_records SET memory_item_id=? WHERE memory_item_id=?", (target_id, source_id))
        conn.execute("UPDATE memory_entities SET status='merged', trust_level='deprecated', updated_at=? WHERE id=?", (now(), source_id))
    aliases = sorted(set(clean(alias) for alias in aliases if clean(alias)))
    conn.execute(
        "UPDATE memory_entities SET aliases_json=?, confidence=MAX(confidence, ?), updated_at=? WHERE id=?",
        (json_dumps(aliases), 0.9, now(), target_id),
    )
    conn.commit()
    row = conn.execute("SELECT * FROM memory_entities WHERE id=?", (target_id,)).fetchone()
    conn.close()
    return row_to_dict(row) or {}


def detect_conflicts(agent_root: Path, project_id: str) -> list[dict[str, Any]]:
    conn = connect(agent_root)
    created: list[dict[str, Any]] = []
    timestamp = now()

    def insert_conflict(conflict_type: str, involved: list[dict[str, Any]], description: str, severity: str, suggestion: str) -> None:
        conflict_id = stable_id(project_id, conflict_type, description, json_dumps(involved), length=24)
        conn.execute(
            """
            INSERT INTO conflict_records(
              id, project_id, conflict_type, involved_items_json, description, severity,
              suggested_resolution, status, resolved_by, resolved_at, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, 'unresolved', '', '', ?, ?)
            ON CONFLICT(id) DO UPDATE SET
              description=excluded.description,
              severity=excluded.severity,
              suggested_resolution=excluded.suggested_resolution,
              updated_at=excluded.updated_at
            """,
            (conflict_id, project_id, conflict_type, json_dumps(involved), description, severity, suggestion, timestamp, timestamp),
        )
        created.append(
            {
                "id": conflict_id,
                "project_id": project_id,
                "conflict_type": conflict_type,
                "involved_items": involved,
                "description": description,
                "severity": severity,
                "suggested_resolution": suggestion,
                "status": "unresolved",
            }
        )

    sample_rows = conn.execute(
        """
        SELECT sample_id, GROUP_CONCAT(DISTINCT condition) AS conditions, GROUP_CONCAT(DISTINCT group_name) AS groups, COUNT(*) AS count
        FROM sample_flows
        WHERE project_id=?
        GROUP BY sample_id
        HAVING COUNT(DISTINCT COALESCE(condition,'')) > 1
        """,
        (project_id,),
    ).fetchall()
    for row in sample_rows:
        insert_conflict(
            "same sample ID with different treatment conditions",
            [{"type": "sample", "id": row["sample_id"]}],
            f"Sample {row['sample_id']} appears with multiple conditions: {row['conditions']}.",
            "high",
            "Inspect source rows, confirm whether the sample ID should be split into unique aliquots or one condition is incorrect.",
        )

    duplicate_rows = conn.execute(
        """
        SELECT checksum, GROUP_CONCAT(id) AS ids, GROUP_CONCAT(original_filename) AS filenames, COUNT(*) AS count
        FROM research_files
        WHERE project_id=? AND checksum!=''
        GROUP BY checksum
        HAVING COUNT(*) > 1
        """,
        (project_id,),
    ).fetchall()
    for row in duplicate_rows:
        filenames = row["filenames"] or ""
        insert_conflict(
            "duplicate files with different names",
            [{"type": "file", "id": file_id} for file_id in (row["ids"] or "").split(",")],
            f"These files have the same checksum but different names: {filenames}.",
            "medium",
            "Keep all raw files, choose a canonical filename, and mark the others as duplicates rather than deleting them.",
        )

    version_rows = conn.execute(
        """
        SELECT version_group_id, GROUP_CONCAT(id) AS ids, GROUP_CONCAT(original_filename) AS filenames, COUNT(DISTINCT checksum) AS checksum_count
        FROM research_files
        WHERE project_id=?
        GROUP BY version_group_id
        HAVING COUNT(*) > 1 AND COUNT(DISTINCT checksum) > 1
        """,
        (project_id,),
    ).fetchall()
    for row in version_rows:
        insert_conflict(
            "same file with different versions",
            [{"type": "file", "id": file_id} for file_id in (row["ids"] or "").split(",")],
            f"Possible file versions have different content: {row['filenames']}.",
            "low",
            "Confirm which version supports each result and keep version links explicit.",
        )

    files = rows_to_dicts(conn.execute("SELECT * FROM research_files WHERE project_id=?", (project_id,)).fetchall())
    for file_record in files:
        filename_times = set(re.findall(r"\b\d+(?:h|hr|hrs|d|day|days)\b", file_record["original_filename"], flags=re.IGNORECASE))
        text_times = set(re.findall(r"\b\d+(?:\.\d+)?\s?(?:h|hr|hrs|hour|hours|d|day|days)\b", file_record.get("extracted_text") or "", flags=re.IGNORECASE))
        normalized_text_times = {re.sub(r"\s+", "", item.lower()).replace("hours", "h").replace("hour", "h").replace("hrs", "h").replace("hr", "h").replace("days", "d").replace("day", "d") for item in text_times}
        normalized_file_times = {item.lower().replace("hrs", "h").replace("hr", "h").replace("days", "d").replace("day", "d") for item in filename_times}
        if normalized_file_times and normalized_text_times and not normalized_file_times.intersection(normalized_text_times):
            insert_conflict(
                "filename says one timepoint but extracted text says another",
                [{"type": "file", "id": file_record["id"]}],
                f"Filename timepoints {sorted(normalized_file_times)} differ from extracted text timepoints {sorted(normalized_text_times)[:5]}.",
                "medium",
                "Check whether the filename or file content timepoint is authoritative before linking samples.",
            )

    conn.commit()
    rows = rows_to_dicts(
        conn.execute(
            "SELECT * FROM conflict_records WHERE project_id=? AND status='unresolved' ORDER BY severity DESC, updated_at DESC",
            (project_id,),
        ).fetchall()
    )
    conn.close()
    return rows or created


def list_conflicts(agent_root: Path, project_id: str = "", status: str = "") -> list[dict[str, Any]]:
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    if status:
        clauses.append("status=?")
        params.append(status)
    conn = connect(agent_root)
    rows = conn.execute(f"SELECT * FROM conflict_records WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC", params).fetchall()
    conn.close()
    return rows_to_dicts(rows)


def resolve_conflict(agent_root: Path, conflict_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    status = clean(payload.get("status")) or "resolved"
    if status not in {"unresolved", "accepted", "dismissed", "resolved"}:
        raise ValueError("unsupported conflict status")
    conn = connect(agent_root)
    conn.execute(
        "UPDATE conflict_records SET status=?, resolved_by=?, resolved_at=?, updated_at=? WHERE id=?",
        (status, clean(payload.get("resolved_by")) or "local_user", now(), now(), conflict_id),
    )
    row = conn.execute("SELECT * FROM conflict_records WHERE id=?", (conflict_id,)).fetchone()
    if not row:
        conn.close()
        raise KeyError("conflict not found")
    conn.commit()
    conn.close()
    return row_to_dict(row) or {}


class LLMAdapter:
    def __init__(self, prompt_language: str = "zh", prompt_policy: str = "backend_llm_guardrails") -> None:
        self.provider = self._resolve_provider()
        self.api_key = self._resolve_api_key()
        self.base_url = self._resolve_base_url()
        self.model = self._resolve_model()
        self.prompt_language = default_prompt_language({"prompt_language": prompt_language})
        self.prompt_policy = normalize_prompt_policy(prompt_policy)

    def _resolve_provider(self) -> str:
        explicit = os.environ.get("LLM_PROVIDER", "").strip()
        if explicit:
            return explicit
        if os.environ.get("MINIMAX_API_KEY"):
            return "minimax"
        if os.environ.get("OPENAI_API_KEY"):
            return "openai-compatible"
        return DEFAULT_SERVER_LLM_PROVIDER

    def _resolve_api_key(self) -> str:
        if self.provider == "minimax":
            return os.environ.get("MINIMAX_API_KEY") or os.environ.get("LLM_API_KEY") or DEFAULT_SERVER_LLM_API_KEY
        if self.provider in {"openai", "openai-compatible", "custom", "local"}:
            return os.environ.get("OPENAI_API_KEY") or os.environ.get("LLM_API_KEY") or DEFAULT_SERVER_LLM_API_KEY
        return os.environ.get("LLM_API_KEY") or DEFAULT_SERVER_LLM_API_KEY

    def _resolve_base_url(self) -> str:
        if self.provider == "minimax":
            return os.environ.get("MINIMAX_BASE_URL") or os.environ.get("LLM_BASE_URL") or "https://api.minimax.chat/v1"
        if self.provider in {"openai", "openai-compatible"}:
            return os.environ.get("OPENAI_BASE_URL") or os.environ.get("LLM_BASE_URL") or "https://api.openai.com/v1"
        return os.environ.get("LLM_BASE_URL") or DEFAULT_SERVER_LLM_BASE_URL

    def _resolve_model(self) -> str:
        if self.provider == "minimax":
            return os.environ.get("MINIMAX_MODEL") or os.environ.get("LLM_MODEL") or DEFAULT_SERVER_LLM_MODEL
        if self.provider in {"openai", "openai-compatible"}:
            return os.environ.get("OPENAI_MODEL") or os.environ.get("LLM_MODEL") or DEFAULT_SERVER_LLM_MODEL
        return os.environ.get("LLM_MODEL") or DEFAULT_SERVER_LLM_MODEL

    @property
    def mode(self) -> str:
        if self.provider == "mock" or (not self.api_key and self.provider in {"minimax", "openai", "openai-compatible", "anthropic", "custom", "local"}):
            return "mock"
        return self.provider

    def policy_prompt(self, prompt_language: str = "", prompt_policy: str = "") -> dict[str, Any]:
        language = default_prompt_language({"prompt_language": prompt_language or self.prompt_language})
        policy = normalize_prompt_policy(prompt_policy or self.prompt_policy)
        composed = compose_researchos_prompt(language, policy)
        return composed

    def generate_json(
        self,
        prompt: str,
        schema_name: str,
        prompt_policy: str = "",
        prompt_language: str = "",
        *,
        agent_root: Path | str | None = None,
        project_id: str = "",
        user_message: str = "",
        task_type: str = "",
        skill_name: str = "",
        skill_id: str = "",
        agent_type: str = "",
        workflow_step_id: str = "",
        file_id: str = "",
        file_category: str = "",
        prompt_context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        use_router = any(clean(value) for value in [agent_root, project_id, user_message, task_type, skill_name, skill_id, agent_type, workflow_step_id, file_id, file_category]) or bool(prompt_context)
        conn: sqlite3.Connection | None = None
        if use_router:
            if agent_root:
                conn = connect(Path(agent_root))
            runtime_prompt = prompt_router.compose_runtime_prompt(
                conn,
                language=prompt_language or self.prompt_language,
                policy=prompt_policy or None,
                user_message=user_message or prompt,
                task_type=task_type,
                skill_name=skill_name,
                skill_id=skill_id,
                agent_type=agent_type,
                workflow_step_id=workflow_step_id,
                file_id=file_id,
                file_category=file_category,
                project_id=project_id,
                prompt_context=prompt_context or {},
                output_schema={"schema_name": schema_name},
            )
            if conn:
                conn.close()
            system_prompt = runtime_prompt["system_prompt"]
            policy = runtime_prompt["prompt_policy"]
            language = runtime_prompt["prompt_language"]
            prompt_files = runtime_prompt.get("prompt_files", [])
            task_type_used = runtime_prompt.get("task_type", "")
            resolved_skill_name = runtime_prompt.get("resolved_skill_name", "")
            skill_prompt_source = runtime_prompt.get("skill_prompt_source", "")
            warnings = runtime_prompt.get("warnings", [])
        else:
            composed = self.policy_prompt(prompt_language=prompt_language, prompt_policy=prompt_policy)
            system_prompt = composed["prompt"]
            policy = composed["prompt_policy"]
            language = composed["prompt_language"]
            prompt_files = composed.get("prompt_files", [])
            task_type_used = ""
            resolved_skill_name = ""
            skill_prompt_source = "researchos_agent_prompt"
            warnings = []
        prompt_meta = {
            "_prompt_policy": policy,
            "_prompt_language": language,
            "_prompt_files": prompt_files,
            "_task_type": task_type_used,
            "_resolved_skill_name": resolved_skill_name,
            "_skill_prompt_source": skill_prompt_source,
            "_system_prompt_preview": system_prompt[:500],
        }
        if warnings:
            prompt_meta["_prompt_warnings"] = warnings
        force_mock = clean(schema_name).endswith("_test")
        if self.mode == "mock" or force_mock:
            return {
                "_mock": True,
                "schema_name": schema_name,
                "prompt_language": language,
                "prompt_policy": policy,
                "prompt_files": prompt_files,
                "system_prompt_preview": system_prompt[:500],
                "raw_prompt_preview": prompt[:500],
                **prompt_meta,
            }
        if self.provider in {"minimax", "openai", "openai-compatible", "custom", "local"}:
            if not self.base_url and self.provider == "local":
                raise ValueError("LLM_BASE_URL is required for local model endpoint mode")
            content = self.chat_text(prompt, system_prompt=system_prompt)
            try:
                parsed = json.loads(content)
                parsed["_mock"] = False
                parsed.update(prompt_meta)
                return parsed
            except json.JSONDecodeError:
                return {
                    "_mock": False,
                    "_parse_warning": "LLM output was not valid JSON",
                    **prompt_meta,
                    "raw_output": content,
                }
        return {
            "_mock": True,
            "schema_name": schema_name,
            "prompt_language": language,
            "prompt_policy": policy,
            "prompt_files": prompt_files,
            "system_prompt_preview": system_prompt[:500],
            "raw_prompt_preview": prompt[:500],
            **prompt_meta,
        }

    def chat_text(self, prompt: str, system_prompt: str = "", temperature: float = 0.1) -> str:
        sentinel_enabled = os.environ.get("TEST_LLM_SENTINEL", "").strip().lower() in {"1", "true", "yes", "on"}
        if self.provider == "mock" or sentinel_enabled:
            return LLM_SENTINEL_OUTPUT
        if self.mode == "mock":
            return "needs_llm_configuration: backend LLM provider is configured but no API key is available."
        if self.provider in {"minimax", "openai", "openai-compatible", "custom", "local"}:
            url = self.base_url.rstrip("/") or "https://api.openai.com/v1"
            last_error = ""
            for attempt in range(4):
                request = urllib.request.Request(
                    f"{url}/chat/completions",
                    data=json_dumps(
                        {
                            "model": self.model,
                            "messages": [
                                {"role": "system", "content": system_prompt or self.policy_prompt()["prompt"]},
                                {"role": "user", "content": prompt},
                            ],
                            "temperature": temperature,
                        }
                    ).encode("utf-8"),
                    headers={
                        "Content-Type": "application/json",
                        "Accept": "application/json",
                        "Connection": "close",
                        "Authorization": f"Bearer {self.api_key}",
                    },
                    method="POST",
                )
                try:
                    with urllib.request.urlopen(request, timeout=180) as response:
                        raw = response.read()
                        if not raw:
                            raise http.client.IncompleteRead(b"")
                        payload = json.loads(raw.decode("utf-8"))
                    return clean(payload.get("choices", [{}])[0].get("message", {}).get("content", ""))
                except (http.client.IncompleteRead, http.client.RemoteDisconnected, urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
                    last_error = str(exc)
                    if attempt < 3:
                        time.sleep(0.8 * (attempt + 1))
                        continue
                    return (
                        "后端模型连接暂时中断，ResearchOS 已保留本地任务计划和可执行工具入口。\n\n"
                        f"模型连接错误：{last_error}\n\n"
                        "你可以先运行文献采集、知识库构建或项目记忆检索；稍后重试 Agent 对话。"
                    )
        return "Unsupported LLM provider."


def parse_protocol_text(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    text = clean(payload.get("text") or payload.get("paper_text") or payload.get("methods_text"))
    if not text:
        raise ValueError("text is required")
    project_id = clean(payload.get("project_id"))
    source_file_id = clean(payload.get("created_from_file_id") or payload.get("source_file_id"))
    lower = text.lower()
    protocol_type = clean(payload.get("protocol_type"))
    if not protocol_type:
        protocol_type = "qPCR" if "qpcr" in lower or "ct" in lower else "ELISA" if "elisa" in lower else "LC-MS" if "lc-ms" in lower or "m/z" in lower else "general wet-lab protocol"
    title = clean(payload.get("title")) or f"{protocol_type} structured protocol"
    adapter = LLMAdapter(
        prompt_language=clean(payload.get("prompt_language")) or "zh",
        prompt_policy=clean(payload.get("prompt_policy")) or "protocol_extraction",
    )
    llm_hint = adapter.generate_json(
        "Convert this methods text into structured wet-lab protocol JSON. Return JSON only.\n\n" + text[:4000],
        "structured_protocol",
        prompt_policy="protocol_extraction",
        agent_root=agent_root,
        project_id=project_id,
        user_message=clean(payload.get("user_message")) or "Convert methods text into a structured wet-lab protocol.",
        task_type=clean(payload.get("task_type")) or ("kit_manual_parsing" if "kit" in lower or "manual" in lower else "protocol_extraction"),
        skill_name=clean(payload.get("skill_name")) or ("KitManualParserSkill" if "kit" in lower or "manual" in lower else "PaperToProtocolSkill"),
        skill_id=clean(payload.get("skill_id")),
        workflow_step_id=clean(payload.get("workflow_step_id")),
        file_id=source_file_id,
        file_category=clean(payload.get("file_category")) or clean(payload.get("category")) or "protocol methods",
        prompt_context={"protocol_type": protocol_type, "source_file_id": source_file_id},
    )
    steps = deterministic_protocol_steps(text, protocol_type)
    reagents = sorted(set(re.findall(r"\b(?:LPS|PBS|DMSO|TRIzol|SYBR Green|antibody|primer|ELISA kit|serum|plasma|RNA|cDNA|extract|compound [A-Za-z0-9_-]+)\b", text, re.IGNORECASE)))
    equipment = sorted(set(re.findall(r"\b(?:qPCR|thermocycler|plate reader|centrifuge|LC-MS|HPLC|NMR|western blot|gel imager|biosafety cabinet)\b", text, re.IGNORECASE)))
    controls = [snippet_around(text, term) for term in ["control", "vehicle", "blank", "positive control", "negative control"] if re.search(term, text, re.IGNORECASE)]
    variables = {
        "concentrations": re.findall(r"\b\d+(?:\.\d+)?\s?(?:nM|uM|µM|mM|M|mg/mL|ug/mL|µg/mL|ng/mL|mg/kg|%)\b", text),
        "timepoints": re.findall(r"\b\d+(?:\.\d+)?\s?(?:min|h|hr|hour|hours|day|days|d)\b", text, re.IGNORECASE),
        "temperatures": re.findall(r"\b\d+(?:\.\d+)?\s?(?:°C|C)\b", text),
    }
    kit_context = find_relevant_kit_templates(agent_root, project_id, protocol_type)
    kit_reagents = sorted({str(item) for kit in kit_context for item in as_list(kit.get("parsed_reagents"))})
    kit_qc = sorted({str(item) for kit in kit_context for item in as_list(kit.get("parsed_qc_rules"))})
    default_sample_plan = build_default_sample_plan(protocol_type)
    protocol = {
        "id": stable_id(project_id, title, text[:200], length=20),
        "project_id": project_id,
        "title": title,
        "protocol_type": protocol_type,
        "objective": "Convert human-readable wet-lab plans into editable, human-executable workflow tasks.",
        "assay_type": protocol_type,
        "purpose": "Structured from pasted methods text; human confirmation is required before execution.",
        "biological_or_material_system": infer_system(text),
        "input_materials": extract_input_materials(text),
        "reagents": sorted(set(reagents + kit_reagents)),
        "equipment": equipment,
        "safety_notes": infer_safety_notes(text),
        "steps": steps,
        "sample_numbering": default_sample_plan,
        "experimental_groups": [item.get("group", "") for item in default_sample_plan],
        "dose_design": variables["concentrations"] or ["TBD by scientist"],
        "timeline": variables["timepoints"] or [step.get("duration", "") for step in steps if step.get("duration")],
        "instrument_parameters": [{"instrument": item, "parameters": "Confirm against local instrument method"} for item in equipment],
        "data_naming_rules": "PROJECT_EXPERIMENT_SAMPLE_GROUP_DOSE_TIMEPOINT_ASSAY_DATE_VERSION",
        "expected_output_files": infer_data_outputs(protocol_type),
        "required_human_confirmation_points": [
            "Confirm protocol conversion before execution",
            "Confirm sample table before wet-lab work",
            "Confirm conclusions before memory writeback",
        ],
        "variables": variables,
        "controls": controls,
        "sample_plan": default_sample_plan,
        "data_outputs": infer_data_outputs(protocol_type),
        "quality_control_points": sorted(set(["Confirm sample identity before assay", "Record raw data file path", "Do not overwrite raw instrument exports"] + kit_qc)),
        "expected_results": ["Expected result descriptions are suggestions and must be supported by uploaded data"],
        "failure_modes": infer_failure_modes(protocol_type),
        "kit_template_context": kit_context,
        "created_from_file_id": source_file_id,
        "extraction_mode": "rule+mock" if llm_hint.get("_mock") else "llm",
        "validation_warning": "Mock/demo extraction used because no configured LLM API returned validated JSON." if llm_hint.get("_mock") else clean(llm_hint.get("_parse_warning")),
    }
    return {
        "protocol": protocol,
        "llm_adapter": {
            "provider": adapter.provider,
            "mode": adapter.mode,
            "model": adapter.model,
            "prompt_language": llm_hint.get("prompt_language") or llm_hint.get("_prompt_language") or adapter.prompt_language,
            "prompt_policy": llm_hint.get("prompt_policy") or llm_hint.get("_prompt_policy") or adapter.prompt_policy,
            "prompt_files": llm_hint.get("prompt_files") or llm_hint.get("_prompt_files") or [],
            "task_type": llm_hint.get("_task_type"),
            "resolved_skill_name": llm_hint.get("_resolved_skill_name"),
            "skill_prompt_source": llm_hint.get("_skill_prompt_source"),
            "system_prompt_preview": llm_hint.get("_system_prompt_preview") or llm_hint.get("system_prompt_preview"),
        },
    }


def deterministic_protocol_steps(text: str, protocol_type: str) -> list[dict[str, Any]]:
    sentences = [clean(part) for part in re.split(r"(?<=[.;])\s+|\n+", text) if clean(part)]
    action_sentences = [s for s in sentences if re.search(r"\b(seed|treat|incubat|wash|extract|measure|run|centrifuge|mix|add|collect|analy[sz]e|amplif|denature|block|transfer)\b", s, re.IGNORECASE)]
    if not action_sentences:
        action_sentences = sentences[:6]
    steps = []
    for idx, sentence in enumerate(action_sentences[:12], start=1):
        steps.append(
            {
                "step_number": idx,
                "title": sentence[:60],
                "action": sentence,
                "duration": first_match(sentence, r"\b\d+(?:\.\d+)?\s?(?:min|h|hr|hour|hours|day|days|d)\b"),
                "temperature": first_match(sentence, r"\b\d+(?:\.\d+)?\s?(?:°C|C)\b"),
                "volume": first_match(sentence, r"\b\d+(?:\.\d+)?\s?(?:uL|µL|mL|L)\b"),
                "concentration": first_match(sentence, r"\b\d+(?:\.\d+)?\s?(?:nM|uM|µM|mM|M|mg/mL|ug/mL|µg/mL|ng/mL|%)\b"),
                "equipment": first_match(sentence, r"\b(?:qPCR|thermocycler|plate reader|centrifuge|LC-MS|HPLC|NMR|western blot|gel imager)\b"),
                "input_sample": "previous step sample" if idx > 1 else "starting sample",
                "output_sample": f"step_{idx}_output",
                "parameters": {},
                "notes": "Verify against original protocol before execution.",
                "risk_points": ["Ambiguous parameter should be confirmed"] if "room temperature" in sentence.lower() else [],
                "QC_points": ["Record exact time and operator"] if idx == 1 else [],
            }
        )
    if not steps:
        steps.append(
            {
                "step_number": 1,
                "title": f"Execute {protocol_type}",
                "action": "Protocol text was too short; create a human-reviewed step list before use.",
                "duration": "",
                "temperature": "",
                "volume": "",
                "concentration": "",
                "equipment": "",
                "input_sample": "starting sample",
                "output_sample": "processed sample",
                "parameters": {},
                "notes": "Mock/demo extraction.",
                "risk_points": ["Incomplete protocol"],
                "QC_points": ["Human review required"],
            }
        )
    return steps


def first_match(text: str, pattern: str) -> str:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    return clean(match.group(0)) if match else ""


def infer_system(text: str) -> str:
    matches = re.findall(r"\b(?:RAW264\.7|HEK293T?|HeLa|HepG2|A549|HUVEC|mouse|mice|rat|serum|plasma|natural product extract|nanoparticle)\b", text, re.IGNORECASE)
    return ", ".join(sorted(set(matches))) or "general biological/material sample"


def extract_input_materials(text: str) -> list[str]:
    values = re.findall(r"\b(?:cells?|serum|plasma|tissue|RNA|cDNA|protein lysate|extract|fraction|compound|nanoparticle|material sample|mouse|mice|rat)\b", text, re.IGNORECASE)
    return sorted(set(values)) or ["research sample"]


def infer_safety_notes(text: str) -> list[str]:
    notes = ["Follow institutional biosafety and chemical hygiene SOPs."]
    lower = text.lower()
    if any(term in lower for term in ["animal", "mouse", "mice", "rat"]):
        notes.append("Animal work requires approved protocol review before execution.")
    if any(term in lower for term in ["human", "patient", "clinical"]):
        notes.append("Human-derived samples require ethics and privacy review.")
    if any(term in lower for term in ["toxic", "chloroform", "trizol", "flammable"]):
        notes.append("Confirm hazardous reagent handling, PPE, and waste disposal.")
    return notes


def build_default_sample_plan(protocol_type: str) -> list[dict[str, str]]:
    return [
        {"sample_prefix": "S", "group": "Control", "dose": "vehicle", "timepoint": "baseline", "replicates": "3"},
        {"sample_prefix": "S", "group": "Treatment", "dose": "TBD", "timepoint": "TBD", "replicates": "3"},
        {"sample_prefix": "S", "group": "Positive control", "dose": "TBD", "timepoint": "TBD", "replicates": "3"},
    ]


def infer_data_outputs(protocol_type: str) -> list[str]:
    lower = protocol_type.lower()
    if "qpcr" in lower:
        return ["raw Ct table", "delta Ct table", "fold-change table", "QC notes"]
    if "elisa" in lower:
        return ["raw OD450 table", "standard curve", "concentration table", "QC notes"]
    if "lc-ms" in lower:
        return ["raw instrument export", "feature table", "sample metadata table", "QC feature summary"]
    return ["raw data file", "processed data table", "analysis notes"]


def infer_failure_modes(protocol_type: str) -> list[str]:
    lower = protocol_type.lower()
    if "qpcr" in lower:
        return ["primer-dimer or non-specific amplification", "RNA degradation", "sample ID mismatch", "missing no-template control"]
    if "elisa" in lower:
        return ["standard curve failure", "edge effects", "plate washing inconsistency", "sample out of range"]
    if "western" in lower or "wb" in lower:
        return ["uneven transfer", "saturated signal", "loading control inconsistency", "antibody lot variation"]
    return ["missing control", "ambiguous sample mapping", "instrument export not linked", "unrecorded deviation"]


def store_protocol(agent_root: Path, protocol_payload: dict[str, Any]) -> dict[str, Any]:
    protocol = protocol_payload.get("protocol") if "protocol" in protocol_payload else protocol_payload
    project_id = clean(protocol.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    protocol_id = clean(protocol.get("id")) or stable_id(project_id, protocol.get("title"), now(), length=20)
    timestamp = now()
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO protocols(
          id, project_id, title, protocol_type, objective, assay_type, purpose, biological_or_material_system, input_materials_json,
          reagents_json, equipment_json, safety_notes_json, sample_numbering_json, experimental_groups_json,
          dose_design_json, timeline_json, instrument_parameters_json, data_naming_rules_json,
          expected_output_files_json, required_human_confirmation_points_json, variables_json, controls_json,
          sample_plan_json, data_outputs_json, quality_control_points_json, expected_results_json, failure_modes_json,
          created_from_file_id, extraction_mode, validation_warning, skill_run_id, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          title=excluded.title,
          protocol_type=excluded.protocol_type,
          objective=excluded.objective,
          assay_type=excluded.assay_type,
          purpose=excluded.purpose,
          biological_or_material_system=excluded.biological_or_material_system,
          input_materials_json=excluded.input_materials_json,
          reagents_json=excluded.reagents_json,
          equipment_json=excluded.equipment_json,
          safety_notes_json=excluded.safety_notes_json,
          sample_numbering_json=excluded.sample_numbering_json,
          experimental_groups_json=excluded.experimental_groups_json,
          dose_design_json=excluded.dose_design_json,
          timeline_json=excluded.timeline_json,
          instrument_parameters_json=excluded.instrument_parameters_json,
          data_naming_rules_json=excluded.data_naming_rules_json,
          expected_output_files_json=excluded.expected_output_files_json,
          required_human_confirmation_points_json=excluded.required_human_confirmation_points_json,
          variables_json=excluded.variables_json,
          controls_json=excluded.controls_json,
          sample_plan_json=excluded.sample_plan_json,
          data_outputs_json=excluded.data_outputs_json,
          quality_control_points_json=excluded.quality_control_points_json,
          expected_results_json=excluded.expected_results_json,
          failure_modes_json=excluded.failure_modes_json,
          validation_warning=excluded.validation_warning,
          skill_run_id=COALESCE(NULLIF(excluded.skill_run_id,''), protocols.skill_run_id),
          updated_at=excluded.updated_at
        """,
        (
            protocol_id,
            project_id,
            clean(protocol.get("title")),
            clean(protocol.get("protocol_type")),
            clean(protocol.get("objective")),
            clean(protocol.get("assay_type") or protocol.get("protocol_type")),
            clean(protocol.get("purpose")),
            clean(protocol.get("biological_or_material_system")),
            json_dumps(protocol.get("input_materials") or []),
            json_dumps(protocol.get("reagents") or []),
            json_dumps(protocol.get("equipment") or []),
            json_dumps(protocol.get("safety_notes") or []),
            json_dumps(protocol.get("sample_numbering") or []),
            json_dumps(protocol.get("experimental_groups") or []),
            json_dumps(protocol.get("dose_design") or []),
            json_dumps(protocol.get("timeline") or []),
            json_dumps(protocol.get("instrument_parameters") or []),
            json_dumps(protocol.get("data_naming_rules") or ""),
            json_dumps(protocol.get("expected_output_files") or []),
            json_dumps(protocol.get("required_human_confirmation_points") or []),
            json_dumps(protocol.get("variables") or {}),
            json_dumps(protocol.get("controls") or []),
            json_dumps(protocol.get("sample_plan") or []),
            json_dumps(protocol.get("data_outputs") or []),
            json_dumps(protocol.get("quality_control_points") or []),
            json_dumps(protocol.get("expected_results") or []),
            json_dumps(protocol.get("failure_modes") or []),
            clean(protocol.get("created_from_file_id")),
            clean(protocol.get("extraction_mode")),
            clean(protocol.get("validation_warning")),
            clean(protocol.get("skill_run_id")),
            timestamp,
            timestamp,
        ),
    )
    conn.execute("DELETE FROM protocol_steps WHERE protocol_id=?", (protocol_id,))
    for step in protocol.get("steps") or []:
        step_id = stable_id(protocol_id, step.get("step_number"), step.get("action"), length=24)
        conn.execute(
            """
            INSERT INTO protocol_steps(
              id, protocol_id, step_number, title, action, duration, temperature, volume, concentration,
              equipment, input_sample, output_sample, parameters_json, notes, risk_points_json, QC_points_json,
              created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                step_id,
                protocol_id,
                int(step.get("step_number") or 0),
                clean(step.get("title")),
                clean(step.get("action")),
                clean(step.get("duration")),
                clean(step.get("temperature")),
                clean(step.get("volume")),
                clean(step.get("concentration")),
                clean(step.get("equipment")),
                clean(step.get("input_sample")),
                clean(step.get("output_sample")),
                json_dumps(step.get("parameters") or {}),
                clean(step.get("notes")),
                json_dumps(step.get("risk_points") or []),
                json_dumps(step.get("QC_points") or step.get("qc_points") or []),
                timestamp,
                timestamp,
            ),
        )
    if protocol.get("created_from_file_id"):
        create_link(conn, project_id, "protocol", protocol_id, "created_from_file", "file", protocol["created_from_file_id"], 1)
    if protocol.get("skill_run_id"):
        create_link(conn, project_id, "skill_run", clean(protocol["skill_run_id"]), "generated", "protocol", protocol_id, 1)
    row = row_to_dict(conn.execute("SELECT * FROM protocols WHERE id=?", (protocol_id,)).fetchone()) or {}
    steps = rows_to_dicts(conn.execute("SELECT * FROM protocol_steps WHERE protocol_id=? ORDER BY step_number", (protocol_id,)).fetchall())
    upsert_artifact_record(
        conn,
        {
            "project_id": project_id,
            "task_id": clean(protocol.get("task_id")),
            "skill_run_id": clean(protocol.get("skill_run_id")),
            "source_skill_run_id": clean(protocol.get("skill_run_id")),
            "type": "protocol",
            "title": clean(row.get("title")) or clean(protocol.get("title")) or "Protocol",
            "source_object_type": "protocol",
            "source_object_id": protocol_id,
            "status": "created",
            "metadata": {
                "protocol_type": row.get("protocol_type"),
                "assay_type": row.get("assay_type"),
                "created_from_file_id": row.get("created_from_file_id"),
                "step_count": len(steps),
            },
        },
    )
    conn.commit()
    conn.close()
    row["steps"] = steps
    trigger_memory_consolidation_event(
        agent_root,
        project_id,
        {
            "trigger": "artifact_created",
            "source_type": "protocol",
            "source_id": protocol_id,
            "artifact_type": "protocol",
            "source_object_type": "protocol",
            "source_object_id": protocol_id,
        },
        task_id=clean(protocol.get("task_id")),
    )
    return row


def list_protocols(agent_root: Path, project_id: str = "") -> list[dict[str, Any]]:
    conn = connect(agent_root)
    protocols = rows_to_dicts(
        conn.execute(
            "SELECT * FROM protocols WHERE (?='' OR project_id=?) ORDER BY updated_at DESC",
            (project_id, project_id),
        ).fetchall()
    )
    for protocol in protocols:
        protocol["steps"] = rows_to_dicts(
            conn.execute("SELECT * FROM protocol_steps WHERE protocol_id=? ORDER BY step_number", (protocol["id"],)).fetchall()
        )
    conn.close()
    return protocols


def get_protocol(agent_root: Path, protocol_id: str) -> dict[str, Any]:
    conn = connect(agent_root)
    protocol = row_to_dict(conn.execute("SELECT * FROM protocols WHERE id=?", (protocol_id,)).fetchone())
    if not protocol:
        conn.close()
        raise KeyError("protocol not found")
    protocol["steps"] = rows_to_dicts(conn.execute("SELECT * FROM protocol_steps WHERE protocol_id=? ORDER BY step_number", (protocol_id,)).fetchall())
    conn.close()
    return protocol


def dilution_calculation(stock_concentration: float, target_concentration: float, final_volume: float) -> dict[str, float]:
    if stock_concentration <= 0 or target_concentration <= 0 or final_volume <= 0:
        raise ValueError("concentrations and final volume must be positive")
    stock_volume = target_concentration * final_volume / stock_concentration
    diluent_volume = final_volume - stock_volume
    return {"stock_volume": stock_volume, "diluent_volume": diluent_volume, "final_volume": final_volume}


def molarity_to_mass(molarity_mol_l: float, volume_l: float, molecular_weight_g_mol: float) -> dict[str, float]:
    if molarity_mol_l <= 0 or volume_l <= 0 or molecular_weight_g_mol <= 0:
        raise ValueError("molarity, volume, and molecular weight must be positive")
    mass_g = molarity_mol_l * volume_l * molecular_weight_g_mol
    return {"mass_g": mass_g, "mass_mg": mass_g * 1000}


def mass_concentration_to_molarity(mass_concentration_g_l: float, molecular_weight_g_mol: float) -> dict[str, float]:
    if mass_concentration_g_l <= 0 or molecular_weight_g_mol <= 0:
        raise ValueError("mass concentration and molecular weight must be positive")
    molarity = mass_concentration_g_l / molecular_weight_g_mol
    return {"molarity_mol_l": molarity, "molarity_mM": molarity * 1000}


def generate_dose_table(stock_concentration: float, doses: list[float], final_volume: float) -> list[dict[str, float]]:
    return [{"target_concentration": dose, **dilution_calculation(stock_concentration, dose, final_volume)} for dose in doses]


def generate_plate_layout(groups: list[str], replicates: int = 3, wells: int = 96) -> list[dict[str, Any]]:
    if replicates <= 0:
        raise ValueError("replicates must be positive")
    rows = "ABCDEFGH"
    cols = range(1, 13)
    well_names = [f"{row}{col}" for row in rows for col in cols][:wells]
    layout = []
    idx = 0
    for group in groups:
        for rep in range(1, replicates + 1):
            if idx >= len(well_names):
                return layout
            layout.append({"well": well_names[idx], "group": group, "replicate": rep})
            idx += 1
    return layout


def run_reagent_calculator(payload: dict[str, Any]) -> dict[str, Any]:
    mode = clean(payload.get("mode"))
    if mode == "dilution":
        return dilution_calculation(float(payload["stock_concentration"]), float(payload["target_concentration"]), float(payload["final_volume"]))
    if mode == "molarity_to_mass":
        return molarity_to_mass(float(payload["molarity_mol_l"]), float(payload["volume_l"]), float(payload["molecular_weight_g_mol"]))
    if mode == "mass_concentration_to_molarity":
        return mass_concentration_to_molarity(float(payload["mass_concentration_g_l"]), float(payload["molecular_weight_g_mol"]))
    if mode == "dose_table":
        return {"dose_table": generate_dose_table(float(payload["stock_concentration"]), [float(v) for v in as_list(payload.get("doses"))], float(payload["final_volume"]))}
    if mode == "plate_layout":
        return {"plate_layout": generate_plate_layout([str(v) for v in as_list(payload.get("groups"))], int(payload.get("replicates") or 3))}
    raise ValueError("unsupported calculator mode")


def generate_naming_convention(project_title: str, protocol: dict[str, Any], date_value: str | None = None) -> str:
    slug = re.sub(r"[^A-Z0-9]+", "", project_title.upper())[:10] or "PROJECT"
    assay = re.sub(r"[^A-Z0-9]+", "", clean(protocol.get("protocol_type")).upper()) or "ASSAY"
    date_part = date_value or datetime.now().date().isoformat()
    return f"{slug}_EXPERIMENT_SAMPLE_GROUP_DOSE_TIMEPOINT_{assay}_{date_part}_v1.csv"


def generate_execution_package(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    protocol_id = clean(payload.get("protocol_id"))
    skill_run_id = clean(payload.get("skill_run_id"))
    if not protocol_id:
        raise ValueError("protocol_id is required")
    protocol = get_protocol(agent_root, protocol_id)
    project = get_project_detail(agent_root, protocol["project_id"])
    sample_plan = []
    counter = 1
    for plan in protocol.get("sample_plan") or build_default_sample_plan(protocol.get("protocol_type", "")):
        replicates = int(plan.get("replicates") or 3)
        for rep in range(1, replicates + 1):
            sample_plan.append(
                {
                    "sample_id": f"S{counter:03d}",
                    "group": plan.get("group", "Group"),
                    "dose": plan.get("dose", "TBD"),
                    "timepoint": plan.get("timepoint", "TBD"),
                    "replicate": rep,
                    "parent_sample_id": "",
                    "status": "planned",
                }
            )
            counter += 1
    reagent_table = [
        {"calculation": "1:10 dilution example", **dilution_calculation(10, 1, 1000)},
        {"calculation": "96-well 10 uM from 10 mM stock", **dilution_calculation(10000, 10, 12000)},
    ]
    instrument_table = [
        {"parameter": "assay", "value": protocol.get("protocol_type", "general assay")},
        {"parameter": "raw_data_policy", "value": "Preserve raw instrument export separately from processed data."},
        {"parameter": "sample_id_policy", "value": "Use sample_id from sample numbering table exactly."},
    ]
    convention = generate_naming_convention(project["title"], protocol)
    expected_files = [
        convention.replace("EXPERIMENT", "RUN01").replace("SAMPLE", "ALL").replace("GROUP", "RAW").replace("DOSE", "NA").replace("TIMEPOINT", "NA"),
        convention.replace("EXPERIMENT", "RUN01").replace("SAMPLE", "ALL").replace("GROUP", "PROCESSED").replace("DOSE", "NA").replace("TIMEPOINT", "NA"),
    ]
    checklist = [
        "Confirm structured protocol against source methods before execution.",
        "Confirm sample numbering table before preparing samples.",
        "Record reagent lot, operator, date, and deviations.",
        "Save raw data files without overwriting or deleting them.",
        "Link processed data, figures, and conclusions back to raw files.",
    ]
    result_template = [
        {"sample_id": row["sample_id"], "raw_file": "", "processed_file": "", "result": "", "qc_flag": "", "notes": ""}
        for row in sample_plan
    ]
    markdown = protocol_execution_markdown(protocol, sample_plan, reagent_table, instrument_table, convention, expected_files, checklist)
    package = {
        "protocol_id": protocol_id,
        "eln_template": markdown,
        "sample_numbering_table": sample_plan,
        "reagent_calculation_table": reagent_table,
        "instrument_parameter_table": instrument_table,
        "data_filename_convention": convention,
        "expected_output_file_list": expected_files,
        "human_execution_checklist": checklist,
        "result_collection_template": result_template,
        "exports": {
            "json": "",
            "csv": table_to_csv(sample_plan),
            "markdown": markdown,
        },
    }
    package_id = stable_id(protocol_id, json_dumps(sample_plan), length=20)
    timestamp = now()
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO protocol_execution_packages(
          id, protocol_id, project_id, package_json, export_json, export_csv, export_markdown, skill_run_id, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET package_json=excluded.package_json, export_json=excluded.export_json,
          export_csv=excluded.export_csv, export_markdown=excluded.export_markdown,
          skill_run_id=COALESCE(NULLIF(excluded.skill_run_id,''), protocol_execution_packages.skill_run_id),
          updated_at=excluded.updated_at
        """,
        (
            package_id,
            protocol_id,
            protocol["project_id"],
            json_dumps(package),
            json_dumps(package),
            package["exports"]["csv"],
            markdown,
            skill_run_id,
            timestamp,
            timestamp,
        ),
    )
    create_link(conn, protocol["project_id"], "protocol", protocol_id, "generated_execution_package", "protocol_execution_package", package_id, len(sample_plan))
    if skill_run_id:
        create_link(conn, protocol["project_id"], "skill_run", skill_run_id, "generated", "protocol_execution_package", package_id, len(sample_plan))
    conn.commit()
    conn.close()
    return {"id": package_id, **package}


def table_to_csv(rows: list[dict[str, Any]]) -> str:
    if not rows:
        return ""
    output: list[str] = []
    headers = list(rows[0].keys())
    output.append(",".join(headers))
    for row in rows:
        output.append(",".join(str(row.get(header, "")).replace(",", ";") for header in headers))
    return "\n".join(output)


def protocol_execution_markdown(
    protocol: dict[str, Any],
    sample_plan: list[dict[str, Any]],
    reagent_table: list[dict[str, Any]],
    instrument_table: list[dict[str, Any]],
    convention: str,
    expected_files: list[str],
    checklist: list[str],
) -> str:
    lines = [
        f"# Protocol Execution Package: {protocol['title']}",
        "",
        "## Reliability Notes",
        "- This package is a planning aid, not an autonomous lab instruction.",
        "- Human confirmation is required before execution.",
        "- Raw files must be preserved separately from processed files.",
        "",
        "## Sample Numbering",
        table_to_markdown(sample_plan[:20]),
        "",
        "## Reagent Calculations",
        table_to_markdown(reagent_table),
        "",
        "## Instrument Parameters",
        table_to_markdown(instrument_table),
        "",
        "## Naming Convention",
        f"`{convention}`",
        "",
        "## Expected Output Files",
        *[f"- `{item}`" for item in expected_files],
        "",
        "## Human Checklist",
        *[f"- [ ] {item}" for item in checklist],
        "",
        "## Limitations",
        "- Parameters extracted from methods text may be incomplete.",
        "- Recommendations are suggestions until supported by local evidence.",
    ]
    return "\n".join(lines)


def table_to_markdown(rows: list[dict[str, Any]]) -> str:
    if not rows:
        return "_No rows._"
    headers = list(rows[0].keys())
    lines = ["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |"]
    for row in rows:
        lines.append("| " + " | ".join(clean(row.get(header)) for header in headers) + " |")
    return "\n".join(lines)


