def add_claim_evidence(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    conn = connect(agent_root)
    claim = row_to_dict(conn.execute("SELECT * FROM claims WHERE id=?", (claim_id,)).fetchone())
    if not claim:
        conn.close()
        raise KeyError("claim not found")
    evidence_type = clean(payload.get("evidence_type") or payload.get("type"))
    if evidence_type not in CLAIM_EVIDENCE_TYPES:
        raise ValueError("unsupported claim evidence type")
    evidence_id = clean(payload.get("evidence_id") or payload.get("id"))
    source_file_id = clean(payload.get("source_file_id"))
    provenance_record_id = clean(payload.get("provenance_record_id"))
    if evidence_type == "source_file" and not source_file_id:
        source_file_id = evidence_id
    if evidence_type == "provenance_record" and not provenance_record_id:
        provenance_record_id = evidence_id
    timestamp = now()
    evidence_key = evidence_id or source_file_id or provenance_record_id or clean(payload.get("source_snippet"))
    evidence_row = {
        "id": clean(payload.get("evidence_link_id")) or stable_id(claim_id, evidence_type, evidence_key, payload.get("row_number"), payload.get("well"), length=24),
        "claim_id": claim_id,
        "project_id": claim["project_id"],
        "evidence_type": evidence_type,
        "evidence_id": evidence_id,
        "source_file_id": source_file_id,
        "provenance_record_id": provenance_record_id,
        "source_snippet": clean(payload.get("source_snippet")),
        "row_number": int(payload["row_number"]) if str(payload.get("row_number") or "").isdigit() else None,
        "column_name": clean(payload.get("column_name")),
        "well": clean(payload.get("well")),
        "evidence_label": clean(payload.get("evidence_label") or payload.get("label")),
        "evidence_metadata_json": json_dumps(payload.get("metadata") or {}),
        "confidence": float(payload.get("confidence") or claim.get("confidence") or 0.6),
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn.execute(
        """
        INSERT INTO claim_evidence(
          id, claim_id, project_id, evidence_type, evidence_id, source_file_id, provenance_record_id,
          source_snippet, row_number, column_name, well, evidence_label, evidence_metadata_json,
          confidence, created_at, updated_at
        )
        VALUES (
          :id, :claim_id, :project_id, :evidence_type, :evidence_id, :source_file_id, :provenance_record_id,
          :source_snippet, :row_number, :column_name, :well, :evidence_label, :evidence_metadata_json,
          :confidence, :created_at, :updated_at
        )
        ON CONFLICT(id) DO UPDATE SET
          source_snippet=excluded.source_snippet,
          confidence=excluded.confidence,
          updated_at=excluded.updated_at
        """,
        evidence_row,
    )
    target_type = {
        "source_file": "file",
        "provenance_record": "provenance_record",
        "memory_entity": "memory_entity",
        "workflow_step": "workflow_step",
    }.get(evidence_type, evidence_type)
    target_id = evidence_id or source_file_id or provenance_record_id
    if target_id:
        create_link(conn, claim["project_id"], "claim", claim_id, "supported_by", target_type, target_id, 1)
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM claim_evidence WHERE id=?", (evidence_row["id"],)).fetchone()) or {}
    conn.close()
    claim_detail = get_claim_with_evidence(agent_root, claim_id)
    canonical_memory.sync_claim_to_conclusion(agent_root, claim_detail, claim_detail.get("evidence") or [])
    return saved


def list_claims(agent_root: Path, project_id: str = "", status: str = "", claim_type: str = "") -> list[dict[str, Any]]:
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    if status:
        clauses.append("status=?")
        params.append(status)
    if claim_type:
        clauses.append("claim_type=?")
        params.append(claim_type)
    conn = connect(agent_root)
    rows = rows_to_dicts(
        conn.execute(
            f"""
            SELECT c.*, COUNT(e.id) AS evidence_count
            FROM claims c
            LEFT JOIN claim_evidence e ON e.claim_id=c.id
            WHERE {' AND '.join('c.' + clause if clause.startswith(('project_id', 'status', 'claim_type')) else clause for clause in clauses)}
            GROUP BY c.id
            ORDER BY c.updated_at DESC
            """,
            params,
        ).fetchall()
    )
    conn.close()
    return rows


def get_claim_with_evidence(agent_root: Path, claim_id: str) -> dict[str, Any]:
    conn = connect(agent_root)
    claim = row_to_dict(conn.execute("SELECT * FROM claims WHERE id=?", (claim_id,)).fetchone())
    if not claim:
        conn.close()
        raise KeyError("claim not found")
    evidence = rows_to_dicts(conn.execute("SELECT * FROM claim_evidence WHERE claim_id=? ORDER BY created_at", (claim_id,)).fetchall())
    for item in evidence:
        etype = item.get("evidence_type")
        eid = item.get("evidence_id")
        if etype == "source_file" or item.get("source_file_id"):
            file_id = item.get("source_file_id") or eid
            source = row_to_dict(conn.execute("SELECT id, original_filename, detected_document_category, file_path FROM research_files WHERE id=?", (file_id,)).fetchone())
            item["source"] = source or {}
        elif etype == "provenance_record" or item.get("provenance_record_id"):
            prov_id = item.get("provenance_record_id") or eid
            source = row_to_dict(
                conn.execute(
                    """
                    SELECT p.*, f.original_filename
                    FROM provenance_records p
                    LEFT JOIN research_files f ON f.id=p.source_file_id
                    WHERE p.id=?
                    """,
                    (prov_id,),
                ).fetchone()
            )
            item["source"] = source or {}
        elif etype == "sample":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM samples WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "experiment":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM experiments WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "protocol":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM protocols WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "data_context":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM data_contexts WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "report":
            item["source"] = row_to_dict(conn.execute("SELECT id, title, report_type, skill_run_id, created_at FROM reports WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "skill_run":
            item["source"] = row_to_dict(conn.execute("SELECT id, skill_name, status, logs_json, output_object_refs_json FROM skill_runs WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "workflow_step":
            item["source"] = row_to_dict(conn.execute("SELECT id, step_name, agent_type, status, result_summary FROM workflow_steps WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "memory_entity":
            item["source"] = row_to_dict(conn.execute("SELECT id, entity_type, canonical_name, confidence, trust_level FROM memory_entities WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "project_memory":
            item["source"] = row_to_dict(conn.execute("SELECT id, memory_type, title, content, trust_level, confidence FROM agent_memory_entries WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "experiment_log":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM experiment_log_entries WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "failure_log":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM failure_logs WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "retrospective_note":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM retrospective_notes WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "weekly_digest_report":
            item["source"] = row_to_dict(conn.execute("SELECT * FROM weekly_digest_reports WHERE id=?", (eid,)).fetchone()) or {}
        elif etype == "writing_output":
            item["source"] = row_to_dict(conn.execute("SELECT id, skill_name, status, output_payload_json FROM skill_runs WHERE id=?", (eid,)).fetchone()) or {}
        try:
            item["evidence_card"] = get_evidence_item(agent_root, evidence_key(etype, eid or item.get("source_file_id") or item.get("provenance_record_id")))
        except Exception:
            item["evidence_card"] = {}
    claim["evidence"] = evidence
    claim["evidence_count"] = len(evidence)
    conn.close()
    return claim


def evaluate_evidence_for_claim_confirmation(agent_root: Path, claim_id: str) -> dict[str, Any]:
    claim = get_claim_with_evidence(agent_root, claim_id)
    allowed: list[dict[str, Any]] = []
    disallowed: list[dict[str, Any]] = []
    blockers: list[str] = []
    for evidence in claim.get("evidence") or []:
        card = evidence.get("evidence_card") or {}
        if not card and evidence.get("evidence_type") and evidence.get("evidence_id"):
            try:
                card = get_evidence_item(agent_root, evidence_key(evidence["evidence_type"], evidence["evidence_id"]))
            except Exception:
                card = {}
        if card.get("can_support_confirmed_claim"):
            allowed.append(card)
        else:
            reason = clean(card.get("reason_if_not_supporting") or "Evidence cannot support confirmed claims.")
            disallowed.append({"claim_evidence": evidence, "evidence": card, "reason": reason})
            if reason and reason not in blockers:
                blockers.append(reason)
    if not claim.get("evidence"):
        blockers.append("Claim has no linked evidence.")
    if not allowed and not blockers:
        blockers.append("No linked evidence is eligible to support a confirmed claim.")
    recommendation = "confirmable" if allowed else "Link at least one real reference, user-uploaded full text, user-confirmed project data, human-confirmed project memory, or validated data file before confirmation."
    return {
        "claim_id": claim_id,
        "can_confirm": bool(allowed),
        "allowed_evidence": allowed,
        "disallowed_evidence": disallowed,
        "blockers": blockers,
        "recommendation": recommendation,
    }


def claim_review_summary(agent_root: Path, claim: dict[str, Any]) -> dict[str, Any]:
    detail = get_claim_with_evidence(agent_root, claim["id"])
    counts = {
        "real_reference_count": 0,
        "project_memory_count": 0,
        "experiment_log_count": 0,
        "mock_evidence_count": 0,
    }
    evidence_cards = []
    for evidence in detail.get("evidence") or []:
        card = evidence.get("evidence_card") or {}
        evidence_cards.append(card)
        label = clean(card.get("friendly_evidence_label"))
        etype = clean(card.get("evidence_type"))
        if label == "real reference":
            counts["real_reference_count"] += 1
        if etype in {"project_memory", "memory_entity"} or label in {"project memory", "human confirmed"}:
            counts["project_memory_count"] += 1
        if etype == "experiment_log" or label == "experiment log":
            counts["experiment_log_count"] += 1
        if label == "mock placeholder":
            counts["mock_evidence_count"] += 1
    gate = evaluate_evidence_for_claim_confirmation(agent_root, claim["id"])
    unsupported_reason = "; ".join(gate["blockers"]) if not gate["can_confirm"] else ""
    return {
        **detail,
        **counts,
        "evidence_count": len(detail.get("evidence") or []),
        "unsupported_reason": unsupported_reason,
        "generated_by": clean(detail.get("created_from")) or ("skill_run" if detail.get("skill_run_id") else "user"),
        "evidence_cards": evidence_cards,
        "confirmation_gate": gate,
    }


def list_claim_review_queue(agent_root: Path, project_id: str, status: str = "", claim_type: str = "") -> dict[str, Any]:
    claims = list_claims(agent_root, project_id=project_id, status=status, claim_type=claim_type)
    review_claims = [claim_review_summary(agent_root, claim) for claim in claims]
    return {"project_id": project_id, "claims": review_claims, "count": len(review_claims)}


def confirm_claim(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    gate = evaluate_evidence_for_claim_confirmation(agent_root, claim_id)
    if not gate["can_confirm"]:
        claim = get_claim_with_evidence(agent_root, claim_id)
        return {"claim": claim, "confirmation": gate, "status": "blocked", "message": "Claim cannot be confirmed with the currently linked evidence."}
    confirmed_by = clean(payload.get("confirmed_by")) or clean(payload.get("user")) or "local_user"
    timestamp = now()
    conn = connect(agent_root)
    conn.execute(
        "UPDATE claims SET status='confirmed', confirmed_by=?, confirmed_at=?, updated_at=? WHERE id=?",
        (confirmed_by, timestamp, timestamp, claim_id),
    )
    row = row_to_dict(conn.execute("SELECT * FROM claims WHERE id=?", (claim_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("claim not found")
    conn.commit()
    conn.close()
    canonical_memory.sync_claim_to_conclusion(agent_root, row or {}, get_claim_with_evidence(agent_root, claim_id).get("evidence") or [])
    return {"claim": row, "confirmation": gate, "status": "confirmed"}


def reject_claim(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    conn = connect(agent_root)
    conn.execute("UPDATE claims SET status='rejected', updated_at=? WHERE id=?", (now(), claim_id))
    row = row_to_dict(conn.execute("SELECT * FROM claims WHERE id=?", (claim_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("claim not found")
    conn.commit()
    conn.close()
    canonical_memory.sync_claim_to_conclusion(agent_root, row or {}, get_claim_with_evidence(agent_root, claim_id).get("evidence") or [])
    return {"claim": row}


def mark_claim_needs_more_evidence(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    reason = clean(payload.get("reason") or payload.get("unsupported_reason"))
    conn = connect(agent_root)
    conn.execute("UPDATE claims SET status='needs_more_evidence', updated_at=? WHERE id=?", (now(), claim_id))
    row = row_to_dict(conn.execute("SELECT * FROM claims WHERE id=?", (claim_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("claim not found")
    if reason:
        create_link(conn, row["project_id"], "claim", claim_id, "needs_more_evidence", "claim", claim_id, 1)
    conn.commit()
    conn.close()
    return {"claim": get_claim_with_evidence(agent_root, claim_id), "reason": reason}


def link_claim_evidence_from_payload(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    evidence_id = clean(payload.get("evidence_review_id") or payload.get("evidence_key") or payload.get("evidence_id"))
    evidence_type = clean(payload.get("evidence_type") or payload.get("type"))
    raw_id = clean(payload.get("raw_id") or payload.get("id"))
    if evidence_id and ":" in evidence_id:
        return link_evidence_item_to_claim(agent_root, evidence_id, {**payload, "claim_id": claim_id})
    if evidence_type and raw_id:
        return {"claim_evidence": add_claim_evidence(agent_root, claim_id, {**payload, "evidence_type": evidence_type, "evidence_id": raw_id})}
    return {"claim_evidence": add_claim_evidence(agent_root, claim_id, payload)}


def unlink_claim_evidence(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    link_id = clean(payload.get("claim_evidence_id") or payload.get("evidence_link_id") or payload.get("id"))
    evidence_type = clean(payload.get("evidence_type"))
    evidence_id = clean(payload.get("evidence_id"))
    conn = connect(agent_root)
    if link_id:
        conn.execute("DELETE FROM claim_evidence WHERE claim_id=? AND id=?", (claim_id, link_id))
    elif evidence_type and evidence_id:
        conn.execute("DELETE FROM claim_evidence WHERE claim_id=? AND evidence_type=? AND evidence_id=?", (claim_id, evidence_type, evidence_id))
    else:
        conn.close()
        raise ValueError("claim_evidence_id or evidence_type/evidence_id is required")
    conn.commit()
    conn.close()
    return {"claim": get_claim_with_evidence(agent_root, claim_id)}


def supersede_claim(agent_root: Path, claim_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    old_claim = get_claim_with_evidence(agent_root, claim_id)
    new_claim = create_claim(
        agent_root,
        {
            "project_id": old_claim["project_id"],
            "claim_text": clean(payload.get("claim_text") or payload.get("text")) or old_claim["claim_text"],
            "claim_type": clean(payload.get("claim_type")) or old_claim["claim_type"],
            "status": clean(payload.get("status")) or "draft",
            "confidence": float(payload.get("confidence") or old_claim.get("confidence") or 0.6),
            "created_from": "claim",
            "created_from_id": claim_id,
            "supersedes_claim_id": claim_id,
        },
    )
    conn = connect(agent_root)
    conn.execute("UPDATE claims SET status='superseded', updated_at=? WHERE id=?", (now(), claim_id))
    create_link(conn, old_claim["project_id"], "claim", claim_id, "superseded_by", "claim", new_claim["id"], 1)
    conn.commit()
    conn.close()
    return {"superseded_claim": get_claim_with_evidence(agent_root, claim_id), "new_claim": new_claim}


def markdown_claim_candidates(report: dict[str, Any]) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    section = ""
    for raw_line in (report.get("content_markdown") or "").splitlines():
        line = clean(raw_line)
        if not line:
            continue
        if line.startswith("#"):
            section = line.strip("# ").lower()
            continue
        if not line.startswith("-"):
            continue
        text = clean(line.lstrip("- "))
        if not text or text.lower().startswith("this report is"):
            continue
        claim_type = "conclusion"
        status = "draft"
        confidence = 0.6
        if "limitation" in section:
            claim_type = "limitation"
            status = "weak"
            confidence = 0.55
        elif "next experiment" in section or "next step" in section:
            claim_type = "next_step"
            status = "draft"
            confidence = 0.58
        elif "risk" in section or "conflict" in section:
            claim_type = "risk"
            status = "weak"
            confidence = 0.55
        elif "unsupported" in section or "weak" in section:
            claim_type = "unsupported_conclusion"
            status = "unsupported"
            confidence = 0.45
        elif "memory" in section or "evidence" in section:
            claim_type = "result"
            status = "weak"
            confidence = 0.62
        candidates.append({"claim_text": text, "claim_type": claim_type, "status": status, "confidence": confidence})
    return candidates[:30]


def generate_claims_from_report(agent_root: Path, report_id: str) -> dict[str, Any]:
    conn = connect(agent_root)
    report = row_to_dict(conn.execute("SELECT * FROM reports WHERE id=?", (report_id,)).fetchone())
    if not report:
        conn.close()
        raise KeyError("report not found")
    evidence_file_ids = as_list(report.get("evidence_file_ids"))
    skill_run_id = clean(report.get("skill_run_id"))
    conn.close()
    created = []
    for candidate in markdown_claim_candidates(report):
        claim = create_claim(
            agent_root,
            {
                "project_id": report["project_id"],
                "claim_text": candidate["claim_text"],
                "claim_type": candidate["claim_type"],
                "status": candidate["status"],
                "confidence": candidate["confidence"],
                "created_from": "report",
                "created_from_id": report_id,
                "skill_run_id": skill_run_id,
            },
        )
        add_claim_evidence(
            agent_root,
            claim["id"],
            {
                "evidence_type": "report",
                "evidence_id": report_id,
                "source_snippet": candidate["claim_text"],
                "evidence_label": report.get("title"),
                "confidence": candidate["confidence"],
            },
        )
        if skill_run_id:
            add_claim_evidence(agent_root, claim["id"], {"evidence_type": "skill_run", "evidence_id": skill_run_id, "confidence": candidate["confidence"]})
        for file_id in evidence_file_ids[:10]:
            add_claim_evidence(agent_root, claim["id"], {"evidence_type": "source_file", "evidence_id": str(file_id), "source_file_id": str(file_id), "confidence": 0.5})
        created.append(claim)
    return {"report_id": report_id, "claims": created}


def generate_claims_from_memory_entities(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    entity_type = clean(payload.get("entity_type"))
    conn = connect(agent_root)
    clauses = ["project_id=?", "status='active'"]
    params: list[Any] = [project_id]
    if entity_type:
        clauses.append("entity_type=?")
        params.append(entity_type)
    rows = rows_to_dicts(
        conn.execute(
            f"SELECT * FROM memory_entities WHERE {' AND '.join(clauses)} AND entity_type IN ('result','conclusion','next step') ORDER BY updated_at DESC LIMIT 50",
            params,
        ).fetchall()
    )
    conn.close()
    created = []
    for entity in rows:
        claim_type = "next_step" if entity["entity_type"] == "next step" else entity["entity_type"]
        confidence = float(entity.get("confidence") or 0.5)
        status = "weak" if entity.get("trust_level") == "raw_extracted" or confidence < 0.7 else "draft"
        claim = create_claim(
            agent_root,
            {
                "project_id": project_id,
                "claim_text": entity["canonical_name"],
                "claim_type": claim_type,
                "status": status,
                "confidence": confidence,
                "created_from": "memory_entity",
                "created_from_id": entity["id"],
                "skill_run_id": clean(payload.get("skill_run_id")),
            },
        )
        add_claim_evidence(agent_root, claim["id"], {"evidence_type": "memory_entity", "evidence_id": entity["id"], "confidence": confidence})
        search_result = search_memory(agent_root, {"project_id": project_id, "query": entity["canonical_name"], "limit": 1})
        for item in search_result.get("memory", []):
            if item["id"] != entity["id"]:
                continue
            for prov in item.get("provenance") or []:
                add_claim_evidence(
                    agent_root,
                    claim["id"],
                    {
                        "evidence_type": "provenance_record",
                        "evidence_id": prov["id"],
                        "provenance_record_id": prov["id"],
                        "source_file_id": prov.get("source_file_id"),
                        "source_snippet": prov.get("source_text_snippet"),
                        "row_number": prov.get("row_number"),
                        "column_name": prov.get("column_name"),
                        "confidence": prov.get("confidence") or confidence,
                    },
                )
        created.append(claim)
    return {"claims": created}


def rag_tokens(text: str) -> set[str]:
    normalized = clean(text)
    tokens = {token.lower() for token in re.findall(r"[A-Za-z][A-Za-z0-9_.-]{1,}", normalized)}
    tokens.update(token.lower() for token in re.findall(r"\d+(?:\.\d+)?", normalized) if len(token) >= 2)
    tokens.update(token.lower() for token in re.findall(r"[\u4e00-\u9fa5]{2,}", normalized))
    for token in list(tokens):
        if "." in token:
            tokens.add(token.replace(".", ""))
            tokens.add(token.split(".", 1)[0])
    return tokens


def split_reference_chunks(text: str, max_chars: int = 1200, overlap: int = 150) -> list[str]:
    text = clean(text)
    if not text:
        return []
    if len(text) <= max_chars:
        return [text]
    chunks = []
    start = 0
    while start < len(text):
        end = min(len(text), start + max_chars)
        chunks.append(text[start:end])
        if end == len(text):
            break
        start = max(0, end - overlap)
    return chunks


ACCESS_STATUS_VALUES = {
    "oa_pdf_downloaded",
    "non_oa_need_user_download",
    "metadata_only",
    "download_failed",
    "unknown",
}


def normalize_paper_access_status(value: Any, *, has_full_text: bool = False) -> str:
    raw = clean(value).lower()
    mapping = {
        "downloaded": "oa_pdf_downloaded",
        "success": "oa_pdf_downloaded",
        "full_text_available": "oa_pdf_downloaded",
        "open_access": "oa_pdf_downloaded",
        "oa": "oa_pdf_downloaded",
        "closed": "non_oa_need_user_download",
        "paywalled": "non_oa_need_user_download",
        "inaccessible": "non_oa_need_user_download",
        "rate_limited": "non_oa_need_user_download",
        "broken_link": "download_failed",
        "failed": "download_failed",
    }
    normalized = mapping.get(raw, raw)
    if normalized in ACCESS_STATUS_VALUES:
        return normalized
    if has_full_text:
        return "oa_pdf_downloaded"
    return "unknown" if normalized else "metadata_only"


def import_reference(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    title = clean(payload.get("title"))
    if not project_id:
        raise ValueError("project_id is required")
    if not title:
        raise ValueError("title is required")
    authors = as_list(payload.get("authors"))
    year = clean(payload.get("year"))
    doi = clean(payload.get("doi"))
    url = clean(payload.get("url"))
    abstract = clean(payload.get("abstract") or payload.get("abstract_if_available") or payload.get("summary") or payload.get("text"))
    full_text_path = clean(payload.get("full_text_path"))
    full_text = clean(payload.get("full_text") or payload.get("content"))
    if not full_text and full_text_path:
        full_text = clean(text_from_path(Path(full_text_path)))
    source_type = clean(payload.get("source_type")) or "manual_reference"
    source_provider = clean(payload.get("source_provider") or payload.get("provider")) or source_type
    access_status = normalize_paper_access_status(payload.get("access_status"), has_full_text=bool(full_text or full_text_path))
    reference_id = clean(payload.get("id")) or stable_id(project_id, doi or title, year, length=24)
    timestamp = now()
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO "references"(
          id, project_id, title, authors_json, year, doi, url, source_type, abstract, full_text_available,
          access_status, source_path, metadata_json, skill_run_id, created_at, updated_at,
          journal, full_text_path, source_provider, search_task_id, tags_json, research_topic,
          relevance_score, evidence_level, added_at, user_notes, reading_status, paper_type,
          impact_label, reason_for_inclusion, reason_for_exclusion
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          title=excluded.title,
          authors_json=excluded.authors_json,
          year=excluded.year,
          doi=excluded.doi,
          url=excluded.url,
          source_type=excluded.source_type,
          abstract=excluded.abstract,
          full_text_available=excluded.full_text_available,
          access_status=excluded.access_status,
          source_path=excluded.source_path,
          metadata_json=excluded.metadata_json,
          skill_run_id=COALESCE(NULLIF(excluded.skill_run_id,''), "references".skill_run_id),
          journal=COALESCE(NULLIF(excluded.journal,''), "references".journal),
          full_text_path=COALESCE(NULLIF(excluded.full_text_path,''), "references".full_text_path),
          source_provider=COALESCE(NULLIF(excluded.source_provider,''), "references".source_provider),
          search_task_id=COALESCE(NULLIF(excluded.search_task_id,''), "references".search_task_id),
          tags_json=excluded.tags_json,
          research_topic=COALESCE(NULLIF(excluded.research_topic,''), "references".research_topic),
          relevance_score=COALESCE(excluded.relevance_score, "references".relevance_score),
          evidence_level=COALESCE(NULLIF(excluded.evidence_level,''), "references".evidence_level),
          added_at=COALESCE(NULLIF("references".added_at,''), excluded.added_at),
          user_notes=COALESCE(NULLIF(excluded.user_notes,''), "references".user_notes),
          reading_status=COALESCE(NULLIF(excluded.reading_status,''), "references".reading_status),
          paper_type=COALESCE(NULLIF(excluded.paper_type,''), "references".paper_type),
          impact_label=COALESCE(NULLIF(excluded.impact_label,''), "references".impact_label),
          reason_for_inclusion=COALESCE(NULLIF(excluded.reason_for_inclusion,''), "references".reason_for_inclusion),
          reason_for_exclusion=COALESCE(NULLIF(excluded.reason_for_exclusion,''), "references".reason_for_exclusion),
          updated_at=excluded.updated_at
        """,
        (
            reference_id,
            project_id,
            title,
            json_dumps(authors),
            year,
            doi,
            url,
            source_type,
            abstract,
            1 if (full_text or full_text_path) else 0,
            access_status,
            clean(payload.get("source_path")),
            json_dumps(payload.get("metadata") or {}),
            clean(payload.get("skill_run_id")),
            timestamp,
            timestamp,
            clean(payload.get("journal")),
            full_text_path,
            source_provider,
            clean(payload.get("search_task_id")),
            json_dumps(as_list(payload.get("tags"))),
            clean(payload.get("research_topic") or payload.get("topic")),
            float(payload["relevance_score"]) if payload.get("relevance_score") not in (None, "") else None,
            clean(payload.get("evidence_level")) or ("peer_reviewed_metadata" if "mock" not in source_provider.lower() else "mock_not_evidence"),
            clean(payload.get("added_at")) or timestamp,
            clean(payload.get("user_notes") or payload.get("notes")),
            clean(payload.get("reading_status")) or "unread",
            clean(payload.get("paper_type")) or "unknown",
            clean(payload.get("impact_label")) or "unknown",
            clean(payload.get("reason_for_inclusion")),
            clean(payload.get("reason_for_exclusion")),
        ),
    )
    conn.execute("DELETE FROM reference_chunks WHERE reference_id=?", (reference_id,))
    chunk_source = "\n\n".join(item for item in [abstract, full_text] if item)
    chunks = split_reference_chunks(chunk_source or title)
    for index, chunk in enumerate(chunks, start=1):
        chunk_id = stable_id(reference_id, index, chunk[:80], length=24)
        conn.execute(
            """
            INSERT INTO reference_chunks(
              id, reference_id, project_id, chunk_index, chunk_text, page_number, section,
              metadata_json, token_set_json, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                chunk_id,
                reference_id,
                project_id,
                index,
                chunk,
                payload.get("page_number"),
                clean(payload.get("section")) or ("abstract" if not full_text else "full_text"),
                json_dumps({"reference_title": title, "doi": doi, "url": url}),
                json_dumps(sorted(rag_tokens(chunk))),
                timestamp,
                timestamp,
            ),
        )
    if clean(payload.get("skill_run_id")):
        create_link(conn, project_id, "skill_run", clean(payload["skill_run_id"]), "generated", "reference", reference_id, len(chunks))
    upsert_artifact_record(
        conn,
        {
            "project_id": project_id,
            "type": "reference",
            "title": title,
            "path": full_text_path or clean(payload.get("source_path")),
            "source_skill_run_id": clean(payload.get("skill_run_id")),
            "source_object_type": "reference",
            "source_object_id": reference_id,
            "status": "indexed" if chunks else ("parsed" if full_text_path or full_text else "created"),
            "metadata": {"doi": doi, "chunks_count": len(chunks), "source_provider": source_provider},
        },
    )
    for index in range(1, len(chunks) + 1):
        chunk_id = stable_id(reference_id, index, chunks[index - 1][:80], length=24)
        upsert_artifact_record(
            conn,
            {
                "project_id": project_id,
                "type": "chunk",
                "title": f"{title} chunk {index}",
                "source_skill_run_id": clean(payload.get("skill_run_id")),
                "source_object_type": "reference_chunk",
                "source_object_id": chunk_id,
                "status": "indexed",
                "metadata": {"reference_id": reference_id, "chunk_index": index},
            },
        )
    conn.commit()
    reference = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone()) or {}
    reference["chunks"] = rows_to_dicts(conn.execute("SELECT * FROM reference_chunks WHERE reference_id=? ORDER BY chunk_index", (reference_id,)).fetchall())
    conn.close()
    trigger_memory_consolidation_event(
        agent_root,
        project_id,
        {
            "trigger": "artifact_created",
            "source_type": "reference",
            "source_id": reference_id,
            "artifact_type": "reference",
            "chunks_count": len(chunks),
        },
        task_id=clean(payload.get("task_id")),
    )
    return reference


ARTICLE_SECTION_PATTERNS = {
    "background": [r"\bbackground\b", r"\baim\b", r"\bobjective\b", r"\bpurpose\b", r"\b研究背景\b", r"\b目的\b"],
    "methods": [r"\bmethod", r"\bmaterial", r"\bassay\b", r"\banaly[sz]ed\b", r"\bmeasured\b", r"\b方法\b", r"\b检测\b"],
    "results": [r"\bresult", r"\bfound\b", r"\bincreased\b", r"\bdecreased\b", r"\bsignificant\b", r"\b结果\b", r"\b升高\b", r"\b降低\b"],
    "conclusion": [r"\bconclusion\b", r"\bsuggest", r"\bindicat", r"\bdemonstrat", r"\btherefore\b", r"\b结论\b", r"\b提示\b"],
}


def split_sentences(text: str, limit: int = 20) -> list[str]:
    parts = [clean(part) for part in re.split(r"(?<=[.!?。！？;；])\s+|\n+", clean(text)) if clean(part)]
    if len(parts) <= 1:
        parts = [clean(part) for part in re.split(r"(?<=[.!?。！？;；])", clean(text)) if clean(part)]
    return parts[:limit]


def classify_article_sentences(text: str) -> dict[str, list[str]]:
    sections = {key: [] for key in ARTICLE_SECTION_PATTERNS}
    fallback: list[str] = []
    for sentence in split_sentences(text, limit=30):
        matched = False
        for section, patterns in ARTICLE_SECTION_PATTERNS.items():
            if any(re.search(pattern, sentence, re.IGNORECASE) for pattern in patterns):
                sections[section].append(sentence)
                matched = True
                break
        if not matched:
            fallback.append(sentence)
    if not any(sections.values()) and fallback:
        sections["background"] = fallback[:1]
        sections["methods"] = fallback[1:2]
        sections["results"] = fallback[2:3]
        sections["conclusion"] = fallback[3:4]
    return {key: value[:3] for key, value in sections.items()}


def reference_text_for_article_analysis(reference: dict[str, Any]) -> tuple[str, str]:
    abstract = clean(reference.get("abstract"))
    if abstract:
        return abstract, "abstract_metadata"
    full_text_path = clean(reference.get("full_text_path"))
    if full_text_path and Path(full_text_path).exists():
        text = text_from_path(Path(full_text_path))
        abstract_match = re.search(r"\babstract\b\s*[:.\-]?\s*(.{200,2500}?)(?:\n\s*(?:introduction|keywords|materials|methods)\b|$)", text, re.IGNORECASE | re.DOTALL)
        if abstract_match:
            return clean(abstract_match.group(1)), "abstract_extracted_from_full_text"
        if text:
            return clean(text[:3000]), "full_text_fallback"
    return " ".join([clean(reference.get("title")), clean(reference.get("journal")), clean(reference.get("research_topic"))]), "metadata_fallback"


def extract_article_keyword_analysis(reference: dict[str, Any], limit: int = 12) -> dict[str, Any]:
    text, source_mode = reference_text_for_article_analysis(reference)
    sections = classify_article_sentences(text)
    keywords = extract_seed_keywords(text, limit)
    keyphrases = []
    for phrase in re.findall(r"\b[A-Za-z][A-Za-z0-9-]+(?:\s+[A-Za-z][A-Za-z0-9-]+){1,4}\b", text):
        phrase = clean(phrase)
        if phrase and len(phrase) <= 80 and phrase.lower() not in {item.lower() for item in keyphrases}:
            keyphrases.append(phrase)
        if len(keyphrases) >= 12:
            break
    search_queries = []
    for keyword in keywords[:6]:
        if keyword:
            search_queries.append(f"{keyword} methods")
    return {
        "reference_id": reference["id"],
        "title": reference.get("title"),
        "doi": reference.get("doi"),
        "source_mode": source_mode,
        "abstract_summary": {
            "background": " ".join(sections.get("background") or []) or "Missing or not explicit in available metadata.",
            "methods": " ".join(sections.get("methods") or []) or "Missing or not explicit in available metadata.",
            "results": " ".join(sections.get("results") or []) or "Missing or not explicit in available metadata.",
            "conclusion": " ".join(sections.get("conclusion") or []) or "Missing or not explicit in available metadata.",
        },
        "primary_keywords": keywords,
        "keyphrases": keyphrases[:12],
        "search_queries": search_queries,
        "include_terms": keywords[:8],
        "exclude_terms": ["review-only", "metadata-only"] if source_mode == "metadata_fallback" else [],
        "evidence_snippets": [
            {"section": section, "text": sentence}
            for section, sentences in sections.items()
            for sentence in sentences[:2]
        ],
        "limitations": [
            f"Article analysis source mode: {source_mode}.",
            "Extracted keywords are search suggestions, not verified domain facts.",
        ],
    }


def store_article_keyword_analysis(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    reference: dict[str, Any],
    analysis: dict[str, Any],
    skill_run_id: str = "",
) -> list[dict[str, str]]:
    timestamp = now()
    created: list[dict[str, str]] = []
    reference_id = clean(reference.get("id"))
    title = clean(reference.get("title"))
    entries = [
        (
            "article_abstract_analysis",
            f"Article analysis: {title}",
            json_dumps(analysis["abstract_summary"]),
            {"source": "extract-first-article-keywords", "source_mode": analysis["source_mode"], "keywords": analysis["primary_keywords"], "keyphrases": analysis["keyphrases"], "search_queries": analysis["search_queries"]},
        ),
        (
            "keyword_memory",
            f"Keyword memory: {title}",
            "\n".join(analysis["primary_keywords"] + analysis["keyphrases"]),
            {"source": "extract-first-article-keywords", "include_terms": analysis["include_terms"], "exclude_terms": analysis["exclude_terms"], "search_queries": analysis["search_queries"]},
        ),
    ]
    for entry_type, entry_title, content, metadata in entries:
        entry_id = stable_id(project_id, reference_id, entry_type, length=24)
        conn.execute(
            """
            INSERT INTO knowledge_base_entries(
              id, project_id, entry_type, title, content, source_reference_id, source_chunk_id, metadata_json, skill_run_id, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
              title=excluded.title,
              content=excluded.content,
              metadata_json=excluded.metadata_json,
              skill_run_id=COALESCE(NULLIF(excluded.skill_run_id,''), knowledge_base_entries.skill_run_id),
              updated_at=excluded.updated_at
            """,
            (entry_id, project_id, entry_type, entry_title, content, reference_id, "", json_dumps(metadata), clean(skill_run_id), timestamp, timestamp),
        )
        created.append({"type": "knowledge_base_entry", "id": entry_id})
    for index, snippet in enumerate(analysis.get("evidence_snippets") or [], start=1):
        entry_id = stable_id(project_id, reference_id, "evidence_snippet", index, length=24)
        conn.execute(
            """
            INSERT INTO knowledge_base_entries(
              id, project_id, entry_type, title, content, source_reference_id, source_chunk_id, metadata_json, skill_run_id, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
              content=excluded.content,
              metadata_json=excluded.metadata_json,
              updated_at=excluded.updated_at
            """,
            (
                entry_id,
                project_id,
                "evidence_snippet",
                f"{clean(snippet.get('section')) or 'snippet'}: {title}",
                clean(snippet.get("text")),
                reference_id,
                "",
                json_dumps({"source": "extract-first-article-keywords", "section": clean(snippet.get("section")), "source_mode": analysis["source_mode"]}),
                clean(skill_run_id),
                timestamp,
                timestamp,
            ),
        )
        created.append({"type": "knowledge_base_entry", "id": entry_id})
    if skill_run_id:
        for ref in created:
            create_link(conn, project_id, "skill_run", skill_run_id, "generated", ref["type"], ref["id"], 1)
        create_link(conn, project_id, "skill_run", skill_run_id, "used", "reference", reference_id, 1)
    return created


def analyze_references_with_article_keyword_skill(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    reference_ids = [clean(item) for item in as_list(payload.get("reference_ids")) if clean(item)]
    skill_run_id = clean(payload.get("skill_run_id"))
    limit = int(payload.get("limit") or 500)
    conn = connect(agent_root)
    if reference_ids:
        placeholders = ",".join("?" for _ in reference_ids)
        references = rows_to_dicts(conn.execute(f'SELECT * FROM "references" WHERE project_id=? AND id IN ({placeholders}) ORDER BY updated_at DESC', [project_id, *reference_ids]).fetchall())
    else:
        references = rows_to_dicts(conn.execute('SELECT * FROM "references" WHERE project_id=? ORDER BY updated_at DESC LIMIT ?', (project_id, limit)).fetchall())
    analyses = []
    output_refs: list[dict[str, str]] = []
    for reference in references[:limit]:
        analysis = extract_article_keyword_analysis(reference, int(payload.get("keyword_limit") or 12))
        created_refs = store_article_keyword_analysis(conn, project_id=project_id, reference=reference, analysis=analysis, skill_run_id=skill_run_id)
        analyses.append(analysis)
        output_refs.extend(created_refs)
    conn.commit()
    entries = rows_to_dicts(conn.execute("SELECT * FROM knowledge_base_entries WHERE project_id=? ORDER BY updated_at DESC LIMIT 100", (project_id,)).fetchall())
    conn.close()
    return {
        "project_id": project_id,
        "analyzed_count": len(analyses),
        "article_analyses": analyses,
        "output_refs": output_refs,
        "knowledge_base_entries": entries,
    }


def write_article_keyword_outputs(run_root: Path, analyses: list[dict[str, Any]]) -> None:
    if not run_root:
        return
    output_dir = run_root / "article_abstracts"
    output_dir.mkdir(parents=True, exist_ok=True)
    summary_csv = output_dir / "article_abstracts.csv"
    fieldnames = ["reference_id", "title", "doi", "source_mode", "background", "methods", "results", "conclusion", "primary_keywords", "keyphrases", "search_queries"]
    with summary_csv.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        for analysis in analyses:
            summary = analysis.get("abstract_summary") or {}
            writer.writerow(
                {
                    "reference_id": analysis.get("reference_id"),
                    "title": analysis.get("title"),
                    "doi": analysis.get("doi"),
                    "source_mode": analysis.get("source_mode"),
                    "background": summary.get("background"),
                    "methods": summary.get("methods"),
                    "results": summary.get("results"),
                    "conclusion": summary.get("conclusion"),
                    "primary_keywords": "; ".join(as_list(analysis.get("primary_keywords"))),
                    "keyphrases": "; ".join(as_list(analysis.get("keyphrases"))),
                    "search_queries": "; ".join(as_list(analysis.get("search_queries"))),
                }
            )
    (output_dir / "article_abstract_analysis.json").write_text(json.dumps(analyses, ensure_ascii=False, indent=2), encoding="utf-8")
    terms = []
    for analysis in analyses:
        terms.extend(as_list(analysis.get("primary_keywords")))
        terms.extend(as_list(analysis.get("keyphrases")))
    ordered_terms = []
    for term in terms:
        term = clean(term)
        if term and term.lower() not in {item.lower() for item in ordered_terms}:
            ordered_terms.append(term)
    (output_dir / "next_search_terms.txt").write_text("\n".join(ordered_terms[:200]), encoding="utf-8")


def list_references(agent_root: Path, project_id: str = "", search: str = "", limit: int = 100) -> list[dict[str, Any]]:
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    if search:
        clauses.append("(title LIKE ? OR abstract LIKE ? OR doi LIKE ?)")
        pattern = f"%{search}%"
        params.extend([pattern, pattern, pattern])
    params.append(int(limit or 100))
    conn = connect(agent_root)
    rows = rows_to_dicts(conn.execute(f'SELECT * FROM "references" WHERE {" AND ".join(clauses)} ORDER BY updated_at DESC LIMIT ?', params).fetchall())
    conn.close()
    return rows


def update_reference(agent_root: Path, reference_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    allowed = {
        "title",
        "year",
        "doi",
        "url",
        "abstract",
        "access_status",
        "source_path",
        "journal",
        "full_text_path",
        "source_provider",
        "search_task_id",
        "research_topic",
        "relevance_score",
        "evidence_level",
        "user_notes",
        "reading_status",
        "paper_type",
        "impact_label",
        "method_relevance",
        "mechanism_relevance",
        "reason_for_inclusion",
        "reason_for_exclusion",
    }
    assignments: list[str] = []
    values: list[Any] = []
    for key, value in payload.items():
        if key == "authors":
            assignments.append("authors_json=?")
            values.append(json_dumps(as_list(value)))
        elif key == "tags":
            assignments.append("tags_json=?")
            values.append(json_dumps(as_list(value)))
        elif key == "protocol_candidates":
            assignments.append("protocol_candidates_json=?")
            values.append(json_dumps(as_list(value)))
        elif key in allowed:
            assignments.append(f"{key}=?")
            values.append(float(value) if key == "relevance_score" and value not in (None, "") else clean(value))
    if not assignments:
        raise ValueError("no supported reference fields to update")
    assignments.append("updated_at=?")
    values.extend([now(), reference_id])
    conn = connect(agent_root)
    conn.execute(f'UPDATE "references" SET {", ".join(assignments)} WHERE id=?', values)
    row = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("reference not found")
    conn.commit()
    conn.close()
    return row


def add_reference_tag(agent_root: Path, reference_id: str, tag: str) -> dict[str, Any]:
    conn = connect(agent_root)
    row = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("reference not found")
    tags = [clean(item) for item in as_list(row.get("tags")) if clean(item)]
    new_tag = clean(tag)
    if new_tag and new_tag not in tags:
        tags.append(new_tag)
    conn.execute('UPDATE "references" SET tags_json=?, updated_at=? WHERE id=?', (json_dumps(tags), now(), reference_id))
    conn.commit()
    saved = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone()) or {}
    conn.close()
    return saved


def add_reference_note(agent_root: Path, reference_id: str, note: str) -> dict[str, Any]:
    conn = connect(agent_root)
    row = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("reference not found")
    existing = clean(row.get("user_notes"))
    stamped = f"{now()}: {clean(note)}"
    combined = "\n".join(item for item in [existing, stamped] if item)
    conn.execute('UPDATE "references" SET user_notes=?, updated_at=? WHERE id=?', (combined, now(), reference_id))
    conn.commit()
    saved = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone()) or {}
    conn.close()
    return saved


