def create_literature_search_task(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    keywords = [str(item) for item in as_list(payload.get("keywords") or payload.get("query")) if clean(item)]
    query = clean(payload.get("query")) or ", ".join(keywords)
    if not query:
        raise ValueError("query or keywords are required")
    provider = clean(payload.get("provider")) or "mock"
    task_id = clean(payload.get("id")) or stable_id(project_id, query, provider, now(), length=24)
    timestamp = now()
    references_payload = payload.get("references") if isinstance(payload.get("references"), list) else []
    imported_refs = []
    if references_payload:
        for reference_payload in references_payload:
            if isinstance(reference_payload, dict):
                imported_refs.append(import_reference(agent_root, {**reference_payload, "project_id": project_id, "search_task_id": task_id, "source_provider": provider, "skill_run_id": clean(payload.get("skill_run_id"))}))
    elif provider in {"mock", "manual", "browser", "browser/manual"}:
        for index, keyword in enumerate(keywords or [query], start=1):
            imported_refs.append(
                import_reference(
                    agent_root,
                    {
                        "project_id": project_id,
                        "title": f"{keyword} methods and evidence seed {index}",
                        "authors": ["ResearchOS mock provider"],
                        "year": str(datetime.now().year),
                        "abstract": f"Mock/manual literature seed for {keyword}. Store real title, DOI, URL, abstract, and access status when available. This placeholder supports local RAG and citation-numbered testing without live web access.",
                        "source_type": f"{provider}_literature_seed",
                        "source_provider": provider,
                        "search_task_id": task_id,
                        "access_status": "metadata_only",
                        "evidence_level": "mock_not_evidence",
                        "impact_label": "unknown",
                        "paper_type": "unknown",
                        "reason_for_inclusion": "Mock/manual placeholder for local workflow testing; replace with real metadata before scientific use.",
                        "metadata": {"provider": provider, "keywords": keywords, "mock_reference": True},
                        "skill_run_id": clean(payload.get("skill_run_id")),
                    },
                )
            )
    reference_ids = [ref["id"] for ref in imported_refs]
    task_status = clean(payload.get("status")) or ("completed" if imported_refs else "draft")
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO literature_search_tasks(
          id, project_id, query, keywords_json, provider, status, result_reference_ids_json, notes, skill_run_id, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          status=excluded.status,
          result_reference_ids_json=excluded.result_reference_ids_json,
          notes=excluded.notes,
          updated_at=excluded.updated_at
        """,
        (
            task_id,
            project_id,
            query,
            json_dumps(keywords),
            provider,
            task_status,
            json_dumps(reference_ids),
            clean(payload.get("notes")),
            clean(payload.get("skill_run_id")),
            timestamp,
            timestamp,
        ),
    )
    if clean(payload.get("skill_run_id")):
        create_link(conn, project_id, "skill_run", clean(payload["skill_run_id"]), "generated", "literature_search_task", task_id, len(reference_ids))
    conn.commit()
    task = row_to_dict(conn.execute("SELECT * FROM literature_search_tasks WHERE id=?", (task_id,)).fetchone()) or {}
    conn.close()
    return {"task": task, "references": imported_refs}


