def update_literature_search_task(
    agent_root: Path,
    task_id: str,
    *,
    status: str | None = None,
    result_reference_ids: list[str] | None = None,
    notes: str | dict[str, Any] | None = None,
) -> dict[str, Any]:
    conn = connect(agent_root)
    row = row_to_dict(conn.execute("SELECT * FROM literature_search_tasks WHERE id=?", (task_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("literature search task not found")
    next_status = status or clean(row.get("status")) or "draft"
    next_refs = result_reference_ids if result_reference_ids is not None else as_list(row.get("result_reference_ids"))
    next_notes = row.get("notes")
    if notes is not None:
        next_notes = json_dumps(notes) if isinstance(notes, dict) else str(notes)
    conn.execute(
        """
        UPDATE literature_search_tasks
        SET status=?, result_reference_ids_json=?, notes=?, updated_at=?
        WHERE id=?
        """,
        (
            next_status,
            json_dumps(next_refs),
            next_notes,
            now(),
            task_id,
        ),
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM literature_search_tasks WHERE id=?", (task_id,)).fetchone()) or {}
    conn.close()
    return saved


def _parse_literature_task_notes(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    text = clean(value)
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except Exception:
        return {"message": str(value)}
    return parsed if isinstance(parsed, dict) else {"value": parsed}


def keyword_harvest_skill_root() -> Path:
    return REPO_ROOT / "skills" / "researchos_skill_library" / "02_literature_browser_ingestion" / "keyword-research-harvest"


def keyword_harvest_runs_root(agent_root: Path, project_id: str) -> Path:
    root = data_dir(agent_root) / "literature_harvest" / (project_id or "unscoped")
    root.mkdir(parents=True, exist_ok=True)
    return root


def safe_keyword_harvest_folder_name(keywords: list[str], query: str = "") -> str:
    keyword_text = "+".join(clean(item) for item in keywords if clean(item)) or clean(query) or "keyword"
    keyword_text = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "_", keyword_text)
    keyword_text = re.sub(r"\s+", "_", keyword_text).strip("._-")
    keyword_text = re.sub(r"_+", "_", keyword_text) or "keyword"
    if len(keyword_text) > 48:
        keyword_text = keyword_text[:48].rstrip("._-")
    return f"{datetime.now().strftime('%Y%m%d')}+{keyword_text}+pdf"


def unique_keyword_harvest_run_root(agent_root: Path, project_id: str, keywords: list[str], query: str = "") -> Path:
    parent = keyword_harvest_runs_root(agent_root, project_id)
    base_name = safe_keyword_harvest_folder_name(keywords, query)
    candidate = parent / base_name
    suffix = 2
    while candidate.exists():
        candidate = parent / f"{base_name}_{suffix}"
        suffix += 1
    candidate.mkdir(parents=True, exist_ok=False)
    return candidate


def normalized_keyword_query(keywords: list[str], query: str = "") -> str:
    cleaned_keywords = [clean(item) for item in keywords if clean(item)]
    explicit_query = clean(query)
    if explicit_query:
        explicit_query = re.sub(r"[\\,，;；]+", " ", explicit_query)
        return re.sub(r"\s+", " ", explicit_query).strip()
    return re.sub(r"\s+", " ", " ".join(cleaned_keywords)).strip()


def find_reusable_keyword_harvest_task(agent_root: Path, project_id: str, provider: str, query: str) -> dict[str, Any] | None:
    normalized_query = clean(query).lower()
    if not project_id or not normalized_query:
        return None
    conn = connect(agent_root)
    rows = rows_to_dicts(
        conn.execute(
            """
            SELECT * FROM literature_search_tasks
            WHERE project_id=? AND provider=?
            ORDER BY updated_at DESC
            LIMIT 30
            """,
            (project_id, provider),
        ).fetchall()
    )
    conn.close()
    for task in rows:
        if normalized_keyword_query([], clean(task.get("query"))).lower() != normalized_query:
            continue
        notes = _parse_literature_task_notes(task.get("notes"))
        phase = clean(notes.get("phase"))
        run_root = Path(clean(notes.get("run_root"))) if clean(notes.get("run_root")) else None
        if not run_root or not run_root.exists():
            continue
        if phase == "cancelled_by_user" or (run_root / ".researchos_cancel").exists():
            continue
        return {"task": task, "notes": notes, "run_root": run_root}
    return None


def build_keyword_harvest_config(payload: dict[str, Any]) -> dict[str, Any]:
    template_path = keyword_harvest_skill_root() / "references" / "config_template.json"
    config = json.loads(template_path.read_text(encoding="utf-8"))
    keywords = [str(item) for item in as_list(payload.get("keywords") or payload.get("query")) if clean(item)]
    query = normalized_keyword_query(keywords, clean(payload.get("query")))
    provider = clean(payload.get("provider")).lower() or "all"
    if provider in {"mock", "manual", "browser", "browser/manual"}:
        provider = "all"
    sources = {key: False for key in (config.get("sources") or {}).keys()}
    if provider in {"all", "real", "default"}:
        for key in sources:
            sources[key] = True
    elif provider == "pubmed":
        sources["pubmed"] = True
        if "pmc" in sources:
            sources["pmc"] = True
    elif provider in sources:
        sources[provider] = True
    else:
        for key in sources:
            sources[key] = True
    config["sources"] = sources
    combined_query = normalized_keyword_query(keywords, query)
    config["queries"] = [{"name": "keyword_1", "query": combined_query}]
    config["include_terms"] = keywords[:]
    config["secondary_terms"] = []
    config["open_access_only"] = payload.get("open_access_only", True) is not False
    if isinstance(config.get("download"), dict):
        config["download"]["timeout_seconds"] = max(int(config["download"].get("timeout_seconds") or 30), 45)
        config["download"]["max_attempts_per_record"] = max(int(config["download"].get("max_attempts_per_record") or 3), 6)
    if payload.get("codex_scale") is not False:
        default_large_limit = int(os.environ.get("RESEARCHOS_HARVEST_MAX_RESULTS_PER_QUERY", "2000"))
        config["max_results_per_query"] = {key: default_large_limit for key in (config.get("max_results_per_query") or {}).keys()}
        if "page_size" in config:
            for key in list(config["page_size"].keys()):
                if key == "openalex":
                    config["page_size"][key] = min(int(config["page_size"].get(key) or 200), 200)
                elif key == "europepmc":
                    config["page_size"][key] = min(max(int(config["page_size"].get(key) or 1000), 1000), 1000)
                elif key == "crossref":
                    config["page_size"][key] = min(max(int(config["page_size"].get(key) or 100), 100), 100)
    max_results = payload.get("max_results_per_query")
    if max_results not in (None, ""):
        try:
            value = max(1, int(max_results))
            config["max_results_per_query"] = {key: value for key in (config.get("max_results_per_query") or {}).keys()}
        except (TypeError, ValueError):
            pass
    config["email"] = os.environ.get("RESEARCHOS_CONTACT_EMAIL", "")
    return config


def expand_literature_query(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    keywords = [str(item) for item in as_list(payload.get("keywords") or payload.get("query")) if clean(item)]
    query = clean(payload.get("query")) or ", ".join(keywords)
    if not keywords and query:
        keywords = [query]
    if not keywords:
        raise ValueError("keywords or query are required")
    project_hint = ""
    if project_id:
        try:
            project = get_project_detail(agent_root, project_id)
            project_hint = f"Project title: {project.get('title','')}\nResearch area: {project.get('research_area','')}"
        except Exception:
            project_hint = ""
    llm = LLMAdapter(prompt_language=clean(payload.get("prompt_language")) or "zh", prompt_policy="literature_rag")
    prompt = "\n".join(
        [
            "You are a scientific literature search planner.",
            "Expand the user's 1-3 seed keywords into a concise literature harvesting query.",
            "Return JSON only with keys: expanded_keywords, query, rationale.",
            "Rules: keep expanded_keywords between 1 and 8 items; do not invent assay domains; keep terms useful for PubMed, EuropePMC, Crossref, and OpenAlex.",
            project_hint,
            f"Seed keywords: {json_dumps(keywords)}",
            f"Original query: {query}",
        ]
    )
    parsed: dict[str, Any] = {}
    llm_error = ""
    try:
        parsed = llm.generate_json(prompt, "literature_query_expansion", prompt_policy="literature_rag")
    except Exception as exc:  # noqa: BLE001
        llm_error = str(exc)
    expanded_keywords = [clean(item) for item in as_list(parsed.get("expanded_keywords")) if clean(item)]
    if not expanded_keywords:
        expanded_keywords = keywords
    expanded_query = clean(parsed.get("query")) or " OR ".join(expanded_keywords)
    return {
        "project_id": project_id,
        "original_keywords": keywords,
        "expanded_keywords": expanded_keywords[:8],
        "query": expanded_query,
        "rationale": clean(parsed.get("rationale")),
        "llm": {"provider": llm.provider, "model": llm.model, "mode": llm.mode, "called": llm.mode != "mock", "error": llm_error},
        "raw": {key: value for key, value in parsed.items() if key.startswith("_") or key in {"raw_output"}},
    }


def _read_csv_rows(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        return []
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        return [{str(key): str(value or "") for key, value in row.items()} for row in reader]


def keyword_harvest_task_log_path(agent_root: Path, task_id: str) -> Path:
    path = agent_root / "logs" / "literature_harvest" / f"{clean(task_id) or 'task'}.log"
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def read_text_tail(path: Path, limit: int = 6000) -> str:
    if not path.exists():
        return ""
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return ""
    return text[-limit:]


def _latest_rows_by_key(rows: list[dict[str, str]], key: str) -> dict[str, dict[str, str]]:
    latest: dict[str, dict[str, str]] = {}
    for row in rows:
        value = clean(row.get(key))
        if value:
            latest[value] = row
    return latest


def _keyword_harvest_work_path(run_root: Path, legacy_name: str, work_name: str | None = None) -> Path:
    modern = run_root / "_work" / (work_name or legacy_name)
    if modern.exists():
        return modern
    return run_root / legacy_name


def literature_ingest_item_id(task_id: str, record_id: str) -> str:
    return stable_id(task_id, record_id, "literature_ingest_item", length=24)


def upsert_literature_ingest_item(agent_root: Path, item: dict[str, Any]) -> dict[str, Any]:
    timestamp = now()
    task_id = clean(item.get("task_id"))
    record_id = clean(item.get("record_id"))
    if not task_id or not record_id:
        raise ValueError("task_id and record_id are required")
    item_id = clean(item.get("id")) or literature_ingest_item_id(task_id, record_id)
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO literature_ingest_items(
          id, task_id, project_id, record_id, reference_id, title, doi, pdf_path,
          download_status, ingest_status, chunks_count, error, failed_stage,
          retry_available, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(task_id, record_id) DO UPDATE SET
          reference_id=COALESCE(NULLIF(excluded.reference_id,''), literature_ingest_items.reference_id),
          title=COALESCE(NULLIF(excluded.title,''), literature_ingest_items.title),
          doi=COALESCE(NULLIF(excluded.doi,''), literature_ingest_items.doi),
          pdf_path=COALESCE(NULLIF(excluded.pdf_path,''), literature_ingest_items.pdf_path),
          download_status=COALESCE(NULLIF(excluded.download_status,''), literature_ingest_items.download_status),
          ingest_status=COALESCE(NULLIF(excluded.ingest_status,''), literature_ingest_items.ingest_status),
          chunks_count=MAX(COALESCE(excluded.chunks_count, 0), COALESCE(literature_ingest_items.chunks_count, 0)),
          error=excluded.error,
          failed_stage=excluded.failed_stage,
          retry_available=excluded.retry_available,
          updated_at=excluded.updated_at
        """,
        (
            item_id,
            task_id,
            clean(item.get("project_id")),
            record_id,
            clean(item.get("reference_id")),
            clean(item.get("title")),
            clean(item.get("doi")),
            clean(item.get("pdf_path")),
            clean(item.get("download_status")) or "pending",
            clean(item.get("ingest_status")) or "pending",
            int(item.get("chunks_count") or 0),
            clean(item.get("error")),
            clean(item.get("failed_stage")),
            1 if item.get("retry_available") else 0,
            timestamp,
            timestamp,
        ),
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM literature_ingest_items WHERE task_id=? AND record_id=?", (task_id, record_id)).fetchone()) or {}
    conn.close()
    return saved


def list_literature_ingest_items(agent_root: Path, task_id: str = "", project_id: str = "", limit: int = 5000) -> list[dict[str, Any]]:
    clauses = ["1=1"]
