def explicit_longform_request(message: str) -> bool:
    lower = message.lower()
    return any(term in lower for term in ["详细", "展开", "长文", "文档", "报告", "bp", "技术设计", "架构", "机制", "prompt", "documentation", "detailed", "explain"])


def polish_user_facing_answer(answer: str, message: str = "") -> str:
    text = clean(answer)
    if not text or explicit_longform_request(message):
        return text
    text = re.sub(r"\*\*(.*?)\*\*", r"\1", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    text = re.sub(r"(^|\n)\s{0,3}#{1,6}\s*", r"\1", text)
    text = text.replace("模型推断", "基于通用知识")
    text = text.replace("当前会话未提供具体文献列表", "当前项目里没有找到可用文献列表")
    text = text.replace("当前会话未提供", "当前项目里没有找到")
    text = text.replace("系统状态", "当前项目状态")
    text = text.replace("知识库尚无", "当前项目还没有")
    text = text.replace("尚无实验或文献记录", "还没有可引用的实验或文献记录")
    text = re.sub(r"(?m)^\s*[-*]\s+", "", text)
    text = re.sub(r"(?m)^\s*\d+[.)、]\s+", "", text)
    text = re.sub(r"\s+[-*]\s+", "。", text)
    text = re.sub(r"\s+\d+[.)、]\s+", "。", text)
    text = re.sub(r"\s*：\s*", "：", text)
    if len(text) > 850:
        parts = re.split(r"(?<=[。！？])", text)
        shortened = ""
        for part in parts:
            if len(shortened) + len(part) > 780:
                break
            shortened += part
        text = shortened.strip() or text[:780].rstrip()
    return clean(text)


SUPERSCRIPT_DIGITS = {
    "0": "⁰",
    "1": "¹",
    "2": "²",
    "3": "³",
    "4": "⁴",
    "5": "⁵",
    "6": "⁶",
    "7": "⁷",
    "8": "⁸",
    "9": "⁹",
}


def superscript_number(value: int) -> str:
    return "".join(SUPERSCRIPT_DIGITS.get(ch, ch) for ch in str(int(value)))


def normalize_citation_title(value: str) -> str:
    return re.sub(r"\W+", " ", clean(value).lower()).strip()


def citation_source_key(data: dict[str, Any]) -> str:
    for key in ["doi", "pmid", "reference_id", "document_id", "file_path", "pdf_filename", "display_title"]:
        value = clean(data.get(key))
        if value:
            return f"{key}:{normalize_citation_title(value) if key == 'display_title' else value.lower()}"
    return f"source:{clean(data.get('source_id'))}"


def citation_from_reference_row(row: dict[str, Any], source: dict[str, Any]) -> dict[str, Any]:
    authors = row.get("authors")
    if not authors:
        authors = json_loads(row.get("authors_json"), [])
    if isinstance(authors, list):
        authors_text = ", ".join(clean(item) for item in authors if clean(item))[:240]
    else:
        authors_text = clean(authors)
    file_path = clean(row.get("full_text_path") or row.get("source_path"))
    return {
        "source_type": "pdf" if file_path.lower().endswith(".pdf") else "reference",
        "display_title": clean(row.get("title")) or clean(source.get("title")) or clean(source.get("reference_id")) or clean(source.get("chunk_id")),
        "subtitle": clean(row.get("journal") or row.get("source_provider") or row.get("source_type")),
        "authors": authors_text,
        "year": clean(row.get("year")),
        "journal": clean(row.get("journal")),
        "doi": clean(row.get("doi")),
        "pmid": clean((row.get("metadata") or {}).get("pmid") if isinstance(row.get("metadata"), dict) else ""),
        "pdf_filename": Path(file_path).name if file_path else "",
        "file_path": file_path,
        "page": source.get("page"),
        "excerpt": clean(source.get("excerpt")),
        "reference_id": clean(row.get("id") or source.get("reference_id")),
        "document_id": "",
        "chunk_ids": [clean(source.get("chunk_id"))] if clean(source.get("chunk_id")) else [],
        "confidence": float(source.get("confidence") or 0.75),
        "openable": bool(file_path and Path(file_path).exists()),
        "excerpts": [clean(source.get("excerpt"))] if clean(source.get("excerpt")) else [],
    }


def build_evidence_citations(agent_root: Path, project_id: str, sources: list[dict[str, Any]], memory_used: list[dict[str, Any]] | None = None) -> list[dict[str, Any]]:
    citations_by_key: dict[str, dict[str, Any]] = {}
    conn = connect(agent_root)
    try:
        for source in sources:
            source = source if isinstance(source, dict) else {}
            source_kind = clean(source.get("source_kind"))
            chunk_id = clean(source.get("chunk_id"))
            reference_id = clean(source.get("reference_id"))
            kb_row: dict[str, Any] = {}
            chunk_row: dict[str, Any] = {}
            ref_row: dict[str, Any] = {}
            if chunk_id:
                chunk_row = row_to_dict(conn.execute("SELECT * FROM reference_chunks WHERE id=?", (chunk_id,)).fetchone()) or {}
                if not chunk_row:
                    kb_row = row_to_dict(conn.execute("SELECT * FROM knowledge_base_entries WHERE id=?", (chunk_id,)).fetchone()) or {}
                    reference_id = reference_id or clean(kb_row.get("source_reference_id"))
                    chunk_id = clean(kb_row.get("source_chunk_id")) or chunk_id
                else:
                    reference_id = reference_id or clean(chunk_row.get("reference_id"))
            if reference_id:
                ref_row = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone()) or {}
            if ref_row:
                enriched = dict(source)
                enriched["chunk_id"] = chunk_id
                if chunk_row.get("page_number"):
                    enriched["page"] = chunk_row.get("page_number")
                citation = citation_from_reference_row(ref_row, enriched)
            elif kb_row:
                metadata = kb_row.get("metadata") if isinstance(kb_row.get("metadata"), dict) else {}
                citation = {
                    "source_type": "kb_entry",
                    "display_title": clean(kb_row.get("title")) or clean(source.get("title")) or clean(kb_row.get("id")),
                    "subtitle": clean(kb_row.get("entry_type")),
                    "authors": "",
                    "year": "",
                    "journal": "",
                    "doi": "",
                    "pmid": "",
                    "pdf_filename": clean(metadata.get("pdf_filename")),
                    "file_path": clean(metadata.get("file_path")),
                    "page": metadata.get("page"),
                    "excerpt": clean(source.get("excerpt") or kb_row.get("content"))[:500],
                    "reference_id": clean(kb_row.get("source_reference_id")),
                    "document_id": clean(metadata.get("document_id")),
                    "chunk_ids": [chunk_id] if chunk_id else [],
                    "confidence": 0.65,
                    "openable": bool(clean(metadata.get("file_path")) and Path(clean(metadata.get("file_path"))).exists()),
                    "excerpts": [clean(source.get("excerpt") or kb_row.get("content"))[:500]],
                }
            elif source_kind in {"experiment", "experiment_log", "data_file", "memory", "memory_entity", "agent_memory", "project_memory", "project_conclusion", "project_decision", "failure_memory"}:
                citation = {
                    "source_type": "memory" if "memory" in source_kind or source_kind in {"project_conclusion", "project_decision"} else source_kind,
                    "display_title": clean(source.get("title")) or clean(source.get("id")) or "Project evidence",
                    "subtitle": source_kind,
                    "authors": "",
                    "year": "",
                    "journal": "",
                    "doi": "",
                    "pmid": "",
                    "pdf_filename": "",
                    "file_path": "",
                    "page": None,
                    "excerpt": clean(source.get("excerpt")),
                    "reference_id": "",
                    "document_id": "",
                    "chunk_ids": [chunk_id] if chunk_id else [],
                    "confidence": 0.6,
                    "openable": False,
                    "excerpts": [clean(source.get("excerpt"))] if clean(source.get("excerpt")) else [],
                }
            else:
                citation = {
                    "source_type": "reference" if reference_id else "kb_entry",
                    "display_title": clean(source.get("title")) or reference_id or chunk_id or "Evidence source",
                    "subtitle": clean(source_kind),
                    "authors": "",
                    "year": "",
                    "journal": "",
                    "doi": "",
                    "pmid": "",
                    "pdf_filename": "",
                    "file_path": "",
                    "page": source.get("page"),
                    "excerpt": clean(source.get("excerpt")),
                    "reference_id": reference_id,
                    "document_id": "",
                    "chunk_ids": [chunk_id] if chunk_id else [],
                    "confidence": 0.5,
                    "openable": False,
                    "excerpts": [clean(source.get("excerpt"))] if clean(source.get("excerpt")) else [],
                }
            key = citation_source_key(citation)
            existing = citations_by_key.get(key)
            if existing:
                for field in ["display_title", "pdf_filename", "file_path", "doi", "pmid", "reference_id", "document_id", "year", "journal"]:
                    if not clean(existing.get(field)) and clean(citation.get(field)):
                        existing[field] = citation.get(field)
                existing_ids = set(existing.get("chunk_ids") or [])
                for chunk in citation.get("chunk_ids") or []:
                    if clean(chunk) and clean(chunk) not in existing_ids:
                        existing.setdefault("chunk_ids", []).append(clean(chunk))
                        existing_ids.add(clean(chunk))
                existing_excerpts = {clean(item) for item in existing.get("excerpts") or []}
                for excerpt in citation.get("excerpts") or []:
                    excerpt = clean(excerpt)
                    if excerpt and excerpt not in existing_excerpts:
                        existing.setdefault("excerpts", []).append(excerpt)
                        existing_excerpts.add(excerpt)
                if not clean(existing.get("excerpt")) and citation.get("excerpt"):
                    existing["excerpt"] = citation["excerpt"]
            else:
                citations_by_key[key] = citation
    finally:
        conn.close()
    citations = list(citations_by_key.values())
    for index, citation in enumerate(citations, start=1):
        citation["citation_id"] = index
        fallback_title = clean(citation.get("display_title") or citation.get("pdf_filename") or citation.get("reference_id") or citation.get("document_id") or (citation.get("chunk_ids") or [""])[0] or "Evidence source")
        citation["display_title"] = fallback_title
        citation["excerpt"] = clean(citation.get("excerpt") or (citation.get("excerpts") or [""])[0])[:700]
        citation["excerpts"] = [clean(item)[:700] for item in (citation.get("excerpts") or []) if clean(item)][:5]
    return citations[:12]


def strip_inline_source_dump(answer: str) -> str:
    text = answer
    text = re.sub(r"(?is)\n?\s*(来源|参考来源|sources?|references?)\s*[:：].*$", "", text).strip()
    text = re.sub(r"\b(?:chunk|reference|document|kb_entry)_?id\s*[:：=]\s*[\w\-]+", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\[[Cc]hunk[:： ]*[^\]]+\]", "", text)
    return clean(text)


def answer_has_citation_markers(answer: str) -> bool:
    return bool(re.search(r"[¹²³⁴⁵⁶⁷⁸⁹⁰]|\[\d+\]", answer))


def ensure_answer_citations(answer: str, citations: list[dict[str, Any]], message: str = "") -> str:
    text = strip_inline_source_dump(answer)
    if not citations or explicit_longform_request(message):
        return text
    text = re.sub(r"\[(\d+)\]", lambda m: superscript_number(int(m.group(1))), text)
    markers = re.findall(r"([¹²³⁴⁵⁶⁷⁸⁹⁰]+)", text)
    marker_numbers = [clean(marker.translate(str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹", "0123456789"))) for marker in markers]
    unique_markers = {number for number in marker_numbers if number}
    if answer_has_citation_markers(text) and (len(citations) <= 1 or len(unique_markers) > 1):
        return text
    if len(citations) > 1 and unique_markers == {"1"}:
        text = re.sub(r"[¹²³⁴⁵⁶⁷⁸⁹⁰]+", "", text)
    sentences = re.split(r"(?<=[。！？!?])|(?<=[.!?])\s+", text)
    sentences = [item for item in sentences if clean(item)]
    if not sentences:
        return text + superscript_number(1)
    max_markers = min(len(citations), 3, len(sentences))
    for index in range(max_markers):
        marker = superscript_number(index + 1)
        if marker not in sentences[index]:
            sentences[index] = sentences[index].rstrip() + marker
    return clean("".join(sentences))


def agent_next_actions(intent: str, workspace: dict[str, Any] | None = None, task_status: list[dict[str, Any]] | None = None) -> list[dict[str, str]]:
    workspace = workspace or {}
    literature = workspace.get("literature") or {}
    diagnostics = workspace.get("workspace_diagnostics") or {}
    actions: list[dict[str, str]] = []
    if diagnostics.get("warnings"):
        actions.append({"label": "检查文献归属", "intent": "workspace_diagnostics", "description": "当前项目可能没有拿到已采集文献，先确认资产是否挂错项目。"})
    if intent in {"kb_query", "research_advice"}:
        if int(literature.get("references_count") or 0) or int(literature.get("chunks_count") or 0):
            actions.append({"label": "总结已入库文献", "intent": "summarize_literature", "description": "基于当前项目的 references 和 chunks 做归纳。"})
        else:
            actions.append({"label": "启动文献采集", "intent": "start_literature_harvest", "description": "输入 1-3 个关键词，先建立本项目知识库。"})
    if intent in {"task_status_query", "start_skill_request"} or task_status:
        actions.append({"label": "刷新任务进度", "intent": "refresh_task_status", "description": "查看下载、解析、入库的真实进度。"})
    if intent in {"proactive_status_query", "project_status_query"}:
        actions.append({"label": "刷新任务进度", "intent": "refresh_task_status", "description": "查看下载、解析、入库的真实进度。"})
    if intent in {"research_advice", "project_status_query", "project_status"}:
        actions.append({"label": "生成下一步实验", "intent": "next_experiment", "description": "基于当前证据和缺口给出可执行实验路线。"})
    actions.append({"label": "写入项目记忆", "intent": "save_to_memory", "description": "把确认后的结论或决策保存到当前项目。"})
    seen: set[str] = set()
    unique: list[dict[str, str]] = []
    for action in actions:
        label = action["label"]
        if label not in seen:
            seen.add(label)
            unique.append(action)
    return unique[:4]


PROFILE_UPDATE_INTENTS = {"user_profile_update", "project_profile_update", "research_direction_update", "active_project_update"}
PROFILE_QUERY_INTENTS = {"user_profile_query", "project_profile_query"}


def is_user_profile_query_message(message: str) -> bool:
    lower = clean(message).lower()
    return any(term in lower for term in ["我叫什么", "我的名字是什么", "我是谁"])


def is_project_profile_query_message(message: str) -> bool:
    lower = clean(message).lower()
    return any(term in lower for term in ["我现在做什么课题", "我做什么课题", "当前课题是什么", "我的课题是什么"])


def is_current_topic_intro_request(message: str) -> bool:
    lower = clean(message).lower()
    return any(term in lower for term in ["介绍一下这个课题", "介绍这个课题", "讲讲这个课题", "这个课题是什么"])


def extract_profile_update(message: str) -> dict[str, Any]:
    text = clean(message)
    if not text:
        return {}

    def first_match(patterns: list[str]) -> str:
        for pattern in patterns:
            match = re.search(pattern, text, flags=re.IGNORECASE)
            if match:
                value = clean(match.group(1))
                value = re.sub(r"^(是|叫|为)\s*", "", value).strip()
                value = re.sub(r"(请记住|记住)$", "", value).strip()
                if value:
                    return value
        return ""

    user_name = _explicit_user_name_from_message(text)
    research_direction = first_match(
        [
            r"我在研究(.+?)(?=，|,|。|；|;|我目前|我的|我现在|$)",
            r"我的方向是(.+?)(?=，|,|。|；|;|我目前|我的|我现在|$)",
            r"研究方向是(.+?)(?=，|,|。|；|;|我目前|我的|我现在|$)",
        ]
    )
    project_topic = first_match(
        [
            r"我目前的课题是(.+?)(?=，|,|。|；|;|$)",
            r"我的课题是(.+?)(?=，|,|。|；|;|$)",
            r"当前课题是(.+?)(?=，|,|。|；|;|$)",
            r"我现在做的是(.+?)(?=，|,|。|；|;|$)",
        ]
    )
    preference = first_match(
        [
            r"以后围绕(.+?)回答",
            r"记住[:：]?\s*(.+?)(?=。|$)",
        ]
    )
    role = first_match([r"我是(.+?)(?=，|,|。|；|;|我在|我的|我目前|$)"]) if not user_name else ""
    keywords: list[str] = []
    for value in [research_direction, project_topic]:
        for token in re.split(r"[ /\\,，;；、]+", value):
            token = clean(token)
            if token and token not in keywords:
                keywords.append(token)
    return {
        "user_name": user_name,
        "role": role,
        "research_direction": research_direction,
        "project_topic": project_topic,
        "preference": preference,
        "project_keywords": keywords[:8],
    }


def is_profile_update_message(message: str) -> bool:
    gate = classify_memory_candidate(message, {})
    if gate["memory_layer"] == "session_context":
        return False
    profile = extract_profile_update(message)
    return any(clean(profile.get(key)) for key in ["user_name", "research_direction", "project_topic", "preference"])


def is_literature_collection_title(title: str) -> bool:
    value = clean(title)
    if not value:
        return False
    if re.fullmatch(r"[A-Za-z]{1,8}[-_.]?\d+(?:\.\d+)?", value):
        return True
    if re.fullmatch(r"[A-Za-z0-9_.+-]{2,30}", value) and any(ch.isdigit() for ch in value):
        return True
    lowered = value.lower()
    return any(term in lowered for term in ["literature", "文献库", "文献采集"])


def is_generic_project_title(title: str) -> bool:
    lowered = clean(title).lower()
    if not lowered:
        return True
    generic_terms = ["untitled", "test wet lab project", "research task", "aura research", "默认项目", "新项目", "测试项目"]
    return any(term in lowered for term in generic_terms)


def load_profile_memory_snapshot(agent_root: Path, project_id: str) -> dict[str, Any]:
    entries = list_agent_memory(agent_root, scope="project", project_id=project_id, include_disabled=False).get("entries", [])
    snapshot: dict[str, Any] = {}
    for entry in reversed(entries):
        if entry.get("memory_type") not in {"user_profile", "project_profile", "research_preference"}:
            continue
        structured = entry.get("structured_content") if isinstance(entry.get("structured_content"), dict) else {}
        snapshot.update({key: value for key, value in structured.items() if clean(value) or isinstance(value, list)})
    return snapshot


def save_profile_project_update(agent_root: Path, project_id: str, message: str, conversation_id: str = "") -> dict[str, Any]:
    profile = extract_profile_update(message)
    gate = classify_memory_candidate(message, {"project_id": project_id, "source_refs": [{"type": "user_message", "id": conversation_id, "text": message}]})
    project = get_project_detail(agent_root, project_id)
    current_title = clean(project.get("title"))
    topic = clean(profile.get("project_topic"))
    direction = clean(profile.get("research_direction"))
    timestamp = now()
    memories: list[dict[str, Any]] = []

    if (clean(profile.get("user_name")) and gate["memory_layer"] == "user_profile" and gate["should_save"]) or clean(profile.get("preference")):
        memories.append(
            create_agent_memory_entry(
                agent_root,
                {
                    "id": stable_id(project_id, "user_profile", length=24),
                    "memory_scope": "project",
                    "project_id": project_id,
                    "memory_type": "user_profile",
                    "title": "用户画像",
                    "content": "用户提供的稳定身份和偏好信息。",
                    "structured_content": {
                        "user_name": clean(profile.get("user_name")),
                        "role": clean(profile.get("role")),
                        "research_direction": direction,
                        "preference": clean(profile.get("preference")),
                        "updated_from_message": message,
                    },
                    "source_type": "user_message",
                    "source_id": conversation_id or stable_id(project_id, message, timestamp, length=24),
                    "provenance": [{"source": "agent_chat", "message": message, "created_at": timestamp}],
                    "confidence": 0.95,
                    "trust_level": "user_confirmed",
                    "status": "active",
                },
            )
        )

    if topic or direction:
        memories.append(
            create_agent_memory_entry(
                agent_root,
                {
                    "id": stable_id(project_id, "project_profile", length=24),
                    "memory_scope": "project",
                    "project_id": project_id,
                    "memory_type": "project_profile",
                    "title": "当前课题画像",
                    "content": topic or direction,
                    "structured_content": {
                        "project_title": topic,
                        "research_direction": direction,
                        "project_keywords": profile.get("project_keywords") or [],
                        "model_or_keyword": "",
                        "literature_collection_name": current_title if is_literature_collection_title(current_title) else "",
                        "updated_from_message": message,
                    },
                    "source_type": "user_message",
                    "source_id": conversation_id or stable_id(project_id, message, timestamp, length=24),
                    "provenance": [{"source": "agent_chat", "message": message, "created_at": timestamp}],
                    "confidence": 0.95,
                    "trust_level": "user_confirmed",
                    "status": "active",
                },
            )
        )

    conflict = False
    if topic:
        current_lower = current_title.lower()
        topic_lower = topic.lower()
        if current_title and not is_generic_project_title(current_title) and topic_lower not in current_lower and current_lower not in topic_lower:
            conflict = True
        elif is_generic_project_title(current_title):
            project = update_project(
                agent_root,
                project_id,
                {
                    "title": topic,
                    "short_description": topic,
                    "research_area": direction or project.get("research_area", ""),
                    "keywords": profile.get("project_keywords") or as_list(project.get("keywords")),
                },
            )
    elif direction:
        project = update_project(
            agent_root,
            project_id,
            {
                "research_area": direction,
                "keywords": profile.get("project_keywords") or as_list(project.get("keywords")),
            },
        )

    return {"profile": profile, "project": project, "memories": memories, "project_conflict": conflict, "current_project_title": current_title}


def format_profile_update_answer(result: dict[str, Any]) -> str:
    profile = result.get("profile") or {}
    user_name = clean(profile.get("user_name"))
    direction = clean(profile.get("research_direction"))
    topic = clean(profile.get("project_topic"))
    current_title = clean(result.get("current_project_title"))
    if result.get("project_conflict") and topic:
        return f"我已记录你的课题信息。不过当前客户端项目显示为 {current_title}，是否要把“{topic}”设为当前项目？"
    parts: list[str] = []
    if user_name:
        parts.append(f"你叫{user_name}")
    if direction:
        parts.append(f"当前研究方向是{direction}")
    if topic:
        parts.append(f"课题是{topic}")
    if not parts:
        return "好的，我已记录这条长期偏好。"
    return f"好的，我已记录：{'，'.join(parts)}。后续我会优先围绕这个项目整理文献、实验记录和项目记忆。"


def format_profile_query_answer(agent_root: Path, project_id: str, intent: str) -> str:
    snapshot = load_profile_memory_snapshot(agent_root, project_id)
    if intent == "user_profile_query":
        user_name = clean(snapshot.get("user_name"))
        return f"你叫{user_name}。" if user_name else "我还没有记录你的姓名。"
    topic = clean(snapshot.get("project_title") or snapshot.get("project_topic"))
    direction = clean(snapshot.get("research_direction"))
    if topic:
        return f"你目前的课题是{topic}。"
    if direction:
        return f"你目前的研究方向是{direction}。"
    return "我还没有记录你的当前课题。"


