    literature_terms = ["paper", "papers", "literature", "article", "articles", "pdf", "文献", "论文", "关键词", "关键字"]
    has_action = any(term in lower for term in action_terms) or any(term in text for term in chinese_actions)
    has_literature_object = any(term in lower for term in literature_terms) or any(term in text for term in literature_terms)
    has_keyword_list = bool(extract_literature_keywords_from_message(message))
    return has_action and (has_literature_object or has_keyword_list)


