def task_type_for_agent_intent(intent: str, message: str) -> str:
    lower = message.lower()
    if intent in {"kb_query", "start_skill_request"}:
        return "weekly_literature_digest" if any(term in lower for term in ["周报", "digest", "推送"]) else "literature_mining"
    if intent == "skill_learning_request":
        return "memory_update"
    if intent in {"memory_query", "project_status_query", "project_status", "proactive_status_query"}:
        return "memory_update"
    if any(term in lower for term in ["实验", "experiment", "sample", "样品"]):
        return "experiment_log_structuring" if any(term in lower for term in ["记录", "复盘", "log"]) else "data_contextualization"
    if any(term in lower for term in ["写", "论文", "manuscript", "introduction", "discussion", "结果"]):
        return "result_narrative" if any(term in lower for term in ["结果", "result"]) else "manuscript_draft"
    if any(term in lower for term in ["周报", "weekly", "进展", "summary", "总结"]):
        return "weekly_report"
    return prompt_router.infer_task_type(user_message=message)


def extract_literature_keywords_from_message(message: str) -> list[str]:
    text = clean(message)
    if not text:
        return []
    if is_self_description_or_architecture_message(message) or is_capability_explanation_message(message) or is_autonomous_learning_question(message) or is_paper_recommendation_message(message):
        return []
    blocked_patterns = [
        "你学到了什么",
        "学到了什么",
        "有什么高分文献值得读",
        "高分文献值得读",
        "有什么文献值得读",
        "你怎么看",
        "给我讲讲",
        "生成周报",
        "纳入项目记忆",
        "保存刚才",
        "保存",
    ]
    lower = text.lower()
    if any(pattern in text for pattern in blocked_patterns) or any(pattern in lower for pattern in ["what have you learned", "what did you learn", "worth reading", "high quality papers", "recommend papers", "generate weekly digest", "save previous"]):
        return []
    text = re.sub(r"(?i)\b(?:i\s+want\s+to|please|pls|help\s+me|can\s+you|could\s+you|let'?s)\b", " ", text)
    text = re.sub(r"(?i)\b(?:search|find|collect|harvest|download|start|begin|run|use)\b", " ", text)
    text = re.sub(r"(?i)\b(?:papers?|literature|pdfs?|articles?|keywords?|terms?|these|three|two|one)\b", " ", text)
    text = re.sub(r"(帮我|请|用|根据|开始|启动|下载|抓取|采集|搜索|检索|查找|文献|论文|关键词|关键字|这几个|三个|两个|一个|一下|任务)", " ", text)
    text = re.sub(r"(?i)\b(?:for|about|on|with)\b\s*[:：]?", " ", text)
    pieces = [clean(part) for part in re.split(r"[、，,;；\n\r/\\]+", text) if clean(part)]
    stop = {"和", "的", "以及", "and", "or", "to", "for", "about", "on", "with", "the", "a", "an", "skill", "directly", "now", "ahead"}
    keywords: list[str] = []
    for piece in pieces:
        piece = re.sub(r"(?i)\b(?:keywords?|terms?|papers?|literature|articles?|three|two|one)\b.*$", "", piece).strip()
        piece = re.sub(r"(关键词|关键字|文献|论文).*$", "", piece).strip()
        piece = re.sub(r"^(?:and|or|以及|和)\s+", "", piece, flags=re.IGNORECASE).strip()
        piece = clean(piece.strip(" .:：。；;，,、"))
        if not piece or piece.lower() in stop:
            continue
        if piece not in keywords:
            keywords.append(piece)
    return keywords[:8]


def normalize_literature_keyword_display(keyword: str) -> str:
    value = clean(keyword)
    value = re.sub(r"(?i)(^|[\s,，、;；/\\])mmune regulation", r"\1immune regulation", value)
    return value


def display_literature_keywords(value: Any) -> list[str]:
    keywords: list[str] = []
    for item in as_list(value):
        for part in re.split(r"[,，、;；/\\\n]+", clean(item)):
            keyword = normalize_literature_keyword_display(part)
            if keyword and keyword not in keywords:
                keywords.append(keyword)
    return keywords


def normalize_literature_query_display(query: str) -> str:
    return normalize_literature_keyword_display(query)


def message_has_literature_keyword_intent(message: str) -> bool:
    lower = clean(message).lower()
    return bool(
        any(term in lower for term in ["search", "find", "collect", "harvest", "literature", "paper", "papers", "keyword", "keywords"])
        or any(term in clean(message) for term in ["搜索", "检索", "查找", "采集", "文献", "论文", "关键词", "关键字"])
    )


def is_direct_literature_start_message(message: str) -> bool:
    lower = clean(message).lower()
    return any(
        term in lower
        for term in [
            "directly start",
            "start directly",
            "start now",
            "begin",
            "go ahead",
            "search these keywords",
            "collect literature for these keywords",
            "collect papers for these keywords",
            "开始采集",
            "直接开始",
            "开始吧",
        ]
    )


def latest_literature_keywords_from_history(messages: list[dict[str, Any]]) -> list[str]:
    for message in reversed(messages):
        metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else json_loads(message.get("metadata_json"), {})
        if not isinstance(metadata, dict):
            continue
        if clean(metadata.get("intent")) not in {"literature_harvest_prepare", "start_skill_request"}:
            continue
        keywords = display_literature_keywords(metadata.get("literature_keywords") or metadata.get("last_literature_keywords"))
        if keywords:
            return keywords[:8]
    return []


def literature_task_counters(progress: dict[str, Any]) -> dict[str, int]:
    return {
        "found": int(progress.get("total") or progress.get("candidate_count") or 0),
        "downloaded": int(progress.get("downloaded") or progress.get("downloaded_count") or progress.get("pdf_count") or 0),
        "parsed": int(progress.get("parsed") or progress.get("parsed_count") or 0),
        "ingested": int(progress.get("ingested") or progress.get("indexed") or progress.get("indexed_count") or 0),
        "failed": int(progress.get("failed") or progress.get("ingest_failed_count") or 0),
    }


def normalize_literature_current_stage(status: str, progress: dict[str, Any]) -> str:
    status = clean(status).lower()
    if status in {"completed", "failed", "paused"}:
        return status
    raw = clean(progress.get("current_stage") or progress.get("phase")).lower()
    mapping = {
        "queued": "initializing",
        "pending": "downloading",
        "parsing": "parsing",
        "chunking": "parsing",
        "chunked": "ingesting_to_kb",
        "indexing": "ingesting_to_kb",
        "indexed": "completed",
        "second_pass": "downloading",
        "cancelled_by_user": "paused",
    }
    counters = literature_task_counters(progress)
    if raw in mapping:
        stage = mapping[raw]
    elif raw:
        stage = raw
    elif counters["found"] == 0:
        stage = "searching"
    elif counters["downloaded"] == 0:
        stage = "collecting_candidates"
    elif counters["parsed"] == 0:
        stage = "downloading"
    elif counters["ingested"] < counters["parsed"]:
        stage = "ingesting_to_kb"
    else:
        stage = "searching"
    if status == "running" and counters == {"found": 0, "downloaded": 0, "parsed": 0, "ingested": 0, "failed": 0}:
        return "searching"
    return stage


def _literature_sentences(text: str, limit: int = 8) -> list[str]:
    cleaned = clean(text)
    if not cleaned:
        return []
    parts = re.split(r"(?<=[.!?。！？])\s+", cleaned)
    sentences = [clean(part) for part in parts if len(clean(part)) > 20]
    return sentences[:limit]


def _extract_present_terms(text: str, candidates: list[str]) -> list[str]:
    lower = text.lower()
    found: list[str] = []
    for term in candidates:
        value = clean(term)
        if value and value.lower() in lower and value not in found:
            found.append(value)
    return found


def _evidence_sentences(text: str, focus_terms: list[str], limit: int = 3) -> list[str]:
    sentences = _literature_sentences(text, limit=12)
    if not sentences:
        return []
    focus_lower = [term.lower() for term in focus_terms if clean(term)]
    signal_words = ["suggest", "show", "indicat", "reduce", "increase", "activate", "inhibit", "measure", "assess", "suppress", "promote"]
    ranked = []
    for sentence in sentences:
        lower = sentence.lower()
        score = sum(1 for term in focus_lower if term in lower) + sum(1 for word in signal_words if word in lower)
        ranked.append((score, sentence))
    ranked.sort(key=lambda item: item[0], reverse=True)
    selected = [sentence for score, sentence in ranked if score > 0][:limit]
    return selected or sentences[:limit]


def _short_matched_excerpt(text: str, limit: int = 300) -> str:
    excerpt = clean(text)
    if len(excerpt) <= limit:
        return excerpt
    return excerpt[:limit].rstrip() + "..."


def _rank_source_anchors_for_claim(claim: str, source_anchors: list[dict[str, Any]]) -> list[dict[str, Any]]:
    claim_tokens = rag_tokens(claim)
    ranked: list[tuple[int, int, dict[str, Any]]] = []
    for index, anchor in enumerate(source_anchors):
        anchor_text = " ".join(clean(anchor.get(key)) for key in ["matched_excerpt", "supports"])
        overlap = len(claim_tokens.intersection(rag_tokens(anchor_text))) if claim_tokens else 0
        ranked.append((overlap, -index, anchor))
    ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return [anchor for _, _, anchor in ranked]


def build_source_anchored_key_points(claims: list[str], source_anchors: list[dict[str, Any]], max_anchors_per_claim: int = 2) -> list[dict[str, Any]]:
    points: list[dict[str, Any]] = []
    for claim in [clean(item) for item in claims if clean(item)]:
        ranked = _rank_source_anchors_for_claim(claim, source_anchors)
        selected = ranked[:max(1, int(max_anchors_per_claim or 2))] if ranked else []
        points.append(
            {
                "claim": claim,
                "evidence_level": "supported_by_source" if selected else "unsupported_by_retrieved_chunks",
                "source_anchors": selected,
            }
        )
    return points


def _supporting_source_anchors(
    chunk_rows: list[dict[str, Any]],
    kb_rows: list[dict[str, Any]],
    row: dict[str, Any],
    claims: list[str],
    focus_terms: list[str],
    limit: int = 3,
) -> list[dict[str, Any]]:
    if not chunk_rows:
        return []
    kb_by_chunk: dict[str, list[dict[str, Any]]] = {}
    for kb in kb_rows:
        chunk_id = clean(kb.get("source_chunk_id"))
        if chunk_id:
            kb_by_chunk.setdefault(chunk_id, []).append(kb)
    query_tokens = rag_tokens(" ".join([*claims, *focus_terms]))
    ranked: list[tuple[int, int, dict[str, Any]]] = []
    for index, chunk in enumerate(chunk_rows):
        chunk_text = clean(chunk.get("chunk_text"))
        overlap = len(query_tokens.intersection(rag_tokens(chunk_text))) if query_tokens else 0
        ranked.append((overlap, -int(chunk.get("chunk_index") or index), chunk))
    ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
    anchors: list[dict[str, Any]] = []
    seen_chunks: set[str] = set()
    for _, _, chunk in ranked:
        chunk_id = clean(chunk.get("id"))
        if not chunk_id or chunk_id in seen_chunks:
            continue
        seen_chunks.add(chunk_id)
        linked_kb = kb_by_chunk.get(chunk_id, [])
        anchors.append(
            {
                "reference_id": clean(row.get("ref_id") or row.get("reference_id")),
                "chunk_id": chunk_id,
                "kb_entry_id": clean(linked_kb[0].get("id")) if linked_kb else "",
                "doi": clean(row.get("ref_doi") or row.get("doi")),
                "matched_excerpt": _short_matched_excerpt(chunk.get("chunk_text")),
                "supports": "",
            }
        )
        if len(anchors) >= max(1, int(limit or 3)):
            break
    return anchors


def literature_learning_summary_skill(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    task_id = clean(payload.get("task_id"))
    max_papers = max(1, int(payload.get("max_papers") or 5))
    focus_keywords = [normalize_literature_keyword_display(item) for item in as_list(payload.get("focus_keywords")) if clean(item)]
    if not project_id:
        raise ValueError("project_id is required")

    conn = connect(agent_root)
    try:
        params: list[Any] = [project_id]
        task_filter = ""
        if task_id:
            task_filter = " AND i.task_id=?"
            params.append(task_id)
        params.append(max_papers)
        ingest_rows = rows_to_dicts(
            conn.execute(
                f"""
                SELECT i.*, r.id AS ref_id, r.title AS ref_title, r.doi AS ref_doi, r.abstract,
                       r.authors_json AS ref_authors_json, r.journal AS ref_journal,
                       r.source_path, r.full_text_path, r.url, r.year, r.source_provider,
                       r.evidence_level, r.paper_type, r.search_task_id
                FROM literature_ingest_items i
                JOIN "references" r ON r.id=i.reference_id
                WHERE i.project_id=? AND i.ingest_status='indexed' AND i.reference_id!=''{task_filter}
                ORDER BY i.updated_at DESC
                LIMIT ?
                """,
                params,
            ).fetchall()
        )
        if not ingest_rows:
            params = [project_id]
            task_filter = ""
            if task_id:
                task_filter = " AND r.search_task_id=?"
                params.append(task_id)
            params.append(max_papers)
            ingest_rows = rows_to_dicts(
                conn.execute(
                    f"""
                    SELECT r.id AS ref_id, r.title AS ref_title, r.doi AS ref_doi, r.abstract,
                           r.authors_json AS ref_authors_json, r.journal AS ref_journal,
                           r.source_path, r.full_text_path, r.url, r.year, r.source_provider,
                           r.evidence_level, r.paper_type, r.search_task_id,
                           'indexed' AS ingest_status, '' AS pdf_path
                    FROM "references" r
                    WHERE r.project_id=?{task_filter}
                      AND EXISTS (
                        SELECT 1 FROM knowledge_base_entries kb
                        WHERE kb.project_id=r.project_id AND kb.source_reference_id=r.id
                      )
                    ORDER BY r.updated_at DESC
                    LIMIT ?
                    """,
                    params,
                ).fetchall()
            )

        papers: list[dict[str, Any]] = []
        citations: list[dict[str, Any]] = []
        all_mechanisms: list[str] = []
        all_methods: list[str] = []
        all_findings: list[str] = []
        mechanism_terms = focus_keywords + ["NF-kB", "NF-κB", "Nrf2", "MAPK", "TLR4", "cytokine", "TNF-alpha", "IL-6", "inflammation", "immune regulation"]
        method_terms = ["RAW264.7", "macrophage", "LPS", "ELISA", "Western blot", "qPCR", "PCR", "cell model", "animal model", "RNA-seq"]

        for index, row in enumerate(ingest_rows, start=1):
            reference_id = clean(row.get("ref_id") or row.get("reference_id"))
            chunk_rows = rows_to_dicts(
                conn.execute(
                    "SELECT * FROM reference_chunks WHERE project_id=? AND reference_id=? ORDER BY chunk_index LIMIT 5",
                    (project_id, reference_id),
                ).fetchall()
            )
            kb_rows = rows_to_dicts(
                conn.execute(
                    "SELECT * FROM knowledge_base_entries WHERE project_id=? AND source_reference_id=? ORDER BY updated_at DESC LIMIT 5",
                    (project_id, reference_id),
                ).fetchall()
            )
            source_text = "\n".join(
                [clean(row.get("abstract"))]
                + [clean(chunk.get("chunk_text")) for chunk in chunk_rows]
                + [clean(entry.get("content")) for entry in kb_rows]
            )
            mechanisms = _extract_present_terms(source_text, mechanism_terms)
            methods = _extract_present_terms(source_text, method_terms)
            key_findings = _evidence_sentences(source_text, mechanisms + methods + focus_keywords, limit=3)
            all_mechanisms.extend(item for item in mechanisms if item not in all_mechanisms)
            all_methods.extend(item for item in methods if item not in all_methods)
            all_findings.extend(item for item in key_findings if item not in all_findings)
            one_sentence = key_findings[0] if key_findings else "The indexed text is available, but no concise finding sentence could be extracted without risking over-interpretation."
            source_anchors = _supporting_source_anchors(chunk_rows, kb_rows, row, key_findings or [one_sentence], mechanisms + methods + focus_keywords, limit=3)
            key_points = build_source_anchored_key_points(key_findings or [one_sentence], source_anchors)
            for point in key_points:
                for anchor in point.get("source_anchors") or []:
                    anchor["supports"] = point.get("claim")
            chunk_ids_used = [clean(anchor.get("chunk_id")) for anchor in source_anchors if clean(anchor.get("chunk_id"))]
            kb_entry_ids_used = [clean(anchor.get("kb_entry_id")) for anchor in source_anchors if clean(anchor.get("kb_entry_id"))]
            limitations = []
            if len(kb_rows) <= 1:
                limitations.append("Summary is based on limited KB chunks from this paper.")
            if not clean(row.get("full_text_path") or row.get("source_path") or row.get("pdf_path")):
                limitations.append("No local full-text source file path is recorded for this reference.")
            if not key_findings:
                limitations.append("No explicit result sentence was detected in the stored text.")
            if not chunk_ids_used:
                limitations.append("The current KB records do not contain persistent chunk IDs for this source.")
            title = clean(row.get("ref_title") or row.get("title")) or "Untitled ingested paper"
            source_file = clean(row.get("full_text_path") or row.get("source_path") or row.get("pdf_path"))
            paper = {
                "title": title,
                "doi": _metadata_value(row.get("ref_doi")),
                "journal": _metadata_value(row.get("ref_journal")),
                "year": clean(row.get("year")),
                "authors": _clean_author_list(row.get("ref_authors") or row.get("authors")),
                "source_file": _metadata_value(source_file),
                "source_file_path": _metadata_value(source_file),
                "status": "ingested",
                "one_sentence_summary": one_sentence,
                "key_findings": key_findings,
                "key_points": key_points,
                "methods_or_models": methods,
                "mechanisms": mechanisms,
                "relevance_to_project": "Relevant to the current project through: " + ", ".join(_extract_present_terms(source_text + " " + title, focus_keywords + [clean(row.get("ref_title"))])) if focus_keywords else "Relevant because it has been indexed into this project's literature KB.",
                "limitations": limitations,
                "reference_id": reference_id,
                "chunk_ids": chunk_ids_used,
                "chunk_ids_used": chunk_ids_used,
                "kb_entry_ids": kb_entry_ids_used or [clean(entry.get("id")) for entry in kb_rows if clean(entry.get("id"))],
                "kb_entry_ids_used": kb_entry_ids_used,
                "source_anchors": source_anchors,
            }
            papers.append(paper)
            citations.append(
                {
                    "citation_id": index,
                    "reference_id": reference_id,
                    "display_title": title,
                    "doi": paper["doi"],
                    "file_path": paper["source_file"],
                    "chunk_ids": paper["chunk_ids"][:3],
                    "kb_entry_ids": paper["kb_entry_ids"][:3],
                }
            )
    finally:
        conn.close()

    count = len(papers)
    evidence_strength = "low" if count <= 1 else ("medium" if count <= 5 else "moderate")
    next_actions = []
    if papers:
        next_actions.append("Extract Methods details from the most relevant indexed paper.")
        next_actions.append("Continue monitoring the harvest and update this summary after more papers are ingested.")
        if focus_keywords:
            next_actions.append("Compare new papers against focus keywords: " + ", ".join(focus_keywords[:5]) + ".")
    return {
        "skill": "LiteratureLearningSummarySkill",
        "project_id": project_id,
        "task_id": task_id,
        "ingested_paper_count": count,
        "papers": papers,
        "project_level_learning": {
            "new_concepts": all_methods[:8],
            "new_mechanistic_clues": all_mechanisms[:8],
            "potential_experimental_ideas": [
                "Use the indexed Methods chunks as extraction targets before turning any paper-level observation into a project claim."
            ] if papers else [],
            "evidence_strength": evidence_strength,
        },
        "limitations": ["No papers have been ingested into the knowledge base yet."] if not papers else ([] if count > 1 else ["Only one ingested paper is available, so confidence is low."]),
        "next_actions": next_actions,
        "citations": citations,
    }


def _display_or_missing(value: Any, missing: str = "metadata missing") -> str:
    text = clean(value)
    if not text:
        return missing
    if text.strip().lower() in {"unknown_author", "unknown", "none", "null", "n/a", "na", "nan", "[]", "{}"}:
        return missing
    return text


def _metadata_value(value: Any) -> str:
    text = clean(value)
    return "" if text.strip().lower() in {"unknown_author", "unknown", "none", "null", "n/a", "na", "nan", "[]", "{}"} else text


def _display_year(value: Any) -> str:
    return _metadata_value(value) or "year not available"


def _display_doi(value: Any) -> str:
    return _metadata_value(value) or "DOI not available"


def _display_journal(value: Any) -> str:
    return _metadata_value(value) or "journal not available"


def _display_source_file(value: Any) -> str:
    return _metadata_value(value) or "source file not available"


def _clean_author_list(value: Any) -> list[str]:
    authors = []
    for item in as_list(value):
        author = _metadata_value(item)
        if author:
            authors.append(author)
    return authors


def _display_authors(value: Any) -> str:
    authors = _clean_author_list(value)
    return ", ".join(authors) if authors else "authors not available in local metadata"


def _one_sentence_summary_from_sources(*sources: Any) -> str:
    for source in sources:
        text = clean(source)
        if not text:
            continue
        sentences = _literature_sentences(text, limit=1)
        if sentences:
            return sentences[0]
        if len(text) > 20:
            return text[:240].rstrip() + ("..." if len(text) > 240 else "")
    return "No summary available from indexed content."


def backfill_reference_metadata(agent_root: Path, reference_id: str) -> dict[str, Any]:
    reference_id = clean(reference_id)
    if not reference_id:
        raise ValueError("reference_id is required")
    conn = connect(agent_root)
    try:
        reference = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (reference_id,)).fetchone()) or {}
        if not reference:
            return {"ok": False, "status": "missing_reference", "reference_id": reference_id, "updated_fields": []}
        doi = _metadata_value(reference.get("doi"))
        if not doi:
            return {"ok": True, "status": "skipped", "reason": "DOI not available", "reference_id": reference_id, "updated_fields": []}
        provider = None
        for name in ["fetch_reference_metadata_by_doi", "fetch_doi_metadata", "fetch_crossref_metadata", "resolve_doi_metadata"]:
            candidate = globals().get(name)
            if callable(candidate) and candidate is not backfill_reference_metadata:
                provider = candidate
                break
        if provider is None:
            # Hook for future DOI providers. Keep this safe/offline by default and never add a hard dependency here.
            return {"ok": True, "status": "skipped", "reason": "No DOI metadata provider is configured.", "reference_id": reference_id, "doi": doi, "updated_fields": []}
        try:
            fetched = provider(doi)
        except Exception as exc:
            return {"ok": True, "status": "skipped", "reason": f"DOI metadata provider failed: {clean(exc)}", "reference_id": reference_id, "doi": doi, "updated_fields": []}
        if not isinstance(fetched, dict) or not fetched:
            return {"ok": True, "status": "skipped", "reason": "DOI metadata provider returned no metadata.", "reference_id": reference_id, "doi": doi, "updated_fields": []}
        field_map = {
            "title": "title",
            "authors": "authors_json",
            "year": "year",
            "journal": "journal",
            "doi": "doi",
        }
        updates: dict[str, Any] = {}
        for source_key, db_key in field_map.items():
            current = reference.get("authors") if db_key == "authors_json" else reference.get(db_key)
            if _metadata_value(current):
                continue
            incoming = fetched.get(source_key)
            if db_key == "authors_json":
                authors = _clean_author_list(incoming)
                if authors:
                    updates[db_key] = json_dumps(authors)
            elif _metadata_value(incoming):
                updates[db_key] = _metadata_value(incoming)
        if not updates:
            return {"ok": True, "status": "unchanged", "reference_id": reference_id, "doi": doi, "updated_fields": []}
        set_clause = ", ".join(f"{key}=?" for key in updates)
        conn.execute(f'UPDATE "references" SET {set_clause}, updated_at=? WHERE id=?', [*updates.values(), now(), reference_id])
        conn.commit()
        return {"ok": True, "status": "updated", "reference_id": reference_id, "doi": doi, "updated_fields": list(updates.keys())}
    finally:
        conn.close()


def filter_learning_summary_for_source_traceability(summary: dict[str, Any], message: str) -> dict[str, Any]:
    papers = [paper for paper in as_list(summary.get("papers")) if isinstance(paper, dict)]
    if not papers:
        return {**summary, "papers": [], "ingested_paper_count": 0}
    text = clean(message)
    lower = text.lower()
    quoted_titles = [clean(item).lower() for item in re.findall(r"《([^》]+)》", text) if clean(item)]
    years = set(re.findall(r"\b(?:19|20)\d{2}\b", text))
    doi_match = re.search(r"\b10\.\S+", text, flags=re.IGNORECASE)
    doi = clean(doi_match.group(0)).rstrip(".,;，。；") if doi_match else ""
    selected: list[dict[str, Any]] = []
    for paper in papers:
        title = clean(paper.get("title")).lower()
        reference_id = clean(paper.get("reference_id")).lower()
        paper_doi = clean(paper.get("doi")).lower()
        paper_year = clean(paper.get("year"))
        matches = False
        if reference_id and reference_id in lower:
            matches = True
        if doi and paper_doi and doi.lower() == paper_doi:
            matches = True
        if quoted_titles and any(item and item in title for item in quoted_titles):
            matches = True
        if years and paper_year in years:
            matches = matches or not quoted_titles
        if matches:
            selected.append(paper)
    if not selected:
        selected = papers[:1]
    return {**summary, "papers": selected, "ingested_paper_count": len(selected)}


def format_literature_source_traceability(summary: dict[str, Any], *, include_internal_ids: bool = False) -> str:
    papers = [paper for paper in as_list(summary.get("papers")) if isinstance(paper, dict)]
    if not papers:
        return "No papers have been ingested into the knowledge base yet."
    lines: list[str] = []
    for paper in papers:
        lines.append("Paper:")
        lines.append(f"- title: {_display_or_missing(paper.get('title'))}")
        lines.append(f"- year: {_display_year(paper.get('year'))}")
        lines.append(f"- DOI: {_display_doi(paper.get('doi'))}")
        lines.append(f"- journal: {_display_journal(paper.get('journal'))}")
        if include_internal_ids:
            lines.append(f"- reference_id: {_display_or_missing(paper.get('reference_id'))}")
        lines.append(f"- authors: {_display_authors(paper.get('authors'))}")
        lines.append(f"- source file: {_display_source_file(paper.get('source_file_path') or paper.get('source_file'))}")
        lines.append("")
        anchors: list[dict[str, Any]] = []
        seen: set[tuple[str, str]] = set()
        for point in as_list(paper.get("key_points")):
            if not isinstance(point, dict):
                continue
            for anchor in as_list(point.get("source_anchors")):
                if not isinstance(anchor, dict):
                    continue
                key = (clean(anchor.get("chunk_id")), clean(anchor.get("kb_entry_id")))
                if key in seen:
                    continue
                seen.add(key)
                anchor = dict(anchor)
                anchor["supports"] = clean(anchor.get("supports") or point.get("claim"))
                anchors.append(anchor)
        if not anchors:
            for anchor in as_list(paper.get("source_anchors")):
                if isinstance(anchor, dict):
                    anchors.append(anchor)
        lines.append("Here are the source chunks supporting the previous summary.")
        lines.append("Supporting chunks:")
        real_chunk_anchors = [anchor for anchor in anchors if clean(anchor.get("chunk_id"))]
        if not real_chunk_anchors:
            lines.append("The current KB records do not contain public source excerpts for this source.")
            if include_internal_ids and (paper.get("kb_entry_ids") or paper.get("kb_entry_ids_used")):
                lines.append("Available KB entry IDs: " + ", ".join(clean(item) for item in as_list(paper.get("kb_entry_ids_used") or paper.get("kb_entry_ids")) if clean(item)))
            lines.append("")
            continue
        for index, anchor in enumerate(real_chunk_anchors, start=1):
            lines.append(f"{index}. claim: {clean(anchor.get('supports')) or 'source-backed summary point'}")
            lines.append(f"   citation id: {index}")
            if include_internal_ids:
                lines.append(f"   reference_id: {clean(anchor.get('reference_id'))}")
                lines.append(f"   chunk_id: {clean(anchor.get('chunk_id'))}")
            if include_internal_ids and clean(anchor.get("kb_entry_id")):
                lines.append(f"   kb_entry_id: {clean(anchor.get('kb_entry_id'))}")
            lines.append(f"   short excerpt: {clean(anchor.get('matched_excerpt'))}")
            lines.append(f"   DOI: {_display_doi(anchor.get('doi') or paper.get('doi'))}")
            lines.append(f"   source file: {_display_source_file(paper.get('source_file_path') or paper.get('source_file'))}")
        lines.append("")
    return "\n".join(lines).strip()


def list_ingested_papers_skill(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    task_id = clean(payload.get("task_id"))
    limit = max(1, int(payload.get("limit") or 20))
    sort_by = clean(payload.get("sort_by")) or "created_at"
    include_summary = bool(payload.get("include_summary", True))
    include_chunk_count = bool(payload.get("include_chunk_count", True))
    if not project_id:
        raise ValueError("project_id is required")

    order_by = {
        "created_at": "i.updated_at DESC",
        "year": "r.year DESC, i.updated_at DESC",
        "title": "r.title COLLATE NOCASE ASC",
        "relevance": "COALESCE(r.relevance_score, 0) DESC, i.updated_at DESC",
    }.get(sort_by, "i.updated_at DESC")
    params: list[Any] = [project_id]
    task_filter = ""
    if task_id:
        task_filter = " AND i.task_id=?"
        params.append(task_id)
    params.append(limit * 3)
    conn = connect(agent_root)
    try:
        project = row_to_dict(conn.execute("SELECT id, title FROM projects WHERE id=?", (project_id,)).fetchone()) or {}
        ingest_rows = rows_to_dicts(
            conn.execute(
                f"""
                SELECT i.*, r.id AS ref_id, r.title AS ref_title, r.authors_json AS ref_authors_json,
                       r.year AS ref_year, r.doi AS ref_doi, r.abstract AS ref_abstract,
                       r.journal AS ref_journal, r.source_path AS ref_source_path,
                       r.full_text_path AS ref_full_text_path, r.url AS ref_url,
                       r.created_at AS ref_created_at, r.updated_at AS ref_updated_at
                FROM literature_ingest_items i
                JOIN "references" r ON r.id=i.reference_id
                WHERE i.project_id=?
                  AND i.reference_id!=''
                  AND LOWER(COALESCE(i.ingest_status, '')) IN ('indexed', 'ingested', 'chunked')
                  AND (
                    EXISTS (
                      SELECT 1 FROM reference_chunks c
                      WHERE c.project_id=i.project_id AND c.reference_id=i.reference_id
                    )
                    OR EXISTS (
                      SELECT 1 FROM knowledge_base_entries kb
                      WHERE kb.project_id=i.project_id AND kb.source_reference_id=i.reference_id
                    )
                  )
                  {task_filter}
                ORDER BY {order_by}
                LIMIT ?
                """,
                params,
            ).fetchall()
        )
        if not ingest_rows:
            fallback_order_by = {
                "created_at": "r.updated_at DESC",
                "year": "r.year DESC, r.updated_at DESC",
                "title": "r.title COLLATE NOCASE ASC",
                "relevance": "COALESCE(r.relevance_score, 0) DESC, r.updated_at DESC",
            }.get(sort_by, "r.updated_at DESC")
            params = [project_id]
            task_filter = ""
            if task_id:
                task_filter = " AND r.search_task_id=?"
                params.append(task_id)
            params.append(limit * 3)
            ingest_rows = rows_to_dicts(
                conn.execute(
                    f"""
                    SELECT '' AS id, r.search_task_id AS task_id, r.project_id, r.id AS reference_id,
                           r.title, r.doi, r.full_text_path AS pdf_path, 'indexed' AS ingest_status,
                           r.created_at, r.updated_at, r.id AS ref_id, r.title AS ref_title,
                           r.authors_json AS ref_authors_json, r.year AS ref_year, r.doi AS ref_doi,
                           r.abstract AS ref_abstract, r.journal AS ref_journal,
                           r.source_path AS ref_source_path, r.full_text_path AS ref_full_text_path,
                           r.url AS ref_url, r.created_at AS ref_created_at, r.updated_at AS ref_updated_at
                    FROM "references" r
                    WHERE r.project_id=?
                      AND (
                        EXISTS (
                          SELECT 1 FROM reference_chunks c
                          WHERE c.project_id=r.project_id AND c.reference_id=r.id
                        )
                        OR EXISTS (
                          SELECT 1 FROM knowledge_base_entries kb
                          WHERE kb.project_id=r.project_id AND kb.source_reference_id=r.id
                        )
                      )
                      {task_filter}
                    ORDER BY {fallback_order_by}
                    LIMIT ?
                    """,
                    params,
                ).fetchall()
            )

        papers: list[dict[str, Any]] = []
        seen_reference_ids: set[str] = set()
        for row in ingest_rows:
            reference_id = clean(row.get("ref_id") or row.get("reference_id"))
            if not reference_id or reference_id in seen_reference_ids:
                continue
            seen_reference_ids.add(reference_id)
            chunk_count = int(
                conn.execute(
                    "SELECT COUNT(*) FROM reference_chunks WHERE project_id=? AND reference_id=?",
                    (project_id, reference_id),
                ).fetchone()[0]
            ) if include_chunk_count else None
            kb_entry_count = int(
                conn.execute(
                    "SELECT COUNT(*) FROM knowledge_base_entries WHERE project_id=? AND source_reference_id=?",
                    (project_id, reference_id),
                ).fetchone()[0]
            )
            kb_row = row_to_dict(
                conn.execute(
                    "SELECT * FROM knowledge_base_entries WHERE project_id=? AND source_reference_id=? ORDER BY updated_at DESC LIMIT 1",
                    (project_id, reference_id),
                ).fetchone()
            ) or {}
            chunk_row = row_to_dict(
                conn.execute(
                    "SELECT * FROM reference_chunks WHERE project_id=? AND reference_id=? ORDER BY chunk_index LIMIT 1",
                    (project_id, reference_id),
                ).fetchone()
            ) or {}
            title = _display_or_missing(row.get("ref_title") or row.get("title"))
            summary = (
                _one_sentence_summary_from_sources(kb_row.get("content"), row.get("ref_abstract"), chunk_row.get("chunk_text"))
                if include_summary
                else ""
            )
            paper = {
                "reference_id": reference_id,
                "title": title,
                "year": _metadata_value(row.get("ref_year")),
                "doi": _metadata_value(row.get("ref_doi")),
                "journal": _metadata_value(row.get("ref_journal")),
                "authors": _clean_author_list(row.get("ref_authors") or row.get("authors")),
                "ingest_status": _display_or_missing(row.get("ingest_status"), "indexed"),
                "chunk_count": chunk_count,
                "kb_entry_count": kb_entry_count,
                "one_sentence_summary": summary,
                "source_file_path": _metadata_value(row.get("ref_full_text_path") or row.get("ref_source_path") or row.get("pdf_path")),
                "created_at": _display_or_missing(row.get("created_at") or row.get("ref_created_at"), ""),
            }
            papers.append(paper)
            if len(papers) >= limit:
                break
    finally:
        conn.close()

    notes = []
    if not papers:
        notes.append("No papers have been ingested into the knowledge base yet.")
    return {
        "skill": "ListIngestedPapersSkill",
        "project_id": project_id,
        "project_name": clean(project.get("title")) or project_id,
        "task_id": task_id,
        "ingested_paper_count": len(papers),
        "papers": papers,
        "notes": notes,
    }


def format_ingested_papers_inventory(inventory: dict[str, Any], task_status: list[dict[str, Any]] | None = None) -> str:
    count = int(inventory.get("ingested_paper_count") or 0)
    if count <= 0:
        return "No papers have been ingested into the knowledge base yet."
    task_status = task_status or []
    running_lit = next((item for item in task_status if item.get("task_type") == "literature_harvest" and clean(item.get("status")) == "running"), {})
    lines: list[str] = []
    project_name = clean(inventory.get("project_name") or inventory.get("project_id"))
    paper_word = "paper" if count == 1 else "papers"
    lines.append(f"Current KB inventory shows {count} indexed {paper_word} for project {project_name}.")
    if running_lit:
        lines.append("The harvest may still be running, so this number can continue to change.")
    lines.append("")
    for index, paper in enumerate(inventory.get("papers") or [], start=1):
        title = _display_or_missing(paper.get("title"))
        year = _display_year(paper.get("year"))
        doi = _display_doi(paper.get("doi"))
        journal = _display_journal(paper.get("journal"))
        authors = _display_authors(paper.get("authors"))
        reference_id = _display_or_missing(paper.get("reference_id"))
        chunk_count = paper.get("chunk_count")
        chunk_display = str(chunk_count) if chunk_count is not None else "unknown"
        summary = clean(paper.get("one_sentence_summary")) or "No summary available from indexed content."
        lines.append(f"{index}. title: {title}")
        lines.append(f"year: {year}; DOI: {doi}; journal: {journal}; authors: {authors}")
        lines.append(f"reference_id: {reference_id}; chunk_count: {chunk_display}; kb_entry_count: {int(paper.get('kb_entry_count') or 0)}")
        lines.append(f"one_sentence_summary: {summary}")
        lines.append(f"source_file_path: {_display_source_file(paper.get('source_file_path'))}")
        lines.append("")
    return "\n".join(lines).strip()


def format_literature_learning_summary(summary: dict[str, Any], task_status: list[dict[str, Any]] | None = None) -> str:
    count = int(summary.get("ingested_paper_count") or 0)
    if count <= 0:
        return "No papers have been ingested into the knowledge base yet."
    task_status = task_status or []
    running_lit = next((item for item in task_status if item.get("task_type") == "literature_harvest" and clean(item.get("status")) == "running"), {})
    lines: list[str] = []
    paper_word = "paper" if count == 1 else "papers"
    if running_lit:
        lines.append(f"The harvest is still running, but {count} {paper_word} have already been indexed. Here is an early, source-based summary.")
    if count == 1:
        lines.append("Only 1 paper has been ingested so far, so this is an early low-confidence summary.")
    else:
        lines.append(f"{count} papers have been ingested into the project knowledge base so far.")
    if running_lit:
        lines.append(f"Status: {clean(running_lit.get('status'))}; ingested: {count}.")
    lines.append("")
    for index, paper in enumerate(summary.get("papers") or [], start=1):
        lines.append(f"{index}. {clean(paper.get('title'))} [{index}]")
        lines.append(
            "Metadata: "
            f"year: {_display_year(paper.get('year'))}; "
            f"DOI: {_display_doi(paper.get('doi'))}; "
            f"journal: {_display_journal(paper.get('journal'))}; "
            f"authors: {_display_authors(paper.get('authors'))}; "
            f"reference_id: {_display_or_missing(paper.get('reference_id'))}; "
            f"source file: {_display_source_file(paper.get('source_file_path') or paper.get('source_file'))}; "
            f"chunk_count: {len(as_list(paper.get('chunk_ids_used') or paper.get('chunk_ids')))}"
        )
        lines.append(f"What was learned: {clean(paper.get('one_sentence_summary'))}")
        if paper.get("mechanisms"):
            lines.append("Key mechanisms or concepts: " + ", ".join(paper["mechanisms"][:6]))
        if paper.get("methods_or_models"):
            lines.append("Reusable methods: " + ", ".join(paper["methods_or_models"][:6]))
        if paper.get("key_findings"):
            lines.append("Evidence-backed notes: " + " ".join(clean(item) for item in paper["key_findings"][:2]))
        if clean(paper.get("relevance_to_project")):
            lines.append("Project relevance: " + clean(paper.get("relevance_to_project")))
        anchors = []
        for anchor in as_list(paper.get("source_anchors"))[:3]:
            if isinstance(anchor, dict) and clean(anchor.get("chunk_id")):
                anchors.append(clean(anchor.get("chunk_id")))
        if anchors:
            lines.append("Source anchors: " + ", ".join(anchors))
        if paper.get("limitations"):
            lines.append("Limitations: " + "; ".join(clean(item) for item in paper["limitations"][:3]))
        lines.append("")
    project_learning = summary.get("project_level_learning") or {}
    if project_learning.get("new_mechanistic_clues") or project_learning.get("new_concepts"):
        lines.append("Project-level learning:")
        if project_learning.get("new_mechanistic_clues"):
            lines.append("Mechanistic clues: " + ", ".join(project_learning["new_mechanistic_clues"][:8]))
        if project_learning.get("new_concepts"):
            lines.append("Concepts/models: " + ", ".join(project_learning["new_concepts"][:8]))
        lines.append(f"Evidence strength: {clean(project_learning.get('evidence_strength')) or 'low'}")
    if summary.get("next_actions"):
        lines.append("Next extraction priorities: " + "; ".join(clean(item) for item in summary["next_actions"][:3]))
    return "\n".join(line for line in lines if line is not None).strip()


def _strip_local_paths(text: str) -> str:
    text = re.sub(r"[A-Za-z]:\\[^\s\n]+", "[local file hidden]", text)
    text = re.sub(r"/(?:Users|home|mnt|tmp|var)/[^\s\n]+", "[local file hidden]", text)
    return text


def _remove_internal_placeholders(text: str) -> str:
    return re.sub(r"\b(?:unknown_author|null|none|nan)\b", "metadata missing", text, flags=re.IGNORECASE)


def developer_debug_mode_enabled() -> bool:
    return clean(os.environ.get("RESEARCHOS_DEVELOPER_DEBUG") or os.environ.get("AURA_DEVELOPER_DEBUG")).lower() in {"1", "true", "yes", "on", "debug"}


def explicit_debug_identifier_request(message: str = "") -> bool:
    text = clean(message).lower()
    return any(term in text for term in ["debug", "developer mode", "internal id", "internal ids", "调试信息", "内部 id", "内部ID", "开发者模式"])


def final_answer_sanitizer(text: str, message: str = "", *, response_mode: str = "normal_answer", developer_debug: bool = False) -> str:
    safe = _remove_internal_placeholders(str(text or "").strip())
    if developer_debug or (explicit_debug_identifier_request(message) and developer_debug_mode_enabled()):
        return safe
    hidden_labels = [
        "project_id",
        "candidate_id",
        "task_id",
        "memory_id",
        "file_id",
        "chunk_id",
        "session_id",
        "message_id",
        "context_hash",
        "reference_id",
        "kb_entry_id",
        "document_id",
    ]
    lines: list[str] = []
    for line in safe.splitlines():
        stripped = line.strip()
        hidden_line_label = next((label for label in hidden_labels if re.match(rf"^[-*]?\s*{label}\s*[:=]", stripped, flags=re.IGNORECASE)), "")
        if hidden_line_label and response_mode == "memory_commit_result" and hidden_line_label == "memory_id":
            lines.append("memory_id: [已隐藏]")
            continue
        for label in hidden_labels:
            stripped = re.sub(rf"\b{label}\s*[:=]\s*[A-Za-z0-9_.:-]+", "", stripped, flags=re.IGNORECASE).strip()
        stripped = re.sub(r"^\s*[;,]\s*", "", stripped)
        stripped = re.sub(r"\s*;\s*;", ";", stripped)
        if stripped:
            lines.append(stripped)
    safe = "\n".join(lines)
    safe = re.sub(r"\b[a-f0-9]{16,}\b", "[id hidden]", safe, flags=re.IGNORECASE)
    safe = re.sub(r"\n{3,}", "\n\n", safe).strip()
    return safe


def apply_response_policy(text: str, response_mode: str, message: str = "", *, developer_debug: bool = False) -> str:
    safe = _remove_internal_placeholders(str(text or "").strip())
    if not developer_debug:
        safe = _strip_local_paths(safe)
        safe = re.sub(r"\bchunk_id\s*:\s*\S+", "", safe, flags=re.IGNORECASE)
    return final_answer_sanitizer(safe.strip(), message=message, response_mode=response_mode, developer_debug=developer_debug)


def response_mode_for_intent(intent: str) -> str:
    return {
        "literature_learning_summary": "learning_summary",
        "paper_recommendation": "paper_recommendation",
        "task_status_query": "task_status",
        "proactive_status_query": "task_status",
        "literature_source_traceability": "source_traceability",
        "paper_request_list": "normal_answer",
        "paper_request_process": "task_status",
        "memory_commit_request": "memory_commit_result",
        "self_description_or_architecture": "self_description",
        "capability_query": "capability_explanation",
        "capability_explanation": "capability_explanation",
        "autonomous_learning_question": "autonomous_learning",
        "file_registry_query": "file_registry_query",
        "uploaded_file_parse": "uploaded_file_parse",
        "project_list": "project_management",
        "project_switch": "project_management",
        "project_status": "project_status",
        "project_status_query": "project_status",
        "project_archive_request": "project_management",
        "project_unarchive_request": "project_management",
        "project_clear_request": "project_management",
        "project_purge_request": "project_management",
    }.get(clean(intent), "normal_answer")


def format_learning_summary_policy(summary: dict[str, Any], task_status: list[dict[str, Any]] | None = None) -> str:
    count = int(summary.get("ingested_paper_count") or 0)
    if count <= 0:
        return "No papers have been ingested into the knowledge base yet. Evidence is insufficient for a project-level learning summary."
    task_status = task_status or []
    running_lit = next((item for item in task_status if item.get("task_type") == "literature_harvest" and clean(item.get("status")) == "running"), {})
    project_learning = summary.get("project_level_learning") or {}
    concepts = [clean(item) for item in as_list(project_learning.get("new_concepts")) if clean(item)]
    mechanisms = [clean(item) for item in as_list(project_learning.get("new_mechanistic_clues")) if clean(item)]
    papers = [paper for paper in as_list(summary.get("papers")) if isinstance(paper, dict)]
    lines: list[str] = []
    if running_lit:
        lines.append(f"The harvest is still running, but {count} indexed papers are already available. Here is a concise source-based summary.")
    else:
        lines.append(f"{count} indexed papers are available. Here is a concise source-based summary.")
    if count == 1:
        lines.append("Only 1 paper has been ingested so far, so this is an early low-confidence summary.")
    lines.append("")
    lines.append("Project-level learning:")
    findings = []
    for item in mechanisms[:3]:
        findings.append(f"{item} appears in the indexed literature and may be relevant to the project.")
    for item in concepts[:3]:
        if len(findings) >= 5:
            break
        findings.append(f"{item} is a recurring method/model/concept in the indexed papers.")
    for paper in papers[:3]:
        if len(findings) >= 5:
            break
        finding = clean(paper.get("one_sentence_summary"))
        if finding:
            findings.append(finding)
    if not findings:
        findings = ["The indexed papers are available, but the stored text is too limited for strong project-level conclusions."]
    for index, finding in enumerate(findings[:5], start=1):
        lines.append(f"{index}. {finding}")
    lines.append("")
    lines.append("Top relevant papers:")
    for index, paper in enumerate(papers[:3], start=1):
        title = _display_or_missing(paper.get("title"))
        doi = _display_doi(paper.get("doi"))
        authors = _display_authors(paper.get("authors"))
        summary_text = clean(paper.get("one_sentence_summary")) or "Indexed content exists, but no concise finding was extracted."
        lines.append(f"{index}. {title} ({_display_year(paper.get('year'))}; DOI: {doi})")
        lines.append(f"   Authors: {authors}")
        lines.append(f"   Why it matters: {summary_text}")
    if any(as_list(paper.get("source_anchors")) or as_list(paper.get("chunk_ids_used")) for paper in papers[:3]):
        lines.append("Source anchors: available on request. Ask “which chunks support this?” to see chunk-level evidence.")
    lines.append("")
    lines.append(f"Evidence strength: {clean(project_learning.get('evidence_strength')) or ('low' if count <= 1 else 'medium')}.")
    limitations = [clean(item) for item in as_list(summary.get("limitations")) if clean(item)]
    for paper in papers[:3]:
        for item in as_list(paper.get("limitations")):
            if clean(item) and clean(item) not in limitations:
                limitations.append(clean(item))
    if limitations:
        lines.append("Limitations: " + "; ".join(limitations[:3]))
    else:
        lines.append("Limitations: conclusions are based only on currently indexed local KB content.")
    if summary.get("next_actions"):
        lines.append("Next step: " + clean(as_list(summary.get("next_actions"))[0]))
    else:
        lines.append("Next step: ask for source traceability if you want chunk-level evidence.")
    return apply_response_policy("\n".join(lines), "learning_summary")


def format_paper_recommendation_answer(agent_root: Path, project_id: str, message: str, limit: int = 3) -> dict[str, Any]:
    rag = query_research_rag(agent_root, {"project_id": project_id, "question": message, "mode": "literature_only", "limit": max(3, int(limit or 3))})
    chunks = [item for item in as_list(rag.get("retrieved_chunks")) if isinstance(item, dict)]
    seen_refs: set[str] = set()
    papers: list[dict[str, Any]] = []
    for item in chunks:
        ref_id = clean(item.get("reference_id"))
        if ref_id and ref_id in seen_refs:
            continue
        seen_refs.add(ref_id)
        papers.append(item)
        if len(papers) >= 3:
            break
    lines = ["Top 3 papers to read:"]
    if not papers:
        lines.append("No indexed papers are available yet. I cannot rank papers without local KB evidence.")
    for index, paper in enumerate(papers, start=1):
        title = _display_or_missing(paper.get("title"))
        doi = _display_doi(paper.get("doi"))
        score = float(paper.get("score") or 0)
        relevance = "high" if score >= 2 else ("medium" if score >= 1 else "low")
        excerpt = clean(paper.get("matched_text") or paper.get("chunk_text"))[:180]
        lines.append(f"{index}. {title}")
        lines.append(f"   Why worth reading: {excerpt or 'It matched the project question in the local KB.'}")
        lines.append(f"   Relevance: {relevance}; DOI: {doi}")
    lines.append("Ranking basis: local KB relevance and method value. I do not have impact-factor data here, so I am not ranking by journal impact factor.")
    return {"answer": apply_response_policy("\n".join(lines), "paper_recommendation"), "rag": rag, "papers": papers}


def format_self_description_answer(message: str = "") -> str:
    text = clean(message)
    lower = text.lower()
    if any(term in lower for term in ["system prompt", "developer instruction", "hidden prompt", "internal prompt", "internal rules"]) or any(term in text for term in ["提示词", "系统提示", "开发者指令", "内部指令", "内部规则"]):
        return (
            "我不会输出内部提示、系统配置或隐藏指令。"
            "如果你是在排查回答质量，可以描述具体问题；我可以说明可见能力、数据来源范围、任务状态和下一步建议。"
        )
    if "api key" in lower or "密钥" in text:
        return (
            "我不会泄露 API key，也不会在回答里显示部署密钥。"
            "AURA 只能说明密钥应由本地环境或部署配置管理；如果需要排查配置，请检查本地环境变量或项目配置。"
        )
    return (
        "AURA 是受控的项目级科研工作流 Agent，不是模型权重自训练系统。"
        "它由主 Agent/Orchestrator、skills、task runner、KB/RAG 和 project memory 协同工作。"
        "我不会泄露 API key；也不保证永久保存所有 raw chat。"
        "长上下文会通过摘要、项目记忆、KB/RAG 和任务产物来管理。"
    )


def project_status_counts(agent_root: Path, project_id: str) -> dict[str, int]:
    conn = connect(agent_root)
    counts = {
        "experiments": int(conn.execute("SELECT COUNT(*) FROM experiments WHERE project_id=?", (project_id,)).fetchone()[0]),
        "samples": int(conn.execute("SELECT COUNT(*) FROM samples WHERE project_id=?", (project_id,)).fetchone()[0]),
        "files": int(conn.execute("SELECT COUNT(*) FROM research_files WHERE project_id=?", (project_id,)).fetchone()[0]),
        "conclusions": int(conn.execute("SELECT COUNT(*) FROM claims WHERE project_id=?", (project_id,)).fetchone()[0]),
        "running_tasks": int(conn.execute("SELECT COUNT(*) FROM literature_search_tasks WHERE project_id=? AND status='running'", (project_id,)).fetchone()[0]),
    }
    conn.close()
    return counts


def latest_task_status(agent_root: Path, project_id: str, limit: int = 5) -> list[dict[str, Any]]:
    conn = connect(agent_root)
    lit_tasks = rows_to_dicts(
        conn.execute(
            "SELECT * FROM literature_search_tasks WHERE project_id=? ORDER BY updated_at DESC LIMIT ?",
            (project_id, max(int(limit or 5) * 4, 20)),
        ).fetchall()
    )
    skill_rows = rows_to_dicts(
        conn.execute(
            "SELECT id, skill_id, skill_name, status, created_at, updated_at, output_object_refs_json, output_payload_json, logs_json FROM skill_runs WHERE project_id=? ORDER BY updated_at DESC LIMIT ?",
            (project_id, int(limit or 5)),
        ).fetchall()
    )
    exec_rows = rows_to_dicts(
        conn.execute(
            "SELECT id, skill_id, task_title, status, error_message, created_at, updated_at FROM execution_memory WHERE project_id=? ORDER BY updated_at DESC LIMIT ?",
            (project_id, int(limit or 5)),
        ).fetchall()
    )
    agent_task_rows = rows_to_dicts(
        conn.execute(
            "SELECT * FROM agent_tasks WHERE project_id=? ORDER BY updated_at DESC LIMIT ?",
            (project_id, int(limit or 5)),
        ).fetchall()
    )
    conn.close()
    statuses: list[dict[str, Any]] = []
    for task in lit_tasks:
        try:
            progress = collect_keyword_harvest_progress(agent_root, task["id"]).get("progress", {})
        except Exception as exc:  # noqa: BLE001
            progress = {"error": str(exc)}
        counters = literature_task_counters(
            {
                "total": (progress.get("ingest_summary", {}) or {}).get("total") or progress.get("candidate_count", 0),
                "downloaded": max(int((progress.get("ingest_summary", {}) or {}).get("downloaded") or 0), int(progress.get("pdf_count", 0) or 0)),
                "parsed": progress.get("parsed_count", 0),
                "indexed": progress.get("indexed_count", 0),
                "failed": progress.get("ingest_failed_count", 0),
            }
        )
        request_counts = paper_request_counters(agent_root, project_id=project_id, task_id=clean(task.get("id")))
        counters.update({key: value for key, value in request_counts.items() if int(value or 0) > 0})
        current_stage = normalize_literature_current_stage(clean(task.get("status")), {**progress, **counters, "total": counters["found"], "indexed": counters["ingested"]})
        statuses.append(
            {
                "task_type": "literature_harvest",
                "task_name": "文献采集",
                "task_id": task.get("id"),
                "skill_id": "core_keyword_research_harvest",
                "status": task.get("status"),
                "query": normalize_literature_query_display(task.get("query")),
                "started_at": task.get("created_at"),
                "finished_at": task.get("updated_at") if task.get("status") in {"completed", "failed"} else "",
                "keywords": display_literature_keywords(task.get("keywords")),
                "current_stage": current_stage,
                "counters": counters,
                "progress": {
                    "total": counters["found"],
                    "downloaded": counters["downloaded"],
                    "parsed": counters["parsed"],
                    "indexed": counters["ingested"],
                    "ingested": counters["ingested"],
                    "failed": counters["failed"],
                    "current_title": progress.get("current_title", ""),
                    "current_stage": current_stage,
                    "chunks_count": sum(int(item.get("chunks_count") or 0) for item in progress.get("ingest_items", []) if isinstance(item, dict)),
                    **{key: value for key, value in request_counts.items() if int(value or 0) > 0},
                },
                "artifacts": {
                    "run_root": progress.get("run_root", ""),
                    "final_pdf_dir": progress.get("final_pdf_dir", ""),
                    "downloaded_items": progress.get("downloaded_items", [])[:10],
                },
                "error": progress.get("error", ""),
            }
        )
    for row in skill_rows:
        if any(item.get("task_id") == row.get("id") for item in statuses):
            continue
        statuses.append(
            {
                "task_type": "skill_run",
                "task_name": clean(row.get("skill_name")) or clean(row.get("skill_id")),
                "task_id": row.get("id"),
                "skill_id": row.get("skill_id"),
                "status": row.get("status"),
                "started_at": row.get("created_at"),
                "finished_at": row.get("updated_at") if row.get("status") in {"completed", "failed"} else "",
                "progress": {},
                "artifacts": row.get("output_object_refs") or [],
                "error": "",
            }
        )
    for row in exec_rows:
        statuses.append(
            {
                "task_type": "execution_memory",
                "task_name": clean(row.get("task_title")) or "执行记录",
                "task_id": row.get("id"),
                "skill_id": row.get("skill_id"),
                "status": row.get("status"),
                "started_at": row.get("created_at"),
                "finished_at": row.get("updated_at") if row.get("status") in {"completed", "failed"} else "",
                "progress": {},
                "artifacts": [],
                "error": row.get("error_message") or "",
            }
        )
    for row in agent_task_rows:
        statuses.append(
            {
                "task_type": clean(row.get("task_type")),
                "task_name": clean(row.get("task_type")).replace("_", " "),
                "task_id": row.get("task_id"),
                "skill_id": research_operating_loop.task_skill_id(clean(row.get("task_type"))),
                "status": row.get("status"),
                "started_at": row.get("created_at"),
                "finished_at": row.get("updated_at") if clean(row.get("status")) in {"completed", "failed", "cancelled"} else "",
                "progress": row.get("progress") if isinstance(row.get("progress"), dict) else {},
                "artifacts": row.get("artifacts") if isinstance(row.get("artifacts"), list) else [],
                "error": row.get("error") or "",
                "next_action": row.get("next_action") or "",
            }
        )
    def status_rank(item: dict[str, Any]) -> tuple[int, int, int, str]:
        progress = item.get("progress") if isinstance(item.get("progress"), dict) else {}
        return (
            1 if clean(item.get("status")) in {"running", "pending", "waiting_approval"} else 0,
            int(progress.get("downloaded") or 0),
            int(progress.get("indexed") or 0),
            clean(item.get("started_at") or item.get("finished_at")),
        )

    statuses.sort(key=status_rank, reverse=True)
    return statuses[: max(int(limit or 5), 1)]


def format_task_status_answer(task_status: list[dict[str, Any]], last_keywords: list[str] | None = None) -> str:
    lit_candidates = [item for item in task_status if item.get("task_type") == "literature_harvest"]
    lit = next((item for item in lit_candidates if clean(item.get("status")) == "running"), None)
    if not lit and lit_candidates:
        lit = max(
            lit_candidates,
            key=lambda item: (
                int((item.get("progress") or {}).get("downloaded") or 0),
                int((item.get("progress") or {}).get("indexed") or 0),
                int((item.get("progress") or {}).get("total") or 0),
            ),
        )
    if not task_status:
        if last_keywords:
            return f"No active task exists. I can start a literature collection task using the last detected keywords: {', '.join(last_keywords)}."
        return "No active task exists. Tell me the literature keywords and I can start a collection task."
    if lit:
        progress = lit.get("progress") or {}
        counters = lit.get("counters") if isinstance(lit.get("counters"), dict) else literature_task_counters(progress)
        current_stage = clean(lit.get("current_stage") or progress.get("current_stage")) or normalize_literature_current_stage(clean(lit.get("status")), progress)
        answer = (
            "Current harvest task status:\n"
            f"status: {clean(lit.get('status')) or 'unknown'}\n"
            f"Status: {clean(lit.get('status')) or 'unknown'}\n"
            f"current_stage: {current_stage}\n"
            f"keywords: {', '.join([clean(item) for item in as_list(lit.get('keywords')) if clean(item)]) or clean(lit.get('query'))}\n"
            f"found: {counters.get('found', 0)}\n"
            f"downloaded: {counters.get('downloaded', 0)}\n"
            f"parsed: {counters.get('parsed', 0)}\n"
            f"ingested: {counters.get('ingested', 0)}\n"
            f"failed: {counters.get('failed', 0)}\n"
            f"Counters: found {counters.get('found', 0)}, downloaded {counters.get('downloaded', 0)}, "
            f"parsed {counters.get('parsed', 0)}, ingested {counters.get('ingested', 0)}, failed {counters.get('failed', 0)}."
        )
        request_counter_lines = []
        for key in ["non_oa_pending_count", "user_download_needed_count", "user_uploaded_count", "user_uploaded_ingested_count"]:
            if int(counters.get(key) or 0) > 0:
                request_counter_lines.append(f"{key}: {int(counters.get(key) or 0)}")
        if request_counter_lines:
            answer += "\n" + "\n".join(request_counter_lines)
        if counters == {"found": 0, "downloaded": 0, "parsed": 0, "ingested": 0, "failed": 0}:
            answer += "\nCurrent stage: searching PubMed or configured literature sources. No candidate papers have been collected yet."
        if clean(progress.get("current_title")):
            answer += f"\nCurrent item: {clean(progress.get('current_title'))} ({current_stage})."
        return answer
    running = [item for item in task_status if clean(item.get("status")) in {"running", "pending", "waiting_approval"}]
    if not running:
        return "目前没有检测到正在运行的文献采集或 Skill 任务。最近任务记录在右侧状态面板里。"
    item = running[0]
    return f"当前有 1 个任务正在运行：{clean(item.get('task_name'))}，状态 {clean(item.get('status'))}。"


def format_paper_request_list_answer(result: dict[str, Any]) -> str:
    requests = [item for item in as_list(result.get("paper_requests")) if isinstance(item, dict)]
    pending = [item for item in requests if clean(item.get("status")) == "pending"]
    watch_folder = clean(result.get("watch_folder_display")) or "research_os_files/paper_requests/<project_id>"
    if not pending:
        return (
            "当前没有需要你下载的高价值非 OA 文献。"
            f"如果你已经补充 PDF，可以放入 watch folder: {watch_folder}，然后告诉我“我已经把 PDF 放进文件夹了”。"
        )
    lines = [
        f"当前有 {len(pending)} 篇高价值文献需要你下载 PDF。",
        f"请下载后放入 watch folder: {watch_folder}",
        "",
        "待下载文献清单：",
    ]
    for index, item in enumerate(pending[:10], start=1):
        title = _display_or_missing(item.get("title"))
        doi = _display_doi(item.get("doi"))
        journal = _display_or_missing(item.get("journal"), "journal not available")
        year = _display_year(item.get("year"))
        filename = clean(item.get("suggested_filename")) or "metadata missing"
        reason = clean(item.get("reason")) or "High relevance but the PDF was not downloaded automatically."
        lines.append(f"{index}. {title}")
        lines.append(f"   year: {year}; DOI: {doi}; journal: {journal}")
        lines.append(f"   suggested filename: {filename}")
        lines.append(f"   reason: {reason}")
    return "\n".join(lines)


def format_user_pdf_processing_answer(result: dict[str, Any]) -> str:
    watch_folder = clean(result.get("watch_folder_display")) or "research_os_files/paper_requests/<project_id>"
    matched = int(result.get("matched_count") or 0)
    ingested = int(result.get("ingested_count") or 0)
    unmatched = int(result.get("unmatched_count") or 0)
    failed = int(result.get("failed_count") or 0)
    lines = [
        "已检查用户补充 PDF 文件夹。",
        f"watch folder: {watch_folder}",
        f"matched: {matched}",
        f"ingested: {ingested}",
        f"unmatched: {unmatched}",
        f"failed: {failed}",
    ]
    if matched:
        lines.append("匹配成功的 PDF 已解析、切块并写入 KB/RAG。")
    if unmatched:
        lines.append("有 PDF 无法自动匹配，已进入 unmatched_pdf 队列，需要你确认对应哪篇文献。")
    if failed:
        lines.append("有 PDF 处理失败，错误已记录在 paper_request 状态中。")
    return "\n".join(lines)


def _recent_artifact_rows(conn: sqlite3.Connection, project_id: str, limit: int = 30) -> list[dict[str, Any]]:
    if not db_table_exists(conn, "artifacts"):
        return []
    return rows_to_dicts(
        conn.execute(
            "SELECT * FROM artifacts WHERE project_id=? ORDER BY updated_at DESC LIMIT ?",
            (project_id, limit),
        ).fetchall()
    )


def _artifact_counts_by_type(conn: sqlite3.Connection, project_id: str) -> dict[str, int]:
    if not db_table_exists(conn, "artifacts"):
        return {}
    rows = conn.execute(
        "SELECT type, COUNT(*) AS c FROM artifacts WHERE project_id=? GROUP BY type ORDER BY type",
        (project_id,),
    ).fetchall()
    return {clean(row["type"]): int(row["c"]) for row in rows if clean(row["type"])}


def _count_project_pdfs_on_disk(agent_root: Path, project_id: str) -> tuple[int, list[dict[str, Any]]]:
    root = data_dir(agent_root) / "literature_harvest" / project_id
    if not root.exists():
        return 0, []
    pdf_paths = sorted((path for path in root.rglob("*.pdf") if path.is_file()), key=lambda p: p.stat().st_mtime, reverse=True)
    recent = [
        {
            "title": path.stem,
            "path": str(path),
            "filename": path.name,
            "modified_at": datetime.fromtimestamp(path.stat().st_mtime).isoformat(timespec="seconds"),
        }
        for path in pdf_paths[:20]
    ]
    return len(pdf_paths), recent


def _project_literature_inventory(conn: sqlite3.Connection, agent_root: Path, project_id: str) -> dict[str, Any]:
    project_id = clean(project_id)
    project = row_to_dict(conn.execute("SELECT id, title, research_area, status, updated_at FROM projects WHERE id=?", (project_id,)).fetchone()) if project_id else {}
    pdf_files_found, recent_pdfs = _count_project_pdfs_on_disk(agent_root, project_id)
    references_count = db_count(conn, "references", "project_id=?", (project_id,))
    documents_count = db_count(conn, "documents", "project_id=?", (project_id,))
    reference_chunks_count = db_count(conn, "reference_chunks", "project_id=?", (project_id,))
    document_chunks_count = db_count(conn, "document_chunks", "project_id=?", (project_id,))
    kb_entries_count = db_count(conn, "knowledge_base_entries", "project_id=?", (project_id,))
    downloaded_ingest = db_count(conn, "literature_ingest_items", "project_id=? AND download_status='downloaded'", (project_id,))
    chunks_count = reference_chunks_count + document_chunks_count
    score = int(max(pdf_files_found, downloaded_ingest) + references_count * 6 + documents_count * 4 + chunks_count / 20 + kb_entries_count / 20)
    return {
        "project_id": project_id,
        "project_title": clean(project.get("title")) or project_id,
        "research_area": clean(project.get("research_area")),
        "status": clean(project.get("status")),
        "updated_at": clean(project.get("updated_at")),
        "pdf_files_found": max(pdf_files_found, downloaded_ingest),
        "references_count": references_count,
        "documents_count": documents_count,
        "chunks_count": chunks_count,
        "reference_chunks_count": reference_chunks_count,
        "document_chunks_count": document_chunks_count,
        "kb_entries_count": kb_entries_count,
        "recent_pdfs": recent_pdfs[:5],
        "asset_score": score,
    }


def _cross_project_literature_candidates(conn: sqlite3.Connection, agent_root: Path, current_project_id: str, limit: int = 5) -> list[dict[str, Any]]:
    rows = rows_to_dicts(
        conn.execute(
            "SELECT id FROM projects WHERE status!='archived' ORDER BY updated_at DESC LIMIT 50"
        ).fetchall()
    )
    candidates: list[dict[str, Any]] = []
    for row in rows:
        project_id = clean(row.get("id"))
        if not project_id or project_id == current_project_id:
            continue
        inventory = _project_literature_inventory(conn, agent_root, project_id)
        if int(inventory.get("asset_score") or 0) > 0:
            candidates.append(inventory)
    candidates.sort(
        key=lambda item: (
            int(item.get("asset_score") or 0),
            int(item.get("references_count") or 0),
            int(item.get("chunks_count") or 0),
            clean(item.get("updated_at")),
        ),
        reverse=True,
    )
    return candidates[:limit]


def workspace_state(agent_root: Path, project_id: str = "") -> dict[str, Any]:
    project_id = clean(project_id)
    conn = connect(agent_root)
    try:
        if not project_id:
            row = conn.execute("SELECT id FROM projects WHERE status='active' ORDER BY updated_at DESC LIMIT 1").fetchone()
            project_id = clean(row["id"]) if row else ""
        project = normalize_project_row(agent_root, row_to_dict(conn.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone())) if project_id else {}

        pdf_files_found, recent_pdfs = _count_project_pdfs_on_disk(agent_root, project_id)
        references_count = db_count(conn, "references", "project_id=?", (project_id,))
        chunks_count = db_count(conn, "reference_chunks", "project_id=?", (project_id,))
        kb_entries_count = db_count(conn, "knowledge_base_entries", "project_id=?", (project_id,))
        documents_count = db_count(conn, "documents", "project_id=?", (project_id,))
        document_chunks_count = db_count(conn, "document_chunks", "project_id=?", (project_id,))
        downloaded_ingest = db_count(conn, "literature_ingest_items", "project_id=? AND download_status='downloaded'", (project_id,))
        discovered_not_ingested = db_count(
            conn,
            "literature_ingest_items",
            "project_id=? AND download_status='downloaded' AND (reference_id IS NULL OR reference_id='')",
            (project_id,),
        )
        registered_not_chunked = int(
            conn.execute(
                """
                SELECT COUNT(*) FROM "references" r
                WHERE r.project_id=? AND NOT EXISTS (
                  SELECT 1 FROM reference_chunks c WHERE c.reference_id=r.id
                )
                """,
                (project_id,),
            ).fetchone()[0]
        )
        refs_with_chunks = {
            clean(row["reference_id"])
            for row in conn.execute("SELECT DISTINCT reference_id FROM reference_chunks WHERE project_id=?", (project_id,)).fetchall()
        }
        refs_with_kb = {
            clean(row["source_reference_id"])
            for row in conn.execute(
                "SELECT DISTINCT source_reference_id FROM knowledge_base_entries WHERE project_id=? AND source_reference_id IS NOT NULL AND source_reference_id!=''",
                (project_id,),
            ).fetchall()
        }
        chunked_not_indexed = len(refs_with_chunks - refs_with_kb)
        recent_references = rows_to_dicts(
            conn.execute(
                'SELECT id, title, year, doi, source_provider, access_status, full_text_path, updated_at FROM "references" WHERE project_id=? ORDER BY updated_at DESC LIMIT 20',
                (project_id,),
            ).fetchall()
        )
        recent_skill_runs = rows_to_dicts(
            conn.execute(
                "SELECT id, skill_id, skill_name, status, created_at, updated_at, output_object_refs_json FROM skill_runs WHERE project_id=? ORDER BY updated_at DESC LIMIT 12",
                (project_id,),
            ).fetchall()
        )
        task_status: list[dict[str, Any]] = []
        lit_task_rows = rows_to_dicts(
            conn.execute(
                "SELECT * FROM literature_search_tasks WHERE project_id=? ORDER BY updated_at DESC LIMIT 20",
                (project_id,),
            ).fetchall()
        )
        for task in lit_task_rows:
            task_id = clean(task.get("id"))
            ingest_rows = rows_to_dicts(
                conn.execute(
                    "SELECT download_status, ingest_status, chunks_count, title FROM literature_ingest_items WHERE task_id=? LIMIT 5000",
                    (task_id,),
                ).fetchall()
            )
            notes = task.get("notes") if isinstance(task.get("notes"), dict) else json_loads(task.get("notes"), {})
            current = next((item for item in ingest_rows if clean(item.get("ingest_status")) in {"pending", "parsing", "chunked"}), {})
            request_counts = paper_request_counters(agent_root, project_id=project_id, task_id=task_id)
            task_status.append(
                {
                    "task_type": "literature_harvest",
                    "task_name": "文献采集",
                    "task_id": task_id,
                    "skill_id": "core_keyword_research_harvest",
                    "status": task.get("status"),
                    "query": task.get("query"),
                    "started_at": task.get("created_at"),
                    "finished_at": task.get("updated_at") if clean(task.get("status")) in {"completed", "failed"} else "",
                    "progress": {
                        "total": max(len(ingest_rows), len(as_list(task.get("result_reference_ids")))),
                        "downloaded": sum(1 for item in ingest_rows if clean(item.get("download_status")) == "downloaded"),
                        "parsed": sum(1 for item in ingest_rows if clean(item.get("ingest_status")) in {"chunked", "indexed"}),
                        "indexed": sum(1 for item in ingest_rows if clean(item.get("ingest_status")) == "indexed"),
                        "failed": sum(1 for item in ingest_rows if clean(item.get("download_status")) == "failed" or clean(item.get("ingest_status")) == "failed"),
                        "current_title": clean(current.get("title")),
                        "current_stage": clean(current.get("ingest_status")) or clean(notes.get("phase")),
                        "chunks_count": sum(int(item.get("chunks_count") or 0) for item in ingest_rows),
                        **{key: value for key, value in request_counts.items() if int(value or 0) > 0},
                    },
                    "artifacts": {"run_root": clean(notes.get("run_root")), "log_path": clean(notes.get("log_path"))},
                    "error": clean(notes.get("error")),
                }
            )
        for run in recent_skill_runs[:8]:
            task_status.append(
                {
                    "task_type": "skill_run",
                    "task_name": clean(run.get("skill_name")) or clean(run.get("skill_id")),
                    "task_id": run.get("id"),
                    "skill_id": run.get("skill_id"),
                    "status": run.get("status"),
                    "started_at": run.get("created_at"),
                    "finished_at": run.get("updated_at") if clean(run.get("status")) in {"completed", "failed"} else "",
                    "progress": {},
                    "artifacts": run.get("output_object_refs") or [],
                    "error": "",
                }
            )
        agent_task_rows = rows_to_dicts(
            conn.execute(
                "SELECT * FROM agent_tasks WHERE project_id=? ORDER BY updated_at DESC LIMIT 50",
                (project_id,),
            ).fetchall()
        )
        for task in agent_task_rows:
            task_status.append(
                {
                    "task_type": clean(task.get("task_type")),
                    "task_name": clean(task.get("task_type")).replace("_", " "),
                    "task_id": task.get("task_id"),
                    "skill_id": research_operating_loop.task_skill_id(clean(task.get("task_type"))),
                    "status": task.get("status"),
                    "started_at": task.get("created_at"),
                    "finished_at": task.get("updated_at") if clean(task.get("status")) in {"completed", "failed", "cancelled"} else "",
                    "progress": task.get("progress") if isinstance(task.get("progress"), dict) else {},
                    "artifacts": task.get("artifacts") if isinstance(task.get("artifacts"), list) else [],
                    "error": task.get("error") or "",
                    "next_action": task.get("next_action") or "",
                }
            )
        running = [item for item in task_status if clean(item.get("status")) in {"running", "pending", "waiting_approval"}]
        completed = [item for item in task_status if clean(item.get("status")) == "completed"]
        failed = [item for item in task_status if clean(item.get("status")) in {"failed", "cancelled"}]
        artifacts = _recent_artifact_rows(conn, project_id, limit=50)
        artifact_counts = _artifact_counts_by_type(conn, project_id)
        if not artifacts:
            for ref in recent_references[:10]:
                artifacts.append(
                    {
                        "artifact_id": stable_id(project_id, "reference", ref.get("id"), length=24),
                        "project_id": project_id,
                        "type": "reference",
                        "title": ref.get("title"),
                        "path": ref.get("full_text_path"),
                        "source_object_type": "reference",
                        "source_object_id": ref.get("id"),
                        "status": "indexed" if chunks_count else "created",
                        "metadata": {"doi": ref.get("doi"), "access_status": ref.get("access_status")},
                    }
                )
            for pdf in recent_pdfs[:10]:
                artifacts.append(
                    {
                        "artifact_id": stable_id(project_id, "pdf", pdf.get("path"), length=24),
                        "project_id": project_id,
                        "type": "pdf",
                        "title": pdf.get("filename"),
                        "path": pdf.get("path"),
                        "status": "created",
                        "metadata": {"modified_at": pdf.get("modified_at")},
                    }
                )

        current_inventory = _project_literature_inventory(conn, agent_root, project_id)
        cross_project_candidates = _cross_project_literature_candidates(conn, agent_root, project_id)
        diagnostic_warnings: list[str] = []
        selected_literature_total = (
            int(current_inventory.get("pdf_files_found") or 0)
            + int(current_inventory.get("references_count") or 0)
            + int(current_inventory.get("chunks_count") or 0)
            + int(current_inventory.get("kb_entries_count") or 0)
        )
        if selected_literature_total == 0 and cross_project_candidates:
            diagnostic_warnings.append("current_project_has_no_literature_but_other_projects_have_possible_misassigned_assets")
        elif int(current_inventory.get("chunks_count") or 0) == 0 and any(int(item.get("chunks_count") or 0) > 0 for item in cross_project_candidates):
            diagnostic_warnings.append("current_project_has_no_rag_chunks_but_other_projects_do")

        state = {
            "project": project,
            "active_project_id": project_id,
            "active_project_display_name": project_display_name(project),
            "literature": {
                "pdf_files_found": max(pdf_files_found, downloaded_ingest),
                "references_count": references_count,
                "documents_count": documents_count,
                "chunks_count": chunks_count + document_chunks_count,
                "reference_chunks_count": chunks_count,
                "document_chunks_count": document_chunks_count,
                "kb_entries_count": kb_entries_count,
                "recent_references": recent_references,
                "recent_pdfs": recent_pdfs,
                "discovered_not_ingested": discovered_not_ingested,
                "registered_not_chunked": registered_not_chunked,
                "chunked_not_indexed": chunked_not_indexed,
                "paper_requests": paper_request_counters(agent_root, project_id=project_id),
                "paper_request_watch_folder": str(paper_request_watch_folder(agent_root, project_id)),
            },
            "data": {
                "experiments_count": db_count(conn, "experiments", "project_id=?", (project_id,)),
                "samples_count": db_count(conn, "samples", "project_id=?", (project_id,)),
                "data_files_count": db_count(conn, "research_files", "project_id=?", (project_id,)),
                "analysis_results_count": db_count(conn, "claims", "project_id=? AND claim_type='result'", (project_id,)),
            },
            "tasks": {"running": running, "completed": completed, "failed": failed},
            "skills": {"recent_skill_runs": recent_skill_runs},
            "memory": {
                "project_memory_count": db_count(conn, "memory_entities", "project_id=?", (project_id,)),
                "agent_memory_count": db_count(conn, "agent_memory_entries", "project_id=?", (project_id,)),
                "execution_memory_count": db_count(conn, "execution_memory", "project_id=?", (project_id,)),
            },
            "rag": {
                "available": bool((chunks_count + document_chunks_count + kb_entries_count) > 0),
                "queryable_chunks": chunks_count + document_chunks_count,
                "last_indexed_at": clean(conn.execute("SELECT MAX(updated_at) FROM reference_chunks WHERE project_id=?", (project_id,)).fetchone()[0]) if db_table_exists(conn, "reference_chunks") else "",
            },
            "artifacts": artifacts,
            "artifact_summary": {
                "total_count": sum(artifact_counts.values()),
                "by_type": artifact_counts,
            },
            "workspace_diagnostics": {
                "warnings": diagnostic_warnings,
                "current_project_literature": current_inventory,
                "possible_misassigned_literature": cross_project_candidates,
            },
        }
        return state
    finally:
        conn.close()


def ensure_chat_session(agent_root: Path, project_id: str, conversation_id: str = "", title: str = "") -> dict[str, Any]:
    project_id = clean(project_id)
    if not project_id:
        raise ValueError("project_id is required")
    timestamp = now()
    session_id = clean(conversation_id) or stable_id(project_id, "chat_session", timestamp, title, length=24)
    session_title = clean(title)[:120] or "AURA Research chat"
    conn = connect(agent_root)
    try:
        existing = row_to_dict(conn.execute("SELECT * FROM chat_sessions WHERE id=?", (session_id,)).fetchone()) or {}
        if existing:
            existing_project_id = clean(existing.get("project_id"))
            if existing_project_id and existing_project_id != project_id:
                raise ValueError("chat session belongs to a different project")
            if existing_project_id:
                conn.execute(
                    """
                    UPDATE chat_sessions
                    SET title=COALESCE(NULLIF(title,''), ?),
                        updated_at=?
                    WHERE id=? AND project_id=?
                    """,
                    (session_title, timestamp, session_id, project_id),
                )
            else:
                conn.execute(
                    """
                    UPDATE chat_sessions
                    SET project_id=?,
                        title=COALESCE(NULLIF(title,''), ?),
                        updated_at=?
                    WHERE id=?
                    """,
                    (project_id, session_title, timestamp, session_id),
                )
            conn.commit()
            return row_to_dict(conn.execute("SELECT * FROM chat_sessions WHERE id=?", (session_id,)).fetchone()) or {}
        conn.execute(
            """
            INSERT INTO chat_sessions(id, project_id, title, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            """,
            (session_id, project_id, session_title, timestamp, timestamp),
        )
        conn.commit()
        return row_to_dict(conn.execute("SELECT * FROM chat_sessions WHERE id=?", (session_id,)).fetchone()) or {}
    finally:
        conn.close()


USER_VISIBLE_CHAT_ROLES = {"user", "assistant"}
INTERNAL_CONTEXT_MESSAGE_ROLES = {"system", "internal", "debug", "prompt", "developer", "tool"}
CHAT_HISTORY_INTERNAL_METADATA_KEYS = {
    "context_compiler_trace",
    "debug",
    "debug_log",
    "debug_trace",
    "developer_instruction",
    "developer_instructions",
    "error_stack",
    "internal_context",
    "internal_prompt",
    "prompt",
    "prompt_assembly",
    "prompt_messages",
    "raw_json",
    "raw_prompt",
    "routing_trace",
    "stack_trace",
    "system_prompt",
    "tool_routing_trace",
    "tool_routing",
}


def _sanitize_user_visible_chat_metadata(metadata: dict[str, Any] | None, *, role: str = "") -> dict[str, Any]:
    if not isinstance(metadata, dict):
        return {}
    sanitized: dict[str, Any] = {}
    for key, value in metadata.items():
        normalized_key = clean(key).lower()
        if not normalized_key:
            continue
        if normalized_key in CHAT_HISTORY_INTERNAL_METADATA_KEYS:
            continue
        if any(token in normalized_key for token in ["system_prompt", "developer_instruction", "debug_trace", "error_stack", "raw_prompt", "prompt_assembly", "context_compiler_trace"]):
            continue
        sanitized[key] = value
    if clean(role).lower() == "assistant":
        response_type = clean(sanitized.pop("intent", ""))
        canonical_intent = clean(sanitized.pop("canonical_intent", ""))
        if response_type and not clean(sanitized.get("assistant_response_type")):
            sanitized["assistant_response_type"] = response_type
        if canonical_intent and not clean(sanitized.get("assistant_canonical_intent")):
            sanitized["assistant_canonical_intent"] = canonical_intent
    return sanitized


def _insert_internal_context_event(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    session_id: str = "",
    event_type: str,
    source: str,
    content: str,
    metadata: dict[str, Any] | None = None,
    timestamp: str = "",
) -> dict[str, Any]:
    timestamp = clean(timestamp) or now()
    event_type = clean(event_type) or "internal_context_event"
    event_id = stable_id(project_id, session_id, event_type, content, timestamp, length=24)
    conn.execute(
        """
        INSERT INTO internal_context_events(
          id, project_id, session_id, event_type, source, content, metadata_json,
          visible_to_user, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?)
        """,
        (
            event_id,
            clean(project_id),
            clean(session_id),
            event_type,
            clean(source),
            clean(content),
            json_dumps(metadata or {}),
            timestamp,
            timestamp,
        ),
    )
    row = row_to_dict(conn.execute("SELECT * FROM internal_context_events WHERE id=?", (event_id,)).fetchone()) or {}
    row["table"] = "internal_context_events"
    row["visible_to_user"] = False
    return row


def save_internal_context_event(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    session_id = clean(payload.get("session_id") or payload.get("conversation_id"))
    if not project_id:
        raise ValueError("project_id is required")
    conn = connect(agent_root)
    try:
        if session_id:
            session = row_to_dict(conn.execute("SELECT * FROM chat_sessions WHERE id=?", (session_id,)).fetchone()) or {}
            if not session:
                raise ValueError("chat session not found")
            if clean(session.get("project_id")) != project_id:
                raise ValueError("chat session belongs to a different project")
        event = _insert_internal_context_event(
            conn,
            project_id=project_id,
            session_id=session_id,
            event_type=clean(payload.get("event_type")) or "internal_context_event",
            source=clean(payload.get("source")) or "internal",
            content=clean(payload.get("content")),
            metadata=payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {},
        )
        conn.commit()
        return event
    finally:
        conn.close()


def save_chat_message(agent_root: Path, session_id: str, role: str, content: str, metadata: dict[str, Any] | None = None, project_id: str = "") -> dict[str, Any]:
    session_id = clean(session_id)
    role = clean(role).lower()
    metadata = metadata or {}
    project_id = clean(project_id) or clean(metadata.get("project_id"))
    if not session_id:
        raise ValueError("session_id is required")
    if not project_id:
        raise ValueError("project_id is required")
    if role not in USER_VISIBLE_CHAT_ROLES and role not in INTERNAL_CONTEXT_MESSAGE_ROLES:
        raise ValueError("unsupported chat role")
    timestamp = now()
    message_id = stable_id(session_id, role, content, timestamp, length=24)
    conn = connect(agent_root)
    try:
        session = row_to_dict(conn.execute("SELECT * FROM chat_sessions WHERE id=?", (session_id,)).fetchone()) or {}
        if not session:
            raise ValueError("chat session not found")
        if clean(session.get("project_id")) != project_id:
            raise ValueError("chat session belongs to a different project")
        if role not in USER_VISIBLE_CHAT_ROLES:
            event = _insert_internal_context_event(
                conn,
                project_id=project_id,
                session_id=session_id,
                event_type=f"{role}_message",
                source="save_chat_message",
                content=content,
                metadata={**(metadata if isinstance(metadata, dict) else {}), "original_role": role},
                timestamp=timestamp,
            )
            conn.execute("UPDATE chat_sessions SET updated_at=? WHERE id=? AND project_id=?", (timestamp, session_id, project_id))
            conn.commit()
            return event
        conn.execute(
            """
            INSERT INTO chat_messages(id, session_id, role, content, created_at, metadata_json)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (message_id, session_id, role, clean(content), timestamp, json_dumps(_sanitize_user_visible_chat_metadata(metadata, role=role))),
        )
        conn.execute("UPDATE chat_sessions SET updated_at=? WHERE id=? AND project_id=?", (timestamp, session_id, project_id))
        conn.commit()
        return row_to_dict(conn.execute("SELECT * FROM chat_messages WHERE id=?", (message_id,)).fetchone()) or {}
    finally:
        conn.close()


def list_chat_messages(agent_root: Path, conversation_id: str, project_id: str = "", limit: int = 12, include_internal: bool = False) -> list[dict[str, Any]]:
    conversation_id = clean(conversation_id)
    project_id = clean(project_id)
    if not conversation_id:
        return []
    if not project_id:
        raise ValueError("project_id is required")
    conn = connect(agent_root)
    try:
        rows = rows_to_dicts(
            conn.execute(
                """
                SELECT * FROM (
                  SELECT m.*, m.rowid AS _rowid
                  FROM chat_messages m
                  INNER JOIN chat_sessions s ON s.id=m.session_id
                  WHERE m.session_id=? AND s.project_id=?
                    AND (? OR m.role IN ('user', 'assistant'))
                  ORDER BY m.created_at DESC, m.rowid DESC
                  LIMIT ?
                ) ORDER BY created_at ASC, _rowid ASC
                """,
                (conversation_id, project_id, 1 if include_internal else 0, max(1, int(limit or 12))),
            ).fetchall()
        )
        for row in rows:
            row.pop("_rowid", None)
        return rows
    finally:
        conn.close()


def latest_chat_intent(messages: list[dict[str, Any]]) -> str:
    for message in reversed(messages):
        if clean(message.get("role")).lower() != "user":
            continue
        metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else json_loads(message.get("metadata_json"), {})
        return clean(metadata.get("intent")) if isinstance(metadata, dict) else ""
    return ""


def is_conversation_history_query(message: str) -> bool:
    lower = clean(message).lower()
    patterns = [
        "我刚才问",
        "刚才问过",
        "上一个问题",
        "前一个问题",
        "第一句话",
        "第一句",
        "刚才第一句话",
        "刚才第一句",
        "刚才那个",
        "继续刚才",
        "你刚才说",
        "刚才说的",
        "上一个回答",
        "上一条回答",
        "前一个回答",
        "回答第二点",
        "what did i ask",
        "previous question",
        "last question",
        "previous answer",
        "last answer",
    ]
    return any(pattern in lower for pattern in patterns)


def format_conversation_history_answer(messages: list[dict[str, Any]], current_message: str) -> str:
    user_messages = [clean(item.get("content")) for item in messages if clean(item.get("role")) == "user" and clean(item.get("content")) != clean(current_message)]
    assistant_messages = [clean(item.get("content")) for item in messages if clean(item.get("role")) == "assistant"]
    lower = clean(current_message).lower()
    if "你刚才说" in lower or "刚才说的" in lower:
        if assistant_messages:
            return f"我刚才说的是：{assistant_messages[-1][:280]}"
        return "当前会话里还没有上一条回答。"
    if "上一个问题" in lower or "前一个问题" in lower or "last question" in lower or "previous question" in lower:
        if user_messages:
            return f"你上一个问题是：{user_messages[-1]}"
        return "当前会话里还没有上一条用户问题。"
    if user_messages:
        recent = user_messages[-5:]
        return "你刚才问过这些问题：" + "；".join(f"{index}. {text}" for index, text in enumerate(recent, start=1))
    return "当前会话里还没有更早的用户问题。"


def _decode_inbox_row(row: dict[str, Any]) -> dict[str, Any]:
    item = dict(row)
    item["related_sources"] = json_loads(item.pop("related_sources_json", ""), [])
    item["actions"] = json_loads(item.pop("actions_json", ""), [])
    return item


def list_agent_inbox(agent_root: Path, project_id: str = "", status: str = "", limit: int = 50) -> dict[str, Any]:
    project_id = clean(project_id)
    status = clean(status)
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    if status:
        clauses.append("status=?")
        params.append(status)
    params.append(max(1, min(int(limit or 50), 200)))
    conn = connect(agent_root)
    try:
        rows = rows_to_dicts(
            conn.execute(
                f"SELECT * FROM agent_inbox_items WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC LIMIT ?",
                params,
            ).fetchall()
        )
        return {"items": [_decode_inbox_row(row) for row in rows]}
    finally:
        conn.close()


def update_agent_inbox_item(agent_root: Path, item_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    item_id = clean(item_id)
    if not item_id:
        raise ValueError("item_id is required")
    allowed_status = {"unread", "read", "ignored", "dismissed", "accepted"}
    status = clean(payload.get("status"))
    if status and status not in allowed_status:
        raise ValueError("unsupported inbox status")
    assignments: list[str] = []
    values: list[Any] = []
    if status:
        assignments.append("status=?")
        values.append(status)
    if "message" in payload:
        assignments.append("message=?")
        values.append(clean(payload.get("message")))
    if not assignments:
        raise ValueError("no supported inbox fields to update")
    assignments.append("updated_at=?")
    values.extend([now(), item_id])
    conn = connect(agent_root)
    try:
        conn.execute(f"UPDATE agent_inbox_items SET {', '.join(assignments)} WHERE id=?", values)
        row = conn.execute("SELECT * FROM agent_inbox_items WHERE id=?", (item_id,)).fetchone()
        if not row:
            raise KeyError("inbox item not found")
        conn.commit()
        return _decode_inbox_row(row_to_dict(row) or {})
    finally:
        conn.close()


def _persist_agent_inbox_items(conn: sqlite3.Connection, project_id: str, items: list[dict[str, Any]], trigger: str) -> list[dict[str, Any]]:
    saved: list[dict[str, Any]] = []
    timestamp = now()
    for item in items:
        title = clean(item.get("title"))
        message = clean(item.get("message"))
        item_type = clean(item.get("type")) or "next_action"
        if not title:
            continue
        item_id = clean(item.get("id")) or stable_id(project_id, item_type, title, message, length=24)
        row = {
            "id": item_id,
            "project_id": project_id,
            "type": item_type,
            "title": title,
            "message": message,
            "priority": clean(item.get("priority")) or "medium",
            "status": clean(item.get("status")) or "unread",
            "related_sources_json": json_dumps(item.get("related_sources") or []),
            "actions_json": json_dumps(item.get("actions") or []),
            "trigger": trigger,
            "created_from": "research_watcher",
            "created_at": timestamp,
            "updated_at": timestamp,
        }
        conn.execute(
            """
            INSERT INTO agent_inbox_items(
              id, project_id, type, title, message, priority, status, related_sources_json,
              actions_json, trigger, created_from, created_at, updated_at
            )
            VALUES (
              :id, :project_id, :type, :title, :message, :priority, :status, :related_sources_json,
              :actions_json, :trigger, :created_from, :created_at, :updated_at
            )
            ON CONFLICT(id) DO UPDATE SET
              message=excluded.message,
              priority=excluded.priority,
              related_sources_json=excluded.related_sources_json,
              actions_json=excluded.actions_json,
              trigger=excluded.trigger,
              updated_at=excluded.updated_at
            """,
            row,
        )
        saved.append(_decode_inbox_row(row))
    return saved


def run_research_watcher(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    trigger = clean(payload.get("trigger")) or "manual"
    workspace = workspace_state(agent_root, project_id)
    result = research_watcher.watch_project({**payload, "project_id": project_id, "trigger": trigger, "workspace_state": workspace})
    paper_requests_created = []
    for paper in result.get("papers_need_user_download") or []:
        if not isinstance(paper, dict) or not clean(paper.get("title")):
            continue
        reference_id = clean(paper.get("reference_id"))
        reference = _reference_for_paper_request(agent_root, {"reference_id": reference_id}) if reference_id else {}
        try:
            paper_requests_created.append(
                create_paper_request(
                    agent_root,
                    {
                        "project_id": project_id,
                        "task_id": clean(reference.get("search_task_id")),
                        "reference_id": reference_id,
                        "title": clean(paper.get("title")),
                        "doi": clean(paper.get("doi")),
                        "journal": clean(reference.get("journal")),
                        "year": clean(paper.get("year") or reference.get("year")),
                        "url": clean(reference.get("url")),
                        "reason": clean(paper.get("reason")) or "This high-value paper needs a user-provided PDF.",
                        "access_status": clean(reference.get("access_status")) or "non_oa_need_user_download",
                        "metadata": {"source": "research_watcher", "score": paper.get("score")},
                    },
                )
            )
        except Exception:
            pass
    conn = connect(agent_root)
    try:
        saved_items = _persist_agent_inbox_items(conn, project_id, result.get("inbox_items") or [], trigger)
        conn.commit()
    finally:
        conn.close()
    memory_updates = []
    for update in result.get("memory_updates") or []:
        memory_id = stable_id(project_id, "research_watcher", update.get("title"), length=24)
        memory_updates.append(
            create_agent_memory_entry(
                agent_root,
                {
                    "id": memory_id,
                    "memory_scope": "project",
                    "project_id": project_id,
                    "memory_type": clean(update.get("memory_type")) or "project_watch_summary",
                    "title": clean(update.get("title")) or "Agent project watch summary",
                    "content": clean(update.get("content")),
                    "structured_content": update.get("structured_content") or {},
                    "source_type": "research_watcher",
                    "source_id": stable_id(project_id, "research_watcher", trigger, length=24),
                    "provenance": [{"type": "workspace_state", "project_id": project_id}, {"type": "research_watcher", "trigger": trigger}],
                    "confidence": float(update.get("confidence") or 0.76),
                    "trust_level": clean(update.get("trust_level")) or "raw_extracted",
                    "status": "active",
                },
            )
        )
    return {
        **result,
        "project_id": project_id,
        "workspace_state": workspace,
        "inbox_items": saved_items,
        "memory_updates": memory_updates,
        "paper_requests_created": paper_requests_created,
    }


def _project_watch_keywords(project: dict[str, Any]) -> list[str]:
    keywords = as_list(project.get("keywords") or project.get("keywords_json"))
    if not keywords and clean(project.get("keywords_json")):
        keywords = as_list(json_loads(project.get("keywords_json"), []))
    if not keywords:
        keywords = extract_seed_keywords(" ".join([clean(project.get("title")), clean(project.get("research_area")), clean(project.get("short_description"))]), 8)
    seen: set[str] = set()
    result: list[str] = []
    for item in keywords:
        keyword = clean(item)
        if keyword and keyword.lower() not in seen:
            seen.add(keyword.lower())
            result.append(keyword)
    return result[:6]


def _minutes_since(timestamp: str) -> float:
    timestamp = clean(timestamp)
    if not timestamp:
        return 10**9
    try:
        return (datetime.now() - datetime.fromisoformat(timestamp)).total_seconds() / 60
    except Exception:
        return 10**9


def _watch_state_row(conn: sqlite3.Connection, project_id: str) -> dict[str, Any]:
    row = row_to_dict(conn.execute("SELECT * FROM agent_watch_state WHERE project_id=?", (project_id,)).fetchone())
    if row:
        return row
    timestamp = now()
    default_watch_minutes = int(os.environ.get("RESEARCHOS_WATCH_INTERVAL_MINUTES", "360") or 360)
    default_scout_minutes = int(os.environ.get("RESEARCHOS_LITERATURE_SCOUT_INTERVAL_MINUTES", "1440") or 1440)
    conn.execute(
        """
        INSERT INTO agent_watch_state(
          project_id, enabled, auto_literature_scout, watch_interval_minutes,
          literature_scout_interval_minutes, last_watch_at, last_literature_scout_at,
          last_error, metadata_json, created_at, updated_at
        )
        VALUES (?, 1, 1, ?, ?, '', '', '', ?, ?, ?)
        """,
        (project_id, default_watch_minutes, default_scout_minutes, json_dumps({}), timestamp, timestamp),
    )
    return row_to_dict(conn.execute("SELECT * FROM agent_watch_state WHERE project_id=?", (project_id,)).fetchone()) or {}


def configure_project_watch(agent_root: Path, project_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(project_id or payload.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    conn = connect(agent_root)
    try:
        _watch_state_row(conn, project_id)
        assignments: list[str] = []
        values: list[Any] = []
        if "enabled" in payload:
            assignments.append("enabled=?")
            values.append(1 if payload.get("enabled") else 0)
        if "auto_literature_scout" in payload:
            assignments.append("auto_literature_scout=?")
            values.append(1 if payload.get("auto_literature_scout") else 0)
        for field in ["watch_interval_minutes", "literature_scout_interval_minutes"]:
            if field in payload:
                assignments.append(f"{field}=?")
                values.append(max(5, int(payload.get(field) or 0)))
        if "metadata" in payload:
            assignments.append("metadata_json=?")
            values.append(json_dumps(payload.get("metadata") or {}))
        if assignments:
            assignments.append("updated_at=?")
            values.extend([now(), project_id])
            conn.execute(f"UPDATE agent_watch_state SET {', '.join(assignments)} WHERE project_id=?", values)
        conn.commit()
        return row_to_dict(conn.execute("SELECT * FROM agent_watch_state WHERE project_id=?", (project_id,)).fetchone()) or {}
    finally:
        conn.close()


def watcher_scheduler_status(agent_root: Path, project_id: str = "") -> dict[str, Any]:
    project_id = clean(project_id)
    conn = connect(agent_root)
    try:
        if project_id:
            rows = rows_to_dicts(conn.execute("SELECT * FROM agent_watch_state WHERE project_id=?", (project_id,)).fetchall())
        else:
            rows = rows_to_dicts(conn.execute("SELECT * FROM agent_watch_state ORDER BY updated_at DESC LIMIT 100").fetchall())
        return {"watch_states": rows}
    finally:
        conn.close()


def should_start_literature_scout(workspace: dict[str, Any], watch_state: dict[str, Any], force: bool = False) -> bool:
    if force:
        return True
    if int(watch_state.get("auto_literature_scout") or 0) != 1:
        return False
    if _minutes_since(clean(watch_state.get("last_literature_scout_at"))) < int(watch_state.get("literature_scout_interval_minutes") or 1440):
        return False
    running = workspace.get("tasks", {}).get("running") or []
    if any(clean(task.get("task_type")) == "literature_harvest" or "literature" in clean(task.get("task_name")).lower() for task in running if isinstance(task, dict)):
        return False
    literature = workspace.get("literature") or {}
    if int(literature.get("pdf_files_found") or 0) > int(os.environ.get("RESEARCHOS_AUTO_SCOUT_MAX_EXISTING_PDFS", "2000") or 2000):
        return False
    return True


def run_active_literature_scout(agent_root: Path, project_id: str, workspace: dict[str, Any], trigger: str = "scheduled") -> dict[str, Any]:
    project = workspace.get("project") or {}
    keywords = _project_watch_keywords(project)
    if not keywords:
        return {"started": False, "reason": "no project keywords", "keywords": []}
    max_results = int(os.environ.get("RESEARCHOS_AUTO_SCOUT_MAX_RESULTS", "25") or 25)
    payload = {
        "project_id": project_id,
        "keywords": keywords,
        "folder_keywords": keywords,
        "query": " ".join(keywords),
        "provider": "all",
        "max_results": max_results,
        "max_results_per_query": max_results,
        "trigger": trigger,
        "auto_started_by": "research_watcher",
    }
    result = run_skill(agent_root, "core_keyword_research_harvest", project_id=project_id, input_payload=payload)
    return {
        "started": True,
        "skill_run_id": result.get("skill_run_id"),
        "keywords": keywords,
        "max_results": max_results,
        "result": result,
    }


def run_scheduled_research_watch(agent_root: Path, force: bool = False, project_id: str = "") -> dict[str, Any]:
    target_project_id = clean(project_id)
    conn = connect(agent_root)
    try:
        if target_project_id:
            projects = rows_to_dicts(conn.execute("SELECT * FROM projects WHERE id=? AND status!='archived'", (target_project_id,)).fetchall())
        else:
            projects = rows_to_dicts(conn.execute("SELECT * FROM projects WHERE status!='archived' ORDER BY updated_at DESC LIMIT 20").fetchall())
        watch_inputs: list[tuple[dict[str, Any], dict[str, Any]]] = []
        for project in projects:
            pid = clean(project.get("id"))
            state = _watch_state_row(conn, pid)
            watch_inputs.append((project, state))
        conn.commit()
    finally:
        conn.close()

    outcomes: list[dict[str, Any]] = []
    for project, state in watch_inputs:
        pid = clean(project.get("id"))
        if int(state.get("enabled") or 0) != 1 and not force:
            continue
        if not force and _minutes_since(clean(state.get("last_watch_at"))) < int(state.get("watch_interval_minutes") or 360):
            continue
        watcher_result = run_research_watcher(agent_root, {"project_id": pid, "trigger": "scheduled"})
        workspace = watcher_result.get("workspace_state") or workspace_state(agent_root, pid)
        scout_result = {"started": False, "reason": "not due"}
        if should_start_literature_scout(workspace, state, force=bool(force and target_project_id)):
            try:
                scout_result = run_active_literature_scout(agent_root, pid, workspace, trigger="scheduled")
            except Exception as exc:
                scout_result = {"started": False, "error": str(exc)}
        try:
            heartbeat_result = agent_heartbeat(
                agent_root,
                {
                    "project_id": pid,
                    "trigger": "scheduled",
                    "auto_run_low_risk": True,
                    "max_auto_run": int(os.environ.get("RESEARCHOS_SCHEDULER_MAX_AUTO_RUN", "3") or 3),
                    "skip_watcher": True,
                },
            )
        except Exception as exc:
            heartbeat_result = {"ok": False, "error": str(exc), "auto_run_results": []}
        try:
            weekly_digest_result = run_scheduled_weekly_digest(
                agent_root,
                force=bool(force and target_project_id),
                project_id=pid,
            )
        except Exception as exc:
            weekly_digest_result = {"ok": False, "error": str(exc), "outcomes": []}
        timestamp = now()
        conn = connect(agent_root)
        try:
            conn.execute(
                """
                UPDATE agent_watch_state
                SET last_watch_at=?, last_literature_scout_at=CASE WHEN ?=1 THEN ? ELSE last_literature_scout_at END,
                    last_error=?, metadata_json=?, updated_at=?
                WHERE project_id=?
                """,
                (
                    timestamp,
                    1 if scout_result.get("started") else 0,
                    timestamp,
                    clean(scout_result.get("error") or heartbeat_result.get("error") or weekly_digest_result.get("error")),
                    json_dumps({"last_scout": scout_result, "last_heartbeat": heartbeat_result, "last_weekly_digest": weekly_digest_result, "last_tags": watcher_result.get("project_state_tags", [])}),
                    timestamp,
                    pid,
                ),
            )
            conn.commit()
        finally:
            conn.close()
        outcomes.append({"project_id": pid, "watcher": watcher_result, "literature_scout": scout_result, "heartbeat": heartbeat_result, "weekly_digest": weekly_digest_result})
    return {"ok": True, "checked_projects": len(projects), "outcomes": outcomes}


def proactive_progress_answer(watcher_result: dict[str, Any], inbox: list[dict[str, Any]]) -> str:
    summary = clean(watcher_result.get("project_state_summary"))
    findings = watcher_result.get("new_findings") or []
    gaps = watcher_result.get("knowledge_gaps") or []
    questions = watcher_result.get("questions_for_user") or []
    lines = [summary] if summary else ["我已经扫描了当前项目。"]
    if findings:
        lines.append(f"我发现 {len(findings)} 条值得优先看的文献线索，已经放到 Research Feed。")
    if gaps:
        lines.append(f"当前最需要处理的是：{clean(gaps[0].get('gap'))}")
    elif inbox:
        lines.append(f"Research Feed 里有 {len(inbox)} 条待处理建议。")
    if questions:
        lines.append(clean(questions[0]))
    return " ".join(lines[:4])


def agent_capability_summary(agent_root: Path, project_id: str = "") -> dict[str, Any]:
    conn = connect(agent_root)
    try:
        skills = rows_to_dicts(
            conn.execute(
                """
                SELECT skill_id, skill_name, description, skill_type, handler, status
                FROM skill_registry
                WHERE status!='disabled'
                ORDER BY
                  CASE
                    WHEN skill_id='core_keyword_research_harvest' THEN 0
                    WHEN skill_id='core_extract_first_article_keywords' THEN 1
                    WHEN skill_id='core_build_user_research_kb' THEN 2
                    WHEN skill_id='core_ingest_research_evidence' THEN 3
                    WHEN skill_id='core_query_research_rag' THEN 4
                    WHEN skill_id='core_manage_agent_memory' THEN 5
                    ELSE 10
                  END,
                  skill_name
                LIMIT 24
                """
            ).fetchall()
        )
        watch_state = {}
        if project_id:
            watch_state = row_to_dict(conn.execute("SELECT * FROM agent_watch_state WHERE project_id=?", (project_id,)).fetchone()) or {}
    finally:
        conn.close()
    primary = [
        "文献采集和开放全文下载",
        "PDF/HTML/XML 解析入库",
        "单篇文章关键词和证据提取",
        "本地 KB/RAG 查询",
        "项目记忆整理",
        "实验记录结构化",
        "数据文件上下文化",
        "周报、缺口分析和写作辅助",
        "主动 Research Feed 和联网 Scout",
    ]
    return {"primary_capabilities": primary, "skills": skills, "watch_state": watch_state}


def normalize_capability_status(status: str) -> str:
    value = clean(status).lower()
    if value in {"real", "ready", "enabled", "available", "ok"}:
        return "working"
    if value in {"working", "partial", "mock", "missing"}:
        return value
    return "partial" if value else "missing"


def _catalog_item(
    *,
    capability_id: str,
    category: str,
    name: str,
    status: str,
    description: str,
    sources: list[str],
    notes: str = "",
) -> dict[str, Any]:
    return {
        "capability_id": capability_id,
        "category": category,
        "name": name,
        "status": normalize_capability_status(status),
        "description": clean(description),
        "sources": [clean(item) for item in sources if clean(item)],
        "notes": clean(notes),
    }


def build_capability_catalog(agent_root: Path, project_id: str = "") -> dict[str, Any]:
    """Build a user-facing capability catalog from live ResearchOS components."""
    audit = get_researchos_capability_status(agent_root, project_id)
    conn = connect(agent_root)
    try:
        enabled_skill_count = db_count(conn, "skill_registry", "status!='disabled'") if db_table_exists(conn, "skill_registry") else 0
        workflow_count = len(RESEARCH_TASK_WORKFLOWS)
        running_tasks = 0
        if project_id and db_table_exists(conn, "literature_search_tasks"):
            running_tasks += db_count(conn, "literature_search_tasks", "project_id=? AND status IN ('pending','running')", (project_id,))
        if project_id and db_table_exists(conn, "agent_tasks"):
            running_tasks += db_count(conn, "agent_tasks", "project_id=? AND status IN ('pending','running')", (project_id,))
    finally:
        conn.close()

    sources = [
        "skill_registry",
        "workflow_registry",
        "task_types",
        "kb_rag",
        "project_memory",
        "artifact_store",
        "scheduler_watcher",
        "data_tools",
        "literature_tools",
    ]
    details = audit.get("details") if isinstance(audit.get("details"), dict) else {}
    items = [
        _catalog_item(
            capability_id="literature_knowledge_base",
            category="文献与知识库",
            name="文献采集、解析、KB/RAG 查询",
            status=audit.get("kb_rag") if audit.get("kb_rag") == "real" else audit.get("literature_harvest"),
            description="基于关键词采集文献，解析可获得全文，构建项目知识库并支持证据检索。",
            sources=["skill_registry", "kb_rag", "literature_tools"],
            notes=f"{enabled_skill_count} enabled skills" if enabled_skill_count else "",
        ),
        _catalog_item(
            capability_id="autonomous_learning_weekly_digest",
            category="自主学习与周报",
            name="受控项目级学习、学习总结、周报",
            status="working" if _callable_exists("generate_weekly_project_digest") and audit.get("artifact_store") in {"real", "partial"} else "partial",
            description="汇总新增文献、KB 内容、项目记忆和任务状态，生成学习总结或周报 artifact，并创建待确认记忆。",
            sources=["workflow_registry", "artifact_store", "project_memory"],
            notes=f"{workflow_count} workflow types" if workflow_count else "",
        ),
        _catalog_item(
            capability_id="non_oa_paper_requests",
            category="非 OA 文献请求用户下载",
            name="非 OA / 无法自动下载文献请求",
            status="partial" if _callable_exists("generate_paper_requests_for_task") else "missing",
            description="识别无法自动获取的文献，生成用户下载清单，并在用户补充 PDF 后继续解析入库。",
            sources=["literature_tools", "task_types"],
        ),
        _catalog_item(
            capability_id="experiment_failure_knowledge",
            category="实验记录与失败百科",
            name="实验记录结构化与失败复盘",
            status="partial" if _callable_exists("create_experiment_record") or _callable_exists("record_experiment_run") else "missing",
            description="整理实验记录、失败原因和复盘线索，可沉淀为项目记忆或后续 SOP 输入。",
            sources=["task_types", "project_memory"],
        ),
        _catalog_item(
            capability_id="data_analysis",
            category="数据分析",
            name="常见科研数据分析结果整理",
            status="partial" if "data_analysis" in RESEARCH_TASK_WORKFLOWS else "missing",
            description="可承接数据分析任务和结果 artifact；具体统计能力取决于输入文件和可用数据工具。",
            sources=["data_tools", "task_types", "artifact_store"],
        ),
        _catalog_item(
            capability_id="sop_protocol",
            category="SOP / protocol",
            name="Methods protocol 提取与 SOP 草拟",
            status="partial" if "protocol_extraction" in RESEARCH_TASK_WORKFLOWS else "missing",
            description="从论文 Methods 或用户记录中提取步骤，生成 protocol/SOP artifact，并按需进入记忆确认。",
            sources=["workflow_registry", "artifact_store"],
        ),
        _catalog_item(
            capability_id="manuscript_review",
            category="论文写作与审稿",
            name="论文草稿、结果段、讨论段审阅",
            status="partial",
            description="可基于项目 KB、证据和记忆辅助写作、审稿和改写；仍需要用户确认科学结论。",
            sources=["kb_rag", "project_memory", "artifact_store"],
        ),
        _catalog_item(
            capability_id="memory_artifact_lifecycle",
            category="项目记忆与 artifact",
            name="ResearchArtifact 与 PendingMemoryCandidate",
            status="working" if audit.get("artifact_store") in {"real", "partial"} and audit.get("project_memory") in {"real", "partial"} else "partial",
            description="重要输出注册为 artifact，有长期价值的内容生成待确认记忆；用户说“保存刚才的”可提交最近候选。",
            sources=["artifact_store", "project_memory"],
        ),
        _catalog_item(
            capability_id="long_tasks_status",
            category="长任务和任务状态",
            name="任务 runner、状态查询、watcher/scheduler 入口",
            status="partial" if audit.get("long_task_runner") in {"real", "partial"} else audit.get("long_task_runner"),
            description="支持长任务状态查询、watcher 和每周 digest 调度入口；后台执行持久性仍按本地运行环境决定。",
            sources=["scheduler_watcher", "task_types"],
            notes=f"{running_tasks} active tasks" if running_tasks else "",
        ),
        _catalog_item(
            capability_id="mock_provider_fallback",
            category="文献与知识库",
            name="演示/离线 mock fallback",
            status="mock",
            description="当外部 provider 不可用时可使用演示 fallback，不能等同真实联网检索。",
            sources=["literature_tools"],
        ),
        _catalog_item(
            capability_id="model_weight_training",
            category="自主学习与周报",
            name="模型权重自训练",
            status="missing",
            description="AURA 不会训练或更新模型权重，也不会把所有对话无监督写入长期记忆。",
            sources=["response_policy"],
        ),
    ]
    return {
        "catalog_id": "aura_capability_catalog",
        "project_id": clean(project_id),
        "generated_at": now(),
        "sources": sources,
        "items": items,
        "status_summary": {status: sum(1 for item in items if item["status"] == status) for status in ["working", "partial", "mock", "missing"]},
        "diagnostics": {
            "skill_registry_status": normalize_capability_status(audit.get("skill_registry")),
            "workflow_types": list(RESEARCH_TASK_WORKFLOWS.keys()),
            "details_available": sorted(details.keys()),
        },
    }


def _catalog_status_label(status: str) -> str:
    return {
        "working": "working",
        "partial": "partial",
        "mock": "mock",
        "missing": "missing",
    }.get(normalize_capability_status(status), "partial")


def format_capability_catalog_answer(catalog: dict[str, Any], task_status: list[dict[str, Any]] | None = None) -> str:
    categories = [
        "文献与知识库",
        "自主学习与周报",
        "非 OA 文献请求用户下载",
        "实验记录与失败百科",
        "数据分析",
        "SOP / protocol",
        "论文写作与审稿",
        "项目记忆与 artifact",
        "长任务和任务状态",
    ]
    items = [item for item in as_list(catalog.get("items")) if isinstance(item, dict)]
    lines = ["我能做的事按科研场景分为这些能力，括号里是当前状态："]
    for category in categories:
        matched = [item for item in items if clean(item.get("category")) == category]
        if not matched:
            continue
        lines.append(f"{category}:")
        for item in matched[:2]:
            lines.append(f"- {_catalog_status_label(item.get('status'))}: {clean(item.get('name'))}。{clean(item.get('description'))}")
    active_harvest = next((item for item in as_list(task_status) if isinstance(item, dict) and item.get("task_type") == "literature_harvest" and clean(item.get("status")) in {"pending", "running"}), {})
    if active_harvest:
        lines.append("另外，当前也有一个 harvest 任务在运行；如果你明确问进度，我会切到任务状态回答。")
    lines.append("能力咨询不会启动文献采集；只有你明确说“帮我采集/搜索某关键词文献”时才会进入 harvest。")
    return "\n".join(lines)


def format_autonomous_learning_answer(task_status: list[dict[str, Any]] | None = None) -> str:
    lines = [
        "AURA 支持受控项目级学习，但不是模型权重自训练。",
        "可以做的是：采集文献、自动下载可获得全文；对非 OA 或无法自动下载的文献生成请求清单让用户下载；用户补充 PDF 后继续解析、切块、入库、生成学习总结和周报，并创建 memory candidate。",
        "不会做的是：不会训练模型权重，不会无监督保存所有聊天或所有生成内容；关键项目记忆需要用户确认后才写入。",
        "如果你说“生成本周研究周报”或“总结最近学到什么”，我会生成 artifact；如果你再说“保存刚才的”，会提交最近的待确认记忆候选。",
    ]
    active_harvest = next((item for item in as_list(task_status) if isinstance(item, dict) and item.get("task_type") == "literature_harvest" and clean(item.get("status")) in {"pending", "running"}), {})
    if active_harvest:
        lines.append("当前也有一个 harvest 任务在运行；需要进度时可以直接问“现在采集到哪了”。")
    return "\n".join(lines)


def _display_safe_path(path_value: str, project_id: str) -> str:
    path_text = clean(path_value)
    if project_id:
        path_text = path_text.replace(project_id, "<project>")
    return path_text


def format_file_registry_answer(agent_root: Path, project_id: str, files: list[dict[str, Any]], project: dict[str, Any] | None = None) -> str:
    display_name = project_display_name(project or get_project_detail(agent_root, project_id))
    if not files:
        return f"当前项目 {display_name} 里还没有查到最近上传文件。后端没有可用的落盘路径记录。"
    lines = [f"当前项目 {display_name} 最近上传文件："]
    for file_record in files[:5]:
        original = clean(file_record.get("original_filename")) or clean(file_record.get("stored_filename")) or "未命名文件"
        stored_path = clean(file_record.get("stored_path"))
        shown_path = _display_safe_path(stored_path, project_id)
        parse_status = clean(file_record.get("parse_status")) or "not_parsed"
        if shown_path:
            lines.append(f"- original_filename: {original}; stored_path: {shown_path}; parse_status: {parse_status}")
        else:
            lines.append(f"- original_filename: {original}; 后端只看到了文件名，但没有找到落盘路径；parse_status: {parse_status}")
    return "\n".join(lines)


def format_uploaded_file_parse_answer(agent_root: Path, project_id: str, files: list[dict[str, Any]], project: dict[str, Any] | None = None) -> str:
    display_name = project_display_name(project or get_project_detail(agent_root, project_id))
    if not files:
        return f"当前项目 {display_name} 里还没有可解析的最近上传文件。请先上传 Excel/xlsx/csv/pdf，再说“解析这个文件”。"
    file_record = files[0]
    original = clean(file_record.get("original_filename")) or clean(file_record.get("stored_filename")) or "最近上传文件"
    parse_status = clean(file_record.get("parse_status")) or "not_parsed"
    return (
        f"我会优先处理当前项目 {display_name} 的最近上传文件：{original}。"
        f"当前 parse_status: {parse_status}。"
        "如果需要得出实验结论，我会先读取文件内容、建立 data context，再把结论标记为待确认。"
    )


def _callable_exists(name: str) -> bool:
    return callable(globals().get(name))


def _function_references(function_name: str, *needles: str) -> bool:
    fn = globals().get(function_name)
    code = getattr(fn, "__code__", None)
    if code is None:
        return False
    referenced = set(str(name) for name in code.co_names)
    referenced.update(str(value) for value in code.co_consts if isinstance(value, str))
    return all(needle in referenced for needle in needles)


def _capability_status(required_tables: list[str], required_functions: list[str], *, conn: sqlite3.Connection) -> tuple[str, list[str]]:
    missing_tables = [table for table in required_tables if not db_table_exists(conn, table)]
    missing_functions = [name for name in required_functions if not _callable_exists(name)]
    if missing_tables or missing_functions:
        missing: list[str] = []
        if missing_tables:
            missing.append("missing tables: " + ", ".join(missing_tables))
        if missing_functions:
            missing.append("missing functions: " + ", ".join(missing_functions))
        return "missing", missing
    return "real", []


def _append_gap(status: dict[str, Any], gap: str, recommendation: str = "") -> None:
    if gap and gap not in status["known_gaps"]:
        status["known_gaps"].append(gap)
    if recommendation and recommendation not in status["recommended_next_fixes"]:
        status["recommended_next_fixes"].append(recommendation)


def get_researchos_capability_status(agent_root: Path, project_id: str = "") -> dict[str, Any]:
    """Return a conservative audit of ResearchOS/AURA agent capabilities.

    This is intentionally a diagnostic function, not a health-check that starts
    work. It only inspects schema, callable handlers, and whether the main
    chat/task paths reference those handlers.
    """
    project_id = clean(project_id)
    conn = connect(agent_root)
    status: dict[str, Any] = {
        "project_context": "missing",
        "skill_registry": "missing",
        "intent_router": "missing",
        "context_compiler": "missing",
        "long_task_runner": "missing",
        "literature_harvest": "missing",
        "kb_rag": "missing",
        "project_memory": "missing",
        "memory_source_of_truth": "missing",
        "execution_memory": "missing",
        "artifact_store": "missing",
        "response_formatter": "missing",
        "known_gaps": [],
        "recommended_next_fixes": [],
        "details": {},
    }
    try:
        project_row = {}
        if project_id and db_table_exists(conn, "projects"):
            project_row = row_to_dict(conn.execute("SELECT id, title, status FROM projects WHERE id=?", (project_id,)).fetchone()) or {}

        def set_detail(key: str, value: str, evidence: list[str]) -> None:
            status[key] = value
            status["details"][key] = {"status": value, "evidence": evidence}

        project_status, project_evidence = _capability_status(["projects"], ["workspace_state", "agent_chat"], conn=conn)
        if project_status == "real":
            wired = _function_references("agent_chat", "workspace_state")
            if project_id and not project_row:
                set_detail("project_context", "partial", ["projects table exists", "workspace_state exists", "requested project_id not found"])
                _append_gap(status, "Project context storage exists, but the requested project_id was not found.", "Validate project_id before running agent workflows.")
            elif wired:
                set_detail("project_context", "real", ["projects table exists", "workspace_state exists", "agent_chat reads workspace_state"])
            else:
                set_detail("project_context", "partial", ["projects table and workspace_state exist", "agent_chat wiring not confirmed"])
        else:
            set_detail("project_context", project_status, project_evidence)

        skill_status, skill_evidence = _capability_status(["skill_registry"], ["run_skill"], conn=conn)
        if skill_status == "real":
            active_skills = db_count(conn, "skill_registry", "status!='disabled'")
            harvest_skill = db_count(conn, "skill_registry", "skill_id='core_keyword_research_harvest'")
            if active_skills and harvest_skill:
                set_detail("skill_registry", "real", [f"{active_skills} enabled skills", "core literature harvest skill registered", "run_skill exists"])
            else:
                set_detail("skill_registry", "partial", [f"{active_skills} enabled skills", "core literature harvest skill missing" if not harvest_skill else "core literature harvest skill registered"])
                _append_gap(status, "Skill registry exists, but core skill coverage is incomplete.", "Ensure core skills are seeded and enabled during startup.")
        else:
            set_detail("skill_registry", skill_status, skill_evidence)

        if _callable_exists("infer_agent_intent"):
            if _function_references("agent_chat", "infer_agent_intent"):
                set_detail("intent_router", "real", ["infer_agent_intent exists", "agent_chat calls infer_agent_intent"])
            else:
                set_detail("intent_router", "partial", ["infer_agent_intent exists", "agent_chat wiring not confirmed"])
                _append_gap(status, "Intent router exists but main chat wiring could not be confirmed.", "Keep intent routing centralized in agent_chat before fallback answers.")
        else:
            set_detail("intent_router", "missing", ["infer_agent_intent missing"])

        context_compiler_callable = callable(getattr(research_context_compiler, "compile_research_context", None))
        if context_compiler_callable:
            if _function_references("agent_chat", "compile_research_context") or _function_references("agent_chat", "research_context_compiler"):
                set_detail("context_compiler", "real", ["research_context_compiler.compile_research_context exists", "agent_chat references compiled research context"])
            else:
                set_detail("context_compiler", "partial", ["compile_research_context exists", "main chat wiring not confirmed"])
                _append_gap(status, "Research context compiler exists but is not clearly wired into the main answer path.", "Keep project, memory, task and KB context compilation visible in agent_chat.")
        else:
            set_detail("context_compiler", "missing", ["compile_research_context missing"])

        task_status, task_evidence = _capability_status(["agent_tasks"], ["create_agent_task", "update_agent_task", "run_agent_task", "run_skill"], conn=conn)
        if task_status == "real":
            if _function_references("run_agent_task", "run_skill"):
                set_detail("long_task_runner", "partial", ["agent_tasks table exists", "create/update/run task functions exist", "run_agent_task delegates to run_skill"])
                _append_gap(
                    status,
                    "Long task runner is persisted and callable, but execution is synchronous/local-client-poll driven; no durable detached worker queue is confirmed.",
                    "Add a minimal durable worker loop or scheduler contract for background task execution.",
                )
            else:
                set_detail("long_task_runner", "partial", ["agent_tasks table exists", "task functions exist", "run_agent_task-to-run_skill wiring not confirmed"])
        else:
            set_detail("long_task_runner", task_status, task_evidence)

        harvest_status, harvest_evidence = _capability_status(
            ["literature_search_tasks", "literature_ingest_items"],
            ["create_literature_search_task", "start_keyword_harvest_task", "ingest_literature_pdf_record"],
            conn=conn,
        )
        if harvest_status == "real":
            harvest_skill = db_count(conn, "skill_registry", "skill_id='core_keyword_research_harvest'") if db_table_exists(conn, "skill_registry") else 0
            if harvest_skill:
                set_detail(
                    "literature_harvest",
                    "partial",
                    ["literature task and ingest tables exist", "harvest workflow functions exist", "core harvest skill registered", "mock/manual fallback still available"],
                )
                _append_gap(
                    status,
                    "Literature harvest has a real persisted workflow, but mock/manual fallback remains available and provider availability is runtime/config dependent.",
                    "Expose provider availability in diagnostics and keep production harvest separate from mock/manual fallback modes.",
                )
            else:
                set_detail("literature_harvest", "partial", ["workflow tables and functions exist", "core harvest skill not registered"])
        else:
            set_detail("literature_harvest", harvest_status, harvest_evidence)

        parser_status, parser_evidence = _capability_status(["references", "reference_chunks", "literature_ingest_items"], ["text_from_path", "import_reference", "split_reference_chunks", "ingest_literature_pdf_record"], conn=conn)
        if parser_status == "real":
            set_detail("pdf_text_parser", "partial", ["PDF/text parser functions exist", "reference chunk storage exists", "PDF extraction depends on optional pypdf/simple extraction"])
            _append_gap(status, "PDF/Text parsing is available but parser quality is partial and depends on optional pypdf/simple text extraction.", "Add parser diagnostics per ingested file and surface parse quality in task status.")
        else:
            set_detail("pdf_text_parser", parser_status, parser_evidence)

        kb_status, kb_evidence = _capability_status(["references", "reference_chunks", "knowledge_base_entries", "rag_queries"], ["build_project_research_kb", "query_research_rag"], conn=conn)
        if kb_status == "real":
            if _function_references("run_imported_core_skill_adapter", "build_project_research_kb") and _function_references("run_imported_core_skill_adapter", "query_research_rag"):
                set_detail("kb_rag", "real", ["reference_chunks and knowledge_base_entries tables exist", "build/query functions exist", "core skill adapter routes KB/RAG handlers"])
            else:
                set_detail("kb_rag", "partial", ["KB/RAG schema and functions exist", "run_skill handler wiring not fully confirmed"])
                _append_gap(status, "KB/RAG functions exist, but skill-run wiring could not be fully confirmed.", "Keep KB build and query handlers registered in run_skill and skill_registry.")
        else:
            set_detail("kb_rag", kb_status, kb_evidence)

        citation_status, citation_evidence = _capability_status(["references", "reference_chunks", "knowledge_base_entries"], ["build_evidence_citations"], conn=conn)
        if citation_status == "real":
            set_detail("reference_chunk_citation_storage", "real", ["references, reference_chunks and knowledge_base_entries tables exist", "citation builder exists"])
        else:
            set_detail("reference_chunk_citation_storage", citation_status, citation_evidence)

        memory_status, memory_evidence = _capability_status(["agent_memory_entries"], ["create_agent_memory_entry", "list_agent_memory"], conn=conn)
        if memory_status == "real":
            if _function_references("agent_chat", "memory_used") or _function_references("run_research_watcher", "create_agent_memory_entry"):
                set_detail("project_memory", "real", ["agent_memory_entries table exists", "memory create/list functions exist", "chat/watcher memory wiring confirmed"])
            else:
                set_detail("project_memory", "partial", ["memory table and functions exist", "main workflow wiring not confirmed"])
        else:
            set_detail("project_memory", memory_status, memory_evidence)

        registry_status, registry_evidence = _capability_status(["memory_backend_registry"], ["list_memory_backend_registry", "get_memory_source_of_truth_health"], conn=conn)
        if registry_status == "real":
            primary_count = db_count(
                conn,
                "memory_backend_registry",
                "backend_name=? AND source_of_truth=1 AND status='active'",
                (PRIMARY_MEMORY_BACKEND,),
            )
            derived_count = db_count(conn, "memory_backend_registry", "source_of_truth=0 AND status='active'")
            if primary_count >= 7 and derived_count >= 4:
                set_detail(
                    "memory_source_of_truth",
                    "real",
                    [f"{primary_count} primary memory classes registered", f"{derived_count} derived backends registered", "health check function exists"],
                )
            else:
                set_detail(
                    "memory_source_of_truth",
                    "partial",
                    [f"{primary_count} primary memory classes registered", f"{derived_count} derived backends registered"],
                )
                _append_gap(status, "Memory backend registry exists, but source-of-truth declarations are incomplete.", "Bootstrap all primary and derived memory backend registry rows.")
        else:
            set_detail("memory_source_of_truth", registry_status, registry_evidence)

        execution_status, execution_evidence = _capability_status(["skill_runs", "execution_memory"], ["start_service_skill_run", "finish_service_skill_run", "upsert_execution_memory_for_skill_run", "list_execution_memory"], conn=conn)
        if execution_status == "real":
            if _function_references("create_skill_run_record", "upsert_execution_memory_for_skill_run") and _function_references("update_skill_run", "upsert_execution_memory_for_skill_run"):
                set_detail("execution_memory", "real", ["skill_runs and execution_memory tables exist", "service run lifecycle functions exist", "skill run create/update writes execution memory"])
            else:
                set_detail("execution_memory", "partial", ["execution tables and functions exist", "skill lifecycle wiring not confirmed"])
        else:
            set_detail("execution_memory", execution_status, execution_evidence)

        artifact_status, artifact_evidence = _capability_status(["artifacts"], ["register_artifact", "upsert_artifact_record", "artifacts_from_object_refs"], conn=conn)
        if artifact_status == "real":
            weekly_digest = db_table_exists(conn, "weekly_digest_reports")
            if _function_references("workspace_state", "_recent_artifact_rows") and _function_references("finish_service_skill_run", "artifacts_from_object_refs"):
                evidence = ["artifacts table exists", "artifact register/upsert functions exist", "workspace_state and skill-run artifact wiring confirmed"]
                if weekly_digest:
                    evidence.append("weekly_digest_reports table exists")
                set_detail("artifact_store", "real", evidence)
            else:
                set_detail("artifact_store", "partial", ["artifact schema/functions exist", "workspace or skill-run wiring not fully confirmed"])
        else:
            set_detail("artifact_store", artifact_status, artifact_evidence)
            _append_gap(status, "Artifact store is missing or incomplete.", "Create the minimal artifacts table and register outputs from skill runs.")

        formatter_functions = [
            "format_task_status_answer",
            "format_ingested_papers_inventory",
            "format_literature_learning_summary",
            "format_literature_source_traceability",
            "format_capability_answer",
        ]
        formatter_missing = [name for name in formatter_functions if not _callable_exists(name)]
        if formatter_missing:
            set_detail("response_formatter", "missing", ["missing formatters: " + ", ".join(formatter_missing)])
        elif _function_references("agent_chat", "format_task_status_answer") and _function_references("agent_chat", "format_literature_learning_summary"):
            set_detail("response_formatter", "real", ["task, inventory, learning and traceability formatters exist", "agent_chat references response formatters"])
        else:
            set_detail("response_formatter", "partial", ["formatters exist", "agent_chat wiring not fully confirmed"])

        electron_path = REPO_ROOT / "electron" / "main.js"
        web_client_path = REPO_ROOT / "web_client" / "index.html"
        api_client_path = REPO_ROOT / "web_client" / "api.js"
        if electron_path.exists() and web_client_path.exists():
            try:
                electron_text = electron_path.read_text(encoding="utf-8", errors="ignore")
                web_text = web_client_path.read_text(encoding="utf-8", errors="ignore")
                api_text = api_client_path.read_text(encoding="utf-8", errors="ignore") if api_client_path.exists() else ""
            except Exception:
                electron_text = ""
                web_text = ""
                api_text = ""
            client_needles = ["api/backend", "BrowserWindow", "web_client", "runCoordinator", "sendLegacyChat", "getSkillCatalog", "getSkillRuns"]
            combined = "\n".join([electron_text, web_text, api_text])
            if all(needle in combined for needle in client_needles):
                set_detail("local_client_ui", "real", ["Electron client exists", "web_client shell and API hooks found"])
            else:
                set_detail("local_client_ui", "partial", ["Electron/web client exists", "some expected UI hooks missing"])
                _append_gap(status, "Local client exists but some UI integration hooks could not be confirmed.", "Keep chat, task, skill and workspace-state panels wired to backend APIs.")
        else:
            set_detail("local_client_ui", "missing", ["Electron/web_client files missing"])

        if status.get("artifact_store") == "missing":
            _append_gap(status, "Artifact/report/weekly digest storage is not fully available.", "Preserve generated reports and digest outputs through the artifact store.")
        if status.get("project_context") in {"missing", "partial"}:
            _append_gap(status, "Project context is incomplete for the requested project.", "Make project context validation the first step of agent_chat.")
        if status.get("intent_router") in {"missing", "partial"}:
            _append_gap(status, "Intent routing is not fully closed-loop.", "Add regression tests for task status, inventory, learning summary, and source traceability routes.")
        return status
    finally:
        conn.close()


