def sanitizer_requires_answer_rewrite(answer: str, message: str = "") -> bool:
    text = clean(answer)
    if not text:
        return False
    leaked = any(phrase.lower() in text.lower() for phrase in AGENT_LEAKAGE_PHRASES)
    too_long = len(text) > 900 and not explicit_longform_request(message)
    markdown_table = "|" in text and re.search(r"\n\s*\|?\s*[-:]{3,}\s*\|", text) is not None and not explicit_longform_request(message)
    return bool(leaked or too_long or markdown_table)


def sanitize_agent_answer(answer: str, intent: str, *, task_status: list[dict[str, Any]] | None = None, message: str = "", workspace: dict[str, Any] | None = None) -> str:
    text = clean(answer)
    if not text:
        return ""
    if not sanitizer_requires_answer_rewrite(text, message):
        return polish_user_facing_answer(text, message)
    if intent == "task_status_query":
        return polish_user_facing_answer(format_task_status_answer(task_status or []), message)
    if intent in {"capability_query", "capability_explanation"}:
        return polish_user_facing_answer("我可以帮你做文献采集、PDF 入库、实验记录整理、知识库问答、项目记忆整理和论文草稿生成。你可以直接输入关键词、上传 PDF，或告诉我要整理哪条实验记录。", message)
    if intent == "autonomous_learning_question":
        return polish_user_facing_answer(format_autonomous_learning_answer(task_status or []), message)
    if intent in {"project_status_query", "project_status"}:
        return polish_user_facing_answer("我查到了当前项目状态，详细计数在右侧状态面板。下一步可以继续文献采集、PDF 入库，或整理实验记录。", message)
    if intent == "kb_query":
        lit = (workspace or {}).get("literature") or {}
        diagnostics = (workspace or {}).get("workspace_diagnostics") or {}
        if diagnostics.get("warnings"):
            candidates = diagnostics.get("possible_misassigned_literature") or []
            if candidates:
                item = candidates[0]
                return polish_user_facing_answer(
                    f"当前项目里没有找到可用文献，但本地另一个项目下有文献资产：PDF {item.get('pdf_files_found', 0)} 个，已入库文献 {item.get('references_count', 0)} 篇，chunks {item.get('chunks_count', 0)} 个。先确认文献归属，再做总结会更准确。",
                    message,
                )
        if not int(lit.get("references_count") or 0) and not int(lit.get("chunks_count") or 0):
            return "当前项目里还没有可总结的入库文献。你可以先用关键词启动文献采集，或导入 PDF 后再让我总结。"
    return polish_user_facing_answer("我会优先回答你当前的问题。需要详细解释时你可以直接说“详细解释”。", message)


def unwrap_llm_chat_answer(raw_answer: str) -> str:
    text = clean(raw_answer)
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE).strip()
        text = re.sub(r"\s*```$", "", text).strip()
    try:
        parsed = json.loads(text)
    except Exception:
        return raw_answer
    if isinstance(parsed, dict):
        for key in ["answer", "response", "content", "text"]:
            if clean(parsed.get(key)):
                return clean(parsed.get(key))
    return raw_answer


def chat_message_from_payload(payload: dict[str, Any]) -> str:
    for key in ["message", "user_query", "query", "content", "question"]:
        value = payload.get(key)
        if value is not None and clean(value):
            return clean(value)
    return ""


def payload_truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return clean(value).lower() in {"1", "true", "yes", "on"}


ANSWER_SOURCE_VALUES = {
    "llm",
    "template",
    "fallback",
    "validator_rewrite",
    "sanitizer_rewrite",
    "coordinator_handoff",
    "product_demo",
    "cache",
    "error_recovery",
}


def answer_provenance_fields(
    *,
    answer_source: str,
    llm_called: bool = False,
    llm_output_used: bool = False,
    answer_overwritten_after_llm: bool = False,
    llm_provider: str = "",
    llm_model: str = "",
    prompt_router_used: bool = False,
    context_compiler_used: bool = False,
    template_id: str | None = None,
    fallback_reason: str | None = None,
) -> dict[str, Any]:
    source = clean(answer_source)
    if source not in ANSWER_SOURCE_VALUES:
        source = "fallback"
    return {
        "answer_source": source,
        "llm_called": bool(llm_called),
        "llm_output_used": bool(llm_output_used),
        "answer_overwritten_after_llm": bool(answer_overwritten_after_llm),
        "llm_provider": clean(llm_provider),
        "llm_model": clean(llm_model),
        "prompt_router_used": bool(prompt_router_used),
        "context_compiler_used": bool(context_compiler_used),
        "template_id": template_id if template_id is None else clean(template_id),
        "fallback_reason": fallback_reason if fallback_reason is None else clean(fallback_reason),
    }


def attach_answer_provenance(response: dict[str, Any], *, default_source: str = "template") -> dict[str, Any]:
    source = clean(response.get("answer_source")) or default_source
    llm_meta = response.get("llm") if isinstance(response.get("llm"), dict) else {}
    tool_calls = response.get("tool_calls") if isinstance(response.get("tool_calls"), list) else []
    context_used = any(isinstance(call, dict) and clean(call.get("tool")) == "research_context_compiler" for call in tool_calls)
    response.update(
        answer_provenance_fields(
            answer_source=source,
            llm_called=bool(response.get("llm_called")),
            llm_output_used=bool(response.get("llm_output_used")),
            answer_overwritten_after_llm=bool(response.get("answer_overwritten_after_llm")),
            llm_provider=clean(response.get("llm_provider")) or clean(llm_meta.get("provider")),
            llm_model=clean(response.get("llm_model")) or clean(llm_meta.get("model")),
            prompt_router_used=bool(response.get("prompt_router_used")),
            context_compiler_used=bool(response.get("context_compiler_used")) or context_used,
            template_id=response.get("template_id") if "template_id" in response else (clean(response.get("response_mode")) or clean(response.get("intent")) or None),
            fallback_reason=response.get("fallback_reason"),
        )
    )
    if response["answer_source"] == "llm":
        response["template_id"] = None
        response["fallback_reason"] = None
    return response


def should_use_llm_for_ordinary_chat(message: str, intent: str = "", canonical_intent: str = "") -> bool:
    text = clean(message)
    lower = text.lower()
    if not text:
        return False
    local_status_terms = ["/health", "显示系统状态", "显示后端状态", "show system status", "runtime status", "llm-status"]
    if any(term in lower for term in local_status_terms) or any(term in text for term in ["显示系统状态", "显示后端状态"]):
        return False
    compact = re.sub(r"[\s\?？!！。,.，、:：;；]+", "", text).lower()
    exact = {
        "你好",
        "您好",
        "你可以为我做什么",
        "你是什么",
        "介绍一下researchos",
        "怎么使用你",
        "你能帮我做什么",
        "你能为我做什么",
        "当前系统正常吗",
        "介绍一下当前项目",
        "介绍当前项目",
        "你有什么功能",
    }
    if compact in exact:
        return True
    if compact.startswith("你好") and ("正常回答" in text or len(compact) <= 16):
        return True
    if compact.startswith("您好") and len(compact) <= 16:
        return True
    english_terms = [
        "hello",
        "hi",
        "what can you do",
        "what are you",
        "who are you",
        "how do i use you",
        "introduce researchos",
        "introduce the current project",
        "current project introduction",
        "are you working",
        "can you answer",
    ]
    if lower.strip(" ?!.") in english_terms:
        return True
    return False


def should_include_full_task_status(payload: dict[str, Any], message: str, intent: str) -> bool:
    payload_intent = clean(payload.get("intent"))
    if payload_truthy(payload.get("include_task_status")):
        return True
    if payload_intent == "refresh_task_status":
        return True
    if intent in STATUS_QUERY_INTENTS or intent == "task_status_query":
        return True
    return False


def should_suppress_task_status_for_chat(response_mode: str, include_full_task_status: bool) -> bool:
    return not include_full_task_status and clean(response_mode) != "task_status"


def is_product_demo_task_status(item: dict[str, Any]) -> bool:
    name = clean(item.get("task_name") or item.get("skill_name"))
    skill_id = clean(item.get("skill_id"))
    return name == "ResearchOS Product Demo" or skill_id.startswith("product_demo_")


def summarize_task_status_for_chat(task_status: list[dict[str, Any]] | None) -> dict[str, Any]:
    items = [item for item in as_list(task_status) if isinstance(item, dict) and not is_product_demo_task_status(item)]
    running = [item for item in items if clean(item.get("status")) in {"running", "pending", "waiting_approval", "waiting_for_user"}]
    failed = [item for item in items if clean(item.get("status")) in {"failed", "cancelled"}]
    latest = running[0] if running else (items[0] if items else {})
    latest_summary = ""
    if latest:
        latest_summary = f"{clean(latest.get('task_name')) or clean(latest.get('task_type'))}: {clean(latest.get('status')) or 'unknown'}"
    return {
        "running_task_count": len(running),
        "failed_task_count": len(failed),
        "latest_task_summary": latest_summary,
    }


def compact_workspace_state_for_chat(workspace: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(workspace, dict):
        return {}
    compacted = dict(workspace)
    tasks = workspace.get("tasks") if isinstance(workspace.get("tasks"), dict) else {}
    task_items: list[dict[str, Any]] = []
    for key in ["running", "completed", "failed"]:
        task_items.extend([item for item in as_list(tasks.get(key)) if isinstance(item, dict)])
    compacted["task_status_summary"] = summarize_task_status_for_chat(task_items)
    compacted.pop("tasks", None)
    skills = dict(compacted.get("skills") or {}) if isinstance(compacted.get("skills"), dict) else {}
    if skills:
        recent = [
            item
            for item in as_list(skills.get("recent_skill_runs"))
            if isinstance(item, dict) and not is_product_demo_task_status({"task_name": item.get("skill_name"), "skill_id": item.get("skill_id")})
        ]
        if recent:
            skills["recent_skill_runs"] = recent[:5]
        else:
            skills.pop("recent_skill_runs", None)
        compacted["skills"] = skills
    return compacted


def agent_chat(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    message = chat_message_from_payload(payload)
    if not project_id:
        raise ValueError("project_id is required")
    if not message:
        raise ValueError("message is required")
    developer_debug = bool(payload.get("developer_debug") or payload.get("debug_mode") or payload.get("include_internal_ids")) or developer_debug_mode_enabled()

    ensure_default_chat_project(agent_root, project_id)
    requested_conversation_id = clean(payload.get("conversation_id") or payload.get("session_id"))
    conversation = ensure_chat_session(agent_root, project_id, requested_conversation_id, title=message[:80])
    conversation_id = conversation["id"]
    history_before = list_chat_messages(agent_root, conversation_id, project_id, limit=int(payload.get("conversation_limit") or 16))
    previous_intent = clean(payload.get("previous_intent")) or latest_chat_intent(history_before)
    canonical_intent = classify_research_intent(message, previous_intent)
    intent = "conversation_history_query" if is_conversation_history_query(message) else infer_agent_intent(message, previous_intent)
    if clean(payload.get("intent")) == "refresh_task_status":
        intent = "task_status_query"
    force_ordinary_llm_chat = should_use_llm_for_ordinary_chat(message, intent, canonical_intent)
    include_full_task_status = False if force_ordinary_llm_chat else should_include_full_task_status(payload, message, intent)
    detected_literature_keywords = extract_literature_keywords_from_message(message)
    last_literature_keywords = latest_literature_keywords_from_history(history_before)
    if intent != "start_skill_request" and is_direct_literature_start_message(message) and last_literature_keywords:
        intent = "start_skill_request"
    non_harvest_intents = {
        "start_skill_request",
        "task_status_query",
        "proactive_status_query",
        "project_status_query",
        "capability_query",
        "capability_explanation",
        "autonomous_learning_question",
        "file_registry_query",
        "uploaded_file_parse",
        "project_list",
        "project_switch",
        "project_status",
        "project_archive_request",
        "project_unarchive_request",
        "project_clear_request",
        "project_purge_request",
        "literature_learning_summary",
        "ingested_paper_inventory",
        "literature_source_traceability",
        "paper_request_list",
        "paper_request_process",
        "paper_recommendation",
        "general_scientific_explanation",
        "memory_commit_request",
        "conversation_history_query",
        "self_description_or_architecture",
        "data_analysis",
        "artifact_generation",
        "weekly_digest_generation",
        "general_chat",
    }
    if not force_ordinary_llm_chat and intent not in non_harvest_intents and detected_literature_keywords and canonical_intent == "literature_harvest_start":
        intent = "literature_harvest_prepare"
    save_chat_message(
        agent_root,
        conversation_id,
        "user",
        message,
        {"intent": intent, "canonical_intent": canonical_intent, "project_id": project_id, "literature_keywords": detected_literature_keywords if intent in {"literature_harvest_prepare", "start_skill_request"} else []},
        project_id=project_id,
    )

    def finalize(response: dict[str, Any]) -> dict[str, Any]:
        response["conversation_id"] = conversation_id
        response.setdefault("canonical_intent", canonical_intent)
        response.setdefault("response_mode", response_mode_for_intent(clean(response.get("intent")) or intent))
        attach_answer_provenance(response, default_source="template")
        response_mode = clean(response.get("response_mode"))
        if should_suppress_task_status_for_chat(response_mode, include_full_task_status):
            task_status = response.get("task_status") if isinstance(response.get("task_status"), list) else []
            response["task_status_summary"] = summarize_task_status_for_chat(task_status)
            response.pop("task_status", None)
            response.pop("user_visible_task_status", None)
            if isinstance(response.get("workspace_state"), dict):
                response["workspace_state"] = compact_workspace_state_for_chat(response.get("workspace_state"))
        if "task_status" in response and "user_visible_task_status" not in response:
            response["user_visible_task_status"] = research_context_compiler.build_user_visible_task_status(
                response.get("task_status") if isinstance(response.get("task_status"), list) else []
            )
        if clean(response.get("answer")):
            before_policy = str(response.get("answer") or "")
            response["answer"] = apply_response_policy(before_policy, clean(response.get("response_mode")), message, developer_debug=developer_debug)
            if bool(response.get("llm_called")) and clean(response.get("answer")) != clean(before_policy):
                response["answer_source"] = "sanitizer_rewrite"
                response["llm_output_used"] = False
                response["answer_overwritten_after_llm"] = True
        if not developer_debug:
            response.pop("debug", None)
        answer_text = clean(response.get("answer"))
        if answer_text:
            try:
                artifact = response.get("artifact") if isinstance(response.get("artifact"), dict) else {}
                candidate = response.get("memory_candidate") if isinstance(response.get("memory_candidate"), dict) else {}
                save_chat_message(
                    agent_root,
                    conversation_id,
                    "assistant",
                    answer_text,
                    {
                        "assistant_response_type": clean(response.get("intent")),
                        "assistant_canonical_intent": clean(response.get("canonical_intent")),
                        "assistant_response_mode": clean(response.get("response_mode")),
                        "project_id": project_id,
                        "citation_ids": [item.get("citation_id") for item in response.get("citations") or []],
                        "validation_status": clean(response.get("validation_status")),
                        "literature_keywords": [clean(item) for item in as_list(response.get("literature_keywords")) if clean(item)],
                        "artifact_id": clean(artifact.get("artifact_id")),
                        "candidate_id": clean(candidate.get("candidate_id")),
                        "artifact_type": clean(artifact.get("artifact_type") or artifact.get("type")),
                    },
                    project_id=project_id,
                )
            except Exception:
                pass
        return response

    if intent == "project_list":
        grouped = list_projects_grouped(agent_root)
        return finalize(
            {
                "ok": True,
                "intent": "project_list",
                "response_mode": "project_management",
                "answer": format_project_list_answer(grouped),
                "citations": [],
                "memory_used": [],
                "sources": [],
                "tool_calls": [{"tool": "ProjectRegistry.list_projects", "status": "completed"}],
                "task_status": [],
                "workspace_state": workspace_state(agent_root, project_id),
                "projects": grouped,
                "next_actions": [],
                "validation_status": "skipped",
                "debug": {},
                "error": None,
            }
        )

    if intent == "project_switch":
        target = extract_project_switch_target(message)
        resolution = resolve_project_by_display_name_or_alias(agent_root, target)
        if resolution.get("status") == "matched":
            target_project = resolution.get("project") or {}
            target_project_id = clean(target_project.get("id"))
            switched_context = research_context_compiler.compile_research_context(
                agent_root,
                {
                    "user_message": message,
                    "intent": "project_status",
                    "project_id": target_project_id,
                    "max_tokens": int(payload.get("max_context_tokens") or payload.get("max_tokens") or 2000),
                },
            )
            display_name = project_display_name(target_project)
            return finalize(
                {
                    "ok": True,
                    "intent": "project_switch",
                    "response_mode": "project_management",
                    "answer": f"已切换到项目：{display_name}。我已经按该项目重新编译上下文。",
                    "citations": [],
                    "memory_used": switched_context.get("memory_used", []),
                    "sources": switched_context.get("sources", []),
                    "tool_calls": [{"tool": "ProjectRegistry.switch_project", "status": "completed"}, {"tool": "research_context_compiler", "status": "completed", "context_hash": switched_context.get("context_hash")}],
                    "task_status": switched_context.get("task_status", []),
                    "workspace_state": workspace_state(agent_root, target_project_id),
                    "compiled_context": switched_context,
                    "active_project_display_name": display_name,
                    "next_actions": [],
                    "validation_status": "skipped",
                    "debug": {"context_hash": switched_context.get("context_hash"), "context_warnings": switched_context.get("warnings", [])},
                    "error": None,
                }
            )
        if resolution.get("status") == "ambiguous":
            matches = as_list(resolution.get("matches"))
            return finalize(
                {
                    "ok": False,
                    "intent": "project_switch",
                    "response_mode": "project_management",
                    "answer": format_project_switch_ambiguous_answer([item for item in matches if isinstance(item, dict)]),
                    "citations": [],
                    "memory_used": [],
                    "sources": [],
                    "tool_calls": [{"tool": "ProjectRegistry.switch_project", "status": "needs_user_choice"}],
                    "task_status": [],
                    "workspace_state": workspace_state(agent_root, project_id),
                    "project_candidates": [project_public_view(item) for item in matches if isinstance(item, dict)],
                    "next_actions": [],
                    "validation_status": "skipped",
                    "debug": {},
                    "error": None,
                }
            )
        return finalize(
            {
                "ok": False,
                "intent": "project_switch",
                "response_mode": "project_management",
                "answer": f"没有找到名为“{target}”的 active 项目。你可以先问“有哪些项目”。",
                "citations": [],
                "memory_used": [],
                "sources": [],
                "tool_calls": [{"tool": "ProjectRegistry.switch_project", "status": "not_found"}],
                "task_status": [],
                "workspace_state": workspace_state(agent_root, project_id),
                "next_actions": [{"label": "查看项目列表", "intent": "project_list"}],
                "validation_status": "skipped",
                "debug": {},
                "error": None,
            }
        )

    if intent == "conversation_history_query":
        answer = format_conversation_history_answer(history_before, message)
        return finalize(
            {
                "ok": True,
                "intent": intent,
                "answer": answer,
                "citations": [],
                "memory_used": [],
                "sources": [],
                "tool_calls": [{"tool": "chat_history", "status": "completed"}],
                "task_status": [],
                "workspace_state": workspace_state(agent_root, project_id),
                "next_actions": [],
                "validation_status": "skipped",
                "debug": {"history_count": len(history_before)},
                "error": None,
            }
        )

    if intent in PROFILE_UPDATE_INTENTS:
        update_result = save_profile_project_update(agent_root, project_id, message, conversation_id)
        return finalize(
            {
                "ok": True,
                "intent": intent,
                "answer": format_profile_update_answer(update_result),
                "citations": [],
                "memory_used": update_result.get("memories", []),
                "sources": [],
                "tool_calls": [{"tool": "profile_project_memory_update", "status": "completed"}],
                "task_status": [],
                "workspace_state": workspace_state(agent_root, project_id),
                "profile_update": update_result.get("profile", {}),
                "project_conflict": bool(update_result.get("project_conflict")),
                "next_actions": [],
                "validation_status": "skipped",
                "debug": {},
                "error": None,
            }
        )

    if intent in PROFILE_QUERY_INTENTS:
        return finalize(
            {
                "ok": True,
                "intent": intent,
                "answer": format_profile_query_answer(agent_root, project_id, intent),
                "citations": [],
                "memory_used": [],
                "sources": [],
                "tool_calls": [{"tool": "profile_memory_lookup", "status": "completed"}],
                "task_status": [],
                "workspace_state": workspace_state(agent_root, project_id),
                "next_actions": [],
                "validation_status": "skipped",
                "debug": {},
                "error": None,
            }
        )

    tool_calls: list[dict[str, Any]] = []
    context_bundle = research_context_compiler.compile_research_context(
        agent_root,
        {
            "user_message": message,
            "intent": intent,
            "project_id": project_id,
            "conversation_state": {**(payload.get("conversation_state") or {}), "conversation_id": conversation_id, "recent_messages": history_before[-10:]},
            "max_tokens": int(payload.get("max_context_tokens") or payload.get("max_tokens") or 2000),
            "developer_debug": developer_debug,
            "suppress_task_status": force_ordinary_llm_chat or should_suppress_task_status_for_chat(response_mode_for_intent(intent), include_full_task_status),
        },
    )
    compiler_call = {"tool": "research_context_compiler", "status": "completed"}
    if developer_debug:
        compiler_call["context_hash"] = context_bundle.get("context_hash")
    tool_calls.append(compiler_call)
    workspace = workspace_state(agent_root, project_id)
    tool_calls.append({"tool": "workspace_state", "status": "completed"})
    initial_actions = agent_next_actions(intent, workspace, context_bundle.get("task_status", []))

    if intent == "file_registry_query":
        files = list_recent_uploaded_files(agent_root, project_id, limit=5)
        answer = format_file_registry_answer(agent_root, project_id, files, workspace.get("project") or {})
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "file_registry_query",
            "answer": answer,
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": [],
            "tool_calls": tool_calls + [{"tool": "FileRegistry", "status": "completed", "file_count": len(files)}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace,
            "files": files,
            "next_actions": [{"label": "解析最近上传文件", "intent": "uploaded_file_parse"}] if files else [],
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "uploaded_file_parse":
        files = list_recent_uploaded_files(agent_root, project_id, limit=5)
        answer = format_uploaded_file_parse_answer(agent_root, project_id, files, workspace.get("project") or {})
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "uploaded_file_parse",
            "answer": answer,
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": [],
            "tool_calls": tool_calls + [{"tool": "FileRegistry", "status": "completed", "file_count": len(files)}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace,
            "files": files,
            "next_actions": [{"label": "分析这个数据", "intent": "data_analysis"}] if files else [],
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "project_archive_request":
        project = archive_project(agent_root, project_id)
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "project_management",
            "answer": format_project_archive_answer(project),
            "citations": [],
            "memory_used": [],
            "sources": [],
            "tool_calls": tool_calls + [{"tool": "ProjectRegistry.archive_project", "status": "completed"}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace_state(agent_root, project_id),
            "project": project_public_view(project),
            "next_actions": [],
            "validation_status": "skipped",
            "debug": {},
            "error": None,
        })

    if intent == "project_unarchive_request":
        project = unarchive_project(agent_root, project_id)
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "project_management",
            "answer": f"项目 {project_display_name(project)} 已恢复为 active。",
            "citations": [],
            "memory_used": [],
            "sources": [],
            "tool_calls": tool_calls + [{"tool": "ProjectRegistry.unarchive_project", "status": "completed"}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace_state(agent_root, project_id),
            "project": project_public_view(project),
            "next_actions": [],
            "validation_status": "skipped",
            "debug": {},
            "error": None,
        })

    if intent == "project_clear_request":
        result = clear_project(agent_root, project_id, "all", confirmation=message)
        answer = "项目已清空，但项目本身仍保留。" if result.get("executed") else format_project_clear_plan_answer(result)
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "project_management",
            "answer": answer,
            "citations": [],
            "memory_used": [],
            "sources": [],
            "tool_calls": tool_calls + [{"tool": "ProjectRegistry.clear_project", "status": "completed", "executed": bool(result.get("executed"))}],
            "task_status": [],
            "workspace_state": workspace_state(agent_root, project_id),
            "project_operation": result,
            "next_actions": [],
            "validation_status": "skipped",
            "debug": {},
            "error": None,
        })

    if intent == "project_purge_request":
        result = purge_project(agent_root, project_id, confirmation=message)
        answer = "项目已彻底删除，普通项目列表中不再显示。" if result.get("executed") else format_project_purge_plan_answer(result)
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "project_management",
            "answer": answer,
            "citations": [],
            "memory_used": [],
            "sources": [],
            "tool_calls": tool_calls + [{"tool": "ProjectRegistry.purge_project", "status": "completed", "executed": bool(result.get("executed"))}],
            "task_status": [],
            "workspace_state": workspace_state(agent_root, project_id) if not result.get("executed") else {"active_project_id": "", "active_project_display_name": ""},
            "project_operation": result,
            "next_actions": [],
            "validation_status": "skipped",
            "debug": {},
            "error": None,
        })

    if intent in {"capability_query", "capability_explanation"} and not force_ordinary_llm_chat:
        catalog = build_capability_catalog(agent_root, project_id)
        return finalize({
            "ok": True,
            "intent": "capability_explanation",
            "response_mode": "capability_explanation",
            "answer": format_capability_catalog_answer(catalog, context_bundle.get("task_status", [])),
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls,
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace,
            "capability_catalog": catalog,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", []), "workspace_state": workspace},
            "error": None,
        })

    if intent == "autonomous_learning_question":
        catalog = build_capability_catalog(agent_root, project_id)
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "autonomous_learning",
            "answer": format_autonomous_learning_answer(context_bundle.get("task_status", [])),
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls,
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace,
            "capability_catalog": catalog,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "self_description_or_architecture" and not force_ordinary_llm_chat:
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "self_description",
            "answer": format_self_description_answer(message),
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls,
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "paper_recommendation":
        recommendation = format_paper_recommendation_answer(agent_root, project_id, message, limit=3)
        artifact = create_artifact(
            agent_root,
            {
                "project_id": project_id,
                "artifact_type": "paper_recommendation",
                "title": "Paper reading recommendation",
                "content_markdown": recommendation["answer"],
                "content_json": recommendation,
                "status": "pending_confirmation",
                "source_type": "agent_chat",
                "source_id": conversation_id,
                "source_refs": [
                    {"type": "reference", "id": clean(item.get("reference_id")), "title": clean(item.get("title"))}
                    for item in as_list((recommendation.get("rag") or {}).get("retrieved_chunks"))
                    if isinstance(item, dict) and clean(item.get("reference_id"))
                ],
                "evidence_level": "literature_derived" if recommendation.get("papers") else "agent_generated_needs_review",
            },
        )
        candidate = next((item for item in list_pending_memory_candidates(agent_root, project_id, limit=5) if item.get("artifact_id") == artifact.get("artifact_id")), {})
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "paper_recommendation",
            "answer": recommendation["answer"],
            "citations": recommendation.get("rag", {}).get("citations", []),
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "PaperRecommendationFormatter", "status": "completed", "paper_count": len(recommendation.get("papers") or [])}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace,
            "paper_recommendation": recommendation,
            "artifact": artifact,
            "memory_candidate": candidate,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "weekly_digest_generation":
        digest_result = generate_weekly_project_digest(
            agent_root,
            {
                "project_id": project_id,
                "question": message,
                "provider": clean(payload.get("provider")) or "none",
                "research_interests": clean(payload.get("research_interests")),
                "max_papers": int(payload.get("max_papers") or 5),
                "trigger": "agent_chat",
            },
        )
        artifact = digest_result.get("artifact") or {}
        candidate = digest_result.get("memory_candidate") or {}
        answer = (
            f"{artifact.get('title') or 'Weekly research digest'} 已生成，状态为待确认。\n"
            f"artifact_id: {artifact.get('artifact_id')}\n"
            f"candidate_id: {candidate.get('candidate_id')}\n"
            "如果要写入项目记忆，直接说“保存这份周报”或“纳入项目记忆”。"
        )
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "weekly_digest",
            "answer": answer,
            "citations": (digest_result.get("rag") or {}).get("citations", []),
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "WeeklyDigestWorkflow", "status": "completed", "artifact_id": artifact.get("artifact_id"), "candidate_id": candidate.get("candidate_id")}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace_state(agent_root, project_id),
            "artifact": artifact,
            "memory_candidate": candidate,
            "weekly_digest": digest_result.get("weekly_digest", {}),
            "next_actions": [{"label": "保存这份周报", "intent": "memory_commit_request", "artifact_id": artifact.get("artifact_id")}],
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "memory_commit_request":
        resolution = resolve_recent_artifact_reference(
            agent_root,
            project_id,
            message,
            {
                **(payload.get("conversation_state") if isinstance(payload.get("conversation_state"), dict) else {}),
                "recent_messages": history_before[-10:],
            },
        )
        if resolution["resolution"] == "single_candidate" and resolution.get("candidate"):
            commit = commit_pending_memory_candidate(agent_root, resolution["candidate"]["candidate_id"])
            answer = (
                "已保存到项目记忆。\n"
                f"memory_id: {commit['memory_id']}\n"
                f"memory_type: {commit['memory_type']}\n"
                f"source artifact: {commit['source_artifact']}\n"
                f"evidence_level: {commit['evidence_level']}\n"
                "后续可以说“基于刚才保存的项目记忆继续总结/写周报/制定下一步计划”。"
            )
            memory_commit = {**commit, "resolution": "single_candidate"}
        elif resolution["resolution"] == "multiple_candidates":
            lines = ["我找到了多个可保存候选，请选择要纳入项目记忆的编号："]
            for index, candidate in enumerate(resolution.get("candidates") or [], start=1):
                artifact = candidate.get("artifact") or {}
                lines.append(f"{index}. {artifact.get('title') or candidate.get('memory_type')} ({candidate.get('memory_type')}, candidate_id: {candidate.get('candidate_id')})")
            answer = "\n".join(lines)
            memory_commit = {"committed": False, "resolution": "multiple_candidates", "candidates": resolution.get("candidates") or []}
        else:
            answer = "当前没有可确认保存的候选内容。请提供具体内容，或先生成周报、总结、方案、分析结果后再说“保存”。"
            memory_commit = {"committed": False, "resolution": "no_candidate", "candidates": []}
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "memory_commit_result",
            "answer": answer,
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "PendingMemoryCandidateResolver", "status": "completed", "resolution": memory_commit.get("resolution")}],
            "task_status": context_bundle.get("task_status", []),
            "workspace_state": workspace_state(agent_root, project_id),
            "memory_commit": memory_commit,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "literature_harvest_prepare":
        keywords = display_literature_keywords(detected_literature_keywords or last_literature_keywords)
        query = ", ".join(keywords)
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": f"I can start a literature collection task for these keywords: {query}. Say \"start directly\" to begin.",
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls,
            "task_status": latest_task_status(agent_root, project_id, limit=5),
            "workspace_state": workspace,
            "literature_keywords": keywords,
            "next_actions": [{"label": "Start literature collection", "intent": "start_literature_harvest", "description": "Start with the detected keywords."}],
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "paper_request_list":
        task_status = latest_task_status(agent_root, project_id, limit=8)
        for item in task_status:
            if item.get("task_type") == "literature_harvest" and clean(item.get("task_id")):
                try:
                    generate_paper_requests_for_task(agent_root, {"project_id": project_id, "task_id": clean(item.get("task_id"))})
                except Exception:
                    pass
        requests = list_paper_requests(agent_root, project_id=project_id, limit=int(payload.get("limit") or 50))
        watch_folder = paper_request_watch_folder(agent_root, project_id)
        result = {
            "project_id": project_id,
            "paper_requests": requests,
            "watch_folder": str(watch_folder),
            "watch_folder_display": f"research_os_files/paper_requests/{watch_folder.name}",
        }
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": format_paper_request_list_answer(result),
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "ListPaperRequests", "status": "completed", "pending_count": sum(1 for item in requests if clean(item.get("status")) == "pending")}],
            "task_status": task_status,
            "workspace_state": workspace_state(agent_root, project_id),
            "paper_requests": result,
            "next_actions": [{"label": "Process supplemented PDFs", "intent": "paper_request_process", "description": "After putting PDFs into the watch folder, ask me to continue processing them."}],
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "paper_request_process":
        task_status = latest_task_status(agent_root, project_id, limit=8)
        active_lit = next((item for item in task_status if item.get("task_type") == "literature_harvest" and clean(item.get("status")) == "running"), {})
        task_id = clean(payload.get("task_id")) or clean(active_lit.get("task_id"))
        result = process_user_downloaded_pdfs(agent_root, {"project_id": project_id, "task_id": task_id})
        watch_folder = Path(clean(result.get("watch_folder"))) if clean(result.get("watch_folder")) else paper_request_watch_folder(agent_root, project_id)
        result["watch_folder_display"] = f"research_os_files/paper_requests/{watch_folder.name}"
        updated_task_status = latest_task_status(agent_root, project_id, limit=8)
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": format_user_pdf_processing_answer(result),
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "ProcessUserDownloadedPdfs", "status": "completed", "matched_count": result.get("matched_count", 0), "ingested_count": result.get("ingested_count", 0)}],
            "task_status": updated_task_status,
            "workspace_state": workspace_state(agent_root, project_id),
            "paper_request_processing": result,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "literature_source_traceability":
        task_status = latest_task_status(agent_root, project_id, limit=8)
        active_lit = next((item for item in task_status if item.get("task_type") == "literature_harvest" and clean(item.get("status")) == "running"), {})
        focus_keywords = last_literature_keywords or detected_literature_keywords
        if not focus_keywords and active_lit:
            focus_keywords = display_literature_keywords(active_lit.get("keywords"))
        summary = literature_learning_summary_skill(
            agent_root,
            {
                "project_id": project_id,
                "task_id": clean(active_lit.get("task_id")),
                "max_papers": int(payload.get("max_papers") or 5),
                "language": clean(payload.get("language")) or "en",
                "focus_keywords": focus_keywords,
            },
        )
        trace_summary = filter_learning_summary_for_source_traceability(summary, message)
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": format_literature_source_traceability(trace_summary, include_internal_ids=developer_debug),
            "citations": trace_summary.get("citations", []),
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "LiteratureSourceTraceabilitySkill", "status": "completed", "ingested_paper_count": trace_summary.get("ingested_paper_count", 0)}],
            "task_status": task_status,
            "workspace_state": workspace,
            "learning_summary": trace_summary,
            "literature_keywords": focus_keywords,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "ingested_paper_inventory":
        task_status = latest_task_status(agent_root, project_id, limit=8)
        inventory = list_ingested_papers_skill(
            agent_root,
            {
                "project_id": project_id,
                "limit": int(payload.get("limit") or payload.get("max_papers") or 20),
                "sort_by": clean(payload.get("sort_by")) or "created_at",
                "language": clean(payload.get("language")) or "en",
                "include_summary": payload.get("include_summary", True),
                "include_chunk_count": payload.get("include_chunk_count", True),
            },
        )
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": format_ingested_papers_inventory(inventory, task_status),
            "citations": [
                {
                    "citation_id": index,
                    "reference_id": paper.get("reference_id"),
                    "display_title": paper.get("title"),
                    "doi": paper.get("doi"),
                    "file_path": paper.get("source_file_path"),
                }
                for index, paper in enumerate(inventory.get("papers") or [], start=1)
            ],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "ListIngestedPapersSkill", "status": "completed", "ingested_paper_count": inventory.get("ingested_paper_count", 0)}],
            "task_status": task_status,
            "workspace_state": workspace,
            "ingested_paper_inventory": inventory,
            "next_actions": initial_actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "literature_learning_summary":
        task_status = latest_task_status(agent_root, project_id, limit=8)
        active_lit = next((item for item in task_status if item.get("task_type") == "literature_harvest" and clean(item.get("status")) == "running"), {})
        focus_keywords = last_literature_keywords or detected_literature_keywords
        if not focus_keywords and active_lit:
            focus_keywords = display_literature_keywords(active_lit.get("keywords"))
        summary = literature_learning_summary_skill(
            agent_root,
            {
                "project_id": project_id,
                "task_id": clean(active_lit.get("task_id")),
                "max_papers": int(payload.get("max_papers") or 5),
                "language": clean(payload.get("language")) or "en",
                "focus_keywords": focus_keywords,
            },
        )
        answer = format_learning_summary_policy(summary, task_status)
        artifact = create_artifact(
            agent_root,
            {
                "project_id": project_id,
                "artifact_type": "learning_summary",
                "title": "Literature learning summary",
                "content_markdown": answer,
                "content_json": summary,
                "status": "pending_confirmation",
                "source_type": "agent_chat",
                "source_id": conversation_id,
                "source_refs": [{"type": "chat_session", "id": conversation_id}],
                "evidence_level": "literature_derived",
            },
        )
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "learning_summary",
            "answer": answer,
            "citations": summary.get("citations", []),
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "LiteratureLearningSummarySkill", "status": "completed", "ingested_paper_count": summary.get("ingested_paper_count", 0)}],
            "task_status": task_status,
            "workspace_state": workspace,
            "learning_summary": summary,
            "artifact": artifact,
            "literature_keywords": focus_keywords,
            "next_actions": [{"label": item, "intent": "literature_learning_next_action", "description": item} for item in summary.get("next_actions", [])[:4]],
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "task_status_query" and not force_ordinary_llm_chat:
        task_status = latest_task_status(agent_root, project_id, limit=8)
        actions = agent_next_actions(intent, workspace, task_status)
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": format_task_status_answer(task_status, last_literature_keywords),
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls,
            "task_status": task_status,
            "workspace_state": workspace,
            "next_actions": actions,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", []), "workspace_state": workspace},
            "error": None,
        })

    if intent in {"project_status", "project_status_query"} and not force_ordinary_llm_chat:
        project_status = get_project_status(agent_root, project_id)
        task_status = context_bundle.get("task_status", [])
        artifact_summary = workspace.get("artifact_summary") or {}
        artifact_by_type = artifact_summary.get("by_type") if isinstance(artifact_summary.get("by_type"), dict) else {}
        artifact_text = "，".join(f"{key} {value}" for key, value in list(artifact_by_type.items())[:6]) or "暂无注册资产"
        answer = format_project_management_status_answer(project_status)
        answer += f"\n已注册资料：{artifact_summary.get('total_count', 0)} 个：{artifact_text}。"
        answer += "\n下一步可以继续入库 PDF、总结已入库文献，或整理实验记录。"
        actions = agent_next_actions(intent, workspace, task_status)
        return finalize({
            "ok": True,
            "intent": intent,
            "response_mode": "project_status",
            "answer": answer,
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "project_status_counts", "status": "completed"}],
            "task_status": task_status,
            "workspace_state": workspace,
            "next_actions": actions,
            "validation_status": "skipped",
            "debug": {"counts": project_status.get("counts", {}), "context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", []), "workspace_state": workspace},
            "error": None,
        })

    if intent == "proactive_status_query":
        heartbeat = agent_heartbeat(agent_root, {"project_id": project_id, "trigger": "agent_chat", "auto_run_low_risk": True})
        watcher_result = heartbeat.get("watcher_result") or {}
        inbox_items = heartbeat.get("research_feed") or watcher_result.get("inbox_items") or []
        answer = proactive_progress_answer(watcher_result, inbox_items)
        if heartbeat.get("created_tasks"):
            answer += f" 我还创建了 {len(heartbeat.get('created_tasks') or [])} 个可跟踪任务。"
        if heartbeat.get("auto_run_results"):
            answer += f" 其中 {len(heartbeat.get('auto_run_results') or [])} 个低风险任务已自动推进。"
        task_status = latest_task_status(agent_root, project_id, limit=8)
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": answer,
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "agent_heartbeat", "status": "completed", "trigger": "agent_chat"}],
            "task_status": task_status,
            "workspace_state": heartbeat.get("workspace_state") or watcher_result.get("workspace_state") or workspace,
            "research_feed": inbox_items,
            "watcher_result": watcher_result,
            "heartbeat": heartbeat,
            "next_actions": watcher_result.get("recommended_actions") or agent_next_actions(intent, heartbeat.get("workspace_state") or workspace, task_status),
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    if intent == "skill_learning_request":
        task = create_agent_task(
            agent_root,
            {
                "project_id": project_id,
                "task_type": "skill_learning",
                "status": "pending",
                "priority": "medium",
                "input": {"request": message},
                "next_action": "从最近 skill_runs、execution_memory 和 artifacts 中生成 skill 草稿，等待用户确认后再激活。",
                "source_type": "agent_chat",
                "source_id": conversation_id,
                "force_new": True,
            },
        )
        run_result = run_agent_task(agent_root, task["task_id"], {"message": message})
        task_status = latest_task_status(agent_root, project_id, limit=8)
        draft = ((run_result.get("result") or {}).get("skill_draft") if isinstance(run_result.get("result"), dict) else {}) or {}
        answer = "已根据最近执行记录生成一个 skill 草稿，放入 Research Feed 审阅。它还没有激活，确认前不会写入正式 Skill Registry。"
        if draft.get("skill_name"):
            answer += f" 草稿名：{clean(draft.get('skill_name'))}。"
        return finalize({
            "ok": bool(run_result.get("ok")),
            "intent": intent,
            "answer": answer if run_result.get("ok") else f"生成 skill 草稿失败：{clean(run_result.get('error'))}",
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "run_agent_task", "task_type": "skill_learning", "status": "completed" if run_result.get("ok") else "failed"}],
            "task_status": task_status,
            "workspace_state": workspace_state(agent_root, project_id),
            "research_feed": list_agent_inbox(agent_root, project_id=project_id, limit=10).get("items", []),
            "task": run_result.get("task"),
            "skill_draft": draft,
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None if run_result.get("ok") else clean(run_result.get("error")),
        })

    if intent == "start_skill_request":
        keywords = display_literature_keywords(detected_literature_keywords or last_literature_keywords)
        if not keywords:
            return finalize({
            "ok": False,
            "intent": intent,
            "answer": "No active task exists and I do not have literature keywords from this conversation. Tell me the keywords and I can start a literature collection task.",
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
                "sources": context_bundle.get("sources", []),
                "tool_calls": tool_calls,
                "task_status": context_bundle.get("task_status", []),
                "workspace_state": workspace,
                "validation_status": "skipped",
                "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
                "error": "missing_keywords",
            })
        query = " ".join(keywords)
        try:
            agent_task = create_agent_task(
                agent_root,
                {
                    "project_id": project_id,
                    "task_type": "literature_harvest",
                    "status": "pending",
                    "priority": "medium",
                    "input": {"project_id": project_id, "keywords": keywords, "folder_keywords": keywords, "query": query, "provider": "all"},
                    "next_action": "联网检索并下载可公开访问全文，逐篇解析入库。",
                    "source_type": "agent_chat",
                    "source_id": conversation_id,
                    "force_new": True,
                },
            )
            run_result = run_agent_task(agent_root, agent_task["task_id"], {"approved": True})
        except Exception as exc:  # noqa: BLE001
            return finalize({
                "ok": False,
                "intent": intent,
                "answer": "The literature-harvest backend is not available. I can save this as a pending task or generate a search strategy instead.",
                "citations": [],
                "memory_used": context_bundle.get("memory_used", []),
                "sources": context_bundle.get("sources", []),
                "tool_calls": tool_calls + [{"tool": "run_agent_task", "task_type": "literature_harvest", "status": "failed"}],
                "task_status": latest_task_status(agent_root, project_id, limit=5),
                "workspace_state": workspace,
                "literature_keywords": keywords,
                "validation_status": "skipped",
                "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
                "error": clean(exc),
            })
        task_status = latest_task_status(agent_root, project_id, limit=3)
        updated_workspace = workspace_state(agent_root, project_id)
        lit_status = next((item for item in task_status if item.get("task_type") == "literature_harvest"), {})
        counters = lit_status.get("counters") if isinstance(lit_status.get("counters"), dict) else {"found": 0, "downloaded": 0, "parsed": 0, "ingested": 0, "failed": 0}
        current_stage = clean(lit_status.get("current_stage")) or "searching"
        project = get_project_detail(agent_root, project_id)
        user_task = {
            "task_id": clean(lit_status.get("task_id")) or clean((run_result.get("task") or {}).get("task_id")),
            "project_name": clean(project.get("title")) or project_id,
            "keywords": keywords,
            "status": clean(lit_status.get("status")) or "running",
            "current_stage": current_stage,
            "counters": counters,
        }
        answer = (
            "Started literature collection task.\n"
            f"task_id: {user_task['task_id']}\n"
            f"project: {user_task['project_name']}\n"
            f"keywords: {', '.join(keywords)}\n"
            f"status: {user_task['status']}\n"
            f"current_stage: {user_task['current_stage']}\n"
            f"counters: found {counters.get('found', 0)}, downloaded {counters.get('downloaded', 0)}, parsed {counters.get('parsed', 0)}, ingested {counters.get('ingested', 0)}, failed {counters.get('failed', 0)}"
        )
        if counters == {"found": 0, "downloaded": 0, "parsed": 0, "ingested": 0, "failed": 0}:
            answer += "\nCurrent stage: searching PubMed or configured literature sources. No candidate papers have been collected yet."
        return finalize({
            "ok": True,
            "intent": intent,
            "answer": answer,
            "citations": [],
            "memory_used": context_bundle.get("memory_used", []),
            "sources": context_bundle.get("sources", []),
            "tool_calls": tool_calls + [{"tool": "run_agent_task", "task_type": "literature_harvest", "status": "completed", "task_id": agent_task.get("task_id"), "skill_run_id": run_result.get("skill_run_id")}],
            "task_status": task_status,
            "workspace_state": updated_workspace,
            "task": user_task,
            "literature_keywords": keywords,
            "next_actions": agent_next_actions(intent, updated_workspace, task_status),
            "validation_status": "skipped",
            "debug": {"context_hash": context_bundle.get("context_hash"), "context_warnings": context_bundle.get("warnings", [])},
            "error": None,
        })

    memory_used = context_bundle.get("memory_used", [])
    sources = context_bundle.get("sources", [])
    citations = build_evidence_citations(agent_root, project_id, sources, memory_used)
    answer_context = research_context_compiler.sanitize_context_for_user_answer(context_bundle, developer_debug=developer_debug)
    compiled_context = clean(answer_context.get("compiled_context"))
    workspace_for_answer = research_context_compiler.sanitize_workspace_for_user_answer(workspace, developer_debug=developer_debug)
    citation_objects_for_answer = [
        {
            "citation id": item.get("citation_id"),
            "source title": clean(item.get("display_title") or item.get("title")),
            "short excerpt": clean(item.get("excerpt"))[:260],
        }
        for item in citations[:8]
    ]

    prompt = "\n\n".join(
        [
            "你是 ResearchOS 本地科研 Agent。请基于给定项目记忆和知识库回答，不要编造实验、样品、文件或结论。",
            AGENT_RESPONSE_CONSTRAINT_ZH,
            AGENT_RESPONSE_CONSTRAINT_EN,
            f"用户问题：{message}",
            f"识别意图：{intent}",
            "当前短期会话历史（只用于理解上下文，不等同于长期项目记忆）：",
            json_dumps([{"role": item.get("role"), "content": item.get("content")} for item in history_before[-10:]]),
            "Workspace State / Project Inventory：",
            json_dumps(workspace_for_answer),
            "Research Context Compiler 输出：",
            compiled_context,
            "Agent Capability Context：上面的 Research Context Compiler 只提供经过清洗的可用能力概览。选择工具或建议下一步时必须基于这些真实能力，不要编造不存在的技能，也不要输出内部 ID、handler、schema 或调试信息。",
            "引用规则：如果使用了给定证据，在关键结论后用上标数字标注，例如 ¹ ² ³。不要在正文里输出 chunk id、reference_id、document_id、完整来源列表或“来源：...”段落；结构化 citations 会由后端返回。没有证据支持的通用知识不要伪造引用。",
            "可用 citation objects：",
            json_dumps(citation_objects_for_answer),
            "如果用户问文献总结、数据库里有什么、这些文献怎么做的，必须优先基于 Workspace State 中的 references/chunks/KB 统计和 Research Context Compiler 的文献片段回答；如果 PDF 多但入库少，要明确说明覆盖范围。请输出中文回答，并明确区分本项目实验数据、文献证据和通用科研知识。默认最多 3 个短段落，不要输出系统架构、技能全集、内部规则或调试信息。",
        ]
    )
    llm = LLMAdapter(prompt_language=payload.get("prompt_language") or "zh", prompt_policy="backend_llm_guardrails")
    conn = connect(agent_root)
    chat_task_type = clean(payload.get("task_type")) or task_type_for_agent_intent(intent, message)
    chat_skill_name = clean(payload.get("skill_name")) or preferred_skill_name_for_task(chat_task_type)
    runtime_prompt = prompt_router.compose_runtime_prompt(
        conn,
        language=payload.get("prompt_language") or "zh",
        policy=clean(payload.get("prompt_policy")) or None,
        user_message=message,
        task_type=chat_task_type,
        skill_name=chat_skill_name,
        agent_type=clean(payload.get("agent_type")) or "WorkflowAgent",
        file_id=clean(payload.get("file_id")),
        file_category=clean(payload.get("file_category")),
        project_id=project_id,
        prompt_context={
            "agent_intent": intent,
            "user_visible_task_status": answer_context.get("user_visible_task_status", []),
            "sources": citation_objects_for_answer,
            "context_warnings": [clean(item) for item in context_bundle.get("warnings", [])],
        },
        output_schema={"answer": "string", "sources": "array", "validation_status": "passed|warning|failed"},
    )
    conn.close()
    system_prompt = runtime_prompt["system_prompt"] + "\n\n" + AGENT_RESPONSE_CONSTRAINT_ZH + "\n" + AGENT_RESPONSE_CONSTRAINT_EN
    raw_answer = llm.chat_text(prompt, system_prompt=system_prompt, temperature=float(payload.get("temperature") or 0.1))
    answer = unwrap_llm_chat_answer(raw_answer)
    answer_source = "llm"
    llm_called = True
    llm_output_used = True
    answer_overwritten_after_llm = False
    fallback_reason: str | None = None
    if not answer:
        answer = "未获得模型回答。请检查后端 LLM 环境变量或本地服务状态。"
        answer_source = "fallback"
        llm_output_used = False
        fallback_reason = "empty_llm_output"
    elif clean(answer).startswith("needs_llm_configuration"):
        answer = "needs_llm_configuration: 请先在设置页配置后端 LLM API key、模型和 Base URL，然后重试 ResearchOS 对话。"
        answer_source = "fallback"
        llm_called = False
        llm_output_used = False
        fallback_reason = "needs_llm_configuration"
    task_status = context_bundle.get("task_status", [])
    sanitizer_forced_rewrite = sanitizer_requires_answer_rewrite(answer, message)
    sanitized_answer = sanitize_agent_answer(answer, intent, task_status=task_status, message=message, workspace=workspace)
    if sanitizer_forced_rewrite and clean(sanitized_answer) != clean(answer):
        answer_source = "sanitizer_rewrite"
        llm_output_used = False
        answer_overwritten_after_llm = True
    answer = sanitized_answer
    answer = ensure_answer_citations(answer, citations, message=message)

    validation = canonical_memory.validate_research_answer(
        agent_root,
        {
            "project_id": project_id,
            "answer_text": answer,
            "query": message,
            "memory_context": {
                "context_text": compiled_context,
                "results": answer_context.get("user_visible_sources", []),
            },
        },
    )
    tool_calls.append({"tool": "validate_research_answer", "status": "completed"})
    validation_status = "passed" if validation.get("is_valid") else ("warning" if validation.get("issues") else "failed")

    saved_to_memory = False
    if bool(payload.get("save_to_memory")):
        gate = classify_memory_candidate(message, {"project_id": project_id, "source_refs": [{"type": "agent_chat", "id": conversation_id}]})
        if gate["should_save"] and gate["memory_layer"] in {"project_memory", "user_profile"}:
            create_agent_memory_entry(
                agent_root,
                {
                    "memory_scope": "project",
                    "project_id": project_id,
                    "memory_type": gate["memory_type"] or "agent_chat",
                    "title": f"Agent chat: {message[:60]}",
                    "content": gate["normalized_content"] or answer,
                    "structured_content": {"message": message, "intent": intent, "sources": sources, "memory_used": memory_used, "memory_gate": gate},
                    "source_type": "agent_chat",
                    "source_id": stable_id(project_id, message, now(), length=24),
                    "provenance": tool_calls,
                    "trust_level": "user_confirmed" if gate["confidence"] == "high" else "raw_extracted",
                },
            )
            saved_to_memory = True

    return finalize({
        "ok": True,
        "intent": intent,
        "response_mode": "normal_answer" if force_ordinary_llm_chat else response_mode_for_intent(intent),
        "answer": answer,
        "citations": citations,
        "memory_used": memory_used,
        "sources": sources,
        "tool_calls": tool_calls,
        "task_status": task_status,
        "workspace_state": workspace,
        "next_actions": agent_next_actions(intent, workspace, task_status),
        "validation_status": validation_status,
        "validation": validation,
        "saved_to_memory": saved_to_memory,
        "debug": {
            "matched_skill": chat_skill_name,
            "context_hash": context_bundle.get("context_hash"),
            "context_warnings": context_bundle.get("warnings", []),
            "workspace_state": workspace,
            "prompt_routing": {key: value for key, value in runtime_prompt.items() if key != "system_prompt"},
            "llm": {"provider": llm.provider, "model": llm.model, "mode": llm.mode},
            "raw_llm_output_preview": clean(raw_answer)[:500] if developer_debug else "",
        },
        "error": None,
        "matched_skill": chat_skill_name,
        "llm": {"provider": llm.provider, "model": llm.model, "mode": llm.mode},
        "answer_source": answer_source,
        "llm_called": llm_called,
        "llm_output_used": llm_output_used,
        "answer_overwritten_after_llm": answer_overwritten_after_llm,
        "llm_provider": llm.provider,
        "llm_model": llm.model,
        "prompt_router_used": True,
        "context_compiler_used": True,
        "template_id": None,
        "fallback_reason": fallback_reason,
    })


def upsert_weekly_digest_config(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    if not project_id:
        raise ValueError("project_id is required")
    config_id = clean(payload.get("id")) or stable_id(project_id, "weekly_digest_config", clean(payload.get("research_interests")), length=24)
    timestamp = now()
    row = {
        "id": config_id,
        "project_id": project_id,
        "research_interests": clean(payload.get("research_interests") or payload.get("interests")),
        "must_include_keywords_json": json_dumps(as_list(payload.get("must_include_keywords") or payload.get("keywords"))),
        "exclude_keywords_json": json_dumps(as_list(payload.get("exclude_keywords"))),
        "preferred_journals_json": json_dumps(as_list(payload.get("preferred_journals"))),
        "preferred_paper_types_json": json_dumps(as_list(payload.get("preferred_paper_types"))),
        "year_range": clean(payload.get("year_range")) or "last 3 years",
        "high_impact_rules": clean(payload.get("high_impact_rules")) or "Prefer strong relevance, methods value, and reputable journals; do not fabricate impact.",
        "digest_language": clean(payload.get("digest_language")) or "en",
        "delivery_day": clean(payload.get("delivery_day")) or "manual",
        "max_papers": int(payload.get("max_papers") or 5),
        "status": clean(payload.get("status")) or "active",
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO weekly_digest_configs(
          id, project_id, research_interests, must_include_keywords_json, exclude_keywords_json,
          preferred_journals_json, preferred_paper_types_json, year_range, high_impact_rules,
          digest_language, delivery_day, max_papers, status, created_at, updated_at
        )
        VALUES (
          :id, :project_id, :research_interests, :must_include_keywords_json, :exclude_keywords_json,
          :preferred_journals_json, :preferred_paper_types_json, :year_range, :high_impact_rules,
          :digest_language, :delivery_day, :max_papers, :status, :created_at, :updated_at
        )
        ON CONFLICT(id) DO UPDATE SET
          research_interests=excluded.research_interests,
          must_include_keywords_json=excluded.must_include_keywords_json,
          exclude_keywords_json=excluded.exclude_keywords_json,
          preferred_journals_json=excluded.preferred_journals_json,
          preferred_paper_types_json=excluded.preferred_paper_types_json,
          year_range=excluded.year_range,
          high_impact_rules=excluded.high_impact_rules,
          digest_language=excluded.digest_language,
          delivery_day=excluded.delivery_day,
          max_papers=excluded.max_papers,
          status=excluded.status,
          updated_at=excluded.updated_at
        """,
        row,
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM weekly_digest_configs WHERE id=?", (config_id,)).fetchone()) or {}
    conn.close()
    return saved


def list_weekly_digest_configs(agent_root: Path, project_id: str = "") -> list[dict[str, Any]]:
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    conn = connect(agent_root)
    rows = rows_to_dicts(conn.execute(f"SELECT * FROM weekly_digest_configs WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC", params).fetchall())
    conn.close()
    return rows


def _weekly_digest_date_range(payload: dict[str, Any]) -> dict[str, str]:
    explicit = payload.get("date_range")
    if isinstance(explicit, dict) and (explicit.get("start") or explicit.get("end")):
        return {"start": clean(explicit.get("start")), "end": clean(explicit.get("end"))}
    end = datetime.now()
    start = end - timedelta(days=int(payload.get("lookback_days") or 7))
    return {"start": start.date().isoformat(), "end": end.date().isoformat()}


def _source_ref(source_type: str, source_id: Any, title: str = "") -> dict[str, str]:
    ref = {"type": clean(source_type), "id": clean(source_id)}
    if title:
        ref["title"] = clean(title)
    return ref


def _dedupe_source_refs(source_refs: list[dict[str, Any]]) -> list[dict[str, str]]:
    seen: set[tuple[str, str]] = set()
    deduped: list[dict[str, str]] = []
    for item in source_refs:
        source_type = clean(item.get("type"))
        source_id = clean(item.get("id"))
        if not source_type or not source_id:
            continue
        key = (source_type, source_id)
        if key in seen:
            continue
        seen.add(key)
        ref = {"type": source_type, "id": source_id}
        if clean(item.get("title")):
            ref["title"] = clean(item.get("title"))
        deduped.append(ref)
    return deduped


class WeeklyDigestWorkflow:
    """Build a reviewable weekly research digest from existing project context."""

    def __init__(self, agent_root: Path, payload: dict[str, Any]) -> None:
        self.agent_root = agent_root
        self.payload = payload
        self.project_id = clean(payload.get("project_id"))
        if not self.project_id:
            raise ValueError("project_id is required")
        self.date_range = _weekly_digest_date_range(payload)

    def run(self) -> dict[str, Any]:
        config = self._load_config()
        run = start_service_skill_run(self.agent_root, "core_weekly_research_digest", "weekly-research-digest", self.project_id, {**self.payload, "task_type": "weekly_digest", "date_range": self.date_range})
        try:
            if self._should_run_optional_harvest(config):
                search_literature(
                    self.agent_root,
                    {
                        "project_id": self.project_id,
                        "keywords": self._keywords(config),
                        "provider": clean(self.payload.get("provider")) or "mock",
                        "max_results": int(self.payload.get("max_results") or self.payload.get("max_papers") or config.get("max_papers") or 5),
                    },
                )
            build_project_research_kb(
                self.agent_root,
                {
                    "project_id": self.project_id,
                    "skill_run_id": run["id"],
                    "trigger_watcher_after_ingest": False,
                },
            )
            context = self._collect_context(config)
            rag = query_research_rag(
                self.agent_root,
                {
                    "project_id": self.project_id,
                    "question": clean(self.payload.get("question")) or self._rag_question(context, config),
                    "mode": "weekly_digest",
                    "limit": int(config.get("max_papers") or self.payload.get("max_papers") or 5),
                    "skill_run_id": run["id"],
                },
            )
            digest_json = self._build_digest_json(context, rag, config)
            digest_markdown = self._render_markdown(digest_json)
            report = self._store_digest_report(config, digest_markdown, digest_json, rag, run["id"])
            artifact = create_artifact(
                self.agent_root,
                {
                    "project_id": self.project_id,
                    "task_id": clean(self.payload.get("task_id")),
                    "skill_run_id": run["id"],
                    "artifact_type": "weekly_digest",
                    "title": digest_json["title"],
                    "date_range": self.date_range,
                    "content_markdown": digest_markdown,
                    "content_json": {"weekly_digest": digest_json, "report_id": report["id"], "rag_query_id": rag.get("query_id")},
                    "status": "pending_confirmation",
                    "source_type": "weekly_digest_report",
                    "source_id": report["id"],
                    "source_refs": digest_json["source_refs"],
                    "evidence_level": "literature_derived" if digest_json["source_refs"] else "agent_generated_needs_review",
                },
            )
            candidates = [candidate for candidate in list_pending_memory_candidates(self.agent_root, self.project_id, limit=10) if candidate.get("artifact_id") == artifact.get("artifact_id")]
            result = {
                "config": config,
                "digest_report": report,
                "artifact": artifact,
                "memory_candidate": candidates[0] if candidates else {},
                "rag": rag,
                "skill_run_id": run["id"],
                "weekly_digest": digest_json,
            }
            finish_service_skill_run(
                self.agent_root,
                run["id"],
                result,
                [{"type": "weekly_digest_report", "id": report["id"]}, {"type": "artifact", "id": artifact["artifact_id"]}, {"type": "rag_query", "id": rag["query_id"]}],
                ["Weekly digest artifact generated and queued for memory confirmation."],
            )
            register_artifact(
                self.agent_root,
                {
                    "artifact_id": artifact["artifact_id"],
                    "project_id": self.project_id,
                    "task_id": clean(self.payload.get("task_id")),
                    "skill_run_id": run["id"],
                    "type": "weekly_digest",
                    "title": artifact["title"],
                    "source_object_type": "weekly_digest_report",
                    "source_object_id": report["id"],
                    "status": artifact["status"],
                    "metadata": artifact.get("metadata") or {},
                    "skip_memory_consolidation": True,
                },
            )
            return result
        except Exception as exc:
            update_skill_run(self.agent_root, run["id"], status="failed", output_payload={"error": str(exc)}, logs=[str(exc)])
            raise

    def _load_config(self) -> dict[str, Any]:
        if self.payload.get("config_id"):
            return next((item for item in list_weekly_digest_configs(self.agent_root, self.project_id) if item["id"] == self.payload["config_id"]), {})
        if any(key in self.payload for key in ["research_interests", "interests", "keywords", "must_include_keywords", "delivery_day", "max_papers"]):
            return upsert_weekly_digest_config(self.agent_root, self.payload)
        configs = list_weekly_digest_configs(self.agent_root, self.project_id)
        return configs[0] if configs else {
            "id": "",
            "project_id": self.project_id,
            "research_interests": "",
            "must_include_keywords": [],
            "exclude_keywords": [],
            "preferred_journals": [],
            "preferred_paper_types": [],
            "year_range": "last 3 years",
            "high_impact_rules": "Prefer strong relevance, methods value, and reputable journals; do not fabricate impact.",
            "digest_language": "zh",
            "delivery_day": "manual",
            "max_papers": int(self.payload.get("max_papers") or 5),
            "status": "active",
        }

    def _keywords(self, config: dict[str, Any]) -> list[str]:
        keywords = as_list(config.get("must_include_keywords") or self.payload.get("keywords"))
        if keywords:
            return [clean(item) for item in keywords if clean(item)]
        direction = clean(config.get("research_interests") or self.payload.get("research_interests"))
        if not direction:
            project = get_project_detail(self.agent_root, self.project_id)
            direction = " ".join([clean(project.get("title")), clean(project.get("research_area")), clean(project.get("short_description"))])
        return extract_seed_keywords(direction, 8) if direction else []

    def _should_run_optional_harvest(self, config: dict[str, Any]) -> bool:
        provider = clean(self.payload.get("provider")).lower()
        if provider in {"", "none", "off", "disabled"}:
            return False
        return bool(self.payload.get("run_literature_search") or self.payload.get("auto_harvest") or self.payload.get("keywords"))

    def _collect_context(self, config: dict[str, Any]) -> dict[str, Any]:
        workspace = workspace_state(self.agent_root, self.project_id)
        memory_entries = list_agent_memory(self.agent_root, scope="project", project_id=self.project_id, include_disabled=False)["entries"][:12]
        references = list_references(self.agent_root, project_id=self.project_id, limit=50)
        chunks = list_reference_chunks(self.agent_root, project_id=self.project_id, limit=50)
        kb_entries = list_knowledge_base_entries(self.agent_root, project_id=self.project_id, limit=50)
        tasks = list_project_tasks(self.agent_root, self.project_id, limit=30)["tasks"]
        skill_runs = list_skill_runs(self.agent_root, project_id=self.project_id, limit=30)
        project = get_project_detail(self.agent_root, self.project_id)
        project_direction = clean(config.get("research_interests") or self.payload.get("research_interests") or project.get("research_area") or project.get("title"))
        return {
            "project": project,
            "project_direction": project_direction,
            "workspace": workspace,
            "references": references,
            "chunks": chunks,
            "kb_entries": kb_entries,
            "memory_entries": memory_entries,
            "tasks": tasks,
            "skill_runs": skill_runs,
        }

    def _rag_question(self, context: dict[str, Any], config: dict[str, Any]) -> str:
        direction = clean(context.get("project_direction") or config.get("research_interests") or "current project")
        return f"Weekly research digest for {direction}: new knowledge, priority papers, gaps, and next actions"

    def _build_digest_json(self, context: dict[str, Any], rag: dict[str, Any], config: dict[str, Any]) -> dict[str, Any]:
        retrieved = rag.get("retrieved_chunks") if isinstance(rag.get("retrieved_chunks"), list) else []
        top_refs = []
        seen_refs: set[str] = set()
        for item in retrieved:
            ref_id = clean(item.get("reference_id"))
            if not ref_id or ref_id in seen_refs or ref_id.startswith("memory:"):
                continue
            seen_refs.add(ref_id)
            top_refs.append(
                {
                    "reference_id": ref_id,
                    "citation_id": clean(item.get("citation_id")),
                    "title": clean(item.get("title")) or ref_id,
                    "reason": "Matches this week's project direction and KB/RAG context.",
                }
            )
        if not top_refs:
            for ref in context["references"][: int(config.get("max_papers") or 5)]:
                top_refs.append({"reference_id": ref["id"], "citation_id": "", "title": clean(ref.get("title")), "reason": "Recently added project reference."})
        source_refs = []
        source_refs.extend(_source_ref("reference", item["reference_id"], item.get("title", "")) for item in top_refs)
        source_refs.extend(_source_ref("knowledge_base_entry", item.get("id"), item.get("title", "")) for item in context["kb_entries"][:8])
        source_refs.extend(_source_ref("project_memory", item.get("id"), item.get("title", "")) for item in context["memory_entries"][:5])
        source_refs.extend(_source_ref("agent_task", item.get("task_id"), item.get("task_name", "")) for item in context["tasks"][:5])
        source_refs.extend(_source_ref("skill_run", item.get("id"), item.get("skill_name", "")) for item in context["skill_runs"][:5])
        source_refs = _dedupe_source_refs(source_refs)
        new_knowledge = self._new_knowledge(context, top_refs)
        research_gaps = self._research_gaps(context, rag)
        next_actions = self._next_actions(context, top_refs, research_gaps)
        title = f"Weekly Research Digest: {self.date_range['start']} to {self.date_range['end']}"
        return {
            "title": title,
            "project_id": self.project_id,
            "date_range": self.date_range,
            "project_direction": context["project_direction"],
            "new_knowledge": new_knowledge,
            "priority_reading": top_refs,
            "research_gaps": research_gaps,
            "next_actions": next_actions,
            "source_counts": {
                "references": len(context["references"]),
                "chunks": len(context["chunks"]),
                "kb_entries": len(context["kb_entries"]),
                "project_memory": len(context["memory_entries"]),
                "tasks": len(context["tasks"]),
                "skill_runs": len(context["skill_runs"]),
            },
            "source_refs": source_refs,
            "limitations": rag.get("limitations") or [],
        }

    def _new_knowledge(self, context: dict[str, Any], top_refs: list[dict[str, Any]]) -> list[str]:
        items: list[str] = []
        if context["kb_entries"]:
            for entry in context["kb_entries"][:3]:
                items.append(f"KB added/updated: {clean(entry.get('title')) or clean(entry.get('id'))}.")
        if top_refs:
            items.append(f"{len(top_refs)} recent reference(s) are ready for priority reading.")
        if context["memory_entries"]:
            items.append(f"Recent project memory contributes {len(context['memory_entries'])} contextual note(s).")
        return items or ["No new project KB or literature evidence was found in the selected date range."]

    def _research_gaps(self, context: dict[str, Any], rag: dict[str, Any]) -> list[str]:
        gaps: list[str] = []
        literature = (context.get("workspace") or {}).get("literature") or {}
        if int(literature.get("references_count") or 0) == 0:
            gaps.append("No project references are registered yet.")
        if int(literature.get("reference_chunks_count") or 0) == 0:
            gaps.append("No reference chunks are available for RAG-grounded synthesis.")
        if not context["tasks"]:
            gaps.append("No recent task history is available to connect literature findings to execution.")
        for item in rag.get("limitations") or []:
            if clean(item):
                gaps.append(clean(item))
        return gaps[:5] or ["No major gap detected from the available local context; continue evidence review before treating generated summaries as confirmed knowledge."]

    def _next_actions(self, context: dict[str, Any], top_refs: list[dict[str, Any]], gaps: list[str]) -> list[str]:
        actions: list[str] = []
        if top_refs:
            actions.append(f"Read and annotate: {top_refs[0]['title']}.")
        if context["kb_entries"]:
            actions.append("Promote only reviewed KB-derived conclusions into project decisions.")
        if any("chunks" in gap.lower() or "rag" in gap.lower() for gap in gaps):
            actions.append("Ingest or rebuild chunks for the most relevant references.")
        actions.append("After review, say \"保存这份周报\" or \"纳入项目记忆\" to commit this digest.")
        return actions[:5]

    def _render_markdown(self, digest: dict[str, Any]) -> str:
        def bullets(items: list[Any]) -> list[str]:
            return [f"- {clean(item)}" if not isinstance(item, dict) else f"- {clean(item.get('title') or item.get('reference_id'))}: {clean(item.get('reason'))}" for item in items]

        return "\n".join(
            [
                f"# {digest['title']}",
                "",
                f"Project direction: {digest.get('project_direction') or 'not specified'}",
                f"Date range: {digest['date_range']['start']} to {digest['date_range']['end']}",
                "",
                "## This Week's New Knowledge",
                *bullets(digest["new_knowledge"]),
                "",
                "## Priority Reading",
                *bullets(digest["priority_reading"]),
                "",
                "## Research Gaps",
                *bullets(digest["research_gaps"]),
                "",
                "## Suggested Next Actions",
                *bullets(digest["next_actions"]),
            ]
        )

    def _store_digest_report(self, config: dict[str, Any], digest_markdown: str, digest_json: dict[str, Any], rag: dict[str, Any], skill_run_id: str) -> dict[str, Any]:
        report_id = stable_id(self.project_id, "weekly_digest", self.date_range.get("start"), self.date_range.get("end"), now(), length=24)
        timestamp = now()
        top_reference_ids = [item["reference_id"] for item in digest_json.get("priority_reading", []) if clean(item.get("reference_id"))]
        conn = connect(self.agent_root)
        try:
            conn.execute(
                """
                INSERT INTO weekly_digest_reports(
                  id, project_id, config_id, title, digest_markdown, top_reference_ids_json,
                  citation_map_json, suggested_keyword_updates_json, memory_update_ids_json,
                  skill_run_id, created_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    report_id,
                    self.project_id,
                    clean(config.get("id")),
                    digest_json["title"],
                    digest_markdown,
                    json_dumps(top_reference_ids),
                    json_dumps(rag.get("citation_map") or {}),
                    json_dumps(self._keywords(config)),
                    json_dumps([]),
                    skill_run_id,
                    timestamp,
                    timestamp,
                ),
            )
            conn.commit()
            return row_to_dict(conn.execute("SELECT * FROM weekly_digest_reports WHERE id=?", (report_id,)).fetchone()) or {}
        finally:
            conn.close()


def generate_weekly_project_digest(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    return WeeklyDigestWorkflow(agent_root, payload).run()


def _weekly_digest_due(conn: sqlite3.Connection, project_id: str, config: dict[str, Any], force: bool = False) -> bool:
    if force:
        return True
    if clean(config.get("status")) not in {"", "active"}:
        return False
    if clean(config.get("delivery_day")).lower() in {"", "manual", "off", "disabled"}:
        return False
    row = conn.execute("SELECT MAX(updated_at) AS last_at FROM weekly_digest_reports WHERE project_id=? AND config_id=?", (project_id, clean(config.get("id")))).fetchone()
    return _minutes_since(clean(row["last_at"] if row else "")) >= int(os.environ.get("RESEARCHOS_WEEKLY_DIGEST_INTERVAL_MINUTES", "10080") or 10080)


def run_scheduled_weekly_digest(agent_root: Path, force: bool = False, project_id: str = "") -> dict[str, Any]:
    target_project_id = clean(project_id)
    conn = connect(agent_root)
    try:
        clauses = ["status='active'"]
        params: list[Any] = []
        if target_project_id:
            clauses.append("project_id=?")
            params.append(target_project_id)
        configs = rows_to_dicts(conn.execute(f"SELECT * FROM weekly_digest_configs WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC", params).fetchall())
        due = [config for config in configs if _weekly_digest_due(conn, clean(config.get("project_id")), config, force=force)]
    finally:
        conn.close()
    outcomes: list[dict[str, Any]] = []
    for config in due:
        try:
            result = generate_weekly_project_digest(agent_root, {"project_id": config["project_id"], "config_id": config["id"], "trigger": "scheduled"})
            outcomes.append({"project_id": config["project_id"], "config_id": config["id"], "generated": True, "artifact_id": result.get("artifact", {}).get("artifact_id"), "candidate_id": result.get("memory_candidate", {}).get("candidate_id")})
        except Exception as exc:
            outcomes.append({"project_id": config.get("project_id"), "config_id": config.get("id"), "generated": False, "error": str(exc)})
    return {"ok": True, "checked_configs": len(configs), "outcomes": outcomes}


def list_weekly_digest_reports(agent_root: Path, project_id: str = "", limit: int = 50) -> list[dict[str, Any]]:
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    params.append(int(limit or 50))
    conn = connect(agent_root)
    rows = rows_to_dicts(conn.execute(f"SELECT * FROM weekly_digest_reports WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC LIMIT ?", params).fetchall())
    conn.close()
    return rows


def evidence_key(evidence_type: str, evidence_id: str) -> str:
    return f"{clean(evidence_type)}:{clean(evidence_id)}"


def parse_evidence_key(value: str) -> tuple[str, str]:
    decoded = clean(value)
    if ":" not in decoded:
        return "", decoded
    evidence_type, evidence_id = decoded.split(":", 1)
    return clean(evidence_type), clean(evidence_id)


def evidence_support_flags(item: dict[str, Any]) -> tuple[bool, bool, str]:
    evidence_type = clean(item.get("evidence_type"))
    source_type = clean(item.get("source_type"))
    provider = clean(item.get("source_provider"))
    evidence_level = clean(item.get("evidence_level"))
    trust_level = clean(item.get("trust_level"))
    status = clean(item.get("status"))
    combined = " ".join([evidence_type, source_type, provider, evidence_level, trust_level, status, clean(item.get("title"))]).lower()
    if "mock" in combined or evidence_level == "mock_not_evidence":
        return False, False, "Mock or fake validation records cannot support scientific claims."
    if "manual_validation_placeholder" in combined:
        return False, False, "Manual validation placeholders are not evidence."
    if evidence_type in {"project_memory", "memory_entity"}:
        if trust_level in {"human_confirmed", "user_confirmed", "PI_confirmed", "publication_confirmed"}:
            return True, True, "Human-confirmed project memory can support a confirmed claim."
        return True, False, "Project memory must be human-confirmed before it can support a confirmed claim."
    if provider == "manual" or "manual metadata" in combined:
        return True, False, "Manual metadata requires verification before it can support a confirmed claim."
    if evidence_type in {"writing_output", "rag_query"} or "writing draft" in combined:
        return True, False, "Generated answers and writing drafts are review material, not confirmation evidence."
    if evidence_type in {"experiment_log", "failure_log"}:
        return True, False, "Experiment logs and failure logs are observations; they cannot confirm a claim alone."
    if evidence_type in {"reference", "reference_chunk"}:
        if provider in {"mock", "manual"}:
            return True, False, "Reference metadata from mock/manual provider is not enough for confirmation."
        if item.get("doi") or item.get("url") or item.get("full_text_available") or item.get("full_text_path") or evidence_level in {"real_reference", "peer_reviewed_metadata", "full_text", "user_uploaded_full_text"}:
            return True, True, "Real reference metadata or full text can support confirmation."
        return True, False, "Reference lacks DOI, URL, full text, or verified provider metadata."
    if evidence_type == "data_context":
        if status in {"validated", "user_confirmed", "human_confirmed"} or trust_level in {"human_confirmed", "user_confirmed", "PI_confirmed", "publication_confirmed"}:
            return True, True, "Validated data context can support confirmation."
        return True, False, "Data context must be validated before confirmation."
    if evidence_type == "source_file":
        if status in {"validated", "user_confirmed", "human_confirmed"} or item.get("context_status") in {"contextualized", "validated"}:
            return True, True, "Validated or contextualized source file can support confirmation."
        return True, False, "Source file needs validation or contextualization before confirmation."
    if evidence_type == "claim":
        if status == "confirmed":
            return True, True, "A human-confirmed claim can support downstream review."
        if status in {"unsupported", "weak", "inference", "needs_more_evidence"}:
            return True, False, "Weak, inferred, unsupported, or evidence-seeking claims cannot confirm another claim."
        return True, False, "Draft claims need review before they can support confirmation."
    if evidence_type in {"protocol", "weekly_digest_report", "retrospective_note", "knowledge_base_entry", "claim_evidence"}:
        return True, False, "This item is useful context but not direct confirmation evidence."
    return False, False, "Evidence type is not recognized as confirmatory evidence."


def linked_counts(conn: sqlite3.Connection, project_id: str, evidence_type: str, item_id: str) -> dict[str, int]:
    claim_count = conn.execute(
        "SELECT COUNT(*) FROM claim_evidence WHERE project_id=? AND evidence_type=? AND evidence_id=?",
        (project_id, evidence_type, item_id),
    ).fetchone()[0]
    report_count = conn.execute(
        """
        SELECT COUNT(*) FROM research_links
        WHERE project_id=? AND ((source_type=? AND source_id=? AND target_type='report') OR (target_type=? AND target_id=? AND source_type='report'))
        """,
        (project_id, evidence_type, item_id, evidence_type, item_id),
    ).fetchone()[0]
    memory_count = conn.execute(
        """
        SELECT COUNT(*) FROM research_links
        WHERE project_id=? AND ((source_type=? AND source_id=? AND target_type IN ('memory_entity','agent_memory'))
          OR (target_type=? AND target_id=? AND source_type IN ('memory_entity','agent_memory')))
        """,
        (project_id, evidence_type, item_id, evidence_type, item_id),
    ).fetchone()[0]
    return {"linked_claim_count": int(claim_count), "linked_report_count": int(report_count), "linked_memory_count": int(memory_count)}


def evidence_item_from_row(conn: sqlite3.Connection, evidence_type: str, row: dict[str, Any]) -> dict[str, Any]:
    item_id = clean(row.get("id"))
    project_id = clean(row.get("project_id"))
    title = clean(
        row.get("title")
        or row.get("claim_text")
        or row.get("question")
        or row.get("experiment_name")
        or row.get("original_filename")
        or row.get("canonical_name")
        or row.get("step_name")
        or evidence_type
    )
    excerpt = clean(
        row.get("abstract")
        or row.get("chunk_text")
        or row.get("content")
        or row.get("answer")
        or row.get("report_markdown")
        or row.get("digest_markdown")
        or row.get("claim_text")
        or row.get("observations")
        or row.get("observed_failure")
        or row.get("source_snippet")
    )
    source_provider = clean(row.get("source_provider") or row.get("provider") or row.get("source_type"))
    evidence_level = clean(row.get("evidence_level"))
    trust_level = clean(row.get("trust_level"))
    citation_map = row.get("citation_map") if isinstance(row.get("citation_map"), dict) else row.get("citation_map_json")
    item = {
        "evidence_id": evidence_key(evidence_type, item_id),
        "raw_id": item_id,
        "evidence_type": evidence_type,
        "project_id": project_id,
        "title": title,
        "short_excerpt": excerpt[:500],
        "source_type": clean(row.get("source_type") or row.get("created_from") or evidence_type),
        "source_provider": source_provider,
        "evidence_level": evidence_level,
        "trust_level": trust_level,
        "citation_id": clean(row.get("citation_id")),
        "citation_map": citation_map or {},
        "created_at": clean(row.get("created_at")),
        "updated_at": clean(row.get("updated_at") or row.get("created_at")),
        "status": clean(row.get("status")),
        "doi": clean(row.get("doi")),
        "url": clean(row.get("url")),
        "full_text_path": clean(row.get("full_text_path")),
        "full_text_available": row.get("full_text_available"),
        "context_status": clean(row.get("context_status")),
        "row": row,
    }
    item["friendly_evidence_label"] = friendly_evidence_label(item)
    can_support_claim, can_support_confirmed_claim, reason = evidence_support_flags(item)
    item["can_support_claim"] = can_support_claim
    item["can_support_confirmed_claim"] = can_support_confirmed_claim
    item["reason_if_not_supporting"] = "" if can_support_confirmed_claim else reason
    if project_id and item_id:
        item.update(linked_counts(conn, project_id, evidence_type, item_id))
        review = row_to_dict(conn.execute("SELECT * FROM evidence_reviews WHERE evidence_key=?", (item["evidence_id"],)).fetchone()) or {}
        item["review"] = review
    else:
        item.update({"linked_claim_count": 0, "linked_report_count": 0, "linked_memory_count": 0, "review": {}})
    return item


def list_evidence_review_items(agent_root: Path, project_id: str, filters: dict[str, Any] | None = None) -> dict[str, Any]:
    if not project_id:
        raise ValueError("project_id is required")
    filters = filters or {}
    conn = connect(agent_root)
    items: list[dict[str, Any]] = []
    for row in rows_to_dicts(conn.execute('SELECT * FROM "references" WHERE project_id=?', (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "reference", row))
    for row in rows_to_dicts(conn.execute("SELECT c.*, r.title, r.doi, r.url, r.source_provider, r.source_type, r.evidence_level, r.full_text_available, r.full_text_path FROM reference_chunks c JOIN \"references\" r ON r.id=c.reference_id WHERE c.project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "reference_chunk", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM knowledge_base_entries WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "knowledge_base_entry", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM rag_queries WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "rag_query", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM agent_memory_entries WHERE project_id=? AND memory_scope='project'", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "project_memory", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM memory_entities WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "memory_entity", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM experiment_log_entries WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "experiment_log", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM failure_logs WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "failure_log", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM retrospective_notes WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "retrospective_note", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM weekly_digest_reports WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "weekly_digest_report", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM skill_runs WHERE project_id=?", (project_id,)).fetchall()):
        payload = row.get("output_payload") if isinstance(row.get("output_payload"), dict) else {}
        if isinstance(payload, dict) and payload.get("writing_task"):
            writing_row = {**row, "title": f"Writing output: {payload.get('writing_task')}", "content": clean(payload.get("draft_text") or payload.get("draft"))}
            items.append(evidence_item_from_row(conn, "writing_output", writing_row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM claims WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "claim", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM claim_evidence WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "claim_evidence", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM research_files WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "source_file", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM protocols WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "protocol", row))
    for row in rows_to_dicts(conn.execute("SELECT * FROM data_contexts WHERE project_id=?", (project_id,)).fetchall()):
        items.append(evidence_item_from_row(conn, "data_context", row))
    conn.close()

    def matches(item: dict[str, Any]) -> bool:
        evidence_type_filter = clean(filters.get("evidence_type"))
        label_filter = clean(filters.get("label") or filters.get("friendly_evidence_label"))
        provider_filter = clean(filters.get("source_provider"))
        trust_filter = clean(filters.get("trust_level"))
        linked_filter = clean(filters.get("linked"))
        search = clean(filters.get("search") or filters.get("query")).lower()
        date_from = clean(filters.get("date_from"))
        date_to = clean(filters.get("date_to"))
        can_confirm_filter = clean(filters.get("can_support_confirmed_claim"))
        if evidence_type_filter and item["evidence_type"] != evidence_type_filter:
            return False
        if label_filter and item["friendly_evidence_label"] != label_filter:
            return False
        if provider_filter and item.get("source_provider") != provider_filter:
            return False
        if trust_filter and item.get("trust_level") != trust_filter:
            return False
        if can_confirm_filter:
            desired = can_confirm_filter.lower() in {"1", "true", "yes"}
            if bool(item.get("can_support_confirmed_claim")) != desired:
                return False
        if linked_filter == "linked" and not item.get("linked_claim_count"):
            return False
        if linked_filter == "unlinked" and item.get("linked_claim_count"):
            return False
        haystack = " ".join(clean(item.get(key)) for key in ["title", "short_excerpt", "evidence_type", "friendly_evidence_label"]).lower()
        if search and search not in haystack:
            return False
        created = clean(item.get("created_at") or item.get("updated_at"))
        if date_from and created and created < date_from:
            return False
        if date_to and created and created > date_to:
            return False
        return True

    filtered = [item for item in items if matches(item)]
    filtered.sort(key=lambda item: item.get("updated_at") or item.get("created_at") or "", reverse=True)
    return {"project_id": project_id, "evidence_items": filtered, "count": len(filtered)}


def get_evidence_item(agent_root: Path, evidence_id: str) -> dict[str, Any]:
    evidence_type, raw_id = parse_evidence_key(evidence_id)
    if not evidence_type or not raw_id:
        raise ValueError("evidence_id must use evidence_type:id")
    conn = connect(agent_root)
    row: dict[str, Any] | None = None
    if evidence_type == "reference":
        row = row_to_dict(conn.execute('SELECT * FROM "references" WHERE id=?', (raw_id,)).fetchone())
    elif evidence_type == "reference_chunk":
        row = row_to_dict(conn.execute("SELECT c.*, r.title, r.doi, r.url, r.source_provider, r.source_type, r.evidence_level, r.full_text_available, r.full_text_path FROM reference_chunks c JOIN \"references\" r ON r.id=c.reference_id WHERE c.id=?", (raw_id,)).fetchone())
    elif evidence_type == "knowledge_base_entry":
        row = row_to_dict(conn.execute("SELECT * FROM knowledge_base_entries WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "rag_query":
        row = row_to_dict(conn.execute("SELECT * FROM rag_queries WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "project_memory":
        row = row_to_dict(conn.execute("SELECT * FROM agent_memory_entries WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "memory_entity":
        row = row_to_dict(conn.execute("SELECT * FROM memory_entities WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "experiment_log":
        row = row_to_dict(conn.execute("SELECT * FROM experiment_log_entries WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "failure_log":
        row = row_to_dict(conn.execute("SELECT * FROM failure_logs WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "retrospective_note":
        row = row_to_dict(conn.execute("SELECT * FROM retrospective_notes WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "weekly_digest_report":
        row = row_to_dict(conn.execute("SELECT * FROM weekly_digest_reports WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "writing_output":
        row = row_to_dict(conn.execute("SELECT * FROM skill_runs WHERE id=?", (raw_id,)).fetchone())
        if row:
            payload = row.get("output_payload") if isinstance(row.get("output_payload"), dict) else {}
            row = {**row, "title": f"Writing output: {payload.get('writing_task', '')}", "content": clean(payload.get("draft_text") or payload.get("draft"))}
    elif evidence_type == "claim":
        row = row_to_dict(conn.execute("SELECT * FROM claims WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "claim_evidence":
        row = row_to_dict(conn.execute("SELECT * FROM claim_evidence WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "source_file":
        row = row_to_dict(conn.execute("SELECT * FROM research_files WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "protocol":
        row = row_to_dict(conn.execute("SELECT * FROM protocols WHERE id=?", (raw_id,)).fetchone())
    elif evidence_type == "data_context":
        row = row_to_dict(conn.execute("SELECT * FROM data_contexts WHERE id=?", (raw_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("evidence item not found")
    item = evidence_item_from_row(conn, evidence_type, row)
    conn.close()
    return item


def mark_evidence_reviewed(agent_root: Path, evidence_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    item = get_evidence_item(agent_root, evidence_id)
    timestamp = now()
    review = {
        "id": stable_id(item["evidence_id"], "review", length=24),
        "project_id": item["project_id"],
        "evidence_key": item["evidence_id"],
        "evidence_type": item["evidence_type"],
        "evidence_id": item["raw_id"],
        "status": clean(payload.get("status")) or "reviewed",
        "reviewed_by": clean(payload.get("reviewed_by") or payload.get("user")) or "local_user",
        "reviewed_at": timestamp,
        "notes": clean(payload.get("notes")),
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO evidence_reviews(id, project_id, evidence_key, evidence_type, evidence_id, status, reviewed_by, reviewed_at, notes, created_at, updated_at)
        VALUES (:id, :project_id, :evidence_key, :evidence_type, :evidence_id, :status, :reviewed_by, :reviewed_at, :notes, :created_at, :updated_at)
        ON CONFLICT(evidence_key) DO UPDATE SET
          status=excluded.status,
          reviewed_by=excluded.reviewed_by,
          reviewed_at=excluded.reviewed_at,
          notes=excluded.notes,
          updated_at=excluded.updated_at
        """,
        review,
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM evidence_reviews WHERE evidence_key=?", (item["evidence_id"],)).fetchone()) or {}
    conn.close()
    return {"evidence": get_evidence_item(agent_root, evidence_id), "review": saved}


def link_evidence_item_to_claim(agent_root: Path, evidence_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    claim_id = clean(payload.get("claim_id"))
    if not claim_id:
        raise ValueError("claim_id is required")
    item = get_evidence_item(agent_root, evidence_id)
    claim_evidence_type = item["evidence_type"]
    raw_id = item["raw_id"]
    linked = add_claim_evidence(
        agent_root,
        claim_id,
        {
            "evidence_type": claim_evidence_type,
            "evidence_id": raw_id,
            "source_snippet": item.get("short_excerpt"),
            "evidence_label": item.get("friendly_evidence_label"),
            "metadata": {"evidence_review_id": item["evidence_id"], "evidence_type": item["evidence_type"]},
            "confidence": payload.get("confidence") or 0.65,
        },
    )
    return {"claim_evidence": linked, "evidence": get_evidence_item(agent_root, evidence_id)}


def evidence_label_glossary() -> dict[str, str]:
    return {
        "real reference": "Imported literature metadata or full text that is intended to represent a real source.",
        "manual metadata": "User-entered reference metadata; useful for organization but requires user verification.",
        "mock placeholder": "Synthetic local validation record; never treat as peer-reviewed evidence.",
        "project memory": "Project-scoped memory created from local workflows, RAG answers, logs, reports, or user notes.",
        "experiment log": "Informal or structured lab record; useful context but not a confirmed conclusion.",
        "weak claim": "A claim requiring more evidence or human review.",
        "confirmed claim": "A claim explicitly confirmed by a human reviewer.",
        "unsupported": "A statement with no sufficient local evidence.",
        "inference": "A generated interpretation that must stay separate from evidence.",
        "needs review": "Item should be checked by a scientist before reuse.",
        "raw extracted": "Automatically extracted evidence that has not been confirmed by a human.",
        "human confirmed": "Evidence or memory explicitly confirmed by a human reviewer.",
    }


def friendly_evidence_label(item: dict[str, Any]) -> str:
    status = clean(item.get("status"))
    if status == "confirmed":
        return "confirmed claim"
    if status == "weak":
        return "weak claim"
    if status == "unsupported":
        return "unsupported"
    if status == "inference":
        return "inference"
    if status == "needs_more_evidence":
        return "needs review"
    trust_level = clean(item.get("trust_level"))
    if trust_level in {"human_confirmed", "user_confirmed", "PI_confirmed", "publication_confirmed"}:
        return "human confirmed"
    if trust_level == "raw_extracted":
        return "raw extracted"
    source_kind = clean(item.get("source_kind") or item.get("source_type") or item.get("memory_scope"))
    provider = clean(item.get("source_provider"))
    evidence_level = clean(item.get("evidence_level"))
    if evidence_level == "mock_not_evidence" or "mock" in provider.lower() or "mock" in source_kind.lower():
        return "mock placeholder"
    if provider == "manual" or "manual" in source_kind.lower():
        return "manual metadata"
    if source_kind == "project" or source_kind == "project_memory":
        return "project memory"
    if source_kind == "experiment_log":
        return "experiment log"
    if source_kind in {"inference", "generated"}:
        return "inference"
    if item.get("doi") or item.get("url") or evidence_level in {"real_reference", "peer_reviewed_metadata", "full_text", "user_uploaded_full_text"} or provider in {"crossref", "pubmed", "semantic_scholar"}:
        return "real reference"
    return "needs review"


def export_project_context(agent_root: Path, project_id: str, template: str = "agent_handoff") -> dict[str, Any]:
    if not project_id:
        raise ValueError("project_id is required")
    project = get_project_detail(agent_root, project_id)
    references = list_references(agent_root, project_id, limit=500)
    kb_entries = list_knowledge_base_entries(agent_root, project_id, limit=500)
    rag_queries = list_rag_queries(agent_root, project_id, limit=200)
    memory = list_agent_memory(agent_root, scope="project", project_id=project_id, include_disabled=True)
    experiment_logs = list_experiment_logs(agent_root, project_id, limit=200)
    failure_logs = list_failure_logs(agent_root, project_id, limit=200)
    weekly_reports = list_weekly_digest_reports(agent_root, project_id, limit=100)
    claims = list_claims(agent_root, project_id=project_id)
    reports = list_reports(agent_root, project_id=project_id)
    skill_runs = list_skill_runs(agent_root, project_id=project_id, limit=200)
    evidence_review = list_evidence_review_items(agent_root, project_id)
    conn = connect(agent_root)
    retrospectives = rows_to_dicts(conn.execute("SELECT * FROM retrospective_notes WHERE project_id=? ORDER BY updated_at DESC LIMIT 100", (project_id,)).fetchall())
    conn.close()
    parsed_tasks = [entry for entry in memory.get("project_memory", []) if entry.get("memory_type") == "parsed_research_task"]
    writing_outputs = [
        run for run in skill_runs
        if isinstance(run.get("output_payload"), dict) and run["output_payload"].get("writing_task")
    ]
    unsupported_statements = []
    for claim in claims:
        if claim.get("status") in {"draft", "weak", "unsupported"}:
            unsupported_statements.append(
                {
                    "source": "claim",
                    "claim_id": claim.get("id"),
                    "statement": claim.get("claim_text"),
                    "status": claim.get("status"),
                    "evidence_count": claim.get("evidence_count", 0),
                }
            )
    for run in writing_outputs:
        output_payload = run.get("output_payload") or {}
        for statement in as_list(output_payload.get("unsupported_statements")):
            unsupported_statements.append({"source": "writing_assistant", "skill_run_id": run["id"], "statement": statement, "status": "needs review"})
    limitations = [
        "Mock/manual references are not peer-reviewed evidence.",
        "Project memory and experiment logs are context until human-confirmed.",
        "Generated writing is draft text and must be reviewed before reuse.",
    ]
    bundle = {
        "project": project,
        "parsed_tasks": parsed_tasks,
        "keyword_mining_result": next((run.get("output_payload", {}).get("keyword_mining") for run in skill_runs if isinstance(run.get("output_payload"), dict) and run["output_payload"].get("keyword_mining")), None),
        "references": [{**ref, "friendly_evidence_label": friendly_evidence_label(ref)} for ref in references],
        "knowledge_base_entries_summary": [{"id": item.get("id"), "title": item.get("title"), "source_reference_id": item.get("source_reference_id"), "source_chunk_id": item.get("source_chunk_id")} for item in kb_entries],
        "rag_queries": rag_queries,
        "citation_maps": [{"rag_query_id": query.get("id"), "question": query.get("question"), "citation_map": query.get("citation_map")} for query in rag_queries],
        "project_memory": [{**entry, "friendly_evidence_label": friendly_evidence_label({**entry, "source_kind": "project_memory"})} for entry in memory.get("project_memory", [])],
        "experiment_logs": experiment_logs,
        "failure_logs": failure_logs,
        "retrospectives": retrospectives,
        "weekly_digest_reports": weekly_reports,
        "writing_outputs": writing_outputs,
        "claims": [{**claim, "friendly_evidence_label": friendly_evidence_label(claim)} for claim in claims],
        "evidence_review": evidence_review,
        "reports": reports,
        "unsupported_statements": unsupported_statements,
        "limitations": limitations,
        "evidence_label_glossary": evidence_label_glossary(),
        "exported_at": now(),
        "template": clean(template) or "agent_handoff",
    }
    template_key = clean(template) or "agent_handoff"
    weak_claims = [claim for claim in claims if claim.get("status") in {"draft", "weak", "unsupported", "inference", "needs_more_evidence"}]
    confirmed_claims = [claim for claim in claims if claim.get("status") == "confirmed"]
    unlinked_evidence = [item for item in evidence_review["evidence_items"] if not item.get("linked_claim_count")]
    common_header = [
        f"# Project Context Export: {project.get('title')}",
        "",
        f"- Template: `{template_key}`",
        f"- Project ID: `{project_id}`",
        f"- Exported at: `{bundle['exported_at']}`",
        f"- References: {len(references)}",
        f"- Evidence items: {evidence_review['count']}",
        f"- Claims: {len(claims)}",
        "",
    ]
    if template_key == "pi_review":
        markdown_lines = common_header + [
            "## Weak Or Confirmed Claims",
            *([f"- {claim.get('status')}: {claim.get('claim_text')}" for claim in weak_claims[:20] + confirmed_claims[:20]] or ["- No claims recorded."]),
            "",
            "## Evidence Cards",
            *[f"- {item['friendly_evidence_label']}: {item['title']} | confirmable={item['can_support_confirmed_claim']}" for item in evidence_review["evidence_items"][:30]],
            "",
            "## Unsupported Statements",
            *([f"- {item['statement']} ({item.get('status')})" for item in unsupported_statements[:20]] or ["- None recorded."]),
            "",
            "## Experiment Logs",
            *[f"- {log.get('experiment_name')}: {clean(log.get('observations'))[:180]}" for log in experiment_logs[:10]],
            "",
            "## Retrospective",
            *[f"- {note.get('title')}: {clean(note.get('report_markdown'))[:180]}" for note in retrospectives[:10]],
            "",
            "## Next Decisions Needed",
            "- Review weak/unsupported claims before project-level confirmation.",
            "- Decide which evidence cards can be linked to each claim.",
        ]
    elif template_key == "manuscript_planning":
        markdown_lines = common_header + [
            "## Introduction Points",
            *[f"- {query.get('question')}: {clean(query.get('answer'))[:220]}" for query in rag_queries[:5]],
            "",
            "## Result Narrative Candidates",
            *[f"- {claim.get('claim_text')} ({claim.get('status')})" for claim in claims[:15]],
            "",
            "## Mechanism Hypotheses",
            *[f"- {item['statement']}" for item in unsupported_statements[:10]],
            "",
            "## Limitations",
            *[f"- {item}" for item in limitations],
            "",
            "## Missing Evidence",
            *[f"- {item['title']} ({item['friendly_evidence_label']})" for item in unlinked_evidence[:20]],
            "",
            "## Target Journal Risks",
            "- Unsupported or mock-backed claims must not be used as manuscript facts.",
        ]
    elif template_key == "weekly_update":
        markdown_lines = common_header + [
            "## New References",
            *[f"- {ref.get('title')} ({friendly_evidence_label(ref)})" for ref in references[:15]],
            "",
            "## Digest",
            *[f"- {report.get('title')}: {clean(report.get('digest_markdown'))[:180]}" for report in weekly_reports[:10]],
            "",
            "## Experiment Logs",
            *[f"- {log.get('experiment_name')}: {clean(log.get('decision') or log.get('next_step'))[:180]}" for log in experiment_logs[:10]],
            "",
            "## Decisions",
            *[f"- {claim.get('claim_text')} ({claim.get('status')})" for claim in claims[:10]],
            "",
            "## Next Tasks",
            *[f"- {log.get('next_step')}" for log in experiment_logs[:10] if clean(log.get('next_step'))],
        ]
    elif template_key == "evidence_audit":
        markdown_lines = common_header + [
            "## All Claims",
            *[f"- {claim.get('status')}: {claim.get('claim_text')} | evidence={claim.get('evidence_count', 0)}" for claim in claims[:50]],
            "",
            "## Evidence Counts",
            f"- Confirmable evidence cards: {sum(1 for item in evidence_review['evidence_items'] if item.get('can_support_confirmed_claim'))}",
            f"- Mock evidence blockers: {sum(1 for item in evidence_review['evidence_items'] if item.get('friendly_evidence_label') == 'mock placeholder')}",
            f"- Unlinked evidence: {len(unlinked_evidence)}",
            "",
            "## Mock Evidence Blockers",
            *[f"- {item['title']}: {item['reason_if_not_supporting']}" for item in evidence_review["evidence_items"] if item.get("friendly_evidence_label") == "mock placeholder"],
            "",
            "## Memory Trust Levels",
            *[f"- {entry.get('trust_level')}: {entry.get('title')}" for entry in memory.get("project_memory", [])[:30]],
        ]
    else:
        markdown_lines = common_header + [
            "## Project Summary",
            clean(project.get("short_description")) or "- No summary recorded.",
            "",
            "## Current Memory",
            *[f"- {entry.get('title')} ({entry.get('trust_level')})" for entry in memory.get("project_memory", [])[:20]],
            "",
            "## Active Claims",
            *[f"- {claim.get('status')}: {claim.get('claim_text')}" for claim in claims[:20]],
            "",
            "## Open Questions",
            *[f"- {item['statement']}" for item in unsupported_statements[:20]],
            "",
            "## Available References",
            *[f"- {ref.get('title')} ({friendly_evidence_label(ref)})" for ref in references[:20]],
            "",
            "## Workflow Status",
            *[f"- {run.get('skill_name')}: {run.get('status')}" for run in skill_runs[:20]],
            "",
            "## Limitations",
            *[f"- {item}" for item in limitations],
        ]
    return {"project_id": project_id, "json": bundle, "markdown": "\n".join(markdown_lines)}


def list_tool_capabilities(agent_root: Path) -> list[dict[str, Any]]:
    conn = connect(agent_root)
    rows = rows_to_dicts(conn.execute("SELECT * FROM tool_capability_registry ORDER BY capability_name").fetchall())
    conn.close()
    return rows


def imported_skill_deduplication_report(agent_root: Path) -> dict[str, Any]:
    skills = list_skills(agent_root, include_disabled=True)
    by_id = {skill["skill_id"]: skill for skill in skills}
    overlaps = []
    for folder, builtin in DUPLICATE_CANDIDATES.items():
        skill_id = f"core_{folder.replace('-', '_')}"
        if skill_id in by_id:
            overlaps.append(
                {
                    "imported_skill_id": skill_id,
                    "imported_skill_name": by_id[skill_id]["skill_name"],
                    "overlaps_with": builtin,
                    "decision": "merged via adapter; imported skill remains active because it preserves source instructions and adds behavior.",
                    "source_path": by_id[skill_id].get("source_path", ""),
                }
            )
    return {"overlaps": overlaps, "duplicate_skills": [skill for skill in skills if skill.get("status") in {"duplicate", "deprecated"}]}


def core_skill_integration_summary(agent_root: Path) -> dict[str, Any]:
    skills = list_skills(agent_root, include_disabled=True)
    core = [skill for skill in skills if str(skill.get("skill_id", "")).startswith("core_")]
    tool_caps = list_tool_capabilities(agent_root)
    return {
        **integration_counts(),
        "core_integrated": len(core),
        "active_skills": [skill["skill_id"] for skill in core if skill.get("status") == "active"],
        "draft_skills": [skill["skill_id"] for skill in core if skill.get("status") == "draft"],
        "duplicate_or_deprecated_skills": [skill["skill_id"] for skill in core if skill.get("status") in {"duplicate", "deprecated"}],
        "browser_tool_capabilities": tool_caps,
        "excluded_scientific_registry_paths": EXCLUDED_DEPENDENCY_SKILL_PATHS,
        "browser_tool_skill_paths": BROWSER_TOOL_SKILL_PATHS,
    }


def dashboard(agent_root: Path) -> dict[str, Any]:
    conn = connect(agent_root)
    projects = rows_to_dicts(conn.execute("SELECT * FROM projects ORDER BY updated_at DESC LIMIT 8").fetchall())
    recent_files = rows_to_dicts(conn.execute("SELECT * FROM research_files ORDER BY imported_at DESC LIMIT 8").fetchall())
    recent_experiments = rows_to_dicts(conn.execute("SELECT * FROM experiments ORDER BY updated_at DESC LIMIT 8").fetchall())
    conflicts = rows_to_dicts(conn.execute("SELECT * FROM conflict_records WHERE status='unresolved' ORDER BY updated_at DESC LIMIT 8").fetchall())
    workflows = rows_to_dicts(conn.execute("SELECT * FROM workflows WHERE status IN ('draft','active') ORDER BY updated_at DESC LIMIT 8").fetchall())
    memory = rows_to_dicts(conn.execute("SELECT * FROM memory_entities ORDER BY updated_at DESC LIMIT 8").fetchall())
    counts = {}
    for key, table in {
        "projects": "projects",
        "files": "research_files",
        "memory": "memory_entities",
        "protocols": "protocols",
        "workflows": "workflows",
        "conflicts": "conflict_records",
        "reports": "reports",
    }.items():
        counts[key] = conn.execute(f"SELECT COUNT(*) AS c FROM {table}").fetchone()["c"]
    conn.close()
    return {
        "counts": counts,
        "active_projects": projects,
        "recent_files": recent_files,
        "recent_experiments": recent_experiments,
        "unresolved_conflicts": conflicts,
        "active_workflows": workflows,
        "latest_memory_updates": memory,
        "positioning": "Local-first research memory and workflow infrastructure for wet-lab research groups.",
    }


def relationship_query(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    source_type = clean(payload.get("source_type"))
    source_id = clean(payload.get("source_id"))
    target_type = clean(payload.get("target_type"))
    relation = clean(payload.get("relation"))
    project_id = clean(payload.get("project_id"))
    clauses = ["1=1"]
    params: list[Any] = []
    for column, value in [("project_id", project_id), ("source_type", source_type), ("source_id", source_id), ("target_type", target_type), ("relation", relation)]:
        if value:
            clauses.append(f"{column}=?")
            params.append(value)
    conn = connect(agent_root)
    rows = rows_to_dicts(conn.execute(f"SELECT * FROM research_links WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC", params).fetchall())
    conn.close()
    return {"relationships": rows}


def list_skills(agent_root: Path, include_disabled: bool = False) -> list[dict[str, Any]]:
    conn = connect(agent_root)
    clause = "1=1" if include_disabled else "status!='disabled'"
    rows = rows_to_dicts(conn.execute(f"SELECT * FROM skill_registry WHERE {clause} ORDER BY skill_name, version").fetchall())
    conn.close()
    return rows


def upsert_skill(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    skill_name = clean(payload.get("skill_name"))
    if not skill_name:
        raise ValueError("skill_name is required")
    version = clean(payload.get("version")) or "0.1"
    skill_id = clean(payload.get("skill_id")) or stable_id("custom", skill_name, version, length=20)
    timestamp = now()
    row = {
        "skill_id": skill_id,
        "skill_name": skill_name,
        "version": version,
        "description": clean(payload.get("description")),
        "domain": clean(payload.get("domain")),
        "skill_type": clean(payload.get("skill_type")) or "prompt",
        "source_path": clean(payload.get("source_path")),
        "applicable_domains_json": json_dumps(as_list(payload.get("applicable_domains"))),
        "input_schema_json": json_dumps(payload.get("input_schema") or {}),
        "output_schema_json": json_dumps(payload.get("output_schema") or {}),
        "required_tools_json": json_dumps(as_list(payload.get("required_tools"))),
        "required_file_types_json": json_dumps(as_list(payload.get("required_file_types"))),
        "required_models_json": json_dumps(as_list(payload.get("required_models"))),
        "example_inputs_json": json_dumps(payload.get("example_inputs") or []),
        "example_outputs_json": json_dumps(payload.get("example_outputs") or []),
        "safety_or_reliability_notes_json": json_dumps(payload.get("safety_or_reliability_notes") or []),
        "handler": clean(payload.get("handler") or payload.get("run_method")),
        "handler_ref": clean(payload.get("handler_ref") or payload.get("handler") or payload.get("run_method")),
        "prompt_template": clean(payload.get("prompt_template")),
        "instruction_body": str(payload.get("instruction_body") or ""),
        "citation_policy": clean(payload.get("citation_policy")),
        "memory_policy": clean(payload.get("memory_policy")),
        "duplicate_of_skill_id": clean(payload.get("duplicate_of_skill_id")),
        "migration_notes": clean(payload.get("migration_notes")),
        "status": clean(payload.get("status")) or "enabled",
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO skill_registry(
          skill_id, skill_name, version, description, domain, skill_type, source_path, applicable_domains_json,
          input_schema_json, output_schema_json, required_tools_json, required_file_types_json, required_models_json,
          example_inputs_json, example_outputs_json, safety_or_reliability_notes_json, handler, handler_ref,
          prompt_template, instruction_body, citation_policy, memory_policy, duplicate_of_skill_id, migration_notes,
          status, created_at, updated_at
        )
        VALUES (
          :skill_id, :skill_name, :version, :description, :domain, :skill_type, :source_path, :applicable_domains_json,
          :input_schema_json, :output_schema_json, :required_tools_json, :required_file_types_json, :required_models_json,
          :example_inputs_json, :example_outputs_json, :safety_or_reliability_notes_json, :handler, :handler_ref,
          :prompt_template, :instruction_body, :citation_policy, :memory_policy, :duplicate_of_skill_id, :migration_notes,
          :status, :created_at, :updated_at
        )
        ON CONFLICT(skill_id) DO UPDATE SET
          description=excluded.description,
          domain=excluded.domain,
          skill_type=excluded.skill_type,
          source_path=excluded.source_path,
          applicable_domains_json=excluded.applicable_domains_json,
          input_schema_json=excluded.input_schema_json,
          output_schema_json=excluded.output_schema_json,
          required_tools_json=excluded.required_tools_json,
          required_file_types_json=excluded.required_file_types_json,
          required_models_json=excluded.required_models_json,
          example_inputs_json=excluded.example_inputs_json,
          example_outputs_json=excluded.example_outputs_json,
          safety_or_reliability_notes_json=excluded.safety_or_reliability_notes_json,
          handler=excluded.handler,
          handler_ref=excluded.handler_ref,
          prompt_template=excluded.prompt_template,
          instruction_body=excluded.instruction_body,
          citation_policy=excluded.citation_policy,
          memory_policy=excluded.memory_policy,
          duplicate_of_skill_id=excluded.duplicate_of_skill_id,
          migration_notes=excluded.migration_notes,
          status=excluded.status,
          updated_at=excluded.updated_at
        """,
        row,
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM skill_registry WHERE skill_id=?", (skill_id,)).fetchone()) or {}
    conn.close()
    return saved


def update_skill_status(agent_root: Path, skill_id: str, status: str) -> dict[str, Any]:
    if status not in {"enabled", "active", "disabled", "draft", "duplicate", "deprecated", "broken"}:
        raise ValueError("unsupported skill status")
    conn = connect(agent_root)
    conn.execute("UPDATE skill_registry SET status=?, updated_at=? WHERE skill_id=?", (status, now(), skill_id))
    row = conn.execute("SELECT * FROM skill_registry WHERE skill_id=?", (skill_id,)).fetchone()
    if not row:
        conn.close()
        raise KeyError("skill not found")
    conn.commit()
    conn.close()
    return row_to_dict(row) or {}


def normalize_object_refs(refs: Any) -> list[dict[str, str]]:
    normalized = []
    for ref in as_list(refs):
        if isinstance(ref, dict):
            ref_type = clean(ref.get("type") or ref.get("object_type") or ref.get("source_type"))
            ref_id = clean(ref.get("id") or ref.get("object_id") or ref.get("source_id"))
        else:
            continue
        if ref_type and ref_id:
            normalized.append({"type": ref_type, "id": ref_id})
    return normalized


def infer_input_object_refs(payload: dict[str, Any]) -> list[dict[str, str]]:
    candidates = [
        ("file", payload.get("file_id") or payload.get("source_file_id")),
        ("protocol", payload.get("protocol_id")),
        ("report", payload.get("report_id")),
        ("data_context", payload.get("data_context_id")),
        ("workflow_step", payload.get("workflow_step_id")),
        ("workflow", payload.get("workflow_id")),
        ("memory_entity", payload.get("memory_entity_id")),
    ]
    refs = [{"type": ref_type, "id": clean(ref_id)} for ref_type, ref_id in candidates if clean(ref_id)]
    refs.extend(normalize_object_refs(payload.get("input_object_refs")))
    unique = []
    seen = set()
    for ref in refs:
        key = (ref["type"], ref["id"])
        if key not in seen:
            unique.append(ref)
            seen.add(key)
    return unique


def add_skill_run_links(conn: sqlite3.Connection, project_id: str, skill_run_id: str, relation: str, refs: list[dict[str, str]]) -> None:
    if not project_id:
        return
    for ref in refs:
        ref_type = clean(ref.get("type"))
        ref_id = clean(ref.get("id"))
        if ref_type and ref_id:
            create_link(conn, project_id, "skill_run", skill_run_id, relation, ref_type, ref_id, 1)


def execution_memory_id_for_skill_run(skill_run_id: str) -> str:
    return stable_id("execution_memory", skill_run_id, length=24)


def upsert_execution_memory_for_skill_run(
    conn: sqlite3.Connection,
    *,
    skill_run: dict[str, Any],
    input_payload: dict[str, Any],
    output_payload: dict[str, Any] | None = None,
    output_object_refs: list[dict[str, str]] | None = None,
    status: str = "running",
) -> dict[str, Any]:
    timestamp = now()
    skill_run_id = clean(skill_run.get("id"))
    memory_id = execution_memory_id_for_skill_run(skill_run_id)
    error_message = clean((output_payload or {}).get("error")) if isinstance(output_payload, dict) else ""
    output_lesson = (output_payload or {}).get("reusable_lesson") if isinstance(output_payload, dict) else ""
    reusable_lesson = clean(input_payload.get("reusable_lesson") or output_lesson)
    should_promote = 1 if input_payload.get("should_promote_to_skill") or reusable_lesson else 0
    row = {
        "id": memory_id,
        "project_id": clean(skill_run.get("project_id")),
        "task_type": clean(input_payload.get("task_type")) or "skill_run",
        "task_title": clean(input_payload.get("task_title") or skill_run.get("skill_name")),
        "user_intent": clean(input_payload.get("user_intent") or input_payload.get("intent") or input_payload.get("question") or input_payload.get("query")),
        "input_object_refs_json": json_dumps(normalize_object_refs(skill_run.get("input_object_refs"))),
        "output_object_refs_json": json_dumps(output_object_refs or normalize_object_refs(skill_run.get("output_object_refs"))),
        "skill_id": clean(skill_run.get("skill_id")),
        "skill_run_id": skill_run_id,
        "workflow_id": clean(skill_run.get("workflow_id")),
        "workflow_step_id": clean(skill_run.get("workflow_step_id")),
        "status": status,
        "error_message": error_message,
        "reusable_lesson": reusable_lesson,
        "should_promote_to_skill": should_promote,
        "promoted_skill_id": clean((output_payload or {}).get("promoted_skill_id")) if isinstance(output_payload, dict) else "",
        "created_at": clean(skill_run.get("created_at")) or timestamp,
        "updated_at": timestamp,
    }
    conn.execute(
        """
        INSERT INTO execution_memory(
          id, project_id, task_type, task_title, user_intent, input_object_refs_json, output_object_refs_json,
          skill_id, skill_run_id, workflow_id, workflow_step_id, status, error_message, reusable_lesson,
          should_promote_to_skill, promoted_skill_id, created_at, updated_at
        )
        VALUES (
          :id, :project_id, :task_type, :task_title, :user_intent, :input_object_refs_json, :output_object_refs_json,
          :skill_id, :skill_run_id, :workflow_id, :workflow_step_id, :status, :error_message, :reusable_lesson,
          :should_promote_to_skill, :promoted_skill_id, :created_at, :updated_at
        )
        ON CONFLICT(id) DO UPDATE SET
          output_object_refs_json=excluded.output_object_refs_json,
          status=excluded.status,
          error_message=excluded.error_message,
          reusable_lesson=COALESCE(NULLIF(excluded.reusable_lesson,''), execution_memory.reusable_lesson),
          should_promote_to_skill=MAX(execution_memory.should_promote_to_skill, excluded.should_promote_to_skill),
          promoted_skill_id=COALESCE(NULLIF(excluded.promoted_skill_id,''), execution_memory.promoted_skill_id),
          updated_at=excluded.updated_at
        """,
        row,
    )
    return row


def update_skill_run(
    agent_root: Path,
    skill_run_id: str,
    *,
    status: str,
    output_payload: dict[str, Any] | None = None,
    output_object_refs: list[dict[str, str]] | None = None,
    logs: list[str] | None = None,
    provenance: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    if status not in SKILL_RUN_STATUSES:
        raise ValueError("unsupported skill run status")
    conn = connect(agent_root)
    row = row_to_dict(conn.execute("SELECT * FROM skill_runs WHERE id=?", (skill_run_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("skill run not found")
    merged_logs = as_list(row.get("logs")) + (logs or [])
    merged_output_refs = output_object_refs if output_object_refs is not None else normalize_object_refs(row.get("output_object_refs"))
    conn.execute(
        """
        UPDATE skill_runs
        SET status=?, output_payload_json=?, output_object_refs_json=?, logs_json=?, provenance_json=?, updated_at=?
        WHERE id=?
        """,
        (
            status,
            json_dumps(output_payload or row.get("output_payload") or {}),
            json_dumps(merged_output_refs or []),
            json_dumps(merged_logs),
            json_dumps(provenance or row.get("provenance") or []),
            now(),
            skill_run_id,
        ),
    )
    add_skill_run_links(conn, clean(row.get("project_id")), skill_run_id, "generated", merged_output_refs or [])
    upsert_execution_memory_for_skill_run(
        conn,
        skill_run={**row, "output_object_refs": merged_output_refs},
        input_payload=row.get("input_payload") or {},
        output_payload=output_payload or row.get("output_payload") or {},
        output_object_refs=merged_output_refs or [],
        status=status,
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM skill_runs WHERE id=?", (skill_run_id,)).fetchone()) or {}
    conn.close()
    if status in {"completed", "failed"}:
        artifacts_from_object_refs(agent_root, clean(row.get("project_id")), skill_run_id, merged_output_refs or [])
    return saved


def update_skill_run_prompt_metadata(agent_root: Path, skill_run_id: str, runtime_prompt: dict[str, Any]) -> None:
    skill_run_id = clean(skill_run_id)
    if not skill_run_id:
        return
    conn = connect(agent_root)
    row = row_to_dict(conn.execute("SELECT * FROM skill_runs WHERE id=?", (skill_run_id,)).fetchone())
    if not row:
        conn.close()
        return
    provenance = as_list(row.get("provenance"))
    provenance.append(
        {
            "type": "prompt_router",
            "task_type": runtime_prompt.get("task_type"),
            "skill_prompt_source": runtime_prompt.get("skill_prompt_source"),
            "resolved_skill_name": runtime_prompt.get("resolved_skill_name"),
            "citation_policy": runtime_prompt.get("citation_policy"),
            "memory_policy": runtime_prompt.get("memory_policy"),
            "warnings": runtime_prompt.get("warnings", []),
        }
    )
    conn.execute(
        """
        UPDATE skill_runs
        SET prompt_language=?, prompt_policy=?, prompt_files_json=?, provenance_json=?, updated_at=?
        WHERE id=?
        """,
        (
            runtime_prompt.get("prompt_language") or row.get("prompt_language"),
            runtime_prompt.get("prompt_policy") or row.get("prompt_policy"),
            json_dumps(runtime_prompt.get("prompt_files") or row.get("prompt_files") or []),
            json_dumps(provenance),
            now(),
            skill_run_id,
        ),
    )
    conn.commit()
    conn.close()


def preferred_skill_name_for_task(task_type: str) -> str:
    if task_type == "protocol_extraction":
        return "PaperToProtocolSkill"
    for skill_name, mapped_task in prompt_router.SKILL_TASK_MAP.items():
        if mapped_task == task_type:
            return skill_name
    for skill_name, mapped_task in prompt_router.CORE_SKILL_TASK_MAP.items():
        if mapped_task == task_type:
            return skill_name
    return ""


def simulate_prompt_routing(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    conn = connect(agent_root)
    task_type = clean(payload.get("task_type")) or prompt_router.infer_task_type(
        user_message=clean(payload.get("user_message") or payload.get("message") or payload.get("text")),
        file_context=payload.get("file_context") if isinstance(payload.get("file_context"), dict) else {},
        workflow_step=payload.get("workflow_step") if isinstance(payload.get("workflow_step"), dict) else {},
        skill_name=clean(payload.get("skill_name")),
        agent_type=clean(payload.get("agent_type")),
        file_category=clean(payload.get("file_category")),
    )
    skill_name = clean(payload.get("skill_name")) or preferred_skill_name_for_task(task_type)
    runtime_prompt = prompt_router.compose_runtime_prompt(
        conn,
        language=clean(payload.get("prompt_language")) or "zh",
        policy=clean(payload.get("prompt_policy")) or None,
        user_message=clean(payload.get("user_message") or payload.get("message") or payload.get("text")),
        task_type=task_type,
        skill_name=skill_name,
        skill_id=clean(payload.get("skill_id")),
        agent_type=clean(payload.get("agent_type")),
        workflow_step=payload.get("workflow_step") if isinstance(payload.get("workflow_step"), dict) else {},
        workflow_step_id=clean(payload.get("workflow_step_id")),
        file_context=payload.get("file_context") if isinstance(payload.get("file_context"), dict) else {},
        file_id=clean(payload.get("file_id")),
        file_category=clean(payload.get("file_category")),
        project_id=clean(payload.get("project_id")),
        prompt_context=payload.get("prompt_context") if isinstance(payload.get("prompt_context"), dict) else {},
        output_schema=payload.get("output_schema") if isinstance(payload.get("output_schema"), dict) else {},
    )
    conn.close()
    return {
        "task_type": runtime_prompt["task_type"],
        "resolved_skill_name": runtime_prompt["resolved_skill_name"] or skill_name,
        "prompt_policy": runtime_prompt["prompt_policy"],
        "prompt_language": runtime_prompt["prompt_language"],
        "prompt_files": runtime_prompt["prompt_files"],
        "skill_prompt_source": runtime_prompt["skill_prompt_source"],
        "system_prompt_preview": runtime_prompt["system_prompt"][:1000],
        "citation_policy": runtime_prompt["citation_policy"],
        "memory_policy": runtime_prompt["memory_policy"],
        "warnings": runtime_prompt.get("warnings", []),
    }


def default_prompt_language(payload: dict[str, Any]) -> str:
    language = clean(payload.get("prompt_language") or payload.get("language") or os.environ.get("RESEARCHOS_PROMPT_LANGUAGE") or "zh").lower()
    return "zh" if language.startswith("zh") else "en"


def prompt_policy_for_skill(skill: dict[str, Any], payload: dict[str, Any]) -> str:
    explicit = clean(payload.get("prompt_policy"))
    if explicit:
        return prompt_router.resolve_prompt_policy(explicit)
    task_type = prompt_router.infer_task_type(
        user_message=clean(payload.get("user_message") or payload.get("message") or payload.get("objective") or payload.get("text")),
        file_context={"task_type": payload.get("task_type")},
        skill_name=clean(skill.get("skill_name") or skill.get("handler") or skill.get("handler_ref") or skill.get("skill_id")),
        agent_type=clean(payload.get("agent_type")),
        file_category=clean(payload.get("file_category") or payload.get("category")),
    )
    return prompt_router.resolve_prompt_policy(task_type, skill_name=clean(skill.get("skill_name") or skill.get("handler")))


def create_skill_run_record(
    agent_root: Path,
    skill: dict[str, Any],
    project_id: str,
    input_payload: dict[str, Any],
    input_object_refs: list[dict[str, str]],
    workflow_id: str = "",
    workflow_step_id: str = "",
) -> dict[str, Any]:
    timestamp = datetime.now().isoformat(timespec="microseconds")
    run_id = stable_id(skill["skill_id"], project_id, json_dumps(input_payload), timestamp, length=24)
    prompt_language = default_prompt_language(input_payload)
    conn = connect(agent_root)
    runtime_prompt = prompt_router.compose_runtime_prompt(
        conn,
        language=prompt_language,
        policy=clean(input_payload.get("prompt_policy")) or None,
        user_message=clean(input_payload.get("user_message") or input_payload.get("message") or input_payload.get("objective") or input_payload.get("text")),
        task_type=clean(input_payload.get("task_type")),
        skill_name=clean(skill.get("skill_name") or skill.get("handler")),
        skill_id=clean(skill.get("skill_id")),
        agent_type=clean(input_payload.get("agent_type")),
        workflow_step_id=clean(workflow_step_id or input_payload.get("workflow_step_id")),
        file_id=clean(input_payload.get("file_id") or input_payload.get("source_file_id")),
        file_category=clean(input_payload.get("file_category") or input_payload.get("category")),
        project_id=project_id,
        prompt_context=input_payload.get("prompt_context") if isinstance(input_payload.get("prompt_context"), dict) else {},
    )
    prompt_policy = runtime_prompt["prompt_policy"]
    prompt_files = runtime_prompt.get("prompt_files", [])
    prompt_provenance = {
        "type": "prompt_router",
        "task_type": runtime_prompt.get("task_type"),
        "skill_prompt_source": runtime_prompt.get("skill_prompt_source"),
        "resolved_skill_name": runtime_prompt.get("resolved_skill_name"),
        "citation_policy": runtime_prompt.get("citation_policy"),
        "memory_policy": runtime_prompt.get("memory_policy"),
        "warnings": runtime_prompt.get("warnings", []),
    }
    row = {
        "id": run_id,
        "skill_id": skill["skill_id"],
        "skill_name": skill["skill_name"],
        "project_id": project_id,
        "workflow_id": clean(workflow_id or input_payload.get("workflow_id")),
        "workflow_step_id": clean(workflow_step_id or input_payload.get("workflow_step_id")),
        "input_object_refs_json": json_dumps(input_object_refs),
        "output_object_refs_json": json_dumps([]),
        "input_payload_json": json_dumps(input_payload),
        "output_payload_json": json_dumps({}),
        "status": "running",
        "logs_json": json_dumps([f"Skill run {skill['skill_name']} started at {timestamp}"]),
        "provenance_json": json_dumps([prompt_provenance]),
        "prompt_language": prompt_language,
        "prompt_policy": prompt_policy,
        "prompt_files_json": json_dumps(prompt_files),
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn.execute(
        """
        INSERT INTO skill_runs(
          id, skill_id, skill_name, project_id, workflow_id, workflow_step_id,
          input_object_refs_json, output_object_refs_json, input_payload_json, output_payload_json,
          status, logs_json, provenance_json, prompt_language, prompt_policy, prompt_files_json, created_at, updated_at
        )
        VALUES (
          :id, :skill_id, :skill_name, :project_id, :workflow_id, :workflow_step_id,
          :input_object_refs_json, :output_object_refs_json, :input_payload_json, :output_payload_json,
          :status, :logs_json, :provenance_json, :prompt_language, :prompt_policy, :prompt_files_json, :created_at, :updated_at
        )
        """,
        row,
    )
    add_skill_run_links(conn, project_id, run_id, "used", input_object_refs)
    upsert_execution_memory_for_skill_run(conn, skill_run=row, input_payload=input_payload, status="running")
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM skill_runs WHERE id=?", (run_id,)).fetchone()) or {}
    conn.close()
    return saved


def extract_seed_keywords(text: str, limit: int = 12) -> list[str]:
    stopwords = {
        "with",
        "from",
        "that",
        "this",
        "were",
        "was",
        "are",
        "and",
        "for",
        "the",
        "into",
        "using",
        "study",
        "results",
        "methods",
        "abstract",
        "conclusion",
    }
    tokens = [token.lower() for token in re.findall(r"[A-Za-z][A-Za-z0-9-]{2,}", text)]
    counts: dict[str, int] = {}
    for token in tokens:
        if token not in stopwords:
            counts[token] = counts.get(token, 0) + 1
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [token for token, _count in ranked[:limit]]


def create_experiment_matrix(payload: dict[str, Any]) -> dict[str, Any]:
    groups = [clean(item) for item in as_list(payload.get("groups") or payload.get("conditions")) if clean(item)] or ["Control", "Model", "Treatment"]
    doses = [clean(item) for item in as_list(payload.get("doses")) if clean(item)] or ["0", "low", "high"]
    timepoints = [clean(item) for item in as_list(payload.get("timepoints")) if clean(item)] or ["baseline", "endpoint"]
    replicates = int(payload.get("replicates") or 3)
    rows = []
    sample_index = 1
    for group in groups:
        for dose in doses[: max(1, len(doses))]:
            for timepoint in timepoints:
                for replicate in range(1, replicates + 1):
                    rows.append(
                        {
                            "sample_id": f"S{sample_index:03d}",
                            "group": group,
                            "dose": dose,
                            "timepoint": timepoint,
                            "replicate": replicate,
                        }
                    )
                    sample_index += 1
    return {
        "objective": clean(payload.get("objective")) or "Controlled experiment matrix",
        "sample_table": rows,
        "controls": as_list(payload.get("controls")) or ["vehicle/negative control", "positive control if applicable"],
        "qc_rules": ["Randomize processing order when possible.", "Record batch, operator, instrument, and raw file names.", "Do not claim significance without replicate-level statistics."],
    }


def simple_peer_review(payload: dict[str, Any]) -> dict[str, Any]:
    text = clean(payload.get("manuscript_text") or payload.get("claim_text") or payload.get("text"))
    lower = text.lower()
    risks = []
    if "significant" in lower and not re.search(r"\bp\s?[<=>]\s?0\.\d+", lower):
        risks.append("Statistical significance is claimed without an explicit p value or confidence interval.")
    if "mechanism" in lower and not any(term in lower for term in ["inhibitor", "knockdown", "rescue", "pathway"]):
        risks.append("Mechanistic language may need direct validation.")
    if "novel" in lower and not any(term in lower for term in ["compared", "prior", "literature", "baseline"]):
        risks.append("Novelty claim needs clearer comparison against prior work.")
    return {
        "mode": clean(payload.get("review_mode")) or "general",
        "risk_flags": risks or ["No obvious high-risk claim was detected by the rule-based reviewer."],
        "required_evidence": ["sample size", "replicate definition", "statistical method", "controls", "source data links"],
        "reviewer_summary": "Draft review is conservative and should be checked by a domain expert.",
    }


def simple_result_narrative(payload: dict[str, Any]) -> dict[str, Any]:
    summary = clean(payload.get("data_summary") or payload.get("summary") or payload.get("claim_text"))
    experiment_type = clean(payload.get("experiment_type")) or "experiment"
    paragraph = f"The {experiment_type} results were summarized from the provided evidence."
    if summary:
        paragraph += f" The current supported observation is: {summary}"
    paragraph += " Interpretive strength remains limited until replicate-level statistics and provenance are confirmed."
    return {
        "result_paragraph": paragraph,
        "figure_legend": f"Figure X. Evidence-linked summary of {experiment_type} results.",
        "unsupported_claims_to_avoid": ["Do not claim statistical significance without statistics.", "Do not claim mechanism without mechanism-specific validation."],
    }


def _artifact_markdown_from_output(title: str, result: dict[str, Any]) -> str:
    body = json_dumps(result)
    if len(body) > 4000:
        body = body[:4000] + "...[truncated]"
    return f"# {title}\n\n```json\n{body}\n```"


def _core_output_artifact_spec(folder: str, result: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
    mapping = {
        "weekly-research-digest": ("weekly_digest", "Weekly literature digest"),
        "browser-research-learning": ("learning_summary", "Browser literature learning summary"),
        "build-user-research-kb": ("learning_summary", "Research KB learning summary"),
        "protocol-extraction": ("protocol", "Protocol extraction result"),
        "sop-generation": ("sop", "SOP generation result"),
        "parse-scientific-data": ("data_analysis_result", "Parsed scientific data result"),
        "analyze-experiment-results": ("data_analysis_result", "Data analysis result"),
        "design-experiment-matrix": ("experiment_plan", "Experiment plan"),
        "plan-research-route": ("experiment_plan", "Research route plan"),
        "peer-review-simulation": ("manuscript_review_summary", "Manuscript review summary"),
        "failure-log": ("failure_summary", "Failure summary"),
    }
    if folder not in mapping:
        return {}
    artifact_type, default_title = mapping[folder]
    title = clean(payload.get("title")) or default_title
    claims = as_list(result.get("claims"))
    confirmed_analysis = artifact_type == "data_analysis_result" and any(clean(claim.get("status")) == "confirmed" for claim in claims if isinstance(claim, dict))
    create_candidate = artifact_type != "data_analysis_result" or confirmed_analysis
    evidence_level = "user_confirmed" if confirmed_analysis else clean(payload.get("evidence_level")) or "agent_generated_needs_review"
    return {
        "artifact_type": artifact_type,
        "title": title,
        "content_markdown": _artifact_markdown_from_output(title, result),
        "content_json": result,
        "status": "pending_confirmation" if artifact_type in LONG_TERM_ARTIFACT_MEMORY_TYPES else "draft",
        "evidence_level": evidence_level,
        "create_memory_candidate": create_candidate,
    }


def _register_core_output_artifact(agent_root: Path, folder: str, project_id: str, run_id: str, result: dict[str, Any], output_refs: list[dict[str, str]], payload: dict[str, Any]) -> dict[str, Any]:
    if not project_id:
        return {}
    spec = _core_output_artifact_spec(folder, result, payload)
    if not spec:
        return {}
    artifact = create_artifact(
        agent_root,
        {
            "project_id": project_id,
            "skill_run_id": run_id,
            "artifact_type": spec["artifact_type"],
            "title": spec["title"],
            "content_markdown": spec["content_markdown"],
            "content_json": spec["content_json"],
            "status": spec["status"],
            "source_type": "skill_run",
            "source_id": run_id,
            "source_refs": _dedupe_source_refs(output_refs + [{"type": "skill_run", "id": run_id}]),
            "evidence_level": spec["evidence_level"],
            "create_memory_candidate": spec["create_memory_candidate"],
        },
    )
    output_refs.append({"type": "artifact", "id": artifact["artifact_id"]})
    return artifact


def run_imported_core_skill_adapter(agent_root: Path, folder: str, skill: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    run_id = clean(payload.get("skill_run_id"))
    output_refs: list[dict[str, str]] = []
    result: dict[str, Any] = {"adapter": folder, "source_path": skill.get("source_path")}

    if folder == "keyword-research-harvest":
        provider = clean(payload.get("provider")) or "all"
        if provider in {"mock", "manual", "browser", "browser/manual"}:
            task_result = create_literature_search_task(agent_root, {**payload, "provider": provider})
            kb = build_project_research_kb(agent_root, {"project_id": project_id, "skill_run_id": run_id})
            result.update({"literature_search": task_result, "knowledge_base": kb})
            output_refs.append({"type": "literature_search_task", "id": task_result["task"]["id"]})
            output_refs.extend({"type": "reference", "id": ref["id"]} for ref in task_result.get("references", []))
        else:
            task_result = start_keyword_harvest_task(agent_root, {**payload, "provider": provider})
            result.update({"literature_search": task_result, "progress": task_result.get("progress", {})})
            output_refs.append({"type": "literature_search_task", "id": task_result["task"]["id"]})
            return {"mode": "adapter", "output": result, "output_refs": output_refs, "defer_completion": bool(task_result.get("background_started", True))}
    elif folder == "browser-research-learning":
        task_result = create_literature_search_task(agent_root, {**payload, "provider": payload.get("provider") or "browser/manual"})
        result.update({"browser_learning_plan": {"provider": "authorized local browser or manual notes", "status": "mock_ready"}, "literature_search": task_result})
        output_refs.append({"type": "literature_search_task", "id": task_result["task"]["id"]})
    elif folder == "compliant-literature-access":
        access_plan = {
            "priority": ["local licensed access", "open access", "publisher/Crossref TDM links", "manual metadata-only record"],
            "guardrails": ["No paywall bypass.", "No credential leakage.", "No redistribution of unauthorized full text."],
        }
        references = []
        if payload.get("title") or payload.get("doi"):
            references.append(import_reference(agent_root, {**payload, "title": clean(payload.get("title")) or clean(payload.get("doi")), "source_type": "compliant_metadata", "access_status": clean(payload.get("access_status")) or "metadata_only"}))
        result.update({"access_plan": access_plan, "references": references})
        output_refs.extend({"type": "reference", "id": ref["id"]} for ref in references)
    elif folder == "extract-first-article-keywords":
        text = clean(payload.get("article_text") or payload.get("abstract") or payload.get("text"))
        reference_id = clean(payload.get("reference_id"))
        if reference_id:
            analysis = analyze_references_with_article_keyword_skill(
                agent_root,
                {
                    "project_id": project_id,
                    "reference_ids": [reference_id],
                    "skill_run_id": run_id,
                    "keyword_limit": int(payload.get("limit") or 12),
                },
            )
            result.update({"article_keyword_analysis": analysis})
            output_refs.extend(analysis.get("output_refs", []))
        else:
            keywords = extract_seed_keywords(text, int(payload.get("limit") or 12))
            result.update({"seed_keywords": keywords, "expanded_queries": [f"{kw} methods" for kw in keywords[:6]]})
        if reference_id:
            output_refs.append({"type": "reference", "id": reference_id})
    elif folder == "ingest-research-evidence":
        references = []
        ref_payload = payload.get("reference") if isinstance(payload.get("reference"), dict) else {}
        if ref_payload or payload.get("title") or payload.get("evidence_text"):
            references.append(
                import_reference(
                    agent_root,
                    {
                        **ref_payload,
                        "project_id": project_id,
                        "title": clean(ref_payload.get("title") if isinstance(ref_payload, dict) else "") or clean(payload.get("title")) or "Manual research evidence",
                        "abstract": clean(ref_payload.get("abstract") if isinstance(ref_payload, dict) else "") or clean(payload.get("evidence_text") or payload.get("text")),
                        "source_type": clean(payload.get("source_type")) or "manual_evidence",
                        "skill_run_id": run_id,
                    },
                )
            )
        kb = build_project_research_kb(agent_root, {"project_id": project_id, "reference_ids": [ref["id"] for ref in references], "skill_run_id": run_id}) if references else {"knowledge_base_entries": []}
        claims = []
        if clean(payload.get("claim_text")):
            claim = create_claim(agent_root, {"project_id": project_id, "claim_text": payload["claim_text"], "claim_type": payload.get("claim_type") or "conclusion", "status": "weak", "skill_run_id": run_id})
            claims.append(claim)
            if references:
                link_claim_reference(agent_root, {"project_id": project_id, "claim_id": claim["id"], "reference_id": references[0]["id"], "citation_number": 1})
        result.update({"references": references, "knowledge_base": kb, "claims": claims})
        output_refs.extend({"type": "reference", "id": ref["id"]} for ref in references)
        output_refs.extend({"type": "claim", "id": claim["id"]} for claim in claims)
    elif folder == "build-user-research-kb":
        reference_ids = [clean(item) for item in as_list(payload.get("reference_ids")) if clean(item)]
        article_analysis = analyze_references_with_article_keyword_skill(
            agent_root,
            {
                "project_id": project_id,
                "reference_ids": reference_ids,
                "skill_run_id": run_id,
                "keyword_limit": int(payload.get("keyword_limit") or 12),
            },
        )
        kb = build_project_research_kb(agent_root, {**payload, "reference_ids": reference_ids, "skill_run_id": run_id})
        result.update({"article_keyword_analysis": article_analysis, "knowledge_base": kb, **kb})
        output_refs.extend(article_analysis.get("output_refs", [])[:100])
        output_refs.extend({"type": "knowledge_base_entry", "id": item["id"]} for item in kb.get("knowledge_base_entries", [])[:20])
    elif folder == "weekly-research-digest":
        if payload.get("keywords"):
            task_result = create_literature_search_task(agent_root, {**payload, "provider": payload.get("provider") or "mock"})
            output_refs.append({"type": "literature_search_task", "id": task_result["task"]["id"]})
        kb = build_project_research_kb(agent_root, {"project_id": project_id, "skill_run_id": run_id})
        question = clean(payload.get("question")) or "What recent literature evidence matters this week?"
        rag = query_research_rag(agent_root, {"project_id": project_id, "question": question, "skill_run_id": run_id})
        memory = create_agent_memory_entry(
            agent_root,
            {
                "memory_scope": "project",
                "project_id": project_id,
                "memory_type": "weekly_literature_digest",
                "title": "Weekly literature digest",
                "content": rag["answer"],
                "source_type": "skill_run",
                "source_id": run_id,
                "provenance": [{"type": "rag_query", "id": rag["query_id"]}],
            },
        )
        result.update({"knowledge_base": kb, "rag": rag, "memory": memory})
        output_refs.extend([{"type": "rag_query", "id": rag["query_id"]}, {"type": "agent_memory", "id": memory["id"]}])
    elif folder == "manage-agent-memory":
        memory = create_agent_memory_entry(
            agent_root,
            {
                **payload,
                "memory_scope": clean(payload.get("memory_scope") or payload.get("scope")) or ("project" if project_id else "system"),
                "project_id": project_id,
                "title": clean(payload.get("title")) or "Skill memory update",
                "content": clean(payload.get("content") or payload.get("note") or "Memory update from imported skill."),
                "source_type": clean(payload.get("source_type")) or "skill_run",
                "source_id": clean(payload.get("source_id")) or run_id,
            },
        )
        result.update({"memory": memory, "isolation": {"system": memory["memory_scope"] == "system", "project_id": memory.get("project_id")}})
        output_refs.append({"type": "agent_memory", "id": memory["id"]})
    elif folder == "failure-log":
        failure = create_failure_log(agent_root, {**payload, "title": clean(payload.get("title")) or "Imported failure log entry", "skill_run_id": run_id})
        result.update({"failure_log": failure, "matched_failures": list_failure_logs(agent_root, project_id, search=failure.get("observed_failure", ""), limit=5)})
        output_refs.append({"type": "failure_log", "id": failure["id"]})
    elif folder == "diagnose-research-bottleneck":
        report = generate_report(agent_root, {**payload, "project_id": project_id, "report_type": "project_gap_analysis", "skill_run_id": run_id})
        failures = list_failure_logs(agent_root, project_id, limit=10)
        result.update({"diagnosis_report": report, "failure_logs": failures})
        output_refs.append({"type": "report", "id": report["id"]})
        output_refs.extend({"type": "claim", "id": claim["id"]} for claim in report.get("generated_claims", []))
    elif folder == "weekly-research-report":
        report = generate_report(agent_root, {**payload, "project_id": project_id, "report_type": payload.get("report_type") or "weekly_report", "skill_run_id": run_id})
        result.update({"report": report})
        output_refs.append({"type": "report", "id": report["id"]})
        output_refs.extend({"type": "claim", "id": claim["id"]} for claim in report.get("generated_claims", []))
    elif folder == "extract-domain-entities":
        file_id = clean(payload.get("file_id") or payload.get("source_file_id"))
        if not file_id:
            file_record = register_file(agent_root, {"project_id": project_id, "filename": clean(payload.get("filename")) or "domain_entities.txt", "content": clean(payload.get("text") or payload.get("content")), "category": payload.get("category") or "experiment log"})
            file_id = file_record["id"]
        extraction = run_extraction(agent_root, {"file_id": file_id, "skill_run_id": run_id})
        result.update(extraction)
        output_refs.append({"type": "file", "id": file_id})
        output_refs.extend({"type": "memory_entity", "id": entity["id"]} for entity in extraction.get("entities", []))
    elif folder == "parse-scientific-data":
        file_id = clean(payload.get("file_id") or payload.get("source_file_id"))
        if not file_id:
            content = clean(payload.get("csv_text") or payload.get("text"))
            filename = clean(payload.get("file_name") or payload.get("filename")) or "scientific_data.csv"
            file_record = register_file(agent_root, {"project_id": project_id, "filename": filename, "content": content, "category": payload.get("category") or "Excel spreadsheet"})
            file_id = file_record["id"]
        extraction = run_extraction(agent_root, {"file_id": file_id, "skill_run_id": run_id})
        file_record = read_file_record(agent_root, file_id)
        result.update({"file": file_record, "extraction": extraction})
        output_refs.append({"type": "file", "id": file_id})
        if file_record.get("data_context"):
            output_refs.append({"type": "data_context", "id": file_record["data_context"]["id"]})
    elif folder == "analyze-experiment-results":
        analysis = {"summary": clean(payload.get("data_summary") or payload.get("summary")) or "Result analysis completed in conservative rule mode.", "recommended_next_action": clean(payload.get("next_action")) or "repeat or validate before strong claims"}
        claims = []
        if project_id and analysis["summary"]:
            claim = create_claim(agent_root, {"project_id": project_id, "claim_text": analysis["summary"], "claim_type": "result", "status": "weak", "confidence": 0.55, "skill_run_id": run_id})
            claims.append(claim)
        result.update({"analysis": analysis, "claims": claims})
        output_refs.extend({"type": "claim", "id": claim["id"]} for claim in claims)
    elif folder == "result-narrative":
        narrative = simple_result_narrative(payload)
        claims = []
        if project_id and clean(payload.get("data_summary")):
            claims.append(create_claim(agent_root, {"project_id": project_id, "claim_text": payload["data_summary"], "claim_type": "result", "status": "weak", "confidence": 0.55, "skill_run_id": run_id}))
        result.update({"narrative": narrative, "claims": claims})
        output_refs.extend({"type": "claim", "id": claim["id"]} for claim in claims)
    elif folder == "peer-review-simulation":
        review = simple_peer_review(payload)
        result.update({"review": review})
    elif folder == "design-experiment-matrix":
        matrix = create_experiment_matrix(payload)
        result.update({"experiment_matrix": matrix})
    elif folder == "plan-research-route":
        template = clean(payload.get("template_key")) or "project_diagnosis_and_peer_review"
        workflow = create_workflow(agent_root, {"project_id": project_id, "template_key": template})
        result.update({"route": {"topic": clean(payload.get("topic") or payload.get("objective")), "template_key": template}, "workflow": workflow})
        output_refs.append({"type": "workflow", "id": workflow["id"]})
    elif folder == "protocol-extraction":
        text = clean(payload.get("paper_text") or payload.get("methods_text") or payload.get("text"))
        parsed = parse_protocol_text(agent_root, {**payload, "project_id": project_id, "text": text or "Protocol source text was not provided.", "skill_run_id": run_id})
        protocol = store_protocol(agent_root, {**parsed["protocol"], "skill_run_id": run_id})
        result.update({"protocol": protocol, "llm_adapter": parsed.get("llm_adapter")})
        output_refs.append({"type": "protocol", "id": protocol["id"]})
    elif folder == "sop-generation":
        protocol_id = clean(payload.get("protocol_id"))
        if not protocol_id:
            text = clean(payload.get("paper_text") or payload.get("methods_text") or payload.get("text") or payload.get("experiment_goal"))
            parsed = parse_protocol_text(agent_root, {**payload, "project_id": project_id, "text": text or "SOP source text was not provided.", "skill_run_id": run_id})
            protocol = store_protocol(agent_root, {**parsed["protocol"], "skill_run_id": run_id})
            protocol_id = protocol["id"]
            output_refs.append({"type": "protocol", "id": protocol_id})
        package = generate_execution_package(agent_root, {"protocol_id": protocol_id, "skill_run_id": run_id})
        result.update({"execution_package": package})
        output_refs.append({"type": "protocol_execution_package", "id": package["id"]})
    elif folder == "research-agent-runtime":
        result.update({"runtime_status": {"skill_run_id": run_id, "project_id": project_id, "workflow_id": clean(payload.get("workflow_id"))}, "execution_memory_id": execution_memory_id_for_skill_run(run_id)})
    elif folder.startswith("nature-"):
        input_summary = {
            "has_text": bool(clean(payload.get("text") or payload.get("manuscript_text") or payload.get("paper_text") or payload.get("claim_text"))),
            "has_file": bool(clean(payload.get("file_id") or payload.get("file_path") or payload.get("paper_pdf") or payload.get("data_file"))),
            "project_id": project_id,
        }
        result.update(
            {
                "nature_skill": {
                    "skill_id": folder,
                    "source_path": skill.get("source_path"),
                    "status": "loaded",
                    "input_summary": input_summary,
                    "execution_policy": "ResearchOS loaded the Nature skill instructions through SkillRun. Artifact generation is delegated to the selected skill workflow and available local tools.",
                }
            }
        )
    else:
        result.update({"plan": "Imported prompt/workflow skill executed with generic adapter.", "input_payload": payload})

    artifact = _register_core_output_artifact(agent_root, folder, project_id, run_id, result, output_refs, payload)
    if artifact:
        result["artifact"] = artifact
    return {"mode": "adapter", "output": result, "output_refs": output_refs}


def run_skill(agent_root: Path, skill_id: str, project_id: str = "", input_payload: dict[str, Any] | None = None, input_object_refs: list[dict[str, str]] | None = None) -> dict[str, Any]:
    payload = dict(input_payload or {})
    conn = connect(agent_root)
    skill = row_to_dict(conn.execute("SELECT * FROM skill_registry WHERE skill_id=?", (skill_id,)).fetchone())
    conn.close()
    if not skill:
        raise KeyError("skill not found")
    project_id = clean(project_id or payload.get("project_id"))
    refs = normalize_object_refs(input_object_refs or payload.get("input_object_refs")) or infer_input_object_refs(payload)
    skill_run = create_skill_run_record(
        agent_root,
        skill,
        project_id,
        payload,
        refs,
        workflow_id=clean(payload.get("workflow_id")),
        workflow_step_id=clean(payload.get("workflow_step_id")),
    )
    run_id = skill_run["id"]
    handler = skill.get("handler") or skill.get("skill_name")
    output_refs: list[dict[str, str]] = []
    output: dict[str, Any] = {"skill_id": skill_id, "skill_run_id": run_id, "handler": handler, "mode": "mock", "confidence": 0.75}
    logs = [f"Handler resolved to {handler}."]
    provenance = [{"type": "skill_registry", "id": skill_id}]
    try:
        payload_with_run = {**payload, "project_id": project_id, "skill_run_id": run_id}
        defer_completion = False
        if str(handler).startswith("core_skill:"):
            folder = str(handler).split(":", 1)[1]
            adapter_result = run_imported_core_skill_adapter(agent_root, folder, skill, payload_with_run)
            output.update({"mode": adapter_result.get("mode", "adapter"), "output": adapter_result.get("output", {})})
            output_refs.extend(adapter_result.get("output_refs", []))
            defer_completion = bool(adapter_result.get("defer_completion"))
        elif handler == "ReagentCalculationSkill":
            output.update({"mode": "rule", "output": run_reagent_calculator(payload)})
        elif handler == "PlateLayoutSkill":
            output.update(
                {
                    "mode": "rule",
                    "output": {
                        "plate_layout": generate_plate_layout(
                            [str(v) for v in as_list(payload.get("groups"))] or ["Control", "Treatment"],
                            int(payload.get("replicates") or 3),
                        )
                    },
                }
            )
        elif handler == "DataNamingConventionSkill":
            if payload.get("protocol_id"):
                protocol = get_protocol(agent_root, clean(payload["protocol_id"]))
                project = get_project_detail(agent_root, protocol["project_id"])
                pattern = generate_naming_convention(project["title"], protocol)
                refs.append({"type": "protocol", "id": protocol["id"]})
            else:
                pattern = "PROJECT_EXPERIMENT_SAMPLE_GROUP_DOSE_TIMEPOINT_ASSAY_DATE_VERSION"
            output.update({"mode": "rule", "output": {"pattern": pattern}})
        elif handler == "KitManualParserSkill":
            kit_payload = {**payload_with_run}
            if not clean(kit_payload.get("content")) and clean(payload.get("text_or_table")):
                kit_payload["content"] = clean(payload["text_or_table"])
            kit = parse_kit_template(agent_root, kit_payload)
            output.update({"mode": "rule", "output": {"kit_template": kit}})
            output_refs.append({"type": "kit_template", "id": kit["id"]})
            if kit.get("source_file_id"):
                refs.append({"type": "file", "id": kit["source_file_id"]})
        elif handler == "PaperToProtocolSkill":
            text = clean(payload.get("text") or payload.get("methods_text") or payload.get("text_or_table"))
            parsed = parse_protocol_text(agent_root, {**payload_with_run, "text": text or "Protocol source text was not provided."})
            protocol_payload = {**parsed["protocol"], "skill_run_id": run_id}
            protocol = store_protocol(agent_root, protocol_payload)
            output.update({"mode": parsed.get("llm_adapter", {}).get("mode", "rule+mock"), "output": {"protocol": protocol, "llm_adapter": parsed.get("llm_adapter")}})
            output_refs.append({"type": "protocol", "id": protocol["id"]})
        elif handler == "WeeklyReportSkill":
            report = generate_report(agent_root, {**payload_with_run, "report_type": payload.get("report_type") or "weekly_report"})
            output.update({"mode": "rule", "output": {"report": report}})
            output_refs.append({"type": "report", "id": report["id"]})
            for claim in report.get("generated_claims") or []:
                output_refs.append({"type": "claim", "id": claim["id"]})
        elif handler == "ProjectGapAnalysisSkill":
            report = generate_report(agent_root, {**payload_with_run, "report_type": "project_gap_analysis"})
            output.update({"mode": "rule", "output": {"report": report}})
            output_refs.append({"type": "report", "id": report["id"]})
            for claim in report.get("generated_claims") or []:
                output_refs.append({"type": "claim", "id": claim["id"]})
        elif handler == "ConflictDetectionSkill":
            conflicts = detect_conflicts(agent_root, project_id)
            output.update({"mode": "rule", "output": {"conflicts": conflicts}})
            output_refs.extend({"type": "conflict_record", "id": conflict["id"]} for conflict in conflicts)
        elif handler == "MemoryUpdateSkill":
            conn = connect(agent_root)
            entity = insert_memory_entity(
                conn,
                project_id=project_id,
                source_file_id=clean(payload.get("source_file_id") or payload.get("file_id")) or None,
                entity_type=clean(payload.get("entity_type")) or "conclusion",
                canonical_name=clean(payload.get("canonical_name") or payload.get("content") or payload.get("claim_text") or "Skill-generated memory update"),
                source_text_snippet=clean(payload.get("source_text_snippet") or payload.get("content")),
                confidence=float(payload.get("confidence") or 0.6),
                extracted_by="MemoryUpdateSkill",
                workflow_id=clean(payload.get("workflow_id")),
                skill_run_id=run_id,
                metadata={"skill_run_id": run_id, "workflow_step_id": clean(payload.get("workflow_step_id"))},
            )
            if payload.get("workflow_step_id"):
                create_link(conn, project_id, "workflow_step", clean(payload["workflow_step_id"]), "generated_memory", "memory_entity", entity["id"], 1)
            create_link(conn, project_id, "skill_run", run_id, "generated", "memory_entity", entity["id"], 1)
            conn.commit()
            conn.close()
            output.update({"mode": "partial", "output": {"memory_entity": entity}})
            output_refs.append({"type": "memory_entity", "id": entity["id"]})
        elif handler == "promoted_execution_memory":
            output.update({"mode": "draft", "output": {"message": "Promoted draft skill executed in mock mode.", "input_payload": payload}})
        else:
            output["output"] = {"message": "Example run completed with mock handler. Add a concrete handler to execute domain-specific logic."}
        if defer_completion:
            update_skill_run(agent_root, run_id, status="running", output_payload=output, output_object_refs=output_refs, logs=logs + ["Skill run delegated to background execution."], provenance=provenance)
        else:
            update_skill_run(agent_root, run_id, status="completed", output_payload=output, output_object_refs=output_refs, logs=logs, provenance=provenance)
    except Exception as exc:
        output = {"skill_id": skill_id, "skill_run_id": run_id, "handler": handler, "error": str(exc)}
        update_skill_run(agent_root, run_id, status="failed", output_payload=output, output_object_refs=output_refs, logs=logs + [str(exc)], provenance=provenance)
        raise
    saved = get_skill_run(agent_root, run_id)
    return {"skill_run_id": run_id, "skill_run": saved, **output}


def run_skill_example(agent_root: Path, skill_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    return run_skill(agent_root, skill_id, project_id=clean(payload.get("project_id")), input_payload=payload, input_object_refs=normalize_object_refs(payload.get("input_object_refs")))


def list_skill_runs(agent_root: Path, project_id: str = "", skill_id: str = "", status: str = "", limit: int = 50) -> list[dict[str, Any]]:
    clauses = ["1=1"]
    params: list[Any] = []
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    if skill_id:
        clauses.append("skill_id=?")
        params.append(skill_id)
    if status:
        clauses.append("status=?")
        params.append(status)
    params.append(int(limit or 50))
    conn = connect(agent_root)
    rows = rows_to_dicts(conn.execute(f"SELECT * FROM skill_runs WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC LIMIT ?", params).fetchall())
    conn.close()
    return rows


def get_skill_run(agent_root: Path, skill_run_id: str) -> dict[str, Any]:
    conn = connect(agent_root)
    row = row_to_dict(conn.execute("SELECT * FROM skill_runs WHERE id=?", (skill_run_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("skill run not found")
    links = rows_to_dicts(conn.execute("SELECT * FROM research_links WHERE source_type='skill_run' AND source_id=? ORDER BY updated_at DESC", (skill_run_id,)).fetchall())
    row["links"] = links
    conn.close()
    return row


