def promote_execution_memory_to_skill_draft(agent_root: Path, execution_memory_id: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    payload = payload or {}
    conn = connect(agent_root)
    memory = row_to_dict(conn.execute("SELECT * FROM execution_memory WHERE id=?", (execution_memory_id,)).fetchone())
    conn.close()
    if not memory:
        raise KeyError("execution memory not found")
    draft_name = clean(payload.get("skill_name") or f"Draft from {memory.get('task_title') or execution_memory_id}")
    draft = upsert_skill(
        agent_root,
        {
            "skill_id": clean(payload.get("skill_id")) or f"draft_{stable_id(execution_memory_id, draft_name, length=18)}",
            "skill_name": draft_name,
            "version": clean(payload.get("version")) or "0.1-draft",
            "description": clean(payload.get("description") or memory.get("reusable_lesson") or memory.get("user_intent") or "Draft skill promoted from execution memory."),
            "domain": clean(payload.get("domain")) or "promoted_execution_memory",
            "skill_type": clean(payload.get("skill_type")) or "workflow",
            "source_path": f"execution_memory:{execution_memory_id}",
            "input_schema": {"project_id": "string optional", "input_payload": "object"},
            "output_schema": {"draft_output": "object"},
            "required_tools": ["SkillRun", "ExecutionMemory"],
            "required_file_types": [],
            "required_models": ["mock LLM adapter optional"],
            "handler": "promoted_execution_memory",
            "handler_ref": "promoted_execution_memory",
            "instruction_body": clean(payload.get("instruction_body"))
            or f"Reusable lesson: {memory.get('reusable_lesson') or memory.get('user_intent') or memory.get('task_title')}",
            "citation_policy": "Preserve the source execution memory id and any object refs when reusing this draft.",
            "memory_policy": "Draft was promoted from execution memory; review before making active.",
            "migration_notes": f"Promoted from execution_memory {execution_memory_id}.",
            "status": "draft",
        },
    )
    conn = connect(agent_root)
    conn.execute(
        "UPDATE execution_memory SET should_promote_to_skill=1, promoted_skill_id=?, updated_at=? WHERE id=?",
        (draft["skill_id"], now(), execution_memory_id),
    )
    conn.commit()
    conn.close()
    return {"execution_memory": {**memory, "promoted_skill_id": draft["skill_id"], "should_promote_to_skill": 1}, "skill": draft}


def list_agent_memory(agent_root: Path, scope: str = "", project_id: str = "", include_disabled: bool = False) -> dict[str, Any]:
    clauses = ["1=1"]
    params: list[Any] = []
    if scope:
        clauses.append("memory_scope=?")
        params.append(scope)
    if project_id:
        clauses.append("project_id=?")
        params.append(project_id)
    if not include_disabled:
        clauses.append("status='active'")
    conn = connect(agent_root)
    entries = rows_to_dicts(conn.execute(f"SELECT * FROM agent_memory_entries WHERE {' AND '.join(clauses)} ORDER BY updated_at DESC", params).fetchall())
    conn.close()
    return {
        "system_memory": [entry for entry in entries if entry.get("memory_scope") == "system"],
        "project_memory": [entry for entry in entries if entry.get("memory_scope") == "project"],
        "entries": entries,
    }


def list_memory_backend_registry(agent_root: Path, memory_class: str = "") -> list[dict[str, Any]]:
    conn = connect(agent_root)
    try:
        bootstrap_memory_backend_registry(conn)
        clauses = ["status='active'"]
        params: list[Any] = []
        if clean(memory_class):
            clauses.append("memory_class=?")
            params.append(clean(memory_class))
        return rows_to_dicts(
            conn.execute(
                f"SELECT * FROM memory_backend_registry WHERE {' AND '.join(clauses)} ORDER BY source_of_truth DESC, memory_class, backend_name",
                params,
            ).fetchall()
        )
    finally:
        conn.close()


def _optional_memory_backend_files(agent_root: Path) -> dict[str, dict[str, Any]]:
    root = Path(agent_root)
    return {
        "agent_memory.sqlite": {"path": str(root / "agent_memory.sqlite"), "exists": (root / "agent_memory.sqlite").exists(), "required_for_answers": False},
        "lab_agent_mvp.sqlite": {"path": str(root / "lab_agent_mvp.sqlite"), "exists": (root / "lab_agent_mvp.sqlite").exists(), "required_for_answers": False},
        "manage-agent-memory folder": {"path": str(WORKSPACE_ROOT / "manage-agent-memory"), "exists": (WORKSPACE_ROOT / "manage-agent-memory").exists(), "required_for_answers": False},
        "backend/researchos/brain": {"path": str(REPO_ROOT / "backend" / "researchos" / "brain"), "exists": (REPO_ROOT / "backend" / "researchos" / "brain").exists(), "required_for_answers": False},
    }


def get_memory_source_of_truth_health(agent_root: Path, project_id: str = "", *, write_probe: bool = True) -> dict[str, Any]:
    project_id = clean(project_id)
    registry = list_memory_backend_registry(agent_root)
    primary_classes = {
        "projects",
        "tasks",
        "chat",
        "agent_memory_entries",
        "references",
        "reference_chunks",
        "knowledge_base_entries",
    }
    primary_rows = [
        row
        for row in registry
        if row.get("memory_class") in primary_classes
        and clean(row.get("backend_name")) == PRIMARY_MEMORY_BACKEND
        and int(row.get("source_of_truth") or 0) == 1
    ]
    optional_backends = _optional_memory_backend_files(Path(agent_root))
    checks: dict[str, Any] = {
        "registry_declared": {"ok": len(primary_rows) == len(primary_classes), "primary_classes": sorted(row.get("memory_class") for row in primary_rows)},
        "derived_missing_does_not_block": {
            "ok": True,
            "optional_backends": optional_backends,
            "missing_optional": [name for name, item in optional_backends.items() if not item.get("exists")],
        },
        "main_context_retrieval": {"ok": False, "probe": "", "context_item_count": 0},
        "primary_priority": {"ok": False, "derived_context_items": []},
    }
    probe_id = ""
    probe_content = ""
    try:
        if project_id and write_probe:
            probe_id = stable_id("memory_source_truth_probe", project_id, now(), length=24)
            probe_content = f"MEMORY_SOURCE_OF_TRUTH_HEALTH_PROBE {probe_id}"
            timestamp = now()
            conn = connect(agent_root)
            try:
                conn.execute(
                    """
                    INSERT INTO agent_memory_entries(
                      id, memory_scope, project_id, memory_type, title, content, structured_content_json,
                      source_type, source_id, provenance_json, confidence, trust_level, status, created_at, updated_at
                    )
                    VALUES (?, 'project', ?, 'health_probe', 'Memory source of truth health probe', ?, '{}',
                            'memory_source_of_truth_health', ?, '[]', 1.0, 'system', 'active', ?, ?)
                    """,
                    (probe_id, project_id, probe_content, probe_id, timestamp, timestamp),
                )
                conn.commit()
            finally:
                conn.close()
        context = (
            research_context_compiler.compile_research_context(
                agent_root,
                {
                    "project_id": project_id,
                    "user_message": probe_content or "memory source of truth health",
                    "intent": "research_advice",
                    "max_tokens": 6000,
                },
            )
            if project_id
            else {"compiled_context": "", "context_items": []}
        )
        context_items = [item for item in as_list(context.get("context_items")) if isinstance(item, dict)]
        rendered = clean(context.get("compiled_context"))
        if probe_content:
            checks["main_context_retrieval"] = {
                "ok": probe_content in rendered or any(probe_content in clean(item.get("content")) for item in context_items),
                "probe": probe_id,
                "context_item_count": len(context_items),
            }
        else:
            checks["main_context_retrieval"] = {"ok": bool(context_items), "probe": "", "context_item_count": len(context_items)}
        derived_items = [
            {
                "source_type": clean(item.get("source_type")),
                "source_id": clean(item.get("source_id")),
                "source_of_truth": clean((item.get("metadata") or {}).get("source_of_truth")) if isinstance(item.get("metadata"), dict) else "",
                "source_role": clean((item.get("metadata") or {}).get("source_role")) if isinstance(item.get("metadata"), dict) else "",
            }
            for item in context_items
            if isinstance(item.get("metadata"), dict) and clean(item.get("metadata", {}).get("source_role")) == "derived"
        ]
        checks["primary_priority"] = {"ok": not derived_items, "derived_context_items": derived_items}
    finally:
        if probe_id:
            conn = connect(agent_root)
            try:
                conn.execute("DELETE FROM agent_memory_entries WHERE id=? AND source_type='memory_source_of_truth_health'", (probe_id,))
                conn.commit()
            finally:
                conn.close()
    ok = all(bool(item.get("ok")) for item in checks.values())
    return {
        "status": "ok" if ok else "degraded",
        "primary_backend": PRIMARY_MEMORY_BACKEND,
        "registry": registry,
        "checks": checks,
    }


def create_agent_memory_entry(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    scope = clean(payload.get("memory_scope") or payload.get("scope")) or "project"
    project_id = clean(payload.get("project_id"))
    if scope == "system":
        project_id = ""
    elif not project_id:
        raise ValueError("project_id is required for project-level agent memory")
    title = clean(payload.get("title"))
    if not title:
        raise ValueError("title is required")
    timestamp = now()
    entry_id = clean(payload.get("id")) or stable_id(scope, project_id, payload.get("memory_type"), title, timestamp, length=24)
    row = {
        "id": entry_id,
        "memory_scope": scope,
        "project_id": project_id,
        "memory_type": clean(payload.get("memory_type")) or "note",
        "title": title,
        "content": clean(payload.get("content")),
        "structured_content_json": json_dumps(payload.get("structured_content") or {}),
        "source_type": clean(payload.get("source_type")) or "manual",
        "source_id": clean(payload.get("source_id")),
        "provenance_json": json_dumps(payload.get("provenance") or []),
        "confidence": float(payload.get("confidence") or 0.8),
        "trust_level": clean(payload.get("trust_level")) or ("system" if scope == "system" else "raw_extracted"),
        "status": clean(payload.get("status")) or "active",
        "created_at": timestamp,
        "updated_at": timestamp,
    }
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO agent_memory_entries(
          id, memory_scope, project_id, memory_type, title, content, structured_content_json,
          source_type, source_id, provenance_json, confidence, trust_level, status, created_at, updated_at
        )
        VALUES (
          :id, :memory_scope, :project_id, :memory_type, :title, :content, :structured_content_json,
          :source_type, :source_id, :provenance_json, :confidence, :trust_level, :status, :created_at, :updated_at
        )
        ON CONFLICT(id) DO UPDATE SET
          content=excluded.content,
          structured_content_json=excluded.structured_content_json,
          status=excluded.status,
          updated_at=excluded.updated_at
        """,
        row,
    )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM agent_memory_entries WHERE id=?", (entry_id,)).fetchone()) or {}
    conn.close()
    canonical_memory.sync_agent_memory_entry(agent_root, saved)
    return saved


def update_agent_memory_entry(agent_root: Path, entry_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    allowed = {"title", "content", "structured_content_json", "confidence", "trust_level", "status"}
    assignments: list[str] = []
    values: list[Any] = []
    for key, value in payload.items():
        column = "structured_content_json" if key == "structured_content" else key
        if column not in allowed:
            continue
        assignments.append(f"{column}=?")
        values.append(json_dumps(value) if column.endswith("_json") else value)
    if not assignments:
        raise ValueError("no supported memory fields to update")
    assignments.append("updated_at=?")
    values.extend([now(), entry_id])
    conn = connect(agent_root)
    conn.execute(f"UPDATE agent_memory_entries SET {', '.join(assignments)} WHERE id=?", values)
    row = conn.execute("SELECT * FROM agent_memory_entries WHERE id=?", (entry_id,)).fetchone()
    if not row:
        conn.close()
        raise KeyError("agent memory entry not found")
    conn.commit()
    conn.close()
    saved = row_to_dict(row) or {}
    canonical_memory.sync_agent_memory_entry(agent_root, saved)
    return saved


def parse_kit_template(agent_root: Path, payload: dict[str, Any]) -> dict[str, Any]:
    project_id = clean(payload.get("project_id"))
    source_file_id = clean(payload.get("source_file_id"))
    text = clean(payload.get("text") or payload.get("content"))
    filename = clean(payload.get("filename")) or "kit_template.txt"
    if not source_file_id:
        if not project_id:
            raise ValueError("project_id is required when source_file_id is not provided")
        file_record = register_file(
            agent_root,
            {
                "project_id": project_id,
                "filename": filename,
                "content": text,
                "category": payload.get("category") or "protocol",
                "tags": ["kit_template"],
            },
        )
        source_file_id = file_record["id"]
        text = file_record.get("extracted_text") or text
    else:
        file_record = read_file_record(agent_root, source_file_id)
        project_id = file_record["project_id"]
        text = file_record.get("extracted_text") or text
        filename = file_record["original_filename"]
    assay_type = clean(payload.get("assay_type")) or classify_file(filename, text).replace(" data", "").replace("Excel spreadsheet", "template")
    parsed = {
        "name": clean(payload.get("name")) or Path(filename).stem,
        "vendor": clean(payload.get("vendor")) or first_or_blank(re.findall(r"\b(?:vendor|manufacturer)[:\s]+([A-Za-z0-9 _.-]+)", text, re.IGNORECASE)),
        "kit_type": clean(payload.get("kit_type")) or ("kit manual" if "kit" in text.lower() or "manual" in filename.lower() else "template"),
        "assay_type": assay_type,
        "parsed_reagents": sorted(set(re.findall(r"\b(?:standard|substrate|stop solution|wash buffer|assay buffer|enzyme conjugate|primer|master mix|antibody|reagent [A-Za-z0-9_-]+)\b", text, re.IGNORECASE))),
        "parsed_steps": deterministic_protocol_steps(text, assay_type)[:8],
        "parsed_calculations": sorted(set(re.findall(r"\b(?:standard curve|4PL|linear regression|Ct|delta Ct|fold change|concentration)\b", text, re.IGNORECASE))),
        "parsed_plate_layout": infer_plate_layout_rules(text),
        "parsed_qc_rules": infer_kit_qc_rules(text),
        "parsed_output_schema": infer_output_schema(text),
        "confidence": 0.78 if text else 0.45,
    }
    template_id = clean(payload.get("id")) or stable_id(project_id, source_file_id, parsed["name"], parsed["assay_type"], length=24)
    skill_run_id = clean(payload.get("skill_run_id"))
    timestamp = now()
    conn = connect(agent_root)
    conn.execute(
        """
        INSERT INTO kit_templates(
          id, project_id, lab_scope, name, vendor, kit_type, assay_type, source_file_id, parsed_reagents_json,
          parsed_steps_json, parsed_calculations_json, parsed_plate_layout_json, parsed_qc_rules_json,
          parsed_output_schema_json, confidence, confirmed_by_user, skill_run_id, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          name=excluded.name,
          vendor=excluded.vendor,
          kit_type=excluded.kit_type,
          assay_type=excluded.assay_type,
          parsed_reagents_json=excluded.parsed_reagents_json,
          parsed_steps_json=excluded.parsed_steps_json,
          parsed_calculations_json=excluded.parsed_calculations_json,
          parsed_plate_layout_json=excluded.parsed_plate_layout_json,
          parsed_qc_rules_json=excluded.parsed_qc_rules_json,
          parsed_output_schema_json=excluded.parsed_output_schema_json,
          confidence=excluded.confidence,
          skill_run_id=COALESCE(NULLIF(excluded.skill_run_id,''), kit_templates.skill_run_id),
          updated_at=excluded.updated_at
        """,
        (
            template_id,
            project_id,
            clean(payload.get("lab_scope")) or "project",
            parsed["name"],
            parsed["vendor"],
            parsed["kit_type"],
            parsed["assay_type"],
            source_file_id,
            json_dumps(parsed["parsed_reagents"]),
            json_dumps(parsed["parsed_steps"]),
            json_dumps(parsed["parsed_calculations"]),
            json_dumps(parsed["parsed_plate_layout"]),
            json_dumps(parsed["parsed_qc_rules"]),
            json_dumps(parsed["parsed_output_schema"]),
            parsed["confidence"],
            1 if payload.get("confirmed_by_user") else 0,
            skill_run_id,
            timestamp,
            timestamp,
        ),
    )
    create_link(conn, project_id, "kit_template", template_id, "learned_from_file", "file", source_file_id, 1)
    if skill_run_id:
        create_link(conn, project_id, "skill_run", skill_run_id, "generated", "kit_template", template_id, 1)
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM kit_templates WHERE id=?", (template_id,)).fetchone()) or {}
    conn.close()
    return saved


def infer_plate_layout_rules(text: str) -> dict[str, Any]:
    lower = text.lower()
    wells = 96 if "96" in lower or "plate" in lower else 0
    return {
        "plate_format": f"{wells}-well" if wells else "not detected",
        "replicates": "duplicate or triplicate recommended" if any(term in lower for term in ["duplicate", "triplicate", "replicate"]) else "not detected",
        "blank_required": "blank" in lower,
        "standard_curve_required": "standard curve" in lower or "standards" in lower,
    }


def infer_kit_qc_rules(text: str) -> list[str]:
    rules = []
    lower = text.lower()
    if "standard curve" in lower:
        rules.append("Review standard curve fit before interpreting concentrations.")
    if "blank" in lower:
        rules.append("Subtract or account for blank wells according to kit manual.")
    if "wavelength" in lower or "450" in lower:
        rules.append("Confirm detection wavelength before plate-reader run.")
    if "duplicate" in lower or "triplicate" in lower:
        rules.append("Check replicate CV before reporting results.")
    return rules or ["Confirm kit-specific QC rules with the source manual."]


def infer_output_schema(text: str) -> list[dict[str, str]]:
    columns = []
    for col in re.findall(r"\b(?:sample_id|well|group|condition|dose|timepoint|OD450|Ct|concentration|fold_change|p_value|feature_id|mz|retention_time)\b", text, re.IGNORECASE):
        columns.append({"column": col, "meaning": "parsed from kit/template text"})
    return columns or [{"column": "sample_id", "meaning": "sample identifier"}, {"column": "value", "meaning": "measured output"}]


def find_relevant_kit_templates(agent_root: Path, project_id: str, assay_type: str) -> list[dict[str, Any]]:
    if not project_id:
        return []
    conn = connect(agent_root)
    rows = rows_to_dicts(
        conn.execute(
            """
            SELECT * FROM kit_templates
            WHERE project_id=? AND confirmed_by_user=1 AND (?='' OR assay_type LIKE ?)
            ORDER BY updated_at DESC
            LIMIT 5
            """,
            (project_id, assay_type, f"%{assay_type}%"),
        ).fetchall()
    )
    conn.close()
    return rows


