def update_kit_template(agent_root: Path, template_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    allowed = {
        "name",
        "vendor",
        "kit_type",
        "assay_type",
        "parsed_reagents_json",
        "parsed_steps_json",
        "parsed_calculations_json",
        "parsed_plate_layout_json",
        "parsed_qc_rules_json",
        "parsed_output_schema_json",
        "confidence",
        "confirmed_by_user",
    }
    assignments: list[str] = []
    values: list[Any] = []
    for key, value in payload.items():
        column = f"{key}_json" if f"{key}_json" in allowed else key
        if column not in allowed:
            continue
        assignments.append(f"{column}=?")
        if column.endswith("_json"):
            values.append(json_dumps(value))
        elif column == "confirmed_by_user":
            values.append(1 if value else 0)
        else:
            values.append(value)
    if not assignments:
        raise ValueError("no supported kit template fields to update")
    assignments.append("updated_at=?")
    values.extend([now(), template_id])
    conn = connect(agent_root)
    conn.execute(f"UPDATE kit_templates SET {', '.join(assignments)} WHERE id=?", values)
    row = conn.execute("SELECT * FROM kit_templates WHERE id=?", (template_id,)).fetchone()
    if not row:
        conn.close()
        raise KeyError("kit template not found")
    conn.commit()
    conn.close()
    return row_to_dict(row) or {}


