def update_data_context(agent_root: Path, context_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    allowed = {
        "experiment_id",
        "experiment_name",
        "sample_source",
        "treatment_group",
        "batch",
        "assay_type",
        "instrument",
        "protocol_id",
        "operator",
        "experiment_date",
        "file_version",
        "raw_processed_status",
        "related_samples",
        "related_figures",
        "related_conclusions",
        "related_reports",
    }
    conn = connect(agent_root)
    row = row_to_dict(conn.execute("SELECT * FROM data_contexts WHERE id=?", (context_id,)).fetchone())
    if not row:
        conn.close()
        raise KeyError("data context not found")
    updated = dict(row)
    for key, value in payload.items():
        if key in allowed:
            updated[key] = value
    if not clean(updated.get("experiment_id")) and clean(updated.get("experiment_name")):
        updated["experiment_id"] = stable_id(updated["project_id"], updated["experiment_name"], updated.get("assay_type"), length=20)
    for key in ["related_samples", "related_figures", "related_conclusions", "related_reports"]:
        updated[key] = as_list(updated.get(key))
    apply_context_validation(updated)
    timestamp = now()
    conn.execute(
        """
        UPDATE data_contexts SET
          experiment_id=?, sample_source=?, treatment_group=?, batch=?, assay_type=?, instrument=?, protocol_id=?,
          operator=?, experiment_date=?, file_version=?, raw_processed_status=?,
          related_samples_json=?, related_figures_json=?, related_conclusions_json=?, related_reports_json=?,
          context_status=?, missing_metadata_json=?, confidence=?, updated_at=?
        WHERE id=?
        """,
        (
            clean(updated.get("experiment_id")),
            clean(updated.get("sample_source")),
            clean(updated.get("treatment_group")),
            clean(updated.get("batch")),
            clean(updated.get("assay_type")),
            clean(updated.get("instrument")),
            clean(updated.get("protocol_id")),
            clean(updated.get("operator")),
            clean(updated.get("experiment_date")),
            clean(updated.get("file_version")) or "v1",
            clean(updated.get("raw_processed_status")) or "raw",
            json_dumps(updated.get("related_samples") or []),
            json_dumps(updated.get("related_figures") or []),
            json_dumps(updated.get("related_conclusions") or []),
            json_dumps(updated.get("related_reports") or []),
            updated["context_status"],
            json_dumps(updated["missing_metadata"]),
            float(updated["confidence"]),
            timestamp,
            context_id,
        ),
    )
    conn.execute(
        """
        UPDATE research_files SET
          experiment_id=?, sample_source=?, treatment_group=?, batch=?, assay_type=?, instrument=?, protocol_id=?,
          operator=?, experiment_date=?, file_version=?, raw_processed_status=?, context_status=?, updated_at=?
        WHERE id=?
        """,
        (
            clean(updated.get("experiment_id")),
            clean(updated.get("sample_source")),
            clean(updated.get("treatment_group")),
            clean(updated.get("batch")),
            clean(updated.get("assay_type")),
            clean(updated.get("instrument")),
            clean(updated.get("protocol_id")),
            clean(updated.get("operator")),
            clean(updated.get("experiment_date")),
            clean(updated.get("file_version")) or "v1",
            clean(updated.get("raw_processed_status")) or "raw",
            updated["context_status"],
            timestamp,
            row["file_id"],
        ),
    )
    if updated.get("experiment_id"):
        ensure_experiment_record(
            conn,
            updated["project_id"],
            clean(updated["experiment_id"]),
            clean(updated.get("experiment_name")) or f"Experiment for {row['file_id']}",
            clean(updated.get("assay_type")),
            {**payload, "protocol_id": updated.get("protocol_id"), "raw_data_file_ids": [row["file_id"]]},
        )
        create_link(conn, updated["project_id"], "file", row["file_id"], "belongs_to_experiment", "experiment", clean(updated["experiment_id"]), 1)
    if updated.get("protocol_id"):
        create_link(conn, updated["project_id"], "file", row["file_id"], "generated_by_protocol", "protocol", clean(updated["protocol_id"]), 1)
    for sample_label in as_list(updated.get("related_samples")):
        sample = upsert_sample_record(conn, project_id=updated["project_id"], sample_label=str(sample_label), metadata={"source": "data_context", "data_context_id": context_id})
        if sample:
            create_file_sample_link(
                conn,
                project_id=updated["project_id"],
                file_id=row["file_id"],
                sample_pk=sample["id"],
                sample_label=sample["sample_id"],
                experiment_id=clean(updated.get("experiment_id")),
                assay_type=clean(updated.get("assay_type")),
            )
    conn.commit()
    saved = row_to_dict(conn.execute("SELECT * FROM data_contexts WHERE id=?", (context_id,)).fetchone()) or {}
    file_record = row_to_dict(conn.execute("SELECT * FROM research_files WHERE id=?", (row["file_id"],)).fetchone()) or {}
    experiment = row_to_dict(conn.execute("SELECT * FROM experiments WHERE id=?", (clean(updated.get("experiment_id")),)).fetchone()) if clean(updated.get("experiment_id")) else None
    samples = rows_to_dicts(conn.execute("SELECT * FROM samples WHERE project_id=? AND id IN (SELECT sample_id FROM file_sample_links WHERE file_id=?)", (updated["project_id"], row["file_id"])).fetchall())
    conn.close()
    if experiment:
        canonical_memory.sync_experiment(agent_root, experiment)
    for sample in samples:
        canonical_memory.sync_sample(agent_root, sample)
    if file_record:
        canonical_memory.sync_data_file(agent_root, file_record)
    return saved


def file_samples(agent_root: Path, file_id: str) -> dict[str, Any]:
    conn = connect(agent_root)
    file_record = row_to_dict(conn.execute("SELECT * FROM research_files WHERE id=?", (file_id,)).fetchone())
    if not file_record:
        conn.close()
        raise KeyError("file not found")
    links = rows_to_dicts(
        conn.execute(
            """
            SELECT fsl.*, s.sample_type, s.storage_location, s.status AS sample_status
            FROM file_sample_links fsl
            LEFT JOIN samples s ON s.id=fsl.sample_id
            WHERE fsl.file_id=?
            ORDER BY COALESCE(fsl.row_number, 999999), fsl.sample_label
            """,
            (file_id,),
        ).fetchall()
    )
    context = row_to_dict(conn.execute("SELECT * FROM data_contexts WHERE file_id=?", (file_id,)).fetchone())
    conn.close()
    return {"file": file_record, "data_context": context, "samples": links}


