def seed_demo(agent_root: Path) -> dict[str, Any]:
    project = create_project(
        agent_root,
        {
            "id": "demo_immunomodulatory_natural_product",
            "title": "Immunomodulatory Natural Product Project",
            "short_description": "Demo project showing evidence-linked wet-lab memory across protocol, qPCR, ELISA, LC-MS, animal records, and experiment logs.",
            "research_area": "biomedical wet-lab natural products",
            "keywords": ["natural products", "immunomodulation", "qPCR", "ELISA", "LC-MS", "RAW264.7"],
            "owner": "local_lab_member",
            "status": "active",
        },
    )
    files = []
    for filename, content in DEMO_FILES.items():
        files.append(register_file(agent_root, {"project_id": project["id"], "filename": filename, "content": content, "tags": ["demo"]}))
    kit_template = parse_kit_template(
        agent_root,
        {
            "project_id": project["id"],
            "filename": "demo_elisa_kit_manual.txt",
            "name": "Demo IL-6 ELISA Kit Manual",
            "vendor": "Local Demo Vendor",
            "kit_type": "ELISA kit",
            "assay_type": "ELISA",
            "confirmed_by_user": True,
            "content": "IL-6 ELISA kit manual. Add standards and samples in duplicate to a 96-well plate. Incubate 2 h. Wash buffer is required. Add substrate and stop solution. Read absorbance at 450 nm. Use a standard curve, check replicate CV, blank wells, and out-of-range samples.",
        },
    )
    extracted = []
    for file_record in files:
        extracted.append(run_extraction(agent_root, {"file_id": file_record["id"]}))
    parsed = parse_protocol_text(
        agent_root,
        {
            "project_id": project["id"],
            "title": "NP-01 LPS macrophage qPCR protocol",
            "text": DEMO_FILES["protocol_methods messy FINAL v2.txt"],
            "created_from_file_id": files[0]["id"],
        },
    )
    protocol = store_protocol(agent_root, parsed["protocol"])
    execution_package = generate_execution_package(agent_root, {"protocol_id": protocol["id"]})
    workflow = create_workflow(agent_root, {"project_id": project["id"], "template_key": "protocol_to_execution"})
    workflow_run = run_workflow(agent_root, workflow["id"])
    conflicts = detect_conflicts(agent_root, project["id"])
    weekly = generate_report(agent_root, {"project_id": project["id"], "report_type": "weekly_report"})
    gap = generate_report(agent_root, {"project_id": project["id"], "report_type": "project_gap_analysis"})
    conflict_report = generate_report(agent_root, {"project_id": project["id"], "report_type": "conflict_report"})
    return {
        "project": project,
        "files": files,
        "kit_template": kit_template,
        "extraction_runs": extracted,
        "protocol": protocol,
        "execution_package": execution_package,
        "workflow": workflow_run["workflow"],
        "conflicts": conflicts,
        "reports": [weekly, gap, conflict_report],
    }


